                                ...(ticketHistoryHs910Snap.exists() ? (ticketHistoryHs910Snap.data().tombstones || []) : []),
                                ...(ticketHistoryHs1112Snap.exists() ? (ticketHistoryHs1112Snap.data().tombstones || []) : []),
