        let currentDataTimeFilter = 'allTime'; // Default to show all data
        let customDataStartDate = null;
        let customDataEndDate = null;
        
        function setDataTimeFilter(filter) {
            currentDataTimeFilter = filter;
            
            // Active state is CSS-driven (.time-filter-btn.active).
            document.querySelectorAll('.time-filter-btn').forEach(btn => btn.classList.remove('active'));
            const activeBtn = document.getElementById('filter' + filter.charAt(0).toUpperCase() + filter.slice(1));
            if (activeBtn) activeBtn.classList.add('active');
            
            // Hide custom date picker
            document.getElementById('customDateRangePicker').style.display = 'none';
            
            // Update display text
            const filterText = {
                'thisWeek': 'This Week (Current)',
                'last7Days': 'Last 7 Days',
                'last30Days': 'Last 30 Days',
                'thisCycle': `This Cycle (${currentCycle.name || 'Not configured'})`,
                'allTime': 'All Time'
            };
            
            document.getElementById('currentFilterText').textContent = filterText[filter];
            
            // Refresh analytics with new filter
            updateAnalyticsCharts();
            updateAnalyticsTables();
            updateTeacherAnalytics(); // Update teacher analytics when filter changes
        }
        
        function toggleCustomDateRange() {
            const picker = document.getElementById('customDateRangePicker');
            picker.style.display = picker.style.display === 'none' ? 'block' : 'none';
        }
        
        function applyCustomDateRange() {
            const startDate = document.getElementById('customStartDate').value;
            const endDate = document.getElementById('customEndDate').value;
            
            if (!startDate || !endDate) {
                alert('⚠️ Please select both start and end dates');
                return;
            }
            
            if (new Date(startDate) > new Date(endDate)) {
                alert('⚠️ Start date must be before end date');
                return;
            }
            
            customDataStartDate = startDate;
            customDataEndDate = endDate;
            currentDataTimeFilter = 'custom';
            
            // Update button states
            document.querySelectorAll('.time-filter-btn').forEach(btn => {
                btn.style.background = 'rgba(255,255,255,0.2)';
                btn.style.color = 'white';
            });
            
            document.getElementById('filterCustom').style.background = 'white';
            document.getElementById('filterCustom').style.color = '#667eea';
            
            // Update display text
            document.getElementById('currentFilterText').textContent = 
                `${new Date(startDate).toLocaleDateString()} - ${new Date(endDate).toLocaleDateString()}`;
            
            // Refresh analytics
            updateAnalyticsCharts();
            updateAnalyticsTables();
            updateTeacherAnalytics(); // Update teacher analytics when custom range is applied
        }
        
        function getFilteredStudentData() {
            // Return filtered student data based on current time filter
            // This function filters ticket history based on date range
            
            const now = new Date();
            let startDate, endDate;
            
            switch (currentDataTimeFilter) {
                case 'thisWeek':
                    // Filter ticket history by current week + current cycle
                    return students.map(s => {
                        const history = s.ticketHistory || [];
                        const thisWeekHistory = history.filter(h => 
                            h.week === currentWeek && entryBelongsToCurrentCycle(h)
                        );
                        
                        const pbisTotal = thisWeekHistory.filter(h => h.category === 'PBIS').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                        const attendanceTotal = thisWeekHistory.filter(h => h.category === 'Attendance').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                        const academicTotal = thisWeekHistory.filter(h => h.category === 'Academics' || h.category === 'Academic').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                        
                        return {
                            ...s,
                            pbisTickets: pbisTotal,
                            attendanceTickets: attendanceTotal,
                            academicTickets: academicTotal
                        };
                    });
                    
                case 'last7Days':
                    startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                    endDate = now;
                    break;
                    
                case 'last30Days':
                    startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
                    endDate = now;
                    break;
                    
                case 'thisCycle':
                    // "This Cycle" means ALL weeks of the current cycle (1 through currentWeek).
                    // Includes the full 5-week sweep so admins can see cycle-wide totals.
                    return students.map(s => {
                        const history = s.ticketHistory || [];
                        const thisCycleHistory = history.filter(h => entryBelongsToCurrentCycle(h));
                        
                        const pbisTotal = thisCycleHistory.filter(h => h.category === 'PBIS').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                        const attendanceTotal = thisCycleHistory.filter(h => h.category === 'Attendance').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                        const academicTotal = thisCycleHistory.filter(h => h.category === 'Academics' || h.category === 'Academic').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                        
                        return {
                            ...s,
                            pbisTickets: pbisTotal,
                            attendanceTickets: attendanceTotal,
                            academicTickets: academicTotal
                        };
                    });
                    
                case 'custom':
                    if (customDataStartDate && customDataEndDate) {
                        startDate = new Date(customDataStartDate);
                        endDate = new Date(customDataEndDate);
                    } else {
                        return students;
                    }
                    break;
                    
                case 'allTime':
                default:
                    // Return all historical data
                    return students.map(s => {
                        // Calculate totals from ticket history
                        const history = s.ticketHistory || [];
                        const pbisTotal = history.filter(h => h.category === 'PBIS').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                        const attendanceTotal = history.filter(h => h.category === 'Attendance').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                        const academicTotal = history.filter(h => h.category === 'Academics' || h.category === 'Academic').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                        
                        return {
                            ...s,
                            pbisTickets: pbisTotal,
                            attendanceTickets: attendanceTotal,
                            academicTickets: academicTotal
                        };
                    });
            }
            
            // For date range filters, calculate from ticket history
            // CRITICAL: Only count tickets that have a week field to avoid counting corrupted data
            return students.map(s => {
                const history = s.ticketHistory || [];
                const filteredHistory = history.filter(h => {
                    // Skip tickets without week field (corrupted data)
                    if (h.week === undefined || h.week === null) return false;
                    
                    const ticketDate = new Date(h.timestamp);
                    return ticketDate >= startDate && ticketDate <= endDate;
                });
                
                const pbisTotal = filteredHistory.filter(h => h.category === 'PBIS').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                const attendanceTotal = filteredHistory.filter(h => h.category === 'Attendance').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                const academicTotal = filteredHistory.filter(h => h.category === 'Academics' || h.category === 'Academic').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                
                return {
                    ...s,
                    pbisTickets: pbisTotal,
                    attendanceTickets: attendanceTotal,
                    academicTickets: academicTotal
                };
            });
        }
        
        function updateAnalyticsCharts() {
            const suffix = currentDataSubtab === 'academy' ? 'Academy' : 
                          currentDataSubtab === 'middleschool' ? 'MS' : 'HS';
            
            updateMetricCards(suffix); // NEW: Update metric cards
            updateTop10Leaderboard(suffix); // NEW: Update Top 10
            updateGradeChart(suffix);
            updateWeekChart(suffix);
            updateQualificationChart(suffix);
        }
        
        // NEW FUNCTION: Update Top 10 Leaderboard
        function updateTop10Leaderboard(suffix) {
            const prefix = suffix === 'Academy' ? 'academy' : 
                          suffix === 'MS' ? 'ms' : 'hs';
            
            const leaderboardEl = document.getElementById(`${prefix}Top10Leaderboard`);
            if (!leaderboardEl) return;
            
            // Get filtered students
            let filteredStudents = getFilteredStudentData();
            
            // Filter by school level if needed
            if (suffix === 'MS') {
                filteredStudents = filteredStudents.filter(s => {
                    const grade = parseInt(s.grade);
                    return grade >= 6 && grade <= 8;
                });
            } else if (suffix === 'HS') {
                filteredStudents = filteredStudents.filter(s => {
                    const grade = parseInt(s.grade);
                    return grade >= 9 && grade <= 12;
                });
            }
            
            // Calculate total tickets for each student
            const studentsWithTotals = filteredStudents.map(s => ({
                student: s,
                totalTickets: (s.pbisTickets || 0) + (s.attendanceTickets || 0) + (s.academicTickets || 0),
                pbis: s.pbisTickets || 0,
                attendance: s.attendanceTickets || 0,
                academic: s.academicTickets || 0
            }));
            
            // Sort by total tickets (descending) and take top 10
            const top10 = studentsWithTotals
                .filter(s => s.totalTickets > 0)
                .sort((a, b) => b.totalTickets - a.totalTickets)
                .slice(0, 10);
            
            if (top10.length === 0) {
                leaderboardEl.innerHTML = '<div style="text-align: center; padding: 30px; color: #999;">No ticket data for this time period</div>';
                return;
            }
            
            // Build leaderboard HTML
            let html = '<div style="display: flex; flex-direction: column; gap: 12px;">';
            
            top10.forEach((item, index) => {
                const s = item.student;
                const rank = index + 1;
                
                // Medal colors for top 3
                let medalIcon = '';
                let bgColor = '#f9fafb';
                if (rank === 1) {
                    medalIcon = '🥇';
                    bgColor = 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)';
                } else if (rank === 2) {
                    medalIcon = '🥈';
                    bgColor = 'linear-gradient(135deg, #e5e7eb 0%, #d1d5db 100%)';
                } else if (rank === 3) {
                    medalIcon = '🥉';
                    bgColor = 'linear-gradient(135deg, #fed7aa 0%, #fdba74 100%)';
                }
                
                html += `
                    <div style="background: ${bgColor}; padding: 15px 20px; border-radius: 10px; display: flex; align-items: center; justify-content: space-between; ${rank <= 3 ? 'box-shadow: 0 2px 8px rgba(0,0,0,0.1);' : ''}">
                        <div style="display: flex; align-items: center; gap: 15px; flex: 1;">
                            <div style="font-size: 24px; font-weight: 700; color: ${rank <= 3 ? '#92400e' : '#666'}; min-width: 35px; text-align: center;">
                                ${medalIcon || rank}
                            </div>
                            <div style="flex: 1;">
                                <div style="font-weight: 600; color: #333; font-size: 15px;">${s.firstName} ${s.lastName}</div>
                                <div style="font-size: 12px; color: #666; margin-top: 2px;">Grade ${s.grade} • ID: ${s.id}</div>
                            </div>
                        </div>
                        <div style="display: flex; align-items: center; gap: 15px;">
                            <div style="text-align: right;">
                                <div style="font-size: 11px; color: #666; margin-bottom: 3px;">
                                    <span style="color: #667eea;">🎯 ${item.pbis}</span> • 
                                    <span style="color: #10b981;">📅 ${item.attendance}</span> • 
                                    <span style="color: #3b82f6;">📚 ${item.academic}</span>
                                </div>
                                <div style="font-size: 20px; font-weight: 700; color: #f59e0b;">
                                    ${item.totalTickets} 🎫
                                </div>
                            </div>
                        </div>
                    </div>
                `;
            });
            
            html += '</div>';
            leaderboardEl.innerHTML = html;
        }
        
        // TEACHER ANALYTICS FUNCTION
        function updateTeacherAnalytics() {
            // Use the main data filter (same as MS/HS tabs)
            const teacherTimeFrame = currentDataTimeFilter;
            
            // Calculate teacher ticket data from audit log based on time filter
            const teacherTickets = {};
            
            // Initialize all teachers
            teachers.forEach(t => {
                teacherTickets[t.name] = {
                    name: t.name,
                    pbis: 0,
                    attendance: 0,
                    academic: 0,
                    total: 0
                };
            });
            
            // Filter audit log by selected time frame (using main filter)
            let filteredAudit = auditLog;
            const now = new Date();
            
            switch (teacherTimeFrame) {
                case 'thisWeek':
                    filteredAudit = auditLog.filter(e => e.week === currentWeek && entryBelongsToCurrentCycle(e));
                    break;
                case 'last7Days':
                    const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                    filteredAudit = auditLog.filter(e => new Date(e.timestamp) >= sevenDaysAgo);
                    break;
                case 'last30Days':
                    const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
                    filteredAudit = auditLog.filter(e => new Date(e.timestamp) >= thirtyDaysAgo);
                    break;
                case 'thisCycle':
                    if (currentCycle.startDate && currentCycle.endDate) {
                        const cycleStart = new Date(currentCycle.startDate);
                        const cycleEnd = new Date(currentCycle.endDate);
                        filteredAudit = auditLog.filter(e => {
                            const entryDate = new Date(e.timestamp);
                            return entryDate >= cycleStart && entryDate <= cycleEnd;
                        });
                    }
                    break;
                case 'allTime':
                    // Use full audit log
                    filteredAudit = auditLog;
                    break;
                case 'custom':
                    // Custom range filtering
                    if (customStartDate && customEndDate) {
                        const startDate = new Date(customStartDate);
                        const endDate = new Date(customEndDate);
                        filteredAudit = auditLog.filter(e => {
                            const entryDate = new Date(e.timestamp);
                            return entryDate >= startDate && entryDate <= endDate;
                        });
                    }
                    break;
            }
            
            // Count tickets by teacher from filtered audit log
            filteredAudit.forEach(entry => {
                if (entry.action === 'Awarded Tickets' && entry.teacher) {
                    const teacherName = entry.teacher;
                    if (!teacherTickets[teacherName]) {
                        teacherTickets[teacherName] = {
                            name: teacherName,
                            pbis: 0,
                            attendance: 0,
                            academic: 0,
                            total: 0
                        };
                    }
                    
                    const count = entry.ticketCount || 1;
                    teacherTickets[teacherName].total += count;
                    
                    if (entry.category === 'PBIS') {
                        teacherTickets[teacherName].pbis += count;
                    } else if (entry.category === 'Attendance') {
                        teacherTickets[teacherName].attendance += count;
                    } else if (entry.category === 'Academics' || entry.category === 'Academic') {
                        teacherTickets[teacherName].academic += count;
                    }
                }
            });
            
            // Convert to array and sort
            const teacherArray = Object.values(teacherTickets);
            const activeTeachers = teacherArray.filter(t => t.total > 0);
            const inactiveTeachers = teacherArray.filter(t => t.total === 0);
            
            // Update overview stats
            document.getElementById('totalTeachers').textContent = teacherArray.length;
            document.getElementById('activeTeachers').textContent = activeTeachers.length;
            const engagementRate = teacherArray.length > 0 ? Math.round((activeTeachers.length / teacherArray.length) * 100) : 0;
            document.getElementById('engagementRate').textContent = engagementRate + '%';
            const avgTickets = activeTeachers.length > 0 ? Math.round(activeTeachers.reduce((sum, t) => sum + t.total, 0) / activeTeachers.length) : 0;
            document.getElementById('avgTicketsPerTeacher').textContent = avgTickets;
            
            // Update Top 10 Teacher Leaderboard
            const top10Teachers = activeTeachers.sort((a, b) => b.total - a.total).slice(0, 10);
            let leaderboardHtml = '';
            
            if (top10Teachers.length === 0) {
                leaderboardHtml = '<div style="text-align: center; padding: 30px; color: #999;">No teacher activity in this time period</div>';
            } else {
                leaderboardHtml = '<div style="display: flex; flex-direction: column; gap: 12px;">';
                top10Teachers.forEach((teacher, index) => {
                    const rank = index + 1;
                    let medalIcon = '';
                    let bgColor = '#f9fafb';
                    
                    if (rank === 1) {
                        medalIcon = '🥇';
                        bgColor = 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)';
                    } else if (rank === 2) {
                        medalIcon = '🥈';
                        bgColor = 'linear-gradient(135deg, #e5e7eb 0%, #d1d5db 100%)';
                    } else if (rank === 3) {
                        medalIcon = '🥉';
                        bgColor = 'linear-gradient(135deg, #fed7aa 0%, #fdba74 100%)';
                    }
                    
                    leaderboardHtml += `
                        <div style="background: ${bgColor}; padding: 15px 20px; border-radius: 10px; display: flex; align-items: center; justify-content: space-between; ${rank <= 3 ? 'box-shadow: 0 2px 8px rgba(0,0,0,0.1);' : ''}">
                            <div style="display: flex; align-items: center; gap: 15px; flex: 1;">
                                <div style="font-size: 24px; font-weight: 700; color: ${rank <= 3 ? '#92400e' : '#666'}; min-width: 35px; text-align: center;">
                                    ${medalIcon || rank}
                                </div>
                                <div style="font-weight: 600; color: #333; font-size: 15px;">${teacher.name}</div>
                            </div>
                            <div style="text-align: right;">
                                <div style="font-size: 11px; color: #666; margin-bottom: 3px;">
                                    <span style="color: #667eea;">🎯 ${teacher.pbis}</span> • 
                                    <span style="color: #10b981;">📅 ${teacher.attendance}</span> • 
                                    <span style="color: #3b82f6;">📚 ${teacher.academic}</span>
                                </div>
                                <div style="font-size: 20px; font-weight: 700; color: #f59e0b;">
                                    ${teacher.total} 🎫
                                </div>
                            </div>
                        </div>
                    `;
                });
                leaderboardHtml += '</div>';
            }
            
            document.getElementById('teacherLeaderboard').innerHTML = leaderboardHtml;
            
            // Update inactive teachers section
            if (inactiveTeachers.length > 0) {
                document.getElementById('inactiveTeachersSection').style.display = 'block';
                let inactiveHtml = '';
                inactiveTeachers.forEach(teacher => {
                    inactiveHtml += `<div style="background: white; padding: 10px 15px; border-radius: 6px; border: 1px solid #f59e0b;">${teacher.name}</div>`;
                });
                document.getElementById('inactiveTeachersList').innerHTML = inactiveHtml;
            } else {
                document.getElementById('inactiveTeachersSection').style.display = 'none';
            }
            
            // Update full teacher table
            const sortedTeachers = [...teacherArray].sort((a, b) => b.total - a.total);
            let tableHtml = '';
            
            sortedTeachers.forEach(teacher => {
                const status = teacher.total > 0 ? 
                    '<span style="background: #d1fae5; color: #065f46; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 600;">Active</span>' :
                    '<span style="background: #fee2e2; color: #991b1b; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 600;">Inactive</span>';
                
                tableHtml += `
                    <tr style="border-bottom: 1px solid #e5e7eb;">
                        <td style="padding: 14px 20px;">${teacher.name}</td>
                        <td style="padding: 14px 20px; text-align: center;">${teacher.pbis}</td>
                        <td style="padding: 14px 20px; text-align: center;">${teacher.attendance}</td>
                        <td style="padding: 14px 20px; text-align: center;">${teacher.academic}</td>
                        <td style="padding: 14px 20px; text-align: center; font-weight: 700;">${teacher.total}</td>
                        <td style="padding: 14px 20px; text-align: center;">${status}</td>
                    </tr>
                `;
            });
            
            document.getElementById('teacherAnalyticsTable').innerHTML = tableHtml;
        }
        
        // Sortable teacher table
        let teacherSortColumn = 'total';
        let teacherSortAsc = false;
        
        function sortTeacherTable(column) {
            if (teacherSortColumn === column) {
                teacherSortAsc = !teacherSortAsc;
            } else {
                teacherSortColumn = column;
                teacherSortAsc = false;
            }
            updateTeacherAnalytics(); // Re-render with new sort
        }
        
        // NEW FUNCTION: Update metric cards for Data & Analytics
        function updateMetricCards(suffix) {
            // Get filtered student data based on current time filter
            let filteredStudents = getFilteredStudentData();
            
            // Further filter by school level (MS/HS) if needed
            if (suffix === 'MS') {
                filteredStudents = filteredStudents.filter(s => {
                    const grade = parseInt(s.grade);
                    return grade >= 6 && grade <= 8;
                });
            } else if (suffix === 'HS') {
                filteredStudents = filteredStudents.filter(s => {
                    const grade = parseInt(s.grade);
                    return grade >= 9 && grade <= 12;
                });
            }
            
            // Calculate totals
            let totalTickets = 0;
            let pbisTickets = 0;
            let attendanceTickets = 0;
            let academicTickets = 0;
            let qualifiedCount = 0;
            
            filteredStudents.forEach(s => {
                const pbis = s.pbisTickets || 0;
                const attendance = s.attendanceTickets || 0;
                const academic = s.academicTickets || 0;
                
                pbisTickets += pbis;
                attendanceTickets += attendance;
                academicTickets += academic;
                totalTickets += pbis + attendance + academic;
            });
            
            // CORRECTED: Count students who are ACTUALLY qualified for Wildcat Jackpot
            // (have bigRaffleQualified array with entries)
            // This counts UNIQUE students, not duplicate audit entries
            if (currentDataTimeFilter === 'allTime' || currentDataTimeFilter === 'thisCycle' || currentDataTimeFilter === 'last30Days') {
                // For time periods that might span multiple weeks, count unique qualified students
                qualifiedCount = filteredStudents.filter(s => 
                    Array.isArray(s.bigRaffleQualified) && s.bigRaffleQualified.length > 0
                ).length;
            } else if (currentDataTimeFilter === 'thisWeek') {
                // For current week only, count students with tickets in all 3 categories THIS WEEK
                filteredStudents.forEach(s => {
                    const pbis = s.pbisTickets || 0;
                    const attendance = s.attendanceTickets || 0;
                    const academic = s.academicTickets || 0;
                    
                    if (pbis > 0 && attendance > 0 && academic > 0) {
                        qualifiedCount++;
                    }
                });
            } else {
                // For other time filters, use ticket-based qualification
                filteredStudents.forEach(s => {
                    const pbis = s.pbisTickets || 0;
                    const attendance = s.attendanceTickets || 0;
                    const academic = s.academicTickets || 0;
                    
                    if (pbis > 0 && attendance > 0 && academic > 0) {
                        qualifiedCount++;
                    }
                });
            }
            
            // Calculate metrics
            const totalStudents = filteredStudents.length;
            const qualificationRate = totalStudents > 0 ? Math.round((qualifiedCount / totalStudents) * 100) : 0;
            const avgTickets = totalStudents > 0 ? (totalTickets / totalStudents).toFixed(1) : '0.0';
            
            // Determine prefix for element IDs
            const prefix = suffix === 'Academy' ? 'academy' : 
                          suffix === 'MS' ? 'ms' : 'hs';
            
            // Update metric cards
            const totalTicketsEl = document.getElementById(`${prefix}TotalTickets`);
            const qualifiedEl = document.getElementById(`${prefix}QualifiedStudents`);
            const qualificationRateEl = document.getElementById(`${prefix}QualificationRate`);
            const avgTicketsEl = document.getElementById(`${prefix}AvgTickets`);
            
            if (totalTicketsEl) totalTicketsEl.textContent = totalTickets;
            if (qualifiedEl) qualifiedEl.textContent = qualifiedCount;
            if (qualificationRateEl) qualificationRateEl.textContent = qualificationRate + '%';
            if (avgTicketsEl) avgTicketsEl.textContent = avgTickets;
            
            // Update category breakdown cards
            const pbisEl = document.getElementById(`${prefix}PbisTickets`);
            const attendanceEl = document.getElementById(`${prefix}AttendanceTickets`);
            const academicEl = document.getElementById(`${prefix}AcademicTickets`);
            
            if (pbisEl) pbisEl.textContent = pbisTickets;
            if (attendanceEl) attendanceEl.textContent = attendanceTickets;
            if (academicEl) academicEl.textContent = academicTickets;
        }

        // ============================================================
        // INSIGHTS (Data & Analytics → Insights subtab)
        // Near-miss students, teacher generosity variance, winner distribution
        // ============================================================
        function updateInsights() {
            updateNearMissStudents();
            updateTeacherGenerosity();
            updateWinnerDistribution();
        }

        function updateNearMissStudents() {
            const listEl = document.getElementById('nearMissList');
            const countEl = document.getElementById('nearMissCount');
            if (!listEl || !countEl) return;

            // Students who earned 2 of 3 category types this week but not all 3
            const nearMiss = students.map(s => {
                const pbis = s.pbisTickets || 0;
                const att = s.attendanceTickets || 0;
                const acad = s.academicTickets || 0;
                const earnedCategories = [pbis > 0, att > 0, acad > 0].filter(Boolean).length;
                return { student: s, pbis, att, acad, earnedCategories };
            }).filter(x => x.earnedCategories === 2);

            countEl.textContent = nearMiss.length;

            if (nearMiss.length === 0) {
                listEl.innerHTML = '<div style="text-align: center; padding: 30px; color: #999;">No near-miss students this week. Either everyone qualified or no one has earned 2-of-3 yet.</div>';
                return;
            }

            // Sort by "how close" — total tickets descending (most engaged near-miss first)
            nearMiss.sort((a, b) => (b.pbis + b.att + b.acad) - (a.pbis + a.att + a.acad));

            let html = '<div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 10px;">';
            nearMiss.forEach(({ student, pbis, att, acad }) => {
                // Which category are they missing?
                const missing = [];
                if (pbis === 0) missing.push('PBIS');
                if (att === 0) missing.push('Attendance');
                if (acad === 0) missing.push('Academic');
                const missingLabel = missing.join(', ');

                const gradeLabel = student.grade >= 6 && student.grade <= 8 ? 'MS' : 'HS';

                html += `
                    <div style="background: #fef3c7; padding: 12px 15px; border-radius: 8px; border-left: 3px solid #f59e0b;">
                        <div style="font-weight: 600; color: #333; font-size: 14px;">${student.firstName} ${student.lastName}</div>
                        <div style="font-size: 11px; color: #666; margin: 3px 0;">Grade ${student.grade} (${gradeLabel}) • ID: ${student.id}</div>
                        <div style="font-size: 12px; color: #92400e; margin-top: 6px;">
                            PBIS: <b>${pbis}</b> • Att: <b>${att}</b> • Acad: <b>${acad}</b>
                        </div>
                        <div style="font-size: 11px; color: #b45309; margin-top: 4px; font-style: italic;">
                            Needs: ${missingLabel}
                        </div>
                    </div>
                `;
            });
            html += '</div>';
            listEl.innerHTML = html;
        }

        function updateTeacherGenerosity() {
            // Pull from audit log so the numbers are authoritative
            const teacherCounts = {};
            auditLog.forEach(e => {
                if (e.action !== 'Awarded Tickets' || !e.teacher) return;
                if (!teacherCounts[e.teacher]) teacherCounts[e.teacher] = 0;
                teacherCounts[e.teacher] += (e.ticketCount || 1);
            });

            const counts = Object.values(teacherCounts).filter(c => c > 0);
            const activeCount = counts.length;

            const mean = activeCount > 0 ? counts.reduce((a, b) => a + b, 0) / activeCount : 0;
            const sortedCounts = [...counts].sort((a, b) => a - b);
            const median = activeCount === 0 ? 0
                : activeCount % 2 === 1
                    ? sortedCounts[Math.floor(activeCount / 2)]
                    : (sortedCounts[activeCount / 2 - 1] + sortedCounts[activeCount / 2]) / 2;
            const variance = activeCount > 0
                ? counts.reduce((sum, c) => sum + Math.pow(c - mean, 2), 0) / activeCount
                : 0;
            const stdDev = Math.sqrt(variance);

            const setText = (id, val) => {
                const el = document.getElementById(id);
                if (el) el.textContent = val;
            };
            setText('genActiveTeachers', activeCount);
            setText('genMean', Math.round(mean));
            setText('genMedian', Math.round(median));
            setText('genStdDev', Math.round(stdDev));

            // Outliers: >= mean + stdDev (high) and <= mean - stdDev (low, still active)
            const highThreshold = mean + stdDev;
            const lowThreshold = Math.max(1, mean - stdDev); // must still be active (>= 1)
            const highOutliers = Object.entries(teacherCounts)
                .filter(([, c]) => c >= highThreshold && stdDev > 0)
                .sort((a, b) => b[1] - a[1]);
            const lowOutliers = Object.entries(teacherCounts)
                .filter(([, c]) => c <= lowThreshold && c > 0 && stdDev > 0)
                .sort((a, b) => a[1] - b[1]);

            const highEl = document.getElementById('genOutliersHigh');
            const lowEl = document.getElementById('genOutliersLow');

            if (highEl) {
                if (highOutliers.length === 0) {
                    highEl.innerHTML = '';
                } else {
                    highEl.innerHTML = `
                        <div style="background: #d1fae5; padding: 12px 15px; border-radius: 8px;">
                            <div style="font-weight: 600; color: #065f46; margin-bottom: 6px; font-size: 13px;">
                                🔝 High Outliers (${highOutliers.length}), awarding significantly more than average
                            </div>
                            <div style="font-size: 13px; color: #047857;">
                                ${highOutliers.map(([name, c]) => `${name}: <b>${c}</b>`).join(' • ')}
                            </div>
                        </div>
                    `;
                }
            }

            if (lowEl) {
                if (lowOutliers.length === 0) {
                    lowEl.innerHTML = '';
                } else {
                    lowEl.innerHTML = `
                        <div style="background: #fee2e2; padding: 12px 15px; border-radius: 8px;">
                            <div style="font-weight: 600; color: #991b1b; margin-bottom: 6px; font-size: 13px;">
                                ⚠️ Low Outliers (${lowOutliers.length}), awarding significantly less than average
                            </div>
                            <div style="font-size: 13px; color: #b91c1c;">
                                ${lowOutliers.map(([name, c]) => `${name}: <b>${c}</b>`).join(' • ')}
                            </div>
                            <div style="font-size: 11px; color: #7f1d1d; margin-top: 8px; font-style: italic;">
                                Students in these teachers' classes have fewer opportunities to earn tickets. Consider coaching.
                            </div>
                        </div>
                    `;
                }
            }
        }

        function updateWinnerDistribution() {
            const allWins = weeklyWinners || [];
            // Count wins per student ID
            const winsByStudent = {};
            allWins.forEach(w => {
                const sid = w.student?.id;
                if (!sid) return;
                winsByStudent[sid] = (winsByStudent[sid] || 0) + 1;
            });

            const uniqueWinners = Object.keys(winsByStudent).length;
            const totalWins = allWins.length;
            const repeatWinners = Object.values(winsByStudent).filter(c => c > 1).length;

            // "Never-won eligible" = students who have qualified at least once but never won a raffle
            const winnerIds = new Set(Object.keys(winsByStudent));
            const neverWonEligible = students.filter(s => {
                const hasQualified = (Array.isArray(s.bigRaffleQualified) ? s.bigRaffleQualified.length > 0 : s.bigRaffleQualified === true);
                return hasQualified && !winnerIds.has(s.id);
            }).length;

            const setText = (id, val) => {
                const el = document.getElementById(id);
                if (el) el.textContent = val;
            };
            setText('winnerUniqueCount', uniqueWinners);
            setText('winnerTotalWins', totalWins);
            setText('winnerRepeatCount', repeatWinners);
            setText('winnerNeverWon', neverWonEligible);

            // Recent first-time winners list
            const recentListEl = document.getElementById('winnerRecentList');
            if (recentListEl) {
                const seenIds = new Set();
                const firstTimes = [];
                // Process wins in chronological order; first appearance of each student = first-time winner
                [...allWins].sort((a, b) => new Date(a.date) - new Date(b.date)).forEach(w => {
                    const sid = w.student?.id;
                    if (!sid || seenIds.has(sid)) return;
                    seenIds.add(sid);
                    firstTimes.push(w);
                });
                // Reverse for most-recent first
                firstTimes.reverse();
                const recent = firstTimes.slice(0, 10);

                if (recent.length === 0) {
                    recentListEl.innerHTML = '<div style="color: #999; font-style: italic; font-size: 13px;">No first-time winners yet.</div>';
                } else {
                    recentListEl.innerHTML = `
                        <div style="margin-bottom: 10px;">
                            <div style="font-weight: 600; color: #333; font-size: 14px; margin-bottom: 8px;">🎉 Recent First-Time Winners (last 10)</div>
                        </div>
                        <div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 8px;">
                            ${recent.map(w => `
                                <div style="background: #f9fafb; padding: 10px 12px; border-radius: 6px; border-left: 3px solid #10b981;">
                                    <div style="font-weight: 600; color: #333; font-size: 13px;">${w.student?.firstName || '?'} ${w.student?.lastName || ''}</div>
                                    <div style="font-size: 11px; color: #666; margin-top: 3px;">Week ${w.week} • ${w.category} • ${w.date}</div>
                                </div>
                            `).join('')}
                        </div>
                    `;
                }
            }
        }

        // ============================================================
        // HALL OF FAME — historical winners view
        //
        // Derives winners from the audit log (the source of truth) rather than
        // from in-memory arrays like weeklyWinners (which can be cleared by
        // stale-tab saves). Renders two sections:
        //   - Wildcat Jackpot Champions (card grid, all entries)
        //   - Weekly Raffle Winners (table, filterable by cycle)
        // ============================================================
        function cycleFromTimestamp(ts) {
            // Best-effort cycle inference: cycleDuration is typically 5 weeks.
            // We don't have a stored cycle-start-date, so we approximate from
            // the difference between the timestamp and the earliest audit entry.
            // For winners that carry an explicit `cycle` field (jackpot entries
            // in bigRaffleWinners), prefer that.
            if (!ts || !auditLog || auditLog.length === 0) return null;
            try {
                const winnerDate = new Date(ts);
                // Find earliest "Awarded Tickets" timestamp as program start
                const earliestAward = auditLog
                    .filter(e => e.action === 'Awarded Tickets')
                    .map(e => new Date(e.timestamp))
                    .filter(d => !isNaN(d.getTime()))
                    .sort((a, b) => a - b)[0];
                if (!earliestAward) return null;
                const daysElapsed = Math.floor((winnerDate - earliestAward) / (1000 * 60 * 60 * 24));
                const cycleDays = (cycleDuration || 5) * 7;
                return Math.floor(daysElapsed / cycleDays) + 1;
            } catch (e) {
                return null;
            }
        }

        function formatHallOfFameDate(ts) {
            if (!ts) return '—';
            try {
                const d = new Date(ts);
                return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
            } catch (e) {
                return ts.substring(0, 10);
            }
        }

        function escapeHtml(s) {
            if (s == null) return '';
            return String(s)
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#39;');
        }

        function renderHallOfFame() {
            const log = auditLog || [];

            // Jackpot winners, sorted newest first
            const jackpot = log
                .filter(e => e.action === 'Wildcat Jackpot Winner')
                .slice()
                .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

            // Weekly raffle winners, sorted newest first
            const allWeekly = log
                .filter(e => e.action === 'Raffle Winner')
                .slice()
                .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

            // Populate cycle dropdown
            const cycleFilterEl = document.getElementById('halloffameCycleFilter');
            const selectedCycle = cycleFilterEl ? cycleFilterEl.value : 'all';
            const cyclesSeen = new Set();
            allWeekly.forEach(e => {
                const c = cycleFromTimestamp(e.timestamp);
                if (c) cyclesSeen.add(c);
            });
            jackpot.forEach(e => {
                const c = cycleFromTimestamp(e.timestamp);
                if (c) cyclesSeen.add(c);
            });
            if (cycleFilterEl) {
                const cyclesList = Array.from(cyclesSeen).sort((a, b) => b - a);
                // Only rebuild options if the set changed (avoid resetting user's selection)
                const existingValues = Array.from(cycleFilterEl.options).map(o => o.value).filter(v => v !== 'all');
                const newValues = cyclesList.map(String);
                if (JSON.stringify(existingValues.sort()) !== JSON.stringify(newValues.slice().sort())) {
                    cycleFilterEl.innerHTML = '<option value="all">All Cycles</option>';
                    cyclesList.forEach(c => {
                        const opt = document.createElement('option');
                        opt.value = String(c);
                        opt.textContent = `Cycle ${c}`;
                        cycleFilterEl.appendChild(opt);
                    });
                    cycleFilterEl.value = selectedCycle && document.querySelector(`#halloffameCycleFilter option[value="${selectedCycle}"]`)
                        ? selectedCycle
                        : 'all';
                }
            }

            // Filter weekly by selected cycle
            const filterCycle = cycleFilterEl ? cycleFilterEl.value : 'all';
            const weekly = filterCycle === 'all'
                ? allWeekly
                : allWeekly.filter(e => String(cycleFromTimestamp(e.timestamp)) === filterCycle);

            // === Render jackpot card grid ===
            const jackpotGrid = document.getElementById('jackpotWinnersGrid');
            const jackpotEmpty = document.getElementById('jackpotWinnersEmpty');
            const jackpotCount = document.getElementById('jackpotWinnerCount');

            if (jackpotCount) {
                jackpotCount.textContent = `${jackpot.length} winner${jackpot.length === 1 ? '' : 's'}`;
            }

            if (jackpot.length === 0) {
                if (jackpotGrid) jackpotGrid.innerHTML = '';
                if (jackpotEmpty) jackpotEmpty.style.display = 'block';
            } else {
                if (jackpotEmpty) jackpotEmpty.style.display = 'none';
                if (jackpotGrid) {
                    jackpotGrid.innerHTML = jackpot.map(e => {
                        const isMS = (e.category || '').toLowerCase().includes('middle');
                        const gradient = isMS
                            ? 'linear-gradient(135deg, #f59e0b 0%, #d97706 100%)'
                            : 'linear-gradient(135deg, #10b981 0%, #059669 100%)';
                        const schoolLabel = isMS ? 'Middle School' : 'High School';
                        const cycle = cycleFromTimestamp(e.timestamp);
                        const student = students.find(s => s.id === e.studentId);
                        const grade = student ? student.grade : '?';
                        const entriesText = e.reason && e.reason.match(/(\d+)/)
                            ? `Drawn from ${e.reason.match(/(\d+)/)[1]} entries`
                            : (e.reason || '');
                        const reconBadge = e.reconstructed
                            ? `<div style="position: absolute; top: 12px; right: 12px; background: rgba(0,0,0,0.3); color: white; padding: 3px 8px; border-radius: 10px; font-size: 10px; font-weight: 600;" title="Reconstructed from system records, not real-time logged">📋 RECONSTRUCTED</div>`
                            : '';
                        return `
                            <div style="background: ${gradient}; color: white; padding: 25px; border-radius: 16px; box-shadow: 0 8px 24px rgba(0,0,0,0.15); position: relative; overflow: hidden;">
                                ${reconBadge}
                                <div style="font-size: 36px; margin-bottom: 10px;">🏆</div>
                                <div style="font-size: 11px; text-transform: uppercase; letter-spacing: 2px; opacity: 0.9; margin-bottom: 4px;">${schoolLabel}</div>
                                <div style="font-size: 22px; font-weight: 700; line-height: 1.2; margin-bottom: 4px;">${escapeHtml(e.studentName || 'Unknown')}</div>
                                <div style="font-size: 13px; opacity: 0.85; margin-bottom: 16px;">Grade ${escapeHtml(grade)}</div>
                                <div style="background: rgba(255,255,255,0.2); padding: 10px 14px; border-radius: 8px; margin-bottom: 12px;">
                                    <div style="font-size: 11px; opacity: 0.9; text-transform: uppercase; letter-spacing: 1px;">Cycle ${cycle || '?'}</div>
                                    <div style="font-size: 14px; font-weight: 600;">${formatHallOfFameDate(e.timestamp)}</div>
                                </div>
                                ${entriesText ? `<div style="font-size: 12px; opacity: 0.9;">🎟️ ${escapeHtml(entriesText)}</div>` : ''}
                                <div style="font-size: 11px; opacity: 0.75; margin-top: 8px;">Drawn by ${escapeHtml(e.teacher || 'Unknown')}</div>
                            </div>
                        `;
                    }).join('');
                }
            }

            // === Render weekly winners table ===
            const weeklyBody = document.getElementById('weeklyWinnersTable');
            const weeklyEmpty = document.getElementById('weeklyWinnersEmpty');
            const weeklyCount = document.getElementById('weeklyWinnerCount');

            if (weeklyCount) {
                weeklyCount.textContent = `${weekly.length} winner${weekly.length === 1 ? '' : 's'}`;
            }

            if (weekly.length === 0) {
                if (weeklyBody) weeklyBody.innerHTML = '';
                if (weeklyEmpty) weeklyEmpty.style.display = 'block';
            } else {
                if (weeklyEmpty) weeklyEmpty.style.display = 'none';
                if (weeklyBody) {
                    weeklyBody.innerHTML = weekly.map(e => {
                        const student = students.find(s => s.id === e.studentId);
                        const grade = student ? student.grade : '?';
                        const cycle = cycleFromTimestamp(e.timestamp);
                        const wkText = (cycle ? `Cycle ${cycle}` : '') + (e.week ? ` · Wk ${e.week}` : '');
                        const reconBadge = e.reconstructed
                            ? ` <span style="background: #fef3c7; color: #92400e; padding: 2px 6px; border-radius: 4px; font-size: 10px; font-weight: 600;" title="Reconstructed from system records">📋</span>`
                            : '';
                        // Light category tint
                        const cat = (e.category || '').toLowerCase();
                        let catColor = '#667eea';
                        if (cat.includes('pbis')) catColor = '#8b5cf6';
                        else if (cat.includes('attendance')) catColor = '#2E7D52';
                        else if (cat.includes('academic')) catColor = '#f59e0b';
                        return `
                            <tr style="border-bottom: 1px solid #f0f0f0;">
                                <td style="padding: 12px 16px; font-size: 13px; color: #666; white-space: nowrap;">${formatHallOfFameDate(e.timestamp)}</td>
                                <td style="padding: 12px 16px; font-size: 13px; color: #666; white-space: nowrap;">${escapeHtml(wkText) || '—'}</td>
                                <td style="padding: 12px 16px; font-size: 13px;"><span style="display: inline-block; padding: 4px 10px; background: ${catColor}; color: white; border-radius: 12px; font-size: 11px; font-weight: 600;">${escapeHtml(e.category || '—')}</span></td>
                                <td style="padding: 12px 16px; font-size: 14px; font-weight: 600; color: #333;">${escapeHtml(e.studentName || 'Unknown')}${reconBadge}</td>
                                <td style="padding: 12px 16px; font-size: 13px; color: #666;">${escapeHtml(grade)}</td>
                                <td style="padding: 12px 16px; font-size: 13px; color: #666;">${escapeHtml(e.teacher || '—')}</td>
                            </tr>
                        `;
                    }).join('');
                }
            }
        }

        // ============================================================
        // ADMIN CORRECTIONS PANEL
        //
        // Safe, UI-driven versions of the correction operations that
        // previously required hand-written console scripts:
        //   1. Re-tag a ticket's week/cycle (fixes history + audit together)
        //   2. Remove a wrongly-awarded ticket (tombstone + direct removal)
        //   3. Invalidate & redraw a raffle winner (pool shown before draw)
        //
        // Design rules (learned the hard way):
        //   - All writes are DIRECT setDoc calls to the specific Firebase
        //     docs, bypassing the merge logic. The merge is append-only /
        //     union-based and silently undoes edits to existing entries.
        //   - Tombstones use persistTombstone() with POSITIONAL args.
        //   - History entries and audit entries have different entryIds;
        //     they're matched by studentId + timestamp (exact, then ±2s).
        //   - Every correction also logs an 'Admin Correction' audit entry
        //     so the corrections themselves are auditable.
        //   - Week/cycle are NOT part of ensureEntryId's hash, so re-tagging
        //     does not change an entry's id (tombstones stay valid).
        // ============================================================

        let _correctionState = { selectedStudentId: null, redraw: null, listenersAttached: false };

        function correctionIsAdmin() {
            return currentUser && (currentUser.role === 'admin' || currentUser.role === 'superadmin');
        }

        function initCorrectionsPanel() {
            if (!correctionIsAdmin()) return;

            // Event delegation: one listener per static container, dispatching on
            // data-act attributes. Inline onclick with interpolated IDs proved
            // fragile (silent dead buttons); delegation survives re-renders and
            // doesn't depend on global scope or attribute quoting.
            if (!_correctionState.listenersAttached) {
                ['correctionStudentResults', 'correctionTicketList', 'correctionWinnerList', 'correctionRedrawPanel'].forEach(cid => {
                    const el = document.getElementById(cid);
                    if (el) el.addEventListener('click', correctionHandleClick);
                });
                _correctionState.listenersAttached = true;
            }

            correctionRenderWinnerList();
            // Clear any stale search state when re-entering
            const res = document.getElementById('correctionStudentResults');
            const list = document.getElementById('correctionTicketList');
            const search = document.getElementById('correctionStudentSearch');
            if (res && search && !search.value) res.innerHTML = '';
            if (list && search && !search.value) list.innerHTML = '';
        }

        function correctionHandleClick(ev) {
            const btn = ev.target.closest('[data-act]');
            if (!btn) return;
            const act = btn.getAttribute('data-act');
            const sid = btn.getAttribute('data-sid');
            const eid = btn.getAttribute('data-eid');
            switch (act) {
                case 'select':          correctionSelectStudent(sid); break;
                case 'edit':            correctionEditTicket(sid, eid); break;
                case 'remove':          correctionRemoveTicket(sid, eid); break;
                case 'apply-edit':      correctionApplyEdit(sid, eid); break;
                case 'apply-remove':    correctionApplyRemove(sid, eid); break;
                case 'cancel-action':   { const a = document.getElementById('correctionTicketAction'); if (a) a.innerHTML = ''; break; }
                case 'start-redraw':    correctionStartRedraw(eid); break;
                case 'build-pool':      correctionBuildPool(); break;
                case 'execute-redraw':  correctionExecuteRedraw(); break;
                case 'cancel-redraw':   { const p = document.getElementById('correctionRedrawPanel'); if (p) p.innerHTML = ''; _correctionState.redraw = null; break; }
            }
        }

        // ---------- Shared direct-write helpers ----------

        function correctionHistDocName(student) {
            const g = parseInt(student.grade);
            return (g >= 6 && g <= 8) ? 'ticket_history_ms' : 'ticket_history_hs';
        }

        // Find the audit entry matching a history entry: same student, same
        // timestamp (exact), falling back to ±2s window + category match.
        function correctionFindAuditMatch(student, histEntry) {
            const exact = auditLog.find(e =>
                e.studentId === student.id &&
                e.action === 'Awarded Tickets' &&
                e.timestamp === histEntry.timestamp
            );
            if (exact) return exact;
            const histTime = new Date(histEntry.timestamp).getTime();
            return auditLog.find(e => {
                if (e.studentId !== student.id) return false;
                if (e.action !== 'Awarded Tickets') return false;
                if (e.category !== histEntry.category) return false;
                const t = new Date(e.timestamp).getTime();
                return Math.abs(t - histTime) <= 2000;
            }) || null;
        }

        // Recompute one student's current week+cycle counters from history.
        function correctionRecomputeCounters(student) {
            const cw = (student.ticketHistory || []).filter(h =>
                h.week === currentWeek && entryBelongsToCurrentCycle(h)
            );
            student.pbisTickets = cw.filter(h => h.category === 'PBIS').reduce((s, h) => s + (h.tickets || h.amount || 0), 0);
            student.attendanceTickets = cw.filter(h => h.category === 'Attendance').reduce((s, h) => s + (h.tickets || h.amount || 0), 0);
            student.academicTickets = cw.filter(h => h.category === 'Academic' || h.category === 'Academics').reduce((s, h) => s + (h.tickets || h.amount || 0), 0);
        }

        // ---------- Tool 1: Find & Fix Tickets ----------

        function correctionSearchStudents() {
            const input = document.getElementById('correctionStudentSearch');
            const resultsEl = document.getElementById('correctionStudentResults');
            if (!input || !resultsEl) return;
            const q = input.value.trim().toLowerCase();
            if (q.length < 2) { resultsEl.innerHTML = ''; return; }

            const matches = students.filter(s =>
                `${s.firstName} ${s.lastName}`.toLowerCase().includes(q)
            ).slice(0, 8);

            if (matches.length === 0) {
                resultsEl.innerHTML = '<div style="color:#999;font-size:13px;">No students match.</div>';
                return;
            }
            resultsEl.innerHTML = matches.map(s => `
                <button data-act="select" data-sid="${s.id}"
                        style="display:inline-block;margin:4px 6px 4px 0;padding:8px 14px;background:#eef2ff;border:1px solid #c7d2fe;border-radius:8px;cursor:pointer;font-size:13px;">
                    ${escapeHtml(s.firstName)} ${escapeHtml(s.lastName)} <span style="color:#888;">(Gr ${escapeHtml(s.grade)})</span>
                </button>
            `).join('');
        }

        function correctionSelectStudent(sid) {
            _correctionState.selectedStudentId = sid;
            correctionRenderTicketList();
        }

        function correctionRenderTicketList() {
            const listEl = document.getElementById('correctionTicketList');
            const student = students.find(s => s.id === _correctionState.selectedStudentId);
            if (!listEl || !student) return;

            const hist = (student.ticketHistory || []).slice()
                .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp))
                .slice(0, 30);

            if (hist.length === 0) {
                listEl.innerHTML = `<div style="color:#999;">No ticket history for ${escapeHtml(student.firstName)} ${escapeHtml(student.lastName)}.</div>`;
                return;
            }

            const rows = hist.map(h => {
                const id = ensureEntryId(h);
                const dt = new Date(h.timestamp);
                const dateStr = isNaN(dt.getTime()) ? (h.timestamp || '?') : dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ' ' + dt.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
                return `
                    <tr style="border-bottom:1px solid #f0f0f0;">
                        <td style="padding:8px 10px;font-size:12px;color:#666;white-space:nowrap;">${dateStr}</td>
                        <td style="padding:8px 10px;font-size:12px;">${escapeHtml(h.category || '?')}</td>
                        <td style="padding:8px 10px;font-size:12px;text-align:center;">${h.tickets || h.amount || 0}</td>
                        <td style="padding:8px 10px;font-size:12px;text-align:center;">W${h.week ?? '?'} / C${h.cycle ?? '—'}</td>
                        <td style="padding:8px 10px;font-size:12px;color:#666;">${escapeHtml(h.teacher || '?')}</td>
                        <td style="padding:8px 10px;font-size:12px;color:#888;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${escapeHtml(h.reason || '')}">${escapeHtml(h.reason || '')}</td>
                        <td style="padding:8px 10px;white-space:nowrap;">
                            <button data-act="edit" data-sid="${student.id}" data-eid="${id}" style="padding:4px 10px;font-size:12px;background:#eef2ff;border:1px solid #c7d2fe;border-radius:6px;cursor:pointer;margin-right:4px;">✏️ Week/Cycle</button>
                            <button data-act="remove" data-sid="${student.id}" data-eid="${id}" style="padding:4px 10px;font-size:12px;background:#fef2f2;border:1px solid #fecaca;border-radius:6px;cursor:pointer;color:#b91c1c;">🗑️ Remove</button>
                        </td>
                    </tr>`;
            }).join('');

            listEl.innerHTML = `
                <div style="font-weight:600;margin-bottom:8px;">${escapeHtml(student.firstName)} ${escapeHtml(student.lastName)}, last ${hist.length} tickets</div>
                <div style="overflow-x:auto;max-height:380px;overflow-y:auto;border:1px solid #eee;border-radius:8px;">
                <table style="width:100%;border-collapse:collapse;background:#fafafa;border-radius:8px;">
                    <thead style="position:sticky;top:0;z-index:1;"><tr style="background:#667eea;color:white;font-size:11px;letter-spacing:0.5px;">
                        <th style="padding:8px 10px;text-align:left;">DATE</th><th style="padding:8px 10px;text-align:left;">CATEGORY</th>
                        <th style="padding:8px 10px;">QTY</th><th style="padding:8px 10px;">WK/CYC</th>
                        <th style="padding:8px 10px;text-align:left;">TEACHER</th><th style="padding:8px 10px;text-align:left;">REASON</th>
                        <th style="padding:8px 10px;"></th>
                    </tr></thead>
                    <tbody>${rows}</tbody>
                </table>
                </div>
                <div id="correctionTicketAction" style="margin-top:14px;"></div>`;
        }

        function correctionEditTicket(sid, entryId) {
            const actionEl = document.getElementById('correctionTicketAction');
            const student = students.find(s => s.id === sid);
            const entry = (student?.ticketHistory || []).find(h => ensureEntryId(h) === entryId);
            if (!actionEl || !entry) return;
            const maxWeek = cycleDuration || 5;
            actionEl.innerHTML = `
                <div style="background:#eef2ff;border:1px solid #c7d2fe;border-radius:10px;padding:16px;">
                    <div style="font-weight:600;margin-bottom:10px;">✏️ Re-tag ticket: ${escapeHtml(entry.category || '?')} on ${new Date(entry.timestamp).toLocaleDateString()}</div>
                    <label style="font-size:13px;margin-right:8px;">Week:
                        <input type="number" id="correctionNewWeek" min="1" max="${maxWeek}" value="${entry.week ?? currentWeek}" style="width:60px;padding:6px;border:1px solid #ccc;border-radius:6px;">
                    </label>
                    <label style="font-size:13px;margin-right:14px;">Cycle:
                        <input type="number" id="correctionNewCycle" min="1" max="${getCurrentCycleNumber()}" value="${entry.cycle ?? getCurrentCycleNumber()}" style="width:60px;padding:6px;border:1px solid #ccc;border-radius:6px;">
                    </label>
                    <button data-act="apply-edit" data-sid="${sid}" data-eid="${entryId}" style="padding:8px 16px;background:#667eea;color:white;border:none;border-radius:8px;cursor:pointer;font-weight:600;">Preview &amp; Apply</button>
                    <button data-act="cancel-action" style="padding:8px 12px;background:#f5f5f5;border:1px solid #ddd;border-radius:8px;cursor:pointer;margin-left:6px;">Cancel</button>
                </div>`;
            actionEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }

        async function correctionApplyEdit(sid, entryId) {
            if (!correctionIsAdmin()) { alert('Admins only.'); return; }
            const student = students.find(s => s.id === sid);
            const entry = (student?.ticketHistory || []).find(h => ensureEntryId(h) === entryId);
            if (!student || !entry) { alert('Ticket not found.'); return; }

            const newWeek = parseInt(document.getElementById('correctionNewWeek')?.value);
            const newCycle = parseInt(document.getElementById('correctionNewCycle')?.value);
            if (isNaN(newWeek) || isNaN(newCycle)) { alert('Enter valid week and cycle numbers.'); return; }
            if (newWeek === entry.week && newCycle === entry.cycle) { alert('No change, week and cycle are already those values.'); return; }

            const auditMatch = correctionFindAuditMatch(student, entry);
            const ok = await showConfirm(
                `Re-tag this ticket?\n\n` +
                `Student: ${student.firstName} ${student.lastName}\n` +
                `Ticket: ${entry.category} (${entry.tickets || entry.amount || 0}) on ${new Date(entry.timestamp).toLocaleString()}\n` +
                `From: Week ${entry.week ?? '?'} / Cycle ${entry.cycle ?? '—'}\n` +
                `To:   Week ${newWeek} / Cycle ${newCycle}\n\n` +
                `Matching audit entry: ${auditMatch ? 'found, will be updated too' : 'NOT FOUND, only history will change'}\n\n` +
                `This writes directly to the database.`
            );
            if (!ok) return;

            try {

                // 1. Direct-write the history doc
                const histDocName = correctionHistDocName(student);
                const histSnap = await readLegacyDoc(histDocName);
                const histories = histSnap.exists() ? (histSnap.data().histories || {}) : {};
                let histChanged = 0;
                histories[student.id] = (histories[student.id] || []).map(h => {
                    if (ensureEntryId(h) === entryId) { histChanged++; return { ...h, week: newWeek, cycle: newCycle }; }
                    return h;
                });
                if (histChanged === 0) { alert('⚠️ Ticket not found in Firebase history doc. Aborting (nothing written).'); return; }
                await saveLegacySlice(histDocName, 'histories', histories);

                // 2. Direct-write the matching audit entry (if found)
                if (auditMatch) {
                    const auditId = ensureEntryId(auditMatch);
                    const mk = monthKeyFromTimestamp(auditMatch.timestamp);
                    if (mk) {
                        const aSnap = await readLegacyDoc(auditDocName(mk));
                        if (aSnap.exists()) {
                            const aEntries = (aSnap.data().auditLog || []).map(e => {
                                if (ensureEntryId(e) === auditId) return { ...e, week: newWeek, cycle: newCycle };
                                return e;
                            });
                            await saveLegacySlice(auditDocName(mk), 'auditLog', aEntries);
                        }
                    }
                    // Local audit memory
                    auditMatch.week = newWeek;
                    auditMatch.cycle = newCycle;
                }

                // 3. Local history memory + counters
                entry.week = newWeek;
                entry.cycle = newCycle;
                correctionRecomputeCounters(student);

                // 4. Leave an audit trail for the correction itself
                addToAuditLog('Admin Correction', student.id, entry.category, null,
                    `Re-tagged ticket (${entry.timestamp}) to Week ${newWeek} / Cycle ${newCycle}`);

                alert(`✅ Ticket re-tagged to Week ${newWeek} / Cycle ${newCycle}.`);
                correctionRenderTicketList();
                updateAllDisplays();
            } catch (err) {
                console.error('correctionApplyEdit failed:', err);
                alert(`❌ Correction failed: ${err.message}. Nothing may have been partially written. Check the console.`);
            }
        }

        function correctionRemoveTicket(sid, entryId) {
            const actionEl = document.getElementById('correctionTicketAction');
            const student = students.find(s => s.id === sid);
            const entry = (student?.ticketHistory || []).find(h => ensureEntryId(h) === entryId);
            if (!actionEl || !entry) return;
            actionEl.innerHTML = `
                <div style="background:#fef2f2;border:1px solid #fecaca;border-radius:10px;padding:16px;">
                    <div style="font-weight:600;margin-bottom:10px;color:#b91c1c;">🗑️ Remove ticket: ${escapeHtml(entry.category || '?')} on ${new Date(entry.timestamp).toLocaleDateString()}</div>
                    <input type="text" id="correctionRemoveReason" placeholder="Reason (required: it goes in the audit trail)" style="width:100%;max-width:480px;padding:8px 12px;border:1px solid #fca5a5;border-radius:8px;font-size:13px;margin-bottom:10px;">
                    <div>
                        <button data-act="apply-remove" data-sid="${sid}" data-eid="${entryId}" style="padding:8px 16px;background:#dc2626;color:white;border:none;border-radius:8px;cursor:pointer;font-weight:600;">Preview &amp; Remove</button>
                        <button data-act="cancel-action" style="padding:8px 12px;background:#f5f5f5;border:1px solid #ddd;border-radius:8px;cursor:pointer;margin-left:6px;">Cancel</button>
                    </div>
                </div>`;
            actionEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }

        async function correctionApplyRemove(sid, entryId) {
            if (!correctionIsAdmin()) { alert('Admins only.'); return; }
            const student = students.find(s => s.id === sid);
            const entry = (student?.ticketHistory || []).find(h => ensureEntryId(h) === entryId);
            if (!student || !entry) { alert('Ticket not found.'); return; }

            const reason = (document.getElementById('correctionRemoveReason')?.value || '').trim();
            if (!reason) { alert('A reason is required. It goes in the audit trail.'); return; }

            const auditMatch = correctionFindAuditMatch(student, entry);
            const ok = await showConfirm(
                `Permanently remove this ticket?\n\n` +
                `Student: ${student.firstName} ${student.lastName}\n` +
                `Ticket: ${entry.category} (${entry.tickets || entry.amount || 0}) on ${new Date(entry.timestamp).toLocaleString()}\n` +
                `Awarded by: ${entry.teacher || '?'}\n` +
                `Reason for removal: ${reason}\n\n` +
                `Matching audit entry: ${auditMatch ? 'found, will be removed too' : 'not found'}\n\n` +
                `The ticket is tombstoned so it cannot come back from stale tabs.`
            );
            if (!ok) return;

            try {
                const who = currentUser.name || 'admin';

                // 1. Tombstones FIRST (so even if later steps fail, merges suppress the entry)
                await persistTombstone(entryId, who, `Admin correction: ${reason}`, 'ticket');
                const auditId = auditMatch ? ensureEntryId(auditMatch) : null;
                if (auditId) await persistTombstone(auditId, who, `Admin correction: ${reason}`, 'audit');

                // 2. Direct-remove from Firebase history doc
                const removalHistDoc = correctionHistDocName(student);
                const histSnap = await readLegacyDoc(removalHistDoc);
                const histories = histSnap.exists() ? (histSnap.data().histories || {}) : {};
                histories[student.id] = (histories[student.id] || []).filter(h => ensureEntryId(h) !== entryId);
                await saveLegacySlice(removalHistDoc, 'histories', histories);

                // 3. Direct-remove the audit entry (if found)
                if (auditMatch && auditId) {
                    const mk = monthKeyFromTimestamp(auditMatch.timestamp);
                    if (mk) {
                        const aSnap = await readLegacyDoc(auditDocName(mk));
                        if (aSnap.exists()) {
                            const aEntries = (aSnap.data().auditLog || []).filter(e => ensureEntryId(e) !== auditId);
                            await saveLegacySlice(auditDocName(mk), 'auditLog', aEntries);
                        }
                    }
                }

                // 4. Local memory + counters
                student.ticketHistory = (student.ticketHistory || []).filter(h => ensureEntryId(h) !== entryId);
                if (auditId) auditLog = auditLog.filter(e => ensureEntryId(e) !== auditId);
                correctionRecomputeCounters(student);

                // 5. Audit trail for the correction
                addToAuditLog('Admin Correction', student.id, entry.category, -(entry.tickets || entry.amount || 0),
                    `Removed ticket (${entry.timestamp}): ${reason}`);

                alert(`✅ Ticket removed and tombstoned.`);
                correctionRenderTicketList();
                updateAllDisplays();
            } catch (err) {
                console.error('correctionApplyRemove failed:', err);
                alert(`❌ Removal failed: ${err.message}. The tombstone may already be in place. Check the console.`);
            }
        }

        // ---------- Tool 2: Invalidate & Redraw a Winner ----------

        function correctionRenderWinnerList() {
            const listEl = document.getElementById('correctionWinnerList');
            if (!listEl) return;
            const winners = auditLog
                .filter(e => e.action === 'Raffle Winner' || e.action === 'Wildcat Jackpot Winner')
                .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp))
                .slice(0, 20);

            if (winners.length === 0) {
                listEl.innerHTML = '<div style="color:#999;">No winner records found.</div>';
                return;
            }
            listEl.innerHTML = `
                <div style="overflow-x:auto;">
                <table style="width:100%;border-collapse:collapse;background:#fafafa;border-radius:8px;">
                    <thead><tr style="background:#667eea;color:white;font-size:11px;letter-spacing:0.5px;">
                        <th style="padding:8px 10px;text-align:left;">DATE</th><th style="padding:8px 10px;text-align:left;">STUDENT</th>
                        <th style="padding:8px 10px;text-align:left;">CATEGORY</th><th style="padding:8px 10px;">WK/CYC</th>
                        <th style="padding:8px 10px;text-align:left;">DRAWN BY</th><th style="padding:8px 10px;"></th>
                    </tr></thead>
                    <tbody>${winners.map(e => {
                        const id = ensureEntryId(e);
                        return `<tr style="border-bottom:1px solid #f0f0f0;">
                            <td style="padding:8px 10px;font-size:12px;color:#666;white-space:nowrap;">${new Date(e.timestamp).toLocaleDateString()}</td>
                            <td style="padding:8px 10px;font-size:13px;font-weight:600;">${escapeHtml(e.studentName || '?')}</td>
                            <td style="padding:8px 10px;font-size:12px;">${escapeHtml(e.category || '?')}</td>
                            <td style="padding:8px 10px;font-size:12px;text-align:center;">W${e.week ?? '?'} / C${e.cycle ?? '—'}</td>
                            <td style="padding:8px 10px;font-size:12px;color:#666;">${escapeHtml(e.teacher || '?')}</td>
                            <td style="padding:8px 10px;"><button data-act="start-redraw" data-eid="${id}" style="padding:4px 10px;font-size:12px;background:#fef3c7;border:1px solid #fcd34d;border-radius:6px;cursor:pointer;">♻️ Invalidate &amp; Redraw</button></td>
                        </tr>`;
                    }).join('')}</tbody>
                </table>
                </div>`;
        }

        function correctionStartRedraw(winnerEntryId) {
            const panel = document.getElementById('correctionRedrawPanel');
            const entry = auditLog.find(e => ensureEntryId(e) === winnerEntryId);
            if (!panel || !entry) return;

            const isJackpot = entry.action === 'Wildcat Jackpot Winner';
            const cat = (entry.category || '').toLowerCase();
            const guessCategory = cat.includes('attendance') ? 'Attendance' : cat.includes('academ') ? 'Academics' : 'PBIS';
            const guessSchool = cat.includes('middle') ? 'MS' : 'HS';

            _correctionState.redraw = { winnerEntryId, isJackpot, pool: null };

            panel.innerHTML = `
                <div style="background:#fef3c7;border:1px solid #fcd34d;border-radius:10px;padding:16px;">
                    <div style="font-weight:600;margin-bottom:6px;">♻️ Invalidating: ${escapeHtml(entry.studentName || '?')}, ${escapeHtml(entry.category || '?')}</div>
                    <input type="text" id="correctionRedrawReason" placeholder="Reason for invalidating (required)" style="width:100%;max-width:480px;padding:8px 12px;border:1px solid #fcd34d;border-radius:8px;font-size:13px;margin-bottom:12px;">
                    ${isJackpot ? `
                        <div style="font-size:13px;color:#92400e;margin-bottom:10px;">
                            Jackpot redraw pool: <b>${guessSchool === 'MS' ? 'Middle School' : 'High School'}</b> students with current-cycle jackpot entries, weighted by entry count (same as the real draw).
                        </div>
                        <input type="hidden" id="correctionPoolSchool" value="${guessSchool}">
                    ` : `
                        <div style="margin-bottom:10px;">
                            <label style="font-size:13px;margin-right:10px;">Category:
                                <select id="correctionPoolCategory" style="padding:6px;border:1px solid #ccc;border-radius:6px;">
                                    <option ${guessCategory === 'PBIS' ? 'selected' : ''}>PBIS</option>
                                    <option ${guessCategory === 'Attendance' ? 'selected' : ''}>Attendance</option>
                                    <option ${guessCategory === 'Academics' ? 'selected' : ''}>Academics</option>
                                </select>
                            </label>
                            <label style="font-size:13px;margin-right:10px;">School:
                                <select id="correctionPoolSchool" style="padding:6px;border:1px solid #ccc;border-radius:6px;">
                                    <option value="MS" ${guessSchool === 'MS' ? 'selected' : ''}>Middle School</option>
                                    <option value="HS" ${guessSchool === 'HS' ? 'selected' : ''}>High School</option>
                                </select>
                            </label>
                            <label style="font-size:13px;margin-right:10px;">Week:
                                <input type="number" id="correctionPoolWeek" min="1" max="${cycleDuration || 5}" value="${entry.week ?? currentWeek}" style="width:60px;padding:6px;border:1px solid #ccc;border-radius:6px;">
                            </label>
                            <label style="font-size:13px;">Cycle:
                                <input type="number" id="correctionPoolCycle" min="1" max="${getCurrentCycleNumber()}" value="${entry.cycle ?? getCurrentCycleNumber()}" style="width:60px;padding:6px;border:1px solid #ccc;border-radius:6px;">
                            </label>
                        </div>
                    `}
                    <button data-act="build-pool" style="padding:8px 16px;background:#667eea;color:white;border:none;border-radius:8px;cursor:pointer;font-weight:600;">Build &amp; Show Pool</button>
                    <button data-act="cancel-redraw" style="padding:8px 12px;background:#f5f5f5;border:1px solid #ddd;border-radius:8px;cursor:pointer;margin-left:6px;">Cancel</button>
                    <div id="correctionPoolDisplay" style="margin-top:14px;"></div>
                </div>`;
            panel.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }

        function correctionBuildPool() {
            const state = _correctionState.redraw;
            const displayEl = document.getElementById('correctionPoolDisplay');
            if (!state || !displayEl) return;

            const school = document.getElementById('correctionPoolSchool')?.value || 'HS';
            const inSchool = (s) => {
                const g = parseInt(s.grade);
                return school === 'MS' ? (g >= 6 && g <= 8) : (g >= 9 && g <= 12);
            };

            let pool = [];
            if (state.isJackpot) {
                // Weighted: one array slot per jackpot entry, same as the real draw
                students.filter(inSchool).forEach(s => {
                    const n = computeJackpotEntries(s.id);
                    for (let i = 0; i < n; i++) pool.push(s);
                });
            } else {
                const category = document.getElementById('correctionPoolCategory')?.value || 'Attendance';
                const week = parseInt(document.getElementById('correctionPoolWeek')?.value);
                const cycle = parseInt(document.getElementById('correctionPoolCycle')?.value);
                if (isNaN(week) || isNaN(cycle)) { alert('Enter valid week and cycle.'); return; }
                const catMatch = (h) => category === 'Academics'
                    ? (h.category === 'Academics' || h.category === 'Academic')
                    : h.category === category;
                pool = students.filter(s =>
                    inSchool(s) &&
                    (s.ticketHistory || []).some(h => catMatch(h) && h.week === week && h.cycle === cycle)
                );
                state.poolParams = { category, week, cycle, school };
            }
            state.pool = pool;

            const uniqueNames = Array.from(new Set(pool.map(s => `${s.firstName} ${s.lastName} (Gr ${s.grade})`))).sort();
            displayEl.innerHTML = `
                <div style="background:white;border-radius:8px;padding:12px;border:1px solid #e5e7eb;">
                    <div style="font-weight:600;margin-bottom:6px;">Eligible pool: ${uniqueNames.length} student${uniqueNames.length === 1 ? '' : 's'}${state.isJackpot ? ` (${pool.length} weighted entries)` : ''}</div>
                    ${uniqueNames.length === 0
                        ? '<div style="color:#b91c1c;font-size:13px;">⚠️ Pool is empty. Check the parameters above. Nothing will be drawn.</div>'
                        : `<details style="font-size:12px;color:#555;"><summary style="cursor:pointer;">Show names</summary><div style="margin-top:6px;line-height:1.7;">${uniqueNames.map(escapeHtml).join('<br>')}</div></details>
                           <button data-act="execute-redraw" style="margin-top:12px;padding:10px 20px;background:#10b981;color:white;border:none;border-radius:8px;cursor:pointer;font-weight:700;">🎲 Draw New Winner</button>`
                    }
                </div>`;
        }

        async function correctionExecuteRedraw() {
            if (!correctionIsAdmin()) { alert('Admins only.'); return; }
            const state = _correctionState.redraw;
            if (!state || !state.pool || state.pool.length === 0) { alert('Build the pool first.'); return; }

            const reason = (document.getElementById('correctionRedrawReason')?.value || '').trim();
            if (!reason) { alert('A reason for invalidating is required.'); return; }

            const oldEntry = auditLog.find(e => ensureEntryId(e) === state.winnerEntryId);
            if (!oldEntry) { alert('Original winner entry no longer found.'); return; }

            const winner = state.pool[Math.floor(Math.random() * state.pool.length)];
            const ok = await showConfirm(
                `Confirm redraw:\n\n` +
                `INVALIDATE: ${oldEntry.studentName} (${oldEntry.category})\n` +
                `Reason: ${reason}\n\n` +
                `NEW WINNER: ${winner.firstName} ${winner.lastName} (Gr ${winner.grade})\n\n` +
                `OK = record this winner. Cancel = abort (you can rebuild the pool and draw again).`
            );
            if (!ok) return;

            try {
                const who = currentUser.name || 'admin';

                // 1. Tombstone the old winner entry
                await persistTombstone(state.winnerEntryId, who, `Winner invalidated: ${reason}`, 'audit');

                // 2. Direct-remove old entry from its month doc
                const oldMk = monthKeyFromTimestamp(oldEntry.timestamp);
                if (oldMk) {
                    const oSnap = await readLegacyDoc(auditDocName(oldMk));
                    if (oSnap.exists()) {
                        const oEntries = (oSnap.data().auditLog || []).filter(e => ensureEntryId(e) !== state.winnerEntryId);
                        await saveLegacySlice(auditDocName(oldMk), 'auditLog', oEntries);
                    }
                }
                auditLog = auditLog.filter(e => ensureEntryId(e) !== state.winnerEntryId);

                // 3. Build + direct-write the replacement winner entry
                const now = new Date();
                const newEntry = {
                    timestamp: now.toISOString(),
                    teacher: who,
                    teacherId: currentUser.id || '',
                    action: oldEntry.action, // Raffle Winner or Wildcat Jackpot Winner
                    studentId: winner.id,
                    studentName: `${winner.firstName} ${winner.lastName}`,
                    category: oldEntry.category,
                    ticketCount: null,
                    reason: `Replacement draw, ${reason}`,
                    week: oldEntry.week ?? currentWeek,
                    cycle: oldEntry.cycle ?? getCurrentCycleNumber()
                };
                newEntry.entryId = ensureEntryId(newEntry);

                const newMk = monthKeyFromTimestamp(newEntry.timestamp);
                const nSnap = await readLegacyDoc(auditDocName(newMk));
                const nEntries = nSnap.exists() ? (nSnap.data().auditLog || []) : [];
                if (!nEntries.some(e => ensureEntryId(e) === newEntry.entryId)) {
                    nEntries.push(newEntry);
                    nEntries.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));
                }
                await saveLegacySlice(auditDocName(newMk), 'auditLog', nEntries);
                auditLog.push(newEntry);
                auditLog.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

                alert(`🎉 New winner recorded: ${winner.firstName} ${winner.lastName} (Grade ${winner.grade})\n\nOld winner invalidated and tombstoned.`);
                _correctionState.redraw = null;
                document.getElementById('correctionRedrawPanel').innerHTML = '';
                correctionRenderWinnerList();
                updateAllDisplays();
            } catch (err) {
                console.error('correctionExecuteRedraw failed:', err);
                alert(`❌ Redraw failed: ${err.message}. Check the console, the old entry may already be tombstoned.`);
            }
        }

