        // Authentication functions
        function showCreateAdmin() {
            document.getElementById('loginScreen').classList.add('hidden');
            document.getElementById('createAdminScreen').classList.remove('hidden');
        }

        function backToLogin() {
            // #connectSchoolScreen went with the "connect to a school by id"
            // onboarding, which nothing could reach: showConnectSchool() was
            // its only opener and nothing called that. Reading .textContent off
            // the null a deleted element returns would throw here and abort the
            // rest of the function, which is how #studentLoginId broke this
            // same function on 2026-08-14.
            document.getElementById('createAdminScreen').classList.add('hidden');
            document.getElementById('loginScreen').classList.remove('hidden');
            const adminErr = document.getElementById('adminError');
            if (adminErr) adminErr.textContent = '';
        }



        function createAdminAccount() {
            const name = document.getElementById('adminName').value.trim();
            const username = document.getElementById('adminUsername').value.trim();
            const password = document.getElementById('adminPassword').value;
            const confirm = document.getElementById('adminPasswordConfirm').value;
            const errorDiv = document.getElementById('adminError');

            if (!name || !username || !password) {
                errorDiv.textContent = 'Please fill in all fields';
                return;
            }

            if (password !== confirm) {
                errorDiv.textContent = 'Passwords do not match';
                return;
            }

            if (teachers.length > 0) {
                errorDiv.textContent = 'Admin account already exists. Please login.';
                return;
            }

            teachers.push({
                id: 'T001',
                name: name,
                username: username,
                password: password,
                role: 'admin',
                ticketsAwarded: 0,
                createdDate: new Date().toISOString()
            });

            saveData();
            
            // Create cloud bin if API key is configured
            if (JSONBIN_API_KEY !== 'YOUR_API_KEY_HERE') {
                createCloudBin();
            } else {
                alert('Admin account created! Please login.\n\n⚠️ Note: Cloud sync is not configured. Data will only be saved on this device.\n\nTo enable multi-device sync, follow the setup instructions.');
            }
            
            // Hide create admin button now that admin exists
            const createAdminSection = document.getElementById('createAdminSection');
            if (createAdminSection) {
                createAdminSection.style.display = 'none';
            }
            
            backToLogin();
        }

        function getFriendlyRoleName(role) {
            const roleNames = {
                'teacher': 'Teacher',
                'campusaide': 'Campus Aide',
                'pbis': 'PBIS Team',
                'admin': 'Admin',
                'superadmin': 'Super Admin'
            };
            return roleNames[role] || role;
        }

        async function login() {
            const username = document.getElementById('loginUsername').value.trim();
            const password = document.getElementById('loginPassword').value;
            const errorDiv = document.getElementById('loginError');

            if (!username || !password) {
                errorDiv.textContent = 'Please enter username and password';
                return;
            }

            const teacher = teachers.find(t => t.username === username && t.password === password);

            if (!teacher) {
                errorDiv.textContent = 'Invalid username or password';
                return;
            }

            return establishTeacherSession(teacher);
        }

        /**
         * Everything that happens AFTER a teacher has been authenticated.
         * Extracted from login() so Entra sign-in and the legacy password
         * form share one session path instead of two that drift apart.
         * Callers must have already proven identity.
         *
         * Wrapped so the full-screen loader covers the whole handoff: the core
         * awaits saveData() BEFORE it hides the login screen, and that gap is
         * exactly the "login screen flashes back with a Saving… pill" the owner
         * reported. The overlay sits over it and lifts in the finally, when
         * mainApp is on screen and drawn, success or error, the loader always
         * comes down.
         */
        async function establishTeacherSession(teacher) {
            // Held for the app-wide 4s default so login reads as a deliberate
            // handoff rather than a flash.
            if (typeof showLoader === 'function') showLoader('Signing you in…');
            try {
                return await establishTeacherSessionCore(teacher);
            } finally {
                if (typeof hideLoader === 'function') hideLoader();
            }
        }

        async function establishTeacherSessionCore(teacher) {
            currentUser = teacher;
            
            // Track login activity
            const loginRecord = {
                id: 'login_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
                userId: teacher.id,
                username: teacher.username,
                name: teacher.name,
                role: teacher.role,
                timestamp: new Date().toISOString(),
                userAgent: navigator.userAgent,
                platform: navigator.platform
            };
            
            // Add login record to history
            loginHistory.push(loginRecord);
            
            // Keep only last 500 login records
            if (loginHistory.length > 500) {
                loginHistory = loginHistory.slice(-500);
            }
            
            saveSession(); // Save session for auto-login
            
            // Save login - saveData() now intelligently merges with Firebase to prevent data loss
            await saveData();
            
            document.getElementById('loginScreen').classList.add('hidden');
            document.getElementById('createAdminScreen').classList.add('hidden');
            document.getElementById('mainApp').classList.remove('hidden');
            
            document.getElementById('currentUserName').textContent = teacher.name;
            document.getElementById('currentUserRole').textContent = getFriendlyRoleName(teacher.role);
            
            // THE MODE IS NOT DECIDED HERE ANY MORE.
            //
            // This block forced teacher, campus aide, PBIS and admin into
            // Raffle and hid Claw Pass and Discipline outright. Two things
            // were wrong with it. Raffle is not what the school launches on --
            // most staff cannot even open it now -- and initSidebarShell
            // restored the person's saved mode a few milliseconds later
            // anyway, so this was overruled on every sign-in while still
            // costing a flash of the wrong screen.
            //
            // wildcat-modes.js owns which modes a role may open, and
            // switchSystemMode owns the DOM that goes with each one. Doing it
            // in one place is what stops the two disagreeing.
            if (typeof switchSystemMode === 'function') {
                switchSystemMode(getSavedTeacherMode() || allowedModeOrDefault());
            }
            
            // Show/hide tabs based on role
            const adminTabs = document.querySelectorAll('.admin-only');
            const superAdminTabs = document.querySelectorAll('.super-admin-only');
            
            if (teacher.role === 'teacher' || teacher.role === 'campusaide' || teacher.role === 'pbis') {
                // Teachers and Campus Aides only see basic tabs
                adminTabs.forEach(tab => tab.classList.add('disabled'));
                superAdminTabs.forEach(tab => tab.classList.add('disabled'));
                
                // Hide week controls for teachers and campus aides
                const weekControls = document.getElementById('weekControls');
                if (weekControls) weekControls.style.display = 'none';
                // No switchTab here: switchSystemMode above already opened the
                // landing screen for whichever mode this person gets. Naming a
                // tab now would drag them out of it.
            } else if (teacher.role === 'admin') {
                // Admins see admin tabs but not super admin tabs
                adminTabs.forEach(tab => tab.classList.remove('disabled'));
                superAdminTabs.forEach(tab => tab.classList.add('disabled'));
                
                // Show week controls for admins
                const weekControls = document.getElementById('weekControls');
                if (weekControls) weekControls.style.display = 'flex';
                // Landing screen already chosen by switchSystemMode above.
            } else if (teacher.role === 'superadmin') {
                // Super admins see everything
                adminTabs.forEach(tab => tab.classList.remove('disabled'));
                superAdminTabs.forEach(tab => tab.classList.remove('disabled'));
                
                // Show week controls for super admins
                const weekControls = document.getElementById('weekControls');
                if (weekControls) weekControls.style.display = 'flex';
                
                // Mode already restored by switchSystemMode at the top of this
                // function, from the PER-USER preference. This branch read the
                // shared `systemMode` key and re-applied the body classes by
                // hand -- a second, divergent copy of what switchSystemMode
                // does, keyed on storage that every account on a shared
                // Chromebook writes to. On a shared machine that handed a
                // superadmin whatever mode the last person left behind.

            }

            updateAllDisplays();
            if (teacher.role === 'superadmin' || teacher.role === 'admin') {
                updateSuperAdminList();
            }
            
            // AUTO-WEEK RESET DISABLED - Check removed to prevent accidental ticket deletion
            // checkAndRunAutoWeekReset();
        }

        async function logout() {
            // The next person on this Chromebook starts where their role starts,
            // not where the last one left off.
            wcForgetTab();
            if (await showConfirm('Are you sure you want to logout?')) {
                currentUser = null;
                currentStudent = null;
                clearSession(); // Clear saved session
                _sidebarModeApplied = false; // next login re-runs mode-first logic
                if (typeof wcStopPassAlertPolling === 'function') wcStopPassAlertPolling();
                document.body.classList.remove('sidebar-open', 'sidebar-collapsed');
                
                // Drop the federated session too. Without this a teacher could
                // "log out", leave the Chromebook, and leave a Microsoft
                // account cached in storage for whoever sat down next.
                if (window.WildcatAuth && window.WildcatAuth.signOut) {
                    try { window.WildcatAuth.signOut(); } catch (e) { /* still log out locally */ }
                }

                document.getElementById('mainApp').classList.add('hidden');
                document.getElementById('studentApp').classList.add('hidden');
                document.getElementById('loginScreen').classList.remove('hidden');
                document.getElementById('loginUsername').value = '';
                document.getElementById('loginPassword').value = '';
                // #studentLoginId was removed with the name lookup on
                // 2026-08-14. Reading .value off null threw here, which meant
                // the two lines below and showTeacherLogin() never ran: a
                // teacher logging out was left on whatever tab was last
                // selected, with stale error text still on it.
                document.getElementById('loginError').textContent = '';
                const studentErr = document.getElementById('studentLoginError');
                if (studentErr) studentErr.textContent = '';
                showStudentLogin(); // Default to the student (Google) tab, never Microsoft
            }
        }

        function addToAuditLog(action, studentId, category, ticketCount, reason, periodInfo = null, weekOverride = null) {
            const student = students.find(s => s.id === studentId);
            // weekOverride lets callers (e.g. the Perfect Attendance upload, which awards
            // tickets for a specific past week) tag the audit entry with the SAME week as
            // the matching ticket-history entry. Without it, the audit entry would use
            // currentWeek and silently disagree with the history entry, the exact bug that
            // caused attendance raffle pools to come up empty. When null, defaults to currentWeek.
            const effectiveWeek = (typeof weekOverride === 'number' && !isNaN(weekOverride))
                ? weekOverride
                : currentWeek;
            const logEntry = {
                // MINTED AT BIRTH, not derived at save time.
                //
                // ensureEntryId hashes the entry's contents into 32 bits. That
                // is stable, which is what it was for, but it is only ~2.1
                // billion values and the birthday bound is what matters for a
                // dedupe key: at ~50,000 entries a year the chance that some
                // pair of DIFFERENT entries collides is better than even, and a
                // collision means the second is treated as a duplicate and
                // dropped. A cash award that happened, with no record that it
                // did. Legacy entries keep their hashed ids -- see wildcat-audit.js.
                entryId: window.WildcatAudit.newAuditEntryId(),
                timestamp: new Date().toISOString(),
                teacher: currentUser.name,
                teacherId: currentUser.id,
                action: action,
                studentId: studentId,
                studentName: student ? `${student.firstName} ${student.lastName}` : 'Unknown',
                category: category,
                ticketCount: ticketCount,
                reason: reason,
                week: effectiveWeek,          // Week within the current cycle (1-5)
                cycle: getCurrentCycleNumber() // Which cycle this entry belongs to
            };
            
            // Add period info if provided
            if (periodInfo) {
                logEntry.period = periodInfo.period;
                logEntry.courseName = periodInfo.courseName;
            }
            
            auditLog.push(logEntry);
            
            // OUTBOX: persist to localStorage immediately so a failed save
            // doesn't lose this entry. Cleared after successful audit-log save.
            try {
                enqueueAuditOutbox(logEntry);
            } catch (e) {
                console.warn('Outbox enqueue failed (non-fatal):', e);
            }
            
            // NOTE: saveData() is called by the parent function, not here
            // This prevents race conditions when awarding to multiple students
        }

        // Track current audit log filter
        let currentAuditSubtab = 'all';
        
        function switchAuditSubtab(subtab) {
            // Update button states
            document.querySelectorAll('.subtab-button').forEach(btn => {
                if (btn.id && btn.id.includes('Audit')) {
                    btn.classList.remove('active');
                }
            });
            
            const activeBtn = document.getElementById(`${subtab}AuditSubtab`);
            if (activeBtn) {
                activeBtn.classList.add('active');
            }
            
            currentAuditSubtab = subtab;
            updateAuditLogTable();
        }

        function updateAuditLogTable(keepPage) {
            const tbody = document.getElementById('auditLogTable');
            
            // Filter to only show RAFFLE MODE transactions
            let raffleAuditLog = auditLog.filter(log => {
                // Only include raffle-related actions
                const raffleActions = ['Awarded Tickets', 'Removed Tickets', 'Raffle Winner', 
                                      'Weekly Raffle Winner', 'Wildcat Jackpot Winner', 
                                      'Reset Wildcat Jackpot Cycle', '↩️ UNDID Award'];
                return raffleActions.includes(log.action);
            });
            
            // Filter by school level if not showing all
            if (currentAuditSubtab !== 'all') {
                raffleAuditLog = raffleAuditLog.filter(log => {
                    // Find the student to check their grade
                    const student = students.find(s => s.id === log.studentId);
                    if (!student) return false; // Skip if student not found
                    
                    const grade = parseInt(student.grade);
                    
                    if (currentAuditSubtab === 'middleschool') {
                        return grade >= 6 && grade <= 8;
                    } else if (currentAuditSubtab === 'highschool') {
                        return grade >= 9 && grade <= 12;
                    }
                    
                    return true;
                });
            }
            
            // Search narrows the DATA before the empty check and the paging, so
            // it searches every entry, not the rows currently on screen. Matches
            // student, teacher, category and action, the way the old row-text
            // filter did, minus the fight with pagination.
            const auditSearch = (document.getElementById('searchAudit')?.value || '').toLowerCase().trim();
            if (auditSearch) {
                raffleAuditLog = raffleAuditLog.filter(log => {
                    const hay = [log.studentName, log.teacher, log.category, log.action, log.reason, log.studentId]
                        .map(v => String(v || '').toLowerCase()).join(' ');
                    return hay.includes(auditSearch);
                });
            }

            if (raffleAuditLog.length === 0) {
                const schoolText = currentAuditSubtab === 'middleschool' ? 'Middle School' :
                                  currentAuditSubtab === 'highschool' ? 'High School' : '';
                const msg = auditSearch ? 'No activity matches your search' : `No ${schoolText} activity logged yet`;
                tbody.innerHTML = `<tr><td colspan="8" style="text-align: center; padding: 40px; color: #999;">${msg}</td></tr>`;
                renderPager('audit', 'auditLogTable', { pages: 1 });
                return;
            }

            // Show most recent first, then page the sorted, searched set.
            const sorted = [...raffleAuditLog].reverse();
            const isAdmin = currentUser && (currentUser.role === 'admin' || currentUser.role === 'superadmin');
            const auditView = paginate('audit', sorted, keepPage);
            renderPager('audit', 'auditLogTable', auditView);

            tbody.innerHTML = auditView.slice.map((log, index) => {
                const date = new Date(log.timestamp);
                const formattedDate = date.toLocaleDateString() + ' ' + date.toLocaleTimeString();
                // Find the actual index in the full auditLog array by matching multiple fields for uniqueness
                const originalIndex = auditLog.findIndex(e => 
                    e.timestamp === log.timestamp && 
                    e.studentId === log.studentId && 
                    e.ticketCount === log.ticketCount &&
                    e.teacher === log.teacher &&
                    e.action === log.action &&
                    e.category === log.category
                );
                
                // Action styling.
                //
                // Seven actions, seven multi-stop gradients: indigo-to-violet,
                // amber, pink-to-red, gold-to-navy, a three-stop pink, cyan,
                // and a mint-to-blush with dark text on it. Plus a gradient
                // wash down each row and a pink gradient on Delete. The colour
                // was doing the categorising, and there were more colours than
                // categories are worth.
                //
                // Three states is what the log actually has: something was
                // given, something was taken away, and something the system
                // did. The icon square carries the category; the chip carries
                // the word; the row stays quiet.
                let chipClass = '';
                let iconClass = '';
                let rowClass = 'wc-row';
                let actionIcon = '';

                if (log.action === 'Awarded Tickets') {
                    chipClass = ''; iconClass = ''; actionIcon = '&#127915;';
                } else if (log.action === '↩️ UNDID Award') {
                    chipClass = 'wu-chip-warn'; iconClass = 'wu-tl-icon-warn'; actionIcon = '&#8630;';
                    rowClass = 'wc-row wc-row-flag';
                } else if (log.action === 'Removed Tickets') {
                    chipClass = 'wu-chip-bad'; iconClass = 'wu-tl-icon-bad'; actionIcon = '&#10005;';
                    rowClass = 'wc-row wc-row-flag';
                } else if (log.action === 'Raffle Winner' || log.action === 'Weekly Raffle Winner'
                        || log.action === 'Wildcat Jackpot Winner') {
                    chipClass = 'wu-chip-good'; iconClass = 'wu-tl-icon-good'; actionIcon = '&#127942;';
                } else if (log.action === 'Reset Wildcat Jackpot Cycle') {
                    chipClass = ''; iconClass = ''; actionIcon = '&#128260;';
                } else {
                    chipClass = ''; iconClass = ''; actionIcon = '&#128221;';
                }

                // A dash is not a fact. An award with no category recorded and
                // an award of zero tickets are different things from an award
                // whose category simply is not applicable, and the log cannot
                // tell them apart, so it says "not recorded" rather than
                // printing a hyphen that reads as data.
                const absent = (what) => `<span class="wu-absent">${what}</span>`;

                return `
                    <tr class="${rowClass}">
                        <td class="cell-muted wc-audit-when">${formattedDate}</td>
                        <td class="cell-muted">${escapeHtml(log.teacher || '')}</td>
                        <td>
                            <span class="wc-audit-action">
                                <span class="wu-tl-icon ${iconClass}" aria-hidden="true">${actionIcon}</span>
                                <span class="wu-chip ${chipClass}">${escapeHtml(
                                    // The stored action for an undo is literally
                                    // "↩️ UNDID Award". The icon square already
                                    // carries that arrow, so the chip drops it
                                    // rather than showing it twice. The stored
                                    // value is untouched.
                                    String(log.action || '').replace(WC_LEAD_EMOJI, ''))}</span>
                            </span>
                        </td>
                        <td class="wc-name">${escapeHtml(log.studentName || '')}</td>
                        <td>${log.category ? `<span class="wu-chip">${escapeHtml(log.category)}</span>` : absent('none')}</td>
                        <td class="wc-money">${(log.ticketCount === null || log.ticketCount === undefined || log.ticketCount === '')
                            ? absent('n/a') : escapeHtml(String(log.ticketCount))}</td>
                        <td class="cell-muted wc-audit-reason">${log.reason ? escapeHtml(log.reason) : absent('none given')}</td>
                        <td>
                            ${isAdmin && log.action === 'Awarded Tickets'
                                ? `<button class="wu-btn wc-btn-sm wc-btn-risk audit-delete-btn"
                                         data-timestamp="${log.timestamp}"
                                         data-student-id="${log.studentId}"
                                         data-ticket-count="${log.ticketCount}"
                                         data-teacher="${escapeHtml(log.teacher || '')}"
                                         data-action="${escapeHtml(log.action)}"
                                         data-category="${escapeHtml(log.category || '')}">Delete</button>`
                                : ''}
                        </td>
                    </tr>
                `;
            }).join('');
            
            // Add event listeners to delete buttons
            setTimeout(() => {
                document.querySelectorAll('.audit-delete-btn').forEach(btn => {
                    btn.onclick = async function() {
                        const timestamp = this.getAttribute('data-timestamp');
                        const studentId = this.getAttribute('data-student-id');
                        const ticketCount = this.getAttribute('data-ticket-count');
                        const teacher = this.getAttribute('data-teacher');
                        const action = this.getAttribute('data-action');
                        const category = this.getAttribute('data-category');
                        
                        // Find the exact entry
                        const entryIndex = auditLog.findIndex(e => 
                            e.timestamp === timestamp &&
                            e.studentId === studentId &&
                            e.ticketCount === parseInt(ticketCount) &&
                            e.teacher === teacher &&
                            e.action === action &&
                            e.category === category
                        );
                        
                        if (entryIndex !== -1) {
                            await deleteTicketEntry(entryIndex);
                        } else {
                            alert('Error: Could not find audit entry to delete');
                        }
                    };
                });
            }, 0);
        }
        
        // Login Activity Functions
        function updateLoginActivityTable(keepPage) {
            const tbody = document.getElementById('loginActivityTableBody');
            const searchUser = document.getElementById('loginSearchUser')?.value.toLowerCase() || '';
            const filterRole = document.getElementById('loginFilterRole')?.value || '';
            const dateRange = document.getElementById('loginDateRange')?.value || 'all';
            
            if (!tbody) return;
            
            // Filter logins
            let filteredLogins = loginHistory.filter(login => {
                // Search filter
                if (searchUser && !login.name.toLowerCase().includes(searchUser) && !login.username.toLowerCase().includes(searchUser)) {
                    return false;
                }
                
                // Role filter
                if (filterRole && login.role !== filterRole) {
                    return false;
                }
                
                // Date range filter
                if (dateRange !== 'all') {
                    const loginDate = new Date(login.timestamp);
                    const now = new Date();
                    const diffTime = now - loginDate;
                    const diffDays = diffTime / (1000 * 60 * 60 * 24);
                    
                    if (dateRange === 'today' && diffDays > 1) return false;
                    if (dateRange === 'week' && diffDays > 7) return false;
                    if (dateRange === 'month' && diffDays > 30) return false;
                }
                
                return true;
            });
            
            // Sort by most recent first
            filteredLogins.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
            
            // Update stats
            updateLoginStats(filteredLogins);
            
            // Render table
            if (filteredLogins.length === 0) {
                tbody.innerHTML = '<tr><td colspan="5" style="padding: 40px; text-align: center; color: #999;">No login activity found</td></tr>';
                renderPager('login', 'loginActivityTableBody', { pages: 1 });
                return;
            }

            // Stats above use the full filtered set; only the rows are paged.
            const loginView = paginate('login', filteredLogins, keepPage);
            renderPager('login', 'loginActivityTableBody', loginView);

            tbody.innerHTML = loginView.slice.map(login => {
                const date = new Date(login.timestamp);
                const formattedDate = date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
                const formattedTime = date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
                
                // Role badge styling
                let roleColor = '#6c757d';
                let roleIcon = '👤';
                if (login.role === 'superadmin') {
                    roleColor = '#B3392F';
                    roleIcon = '👑';
                } else if (login.role === 'admin') {
                    roleColor = '#667eea';
                    roleIcon = '⭐';
                } else if (login.role === 'campusaide') {
                    roleColor = '#2E7D52';
                    roleIcon = '👁️';
                } else if (login.role === 'teacher') {
                    roleColor = '#28a745';
                    roleIcon = '👤';
                }
                
                // Simplify platform display
                let platform = 'Unknown';
                if (login.platform) {
                    if (login.platform.includes('Win')) platform = '💻 Windows';
                    else if (login.platform.includes('Mac')) platform = '🍎 Mac';
                    else if (login.platform.includes('Linux')) platform = '🐧 Linux';
                    else if (login.platform.includes('iPhone') || login.platform.includes('iPad')) platform = '📱 iOS';
                    else if (login.platform.includes('Android')) platform = '📱 Android';
                    else platform = login.platform;
                }
                
                return `
                    <tr style="border-bottom: 1px solid #e9ecef;">
                        <td style="padding: 12px; color: #495057;">
                            <div style="font-weight: 600;">${formattedDate}</div>
                            <div style="font-size: 12px; color: #6c757d;">${formattedTime}</div>
                        </td>
                        <td style="padding: 12px; color: #495057; font-weight: 600;">${login.name}</td>
                        <td style="padding: 12px; color: #6c757d;">${login.username}</td>
                        <td style="padding: 12px;">
                            <span style="background: ${roleColor}; color: white; padding: 4px 12px; border-radius: 12px; font-size: 12px; font-weight: 600;">
                                ${roleIcon} ${getFriendlyRoleName(login.role)}
                            </span>
                        </td>
                        <td style="padding: 12px; color: #6c757d;">${platform}</td>
                    </tr>
                `;
            }).join('');
        }
        
        function updateLoginStats(filteredLogins = loginHistory) {
            // Total logins
            document.getElementById('totalLoginsCount').textContent = filteredLogins.length;
            
            // Unique users
            const uniqueUsers = new Set(filteredLogins.map(l => l.userId));
            document.getElementById('uniqueUsersCount').textContent = uniqueUsers.size;
            
            // Logins today
            const today = new Date();
            today.setHours(0, 0, 0, 0);
            const todayLogins = filteredLogins.filter(l => new Date(l.timestamp) >= today);
            document.getElementById('todayLoginsCount').textContent = todayLogins.length;
        }
        
        function exportLoginActivity() {
            if (loginHistory.length === 0) {
                alert('No login activity to export');
                return;
            }
            
            // Create CSV content
            const headers = ['Date', 'Time', 'User Name', 'Username', 'Role', 'Platform'];
            const rows = loginHistory.map(login => {
                const date = new Date(login.timestamp);
                const formattedDate = date.toLocaleDateString('en-US');
                const formattedTime = date.toLocaleTimeString('en-US');
                
                return [
                    formattedDate,
                    formattedTime,
                    login.name,
                    login.username,
                    getFriendlyRoleName(login.role),
                    login.platform || 'Unknown'
                ];
            });
            
            const csvContent = [
                headers.join(','),
                ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
            ].join('\n');
            
            // Download CSV
            const blob = new Blob([csvContent], { type: 'text/csv' });
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `login-activity-${new Date().toISOString().split('T')[0]}.csv`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            window.URL.revokeObjectURL(url);
            
            alert('✅ Login activity exported successfully!');
        }
        
        async function deleteTicketEntry(logIndex) {
            if (currentUser.role !== 'admin' && currentUser.role !== 'superadmin') {
                alert('Only admins can delete ticket entries');
                return;
            }
            
            const entry = auditLog[logIndex];
            
            if (!entry) {
                alert('Entry not found');
                return;
            }
            
            // Confirm deletion
            if (!await showConfirm(`⚠️ DELETE TICKET ENTRY?\n\n` +
                        `Teacher: ${entry.teacher}\n` +
                        `Student: ${entry.studentName}\n` +
                        `Category: ${entry.category}\n` +
                        `Tickets: ${entry.ticketCount}\n` +
                        `Reason: ${entry.reason}\n\n` +
                        `This will:\n` +
                        `• Remove ${entry.ticketCount} ticket(s) from the student\n` +
                        `• Delete this audit log entry\n` +
                        `• Cannot be undone\n\n` +
                        `Continue?`)) {
                return;
            }
            
            // Find the student
            const student = students.find(s => s.id === entry.studentId);
            
            if (!student) {
                alert('Student not found. The audit entry will be deleted, but tickets cannot be reversed.');
            } else {
                const ticketCount = parseInt(entry.ticketCount) || 0;
                
                // Remove from student's ticket history
                // NOTE: Audit log and ticket history entries are created at slightly different
                // moments, so timestamps usually don't match exactly. Match on category + amount
                // + teacher + reason, then use the closest timestamp within a 30-second window.
                if (student.ticketHistory) {
                    const beforeLength = student.ticketHistory.length;
                    const entryTs = new Date(entry.timestamp).getTime();
                    const WINDOW_MS = 30000; // 30 seconds

                    // Strip subcategory prefix from audit reason if present (e.g. "Being Present: test" -> "test")
                    const auditReasonParts = String(entry.reason || '').split(':');
                    const auditReasonCore = auditReasonParts.length > 1
                        ? auditReasonParts.slice(1).join(':').trim()
                        : String(entry.reason || '').trim();

                    // Candidate matches: same category, same amount, timestamp within window
                    const candidates = student.ticketHistory
                        .map((h, idx) => ({ h, idx, dt: Math.abs(new Date(h.timestamp).getTime() - entryTs) }))
                        .filter(({ h, dt }) => {
                            const historyAmount = h.tickets || h.amount || 0;
                            const historyCategory = h.category || '';
                            const historyCategoryNorm = historyCategory === 'Academics' ? 'Academic' : historyCategory;
                            const entryCategoryNorm = entry.category === 'Academics' ? 'Academic' : entry.category;
                            if (historyAmount !== ticketCount) return false;
                            if (historyCategoryNorm !== entryCategoryNorm) return false;
                            if (dt > WINDOW_MS) return false;
                            // Teacher must match if both have one
                            if (h.teacher && entry.teacher && h.teacher !== entry.teacher) return false;
                            // Reason should match (compare core reason without subcategory prefix)
                            const hReason = String(h.reason || '').trim();
                            if (hReason && auditReasonCore && hReason !== auditReasonCore && hReason !== entry.reason) return false;
                            return true;
                        })
                        .sort((a, b) => a.dt - b.dt); // Closest timestamp first

                    // Take the single closest match (the audit entry describes ONE award, not many)
                    const toRemoveIdx = candidates.length > 0 ? candidates[0].idx : -1;
                    const toRemove = toRemoveIdx >= 0 ? [student.ticketHistory[toRemoveIdx]] : [];

                    for (const h of toRemove) {
                        const tid = ensureEntryId(h);
                        await persistTombstone(tid, currentUser.name || 'admin', `Deleted via audit log: ${h.reason || ''}`, 'ticket');
                    }

                    if (toRemoveIdx >= 0) {
                        student.ticketHistory.splice(toRemoveIdx, 1);
                    }

                    const removed = beforeLength - student.ticketHistory.length;
                    console.log(`Removed ${removed} ticket(s) from ${student.firstName}'s history`);
                    if (removed === 0) {
                        console.warn(`⚠️ Could not find matching ticket history entry for audit entry`, entry);
                    }
                    
                    // Recalculate current week tickets from ticket history
                    const currentWeekHistory = student.ticketHistory.filter(h => h.week === currentWeek);
                    student.pbisTickets = currentWeekHistory.filter(h => h.category === 'PBIS').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                    student.attendanceTickets = currentWeekHistory.filter(h => h.category === 'Attendance').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                    student.academicTickets = currentWeekHistory.filter(h => h.category === 'Academic' || h.category === 'Academics').reduce((sum, h) => sum + (h.tickets || h.amount || 0), 0);
                }
            }
            
            // Tombstone the audit log entry so deletion survives the merge
            const auditEntryId = ensureEntryId(entry);
            await persistTombstone(auditEntryId, currentUser.name || 'admin', `Deleted audit entry: ${entry.action} - ${entry.reason || ''}`, 'audit');
            
            // Remove from local audit log
            auditLog.splice(logIndex, 1);
            
            // Add deletion record to audit log (this is a NEW entry, not tombstoned)
            auditLog.push({
                timestamp: new Date().toISOString(),
                teacher: currentUser.name,
                teacherId: currentUser.id,
                action: 'Deleted Ticket Entry',
                studentId: entry.studentId,
                studentName: entry.studentName,
                category: entry.category,
                ticketCount: entry.ticketCount,
                reason: `Deleted entry by ${entry.teacher} - Original reason: ${entry.reason}`
            });
            
            await saveData();
            updateAllDisplays();
            
            alert(`✅ Ticket entry deleted!\n\n` +
                  `${entry.ticketCount} ticket(s) removed from ${entry.studentName}\n` +
                  `Audit log updated.`);
        }

        function searchAuditLog() {
            // Data-path re-render: search the whole log (all pages), reset to
            // page 1. updateAuditLogTable reads #searchAudit itself.
            updateAuditLogTable();
        }

        function updateCashAuditLogTable(keepPage) {
            const tbody = document.getElementById('cashAuditLogTable');

            // Filter to only show CASH MODE transactions from auditLog
            let cashAuditLog = auditLog.filter(log => {
                // Only include cash-related actions
                const cashActions = ['cash_award', 'cash_deduct', 'reward_redemption', 'reset_all_student_cash'];
                return cashActions.includes(log.action);
            });

            // Search the whole log (all pages), not the rendered rows.
            const cashAuditSearch = (document.getElementById('searchCashAudit')?.value || '').toLowerCase().trim();
            if (cashAuditSearch) {
                cashAuditLog = cashAuditLog.filter(log => {
                    const hay = [log.details, log.teacher, log.studentId, log.action]
                        .map(v => String(v || '').toLowerCase()).join(' ');
                    return hay.includes(cashAuditSearch);
                });
            }

            if (cashAuditLog.length === 0) {
                const msg = cashAuditSearch ? 'No cash activity matches your search' : 'No cash activity logged yet';
                tbody.innerHTML = `<tr><td colspan="7" style="text-align: center; padding: 40px; color: #999;">${msg}</td></tr>`;
                renderPager('cashAudit', 'cashAuditLogTable', { pages: 1 });
                return;
            }

            // Show most recent first, then page the sorted, searched set.
            const sorted = [...cashAuditLog].reverse();
            const cashAuditView = paginate('cashAudit', sorted, keepPage);
            renderPager('cashAudit', 'cashAuditLogTable', cashAuditView);

            tbody.innerHTML = cashAuditView.slice.map(log => {
                const date = new Date(log.timestamp);
                const formattedDate = date.toLocaleDateString() + ' ' + date.toLocaleTimeString();
                
                // Determine styling based on action
                let actionClass = '';
                let actionIcon = '';
                let actionText = '';

                // Action styling is carried by classes (.cash-audit-row and
                // .cash-action-badge in styles.css) instead of inline CSS.
                //
                // Every one of these rows previously set
                //   background: var(--wc-blue), transparent);
                // which is not valid CSS. The unbalanced parenthesis came
                // from a find and replace that swapped a linear-gradient()
                // colour for the token but left the gradient's arguments
                // behind. Browsers dropped the whole declaration, so no row
                // has had its intended tint. The same replace also flattened
                // two badge colours to blue while their border-left kept the
                // original colour; the badges are restored to match.
                if (log.action === 'cash_award') {
                    actionClass = 'act-award';
                    actionIcon = '💰';
                    actionText = 'Cash Awarded';
                } else if (log.action === 'cash_deduct') {
                    actionClass = 'act-deduct';
                    actionIcon = '⚠️';
                    actionText = 'Cash Deducted';
                } else if (log.action === 'reward_redemption') {
                    actionClass = 'act-redeem';
                    actionIcon = '🎁';
                    actionText = 'Reward Redeemed';
                } else if (log.action === 'reset_all_student_cash') {
                    actionClass = 'act-reset';
                    actionIcon = '🔄';
                    actionText = 'System Reset';
                } else {
                    actionClass = 'act-other';
                    actionIcon = '📝';
                    actionText = log.action;
                }
                
                // Get student name safely
                const studentName = log.details && log.details.includes(' ') ? 
                    log.details.split(' ')[0] + ' ' + log.details.split(' ')[1] : 
                    (log.studentId ? `Student #${log.studentId}` : 'Unknown');
                
                // Parse amount and behavior from details
                let behaviorName = '-';
                let amount = '-';
                
                if (log.details) {
                    // Try to extract behavior name and amount
                    const detailMatch = log.details.match(/(.+?) (?:awarded|deducted|redeemed) (.+?) for \$(\d+)/);
                    if (detailMatch) {
                        behaviorName = detailMatch[2];
                        amount = log.action === 'cash_deduct' ? `-$${detailMatch[3]}` : `+$${detailMatch[3]}`;
                    } else if (log.details.includes('$')) {
                        // Try to extract just the amount
                        const amountMatch = log.details.match(/\$(\d+)/);
                        if (amountMatch) {
                            amount = log.action === 'cash_deduct' ? `-$${amountMatch[1]}` : `+$${amountMatch[1]}`;
                        }
                    }
                }
                
                return `
                    <tr class="cash-audit-row ${actionClass}">
                        <td style="padding: 12px 8px;">
                            <span style="font-size: 13px; color: #666;">${formattedDate}</span>
                        </td>
                        <td style="padding: 12px 8px;">
                            <span class="teacher-badge" style="background: #e3f2fd; color: #1976d2; padding: 4px 10px; border-radius: 12px; font-size: 13px; font-weight: 500;">${escapeHtml(log.teacherName || 'System')}</span>
                        </td>
                        <td style="padding: 12px 8px;">
                            <span class="cash-action-badge ${actionClass}">
                                ${actionIcon} ${escapeHtml(actionText)}
                            </span>
                        </td>
                        <td style="padding: 12px 8px; font-weight: 500;">${studentName}</td>
                        <td style="padding: 12px 8px;">
                            <span style="background: #f5f5f5; padding: 4px 8px; border-radius: 8px; font-size: 12px;">${behaviorName}</span>
                        </td>
                        <td style="padding: 12px 8px; text-align: center;">
                            <span style="font-weight: 700; font-size: 16px; color: ${log.action === 'cash_deduct' ? '#B3392F' : '#2E7D52'};">${amount}</span>
                        </td>
                        <td style="padding: 12px 8px; max-width: 250px;">
                            <span style="font-size: 13px; color: #555;">${log.details || '-'}</span>
                        </td>
                    </tr>
                `;
            }).join('');
        }

        function searchCashAuditLog() {
            // Data-path re-render: search all pages, reset to page 1.
            updateCashAuditLogTable();
        }


        let editingTeacherId = null;
        
        function editTeacher(teacherId) {
            const teacher = teachers.find(t => t.id === teacherId);
            if (!teacher) {
                alert('Teacher not found');
                return;
            }
            
            editingTeacherId = teacherId;
            
            // Populate form
            document.getElementById('editTeacherName').value = teacher.name || '';
            document.getElementById('editTeacherUsername').value = teacher.username || '';
            document.getElementById('editTeacherEmail').value = teacher.email || '';
            document.getElementById('editTeacherRole').value = teacher.role || 'teacher';
            
            // Show modal
            document.getElementById('editTeacherModal').classList.remove('hidden');
        }
        
        function closeEditTeacherModal() {
            document.getElementById('editTeacherModal').classList.add('hidden');
            editingTeacherId = null;
        }
        
        function saveTeacherEdit() {
            if (!editingTeacherId) return;
            
            const teacher = teachers.find(t => t.id === editingTeacherId);
            if (!teacher) {
                alert('Teacher not found');
                return;
            }
            
            const name = document.getElementById('editTeacherName').value.trim();
            const email = document.getElementById('editTeacherEmail').value.trim();
            const role = document.getElementById('editTeacherRole').value;
            
            if (!name) {
                alert('Please enter a name');
                return;
            }
            
            if (email && !email.includes('@')) {
                alert('Please enter a valid email address');
                return;
            }
            
            // Update teacher
            teacher.name = name;
            teacher.email = email;
            teacher.role = role;
            
            // If name changed, try to re-match to CSV sections
            matchTeacherToSections(teacher);
            
            // If editing current user, update currentUser reference
            if (editingTeacherId === currentUser.id) {
                currentUser = teacher;
                saveSession(); // Update session
                
                // Update display
                document.getElementById('currentUserName').textContent = teacher.name;
                document.getElementById('currentUserRole').textContent = getFriendlyRoleName(teacher.role);
            }
            
            saveData();
            updateTeachersTable();
            updateAllDisplays(); // Refresh all displays including period filter
            closeEditTeacherModal();
            
            alert(`✅ Teacher updated!\n\n${name}'s information has been saved.`);
        }

        async function deleteTeacher(teacherId) {
            if (currentUser.role !== 'admin' && currentUser.role !== 'superadmin') {
                alert('Only admins can delete teachers');
                return;
            }

            if (teacherId === currentUser.id) {
                alert('You cannot delete your own account');
                return;
            }

            if (await showConfirm('Are you sure you want to delete this teacher?')) {
                // Tombstone the teacher so deletion survives the main-document merge
                const key = `teacher:${teacherId}`;
                if (!entityTombstones.some(t => t.key === key)) {
                    entityTombstones.push({
                        key: key,
                        type: 'teacher',
                        id: teacherId,
                        deletedAt: new Date().toISOString(),
                        deletedBy: currentUser.name || 'admin'
                    });
                }
                teachers = teachers.filter(t => t.id !== teacherId);
                saveData();
                updateTeachersTable();
            }
        }

        // System Admin Functions
        async function promoteToSuperAdmin() {
            if (currentUser.role !== 'superadmin') {
                alert('Only Super Admins can promote others');
                return;
            }

            const selectElement = document.getElementById('promoteAdminSelect');
            const teacherId = selectElement.value;

            if (!teacherId) {
                alert('Please select an admin to promote');
                return;
            }

            const teacher = teachers.find(t => t.id === teacherId);
            if (!teacher) {
                alert('Teacher not found');
                return;
            }

            if (await showConfirm(`Promote ${teacher.name} to Super Admin?\n\nThey will have access to:\n• System reset\n• All admin features\n• Promote other admins`)) {
                teacher.role = 'superadmin';
                saveData();
                updateTeachersTable();
                updateSuperAdminList();
                alert(`${teacher.name} is now a Super Admin!`);
            }
        }

        function updateSuperAdminList() {
            const select = document.getElementById('promoteAdminSelect');
            if (!select) return;

            const admins = teachers.filter(t => t.role === 'admin');
            
            select.innerHTML = '<option value="">Select an admin...</option>';
            admins.forEach(admin => {
                const option = document.createElement('option');
                option.value = admin.id;
                option.textContent = `${admin.name} (${admin.username})`;
                select.appendChild(option);
            });
        }

        async function resetSystemData() {
            if (currentUser.role !== 'superadmin') {
                alert('Only Super Admins can reset the system');
                return;
            }

            const confirmation = document.getElementById('resetConfirmation').value;
            
            if (confirmation !== 'DELETE ALL DATA') {
                alert('Please type "DELETE ALL DATA" exactly to confirm');
                return;
            }

            if (!await showConfirm('⚠️ FINAL WARNING ⚠️\n\nThis will PERMANENTLY DELETE:\n• All students\n• All tickets\n• All raffle winners\n• All audit logs\n• All weekly history\n\nThis CANNOT be undone!\n\nAre you ABSOLUTELY SURE?')) {
                return;
            }

            // Second confirmation
            if (!await showConfirm('Last chance! Click OK to DELETE EVERYTHING or Cancel to abort.')) {
                return;
            }

            // Reset all data
            students = [];
            currentWeek = 1;
            weeklyWinners = [];
            bigRaffleWinners = [];
            auditLog = [];
            weeklyHistory = [];

            // Keep teachers and settings
            // teachers = teachers; (already preserved)
            // pbisSubcategories and academicSubcategories preserved

            // Save the reset
            saveData();
            updateAllDisplays();

            // Clear confirmation field
            document.getElementById('resetConfirmation').value = '';

            alert('✅ System has been reset!\n\nAll student data, tickets, and history have been deleted.\n\nTeacher accounts and settings have been preserved.');
        }

        function exportFullSystemBackup() {
            const backup = {
                exportDate: new Date().toISOString(),
                students: students,
                currentWeek: currentWeek,
                weeklyWinners: weeklyWinners,
                bigRaffleWinners: bigRaffleWinners,
                teachers: teachers,
                auditLog: auditLog,
                weeklyHistory: weeklyHistory,
                pbisSubcategories: pbisSubcategories,
                academicSubcategories: academicSubcategories
            };

            const dataStr = JSON.stringify(backup, null, 2);
            const dataBlob = new Blob([dataStr], { type: 'application/json' });
            const url = URL.createObjectURL(dataBlob);
            const link = document.createElement('a');
            link.href = url;
            link.download = `Westbrook_Raffle_Backup_${new Date().toISOString().split('T')[0]}.json`;
            link.click();
            URL.revokeObjectURL(url);

            alert('✅ Full system backup downloaded!\n\nKeep this file safe in case you need to restore data.');
        }

        function showChangePassword() {
            document.getElementById('mainApp').classList.add('hidden');
            document.getElementById('changePasswordModal').classList.remove('hidden');
            document.getElementById('currentPasswordInput').value = '';
            document.getElementById('newPasswordInput').value = '';
            document.getElementById('confirmPasswordInput').value = '';
            document.getElementById('changePasswordError').textContent = '';
        }

        function closeChangePassword() {
            document.getElementById('changePasswordModal').classList.add('hidden');
            document.getElementById('mainApp').classList.remove('hidden');
        }

        async function changePassword() {
            const currentPassword = document.getElementById('currentPasswordInput').value;
            const newPassword = document.getElementById('newPasswordInput').value;
            const confirmPassword = document.getElementById('confirmPasswordInput').value;
            const errorDiv = document.getElementById('changePasswordError');

            if (!currentPassword || !newPassword || !confirmPassword) {
                errorDiv.textContent = 'Please fill in all fields';
                return;
            }

            if (currentPassword !== currentUser.password) {
                errorDiv.textContent = 'Current password is incorrect';
                return;
            }

            if (newPassword.length < 4) {
                errorDiv.textContent = 'New password must be at least 4 characters';
                return;
            }

            if (newPassword !== confirmPassword) {
                errorDiv.textContent = 'New passwords do not match';
                return;
            }

            // Update password
            const teacher = teachers.find(t => t.id === currentUser.id);
            if (teacher) {
                teacher.password = newPassword;
                currentUser.password = newPassword;
                await saveData();
                saveSession(); // Update session with new password
                
                alert('✅ Password changed successfully!');
                closeChangePassword();
            } else {
                errorDiv.textContent = 'Error updating password. Please try again.';
            }
        }

        // Add Cash Modal Functions
        let selectedStudentForCash = null;

        function showAddCashModal(studentId) {
            const student = students.find(s => s.id === studentId);
            if (!student) return;
            
            selectedStudentForCash = student;
            document.getElementById('addCashStudentName').textContent = `${student.firstName} ${student.lastName}`;
            
            // Populate positive behaviors dropdown
            const behaviorSelect = document.getElementById('addCashBehaviorSelect');
            behaviorSelect.innerHTML = '<option value="">Select positive behavior...</option>';
            
            const positiveBehaviors = wildcatCashBehaviors.filter(b => b.type === 'positive' && b.active !== false);
            positiveBehaviors.forEach(behavior => {
                const option = document.createElement('option');
                option.value = behavior.id;
                option.textContent = `${behavior.name} (+$${behavior.points})`;
                behaviorSelect.appendChild(option);
            });
            
            document.getElementById('addCashAmount').value = '';
            document.getElementById('addCashNotes').value = '';
            
            document.getElementById('mainApp').classList.add('hidden');
            document.getElementById('addCashModal').classList.remove('hidden');
        }

        function updateAddCashAmount() {
            const behaviorId = document.getElementById('addCashBehaviorSelect').value;
            const amountInput = document.getElementById('addCashAmount');
            
            if (behaviorId) {
                const behavior = wildcatCashBehaviors.find(b => b.id === behaviorId);
                if (behavior) {
                    amountInput.value = behavior.points;
                }
            } else {
                amountInput.value = '';
            }
        }

        function cancelAddCash() {
            selectedStudentForCash = null;
            document.getElementById('addCashModal').classList.add('hidden');
            document.getElementById('mainApp').classList.remove('hidden');
        }

        async function confirmAddCash() {
            const behaviorId = document.getElementById('addCashBehaviorSelect').value;
            const notes = (document.getElementById('addCashNotes') || {}).value || '';
            if (!behaviorId) { alert('Please select a behavior'); return; }
            if (!selectedStudentForCash) return;

            const behavior = wildcatCashBehaviors.find(b => b.id === behaviorId);
            if (!behavior) { alert('Behavior not found'); return; }

            const amount = Math.abs(behavior.points);
            recordCashTransaction({
                student: selectedStudentForCash,
                amount,
                behaviorId: behavior.id,
                behaviorName: behavior.name,
                notes: notes.trim(),
                kind: 'award'
            });
            if (typeof addToAuditLog === 'function') {
                // 'cash_award' is what the Cash Audit Log filters for. This
                // used to pass 'Awarded Wildcat Cash', which matched nothing,
                // so awards never appeared there. The last two arguments were
                // also reversed: the signature is (.., ticketCount, reason).
                addToAuditLog('cash_award',
                    selectedStudentForCash.id, 'Wildcat Cash',
                    Math.abs(amount),
                    behavior.name + (notes.trim() ? ', ' + notes.trim() : ''));
            }

            closeAddCashModal();
            if (typeof updateStudentAccounts === 'function') updateStudentAccounts();
            if (typeof updateCashTable === 'function') updateCashTable();
            showToast(`✅ +$${Math.abs(amount)} · ${behavior.name}\n${selectedStudentForCash.firstName} ${selectedStudentForCash.lastName}`, 'success');
            await saveData();
        }

