        // Initialize pass settings UI when switching to settings tab (ClawPass only)
        function initializePassSettingsUI() {
            // Ensure bell schedules exist first
            ensureBellSchedulesExist();
            
            // Update schedule dropdown for current school
            updateScheduleDropdownForSchool();
            
            // Set duration values
            document.getElementById('bathroomDuration').value = passSettings.bathroom;
            document.getElementById('officeDuration').value = passSettings.office;
            document.getElementById('classroomDuration').value = passSettings.classroom;
            document.getElementById('wellnessDuration').value = passSettings.wellness;
            
            // Populate custom schedules in Pass Settings dropdown
            const optgroupSettings = document.getElementById('customSchedulesOptgroupSettings');
            if (optgroupSettings) {
                optgroupSettings.innerHTML = '';
                const builtInSchedules = ['hs_mondayBlock1', 'hs_tuesdayBlock2', 'hs_wednesdayAll', 'hs_thursdayBlock1', 
                                           'hs_fridayBlock2', 'ms_mondayBlock1', 'ms_tuesdayBlock2', 'ms_wednesdayAll',
                                           'ms_thursdayBlock1', 'ms_fridayBlock2', 'minimumDayBlock1', 'minimumDayBlock2', 'assembly'];
                
                let hasCustomSchedules = false;
                for (const key in passSettings.bellSchedules) {
                    if (!builtInSchedules.includes(key)) {
                        const schedule = passSettings.bellSchedules[key];
                        const option = document.createElement('option');
                        option.value = key;
                        option.textContent = `🎨 ${schedule.name}`;
                        optgroupSettings.appendChild(option);
                        hasCustomSchedules = true;
                    }
                }
                
                if (!hasCustomSchedules) {
                    optgroupSettings.style.display = 'none';
                } else {
                    optgroupSettings.style.display = 'block';
                }
            }
            
            // Set schedule values
            document.getElementById('activeScheduleSelect').value = passSettings.activeSchedule || 'auto';
            document.getElementById('enableAutoDetection').checked = passSettings.enableAutoDetection !== false;
        }

        // ============================================
        // STUDENT SNAPSHOT FUNCTIONS
        // ============================================
        
        let selectedSnapshotStudent = null;
        let snapshotPeriod = 'today';
        let snapshotSearchSelectedIndex = -1;
        let snapshotSearchResults = [];
        
        // Show search results as you type
        function showSnapshotSearchResults() {
            const searchTerm = document.getElementById('snapshotStudentSearch').value.toLowerCase().trim();
            const resultsDiv = document.getElementById('snapshotSearchResults');
            
            if (!searchTerm) {
                resultsDiv.style.display = 'none';
                snapshotSearchResults = [];
                snapshotSearchSelectedIndex = -1;
                return;
            }
            
            // Filter students
            snapshotSearchResults = students.filter(student => {
                const fullName = `${student.firstName} ${student.lastName}`.toLowerCase();
                const reverseName = `${student.lastName} ${student.firstName}`.toLowerCase();
                const id = student.id.toLowerCase();
                
                return fullName.includes(searchTerm) || 
                       reverseName.includes(searchTerm) || 
                       id.includes(searchTerm);
            }).sort((a, b) => a.lastName.localeCompare(b.lastName));
            
            // Show results
            if (snapshotSearchResults.length === 0) {
                resultsDiv.innerHTML = '<div style="padding: 15px; color: #999; text-align: center;">No students found</div>';
                resultsDiv.style.display = 'block';
                return;
            }
            
            // Limit to 10 results
            const displayResults = snapshotSearchResults.slice(0, 10);
            resultsDiv.innerHTML = '';
            
            displayResults.forEach((student, index) => {
                const div = document.createElement('div');
                div.style.padding = '12px 15px';
                div.style.cursor = 'pointer';
                div.style.borderBottom = '1px solid #f0f0f0';
                div.style.transition = 'background 0.2s';
                div.innerHTML = `
                    <div style="font-weight: 600; color: #333;">${student.firstName} ${student.lastName}</div>
                    <div style="font-size: 13px; color: #666;">ID: ${student.id} | Grade ${student.grade}</div>
                `;
                
                div.onmouseover = () => {
                    div.style.background = '#f0f4ff';
                    snapshotSearchSelectedIndex = index;
                    updateSnapshotSearchHighlight();
                };
                div.onmouseout = () => {
                    div.style.background = 'white';
                };
                div.onclick = () => {
                    selectSnapshotStudent(student);
                };
                
                resultsDiv.appendChild(div);
            });
            
            if (snapshotSearchResults.length > 10) {
                const moreDiv = document.createElement('div');
                moreDiv.style.padding = '10px 15px';
                moreDiv.style.background = '#f9f9f9';
                moreDiv.style.color = '#666';
                moreDiv.style.fontSize = '13px';
                moreDiv.style.textAlign = 'center';
                moreDiv.textContent = `+ ${snapshotSearchResults.length - 10} more results (keep typing to narrow down)`;
                resultsDiv.appendChild(moreDiv);
            }
            
            resultsDiv.style.display = 'block';
            snapshotSearchSelectedIndex = -1;
        }
        
        // Handle keyboard navigation
        function handleSnapshotSearchKeys(event) {
            const resultsDiv = document.getElementById('snapshotSearchResults');
            if (resultsDiv.style.display === 'none' || snapshotSearchResults.length === 0) return;
            
            const displayCount = Math.min(snapshotSearchResults.length, 10);
            
            if (event.key === 'ArrowDown') {
                event.preventDefault();
                snapshotSearchSelectedIndex = Math.min(snapshotSearchSelectedIndex + 1, displayCount - 1);
                updateSnapshotSearchHighlight();
            } else if (event.key === 'ArrowUp') {
                event.preventDefault();
                snapshotSearchSelectedIndex = Math.max(snapshotSearchSelectedIndex - 1, -1);
                updateSnapshotSearchHighlight();
            } else if (event.key === 'Enter') {
                event.preventDefault();
                if (snapshotSearchSelectedIndex >= 0 && snapshotSearchSelectedIndex < snapshotSearchResults.length) {
                    selectSnapshotStudent(snapshotSearchResults[snapshotSearchSelectedIndex]);
                } else if (snapshotSearchResults.length === 1) {
                    selectSnapshotStudent(snapshotSearchResults[0]);
                }
            } else if (event.key === 'Escape') {
                resultsDiv.style.display = 'none';
            }
        }
        
        // Update visual highlight for keyboard navigation
        function updateSnapshotSearchHighlight() {
            const resultsDiv = document.getElementById('snapshotSearchResults');
            const items = resultsDiv.querySelectorAll('div[style*="cursor: pointer"]');
            
            items.forEach((item, index) => {
                if (index === snapshotSearchSelectedIndex) {
                    item.style.background = '#e3f2fd';
                    item.style.borderLeft = '4px solid #667eea';
                } else {
                    item.style.background = 'white';
                    item.style.borderLeft = 'none';
                }
            });
        }
        
        // Select a student and load their snapshot
        function selectSnapshotStudent(student) {
            selectedSnapshotStudent = student;
            document.getElementById('snapshotStudentSearch').value = `${student.firstName} ${student.lastName} (${student.id})`;
            document.getElementById('snapshotSearchResults').style.display = 'none';
            loadStudentSnapshot();
        }
        
        
        
        // Load student snapshot
        function loadStudentSnapshot() {
            if (!selectedSnapshotStudent) {
                document.getElementById('snapshotContent').style.display = 'none';
                return;
            }
            
            // Show snapshot content
            document.getElementById('snapshotContent').style.display = 'block';
            
            // Update header
            document.getElementById('snapshotStudentName').textContent = 
                `${selectedSnapshotStudent.firstName} ${selectedSnapshotStudent.lastName}`;
            document.getElementById('snapshotStudentId').textContent = selectedSnapshotStudent.id;
            document.getElementById('snapshotStudentGrade').textContent = selectedSnapshotStudent.grade;
            
            // Detect current class
            const currentPeriodInfo = detectCurrentPeriod(selectedSnapshotStudent, new Date());
            if (currentPeriodInfo && currentPeriodInfo.period !== 'Outside Class Time') {
                document.getElementById('snapshotCurrentClass').innerHTML = 
                    `📍 Currently in: <strong>${currentPeriodInfo.period} - ${currentPeriodInfo.teacher || 'N/A'} (${currentPeriodInfo.className || 'N/A'})</strong>`;
            } else {
                document.getElementById('snapshotCurrentClass').innerHTML = 
                    `📍 Currently: <strong>Outside Class Time</strong>`;
            }
            
            // Update snapshot data
            updateSnapshotData();
        }
        
        // Set time period filter
        function setSnapshotPeriod(period) {
            snapshotPeriod = period;
            
            // Update button styles
            ['today', 'week', 'month', 'year'].forEach(p => {
                const btn = document.getElementById('snapshot' + p.charAt(0).toUpperCase() + p.slice(1));
                if (p === period) {
                    btn.className = 'btn';
                    btn.style.background = '#667eea';
                    btn.style.color = 'white';
                } else {
                    btn.className = 'btn btn-secondary';
                    btn.style.background = '';
                    btn.style.color = '';
                }
            });
            
            updateSnapshotData();
        }
        
        // Update all snapshot data
        /* ---- Student Snapshot: this child's passes ------------------------
           EVERY FIGURE HERE USED TO BE ZERO. The counters read the browser's
           pre-Convex `hallPasses` array, so a child could take a pass every
           period all week and this screen would show 0 passes, 0 minutes out,
           0 overtimes, next to a pass limit nothing enforced. It reads
           hallPasses:history for that one student now, through the by_student
           index, so it is a walk of their rows rather than a scan of the
           school's.

           MINUTES OUT IS MEASURED, NOT PROMISED. The old code summed
           `pass.duration`, which is how long a pass was ALLOWED to run; two
           children who took the same pass and came back at very different
           times counted identically. elapsedMinutes is how long it actually
           ran. */
        let wcSnapshotPasses = null;
        // The child's cap AS THE SERVER HAS IT: { limit, takenToday }, or null
        // before the first load. Never derived here; see wcRenderPassLimit.
        let wcSnapshotCap = null;

        async function updateSnapshotData() {
            if (!selectedSnapshotStudent) return;
            const ctx = wcBellSession();
            const setText = function (id, v) { const el = document.getElementById(id); if (el) el.textContent = v; };
            if (!ctx) {
                ['snapshotPassesToday', 'snapshotPassesWeek', 'snapshotPassesMonth', 'snapshotTotalTime', 'snapshotOvertime']
                    .forEach(function (id) { setText(id, '—'); });
                return;
            }
            const number = String(selectedSnapshotStudent.studentNumber || selectedSnapshotStudent.id || '');
            try {
                const res = await ctx.auth.convexQuery('hallPasses:history',
                    { studentNumber: number, limit: 200 }, ctx.session.idToken);
                wcSnapshotPasses = res.passes || [];
                wcSnapshotCap = res.cap || null;
            } catch (e) {
                wcSnapshotCap = null;
                ['snapshotPassesToday', 'snapshotPassesWeek', 'snapshotPassesMonth', 'snapshotTotalTime', 'snapshotOvertime']
                    .forEach(function (id) { setText(id, '—'); });
                console.warn('[snapshot] history failed:', e && e.message);
                return;
            }
            drawSnapshotStats();
        }

        function drawSnapshotStats() {
            const passes = wcSnapshotPasses || [];
            const now = new Date();
            const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
            const weekStart = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
            const monthStart = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
            // The school year starts in August, so "this year" means since the
            // most recent 1 August, not since January.
            const yearStart = new Date(now.getMonth() >= 7 ? now.getFullYear() : now.getFullYear() - 1, 7, 1);
            const since = function (d) {
                return passes.filter(function (p) { return new Date(p.requestedAt) >= d; });
            };
            const windows = { today: todayStart, week: weekStart, month: monthStart, year: yearStart };
            const periodPasses = since(windows[snapshotPeriod] || todayStart);

            let totalTime = 0;
            let overtimeCount = 0;
            periodPasses.forEach(function (p) {
                if (typeof p.elapsedMinutes === 'number' && isFinite(p.elapsedMinutes)) {
                    totalTime += p.elapsedMinutes;
                }
                if (p.overdue) overtimeCount++;
            });

            const setText = function (id, v) { const el = document.getElementById(id); if (el) el.textContent = v; };
            setText('snapshotPassesToday', since(todayStart).length);
            setText('snapshotPassesWeek', since(weekStart).length);
            setText('snapshotPassesMonth', since(monthStart).length);
            setText('snapshotTotalTime', Math.round(totalTime));
            setText('snapshotOvertime', overtimeCount);

            updatePassLimitStatus();
            updatePeriodBreakdown(periodPasses);
        }


        /* ---- pass limit: this child's own cap -----------------------------
           WHAT WAS WRONG. The cap became a server rule (canRequest reads
           students.dailyPassLimit through passLimitFor) and this screen was
           never connected to it, so all three halves lied independently:

           - THE SAVE went nowhere. It set dailyPassLimit on the browser's
             roster object and called saveData(), and appData:save does not
             carry that field — it is not in STUDENT_WRITABLE, deliberately,
             because a cap a browser can write through a settings blob is not a
             cap. A teacher set "2 passes a day", saw "Saved", and the number
             the server enforced stayed whatever it had always been.
           - THE COUNT came off `hallPasses`, the pre-Convex array the deleted
             kiosk used to fill, so "0 of 3 today" was 0 for a child who had
             been out five times.
           - THE LIMIT came off the roster, which does not carry the field, so
             the row hid itself: `|| 0` then `> 0` meant a real cap of 0 (no
             passes at all) rendered as no cap at all, the exact inversion.

           WHY THE FIGURES COME FROM THE SERVER. Both now arrive as `cap` on
           hallPasses:history, computed by the same functions canRequest uses.
           Counting here would mean copying passesTakenOnDay's two rules — the
           school-day rollover and "only approved passes count" — into a second
           place, and a display that re-derives a rule is a display that drifts
           from it.

           BLANK AND 0 ARE DIFFERENT ANSWERS, and this is the sharp edge. Blank
           clears the personal cap back to the school-wide one. 0 means this
           child takes no passes at all. The old modal said "set to 0 to remove
           the limit", which under the server rule would have banned the child
           from every pass instead of freeing them. */
        function wcRenderPassLimit(cap, el) {
            if (!el) return null;
            const limit = cap && typeof cap.limit === 'number' ? cap.limit : null;
            if (limit === null) {
                el.style.display = 'none';
                return null;
            }
            const taken = (cap && typeof cap.takenToday === 'number') ? cap.takenToday : 0;
            const text = document.getElementById('passLimitText');
            if (text) {
                text.innerHTML = limit === 0
                    ? '<strong>Daily Pass Limit:</strong> this student may not take hall passes.'
                    : '<strong>Daily Pass Limit:</strong> ' + taken + ' / ' + limit + ' passes used today';
            }
            el.style.display = 'block';
            // Reached, INCLUDING a cap of zero, which is reached before the day
            // starts and should read as the stop it is.
            if (taken >= limit) {
                el.style.background = '#fee2e2';
                el.style.borderLeftColor = '#B3392F';
            } else {
                el.style.background = '#fff3cd';
                el.style.borderLeftColor = '#B7791F';
            }
            return { limit: limit, taken: taken, reached: taken >= limit };
        }

        // What goes in the modal's box: blank for "no personal cap", the number
        // otherwise, and "0" for a cap of zero rather than an empty box.
        function wcPassLimitInputValue(cap) {
            const limit = cap && typeof cap.limit === 'number' ? cap.limit : null;
            return limit === null ? '' : String(limit);
        }

        // What the box means when Save is pressed. Blank clears; anything else
        // must be a whole number the server will accept, and is rejected here
        // rather than sent, so the teacher is told which box is wrong.
        function wcPassLimitArg(raw) {
            const text = String(raw == null ? '' : raw).trim();
            if (text === '') return { ok: true, limit: null };
            if (!/^\d+$/.test(text)) {
                return { ok: false, message: 'A daily limit is a whole number, or blank to clear it.' };
            }
            const n = Number(text);
            if (n > 50) return { ok: false, message: 'A daily limit cannot be more than 50.' };
            return { ok: true, limit: n };
        }
        /* ---- end pass limit ---- */

        function updatePassLimitStatus() {
            wcRenderPassLimit(wcSnapshotCap, document.getElementById('passLimitStatus'));
        }
        
        // Update per-period breakdown
        function updatePeriodBreakdown(passes) {
            const tbody = document.getElementById('snapshotPeriodBreakdown');
            tbody.innerHTML = '';
            
            if (!selectedSnapshotStudent.sections || selectedSnapshotStudent.sections.length === 0) {
                tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; padding: 40px; color: #999;">No class schedule data available</td></tr>';
                return;
            }
            
            // Group passes by period
            const periodStats = {};
            
            passes.forEach(pass => {
                const period = pass.period || 'Unknown';
                if (!periodStats[period]) {
                    periodStats[period] = {
                        passes: 0,
                        timeMissed: 0,
                        overtime: 0
                    };
                }
                periodStats[period].passes++;
                periodStats[period].timeMissed += pass.duration;
                if (pass.status === 'overtime') periodStats[period].overtime++;
            });
            
            // Show each class period
            selectedSnapshotStudent.sections.forEach(section => {
                const stats = periodStats[section.period] || { passes: 0, timeMissed: 0, overtime: 0 };
                
                const row = document.createElement('tr');
                row.innerHTML = `
                    <td style="font-weight: 600; color: #667eea;">${section.period}</td>
                    <td>${section.courseName || 'N/A'}</td>
                    <td>${section.teacherName || 'N/A'}</td>
                    <td style="text-align: center;">${stats.passes}</td>
                    <td style="text-align: center; font-weight: 600;">${stats.timeMissed}</td>
                    <td style="text-align: center; color: ${stats.overtime > 0 ? '#B3392F' : '#2E7D52'};">${stats.overtime}</td>
                `;
                tbody.appendChild(row);
            });
            
            if (selectedSnapshotStudent.sections.length === 0) {
                tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; padding: 40px; color: #999;">No class periods found</td></tr>';
            }
        }
        
        // Open pass limit modal
        function openPassLimitModal() {
            if (!selectedSnapshotStudent) return;

            document.getElementById('passLimitStudentName').textContent =
                `${selectedSnapshotStudent.firstName} ${selectedSnapshotStudent.lastName}`;
            // The server's number, not the roster's: the roster has never
            // carried this field, so the old prefill was always 0 and offered
            // to overwrite a real cap with one nobody chose.
            document.getElementById('passLimitInput').value = wcPassLimitInputValue(wcSnapshotCap);
            const msg = document.getElementById('passLimitMsg');
            if (msg) { msg.textContent = ''; msg.className = 'sp-edit-msg'; }
            document.getElementById('passLimitModal').classList.remove('hidden');
        }

        // Close pass limit modal
        function closePassLimitModal() {
            document.getElementById('passLimitModal').classList.add('hidden');
        }

        // Save pass limit. studentDetail:setPassLimit is the ONLY writer of
        // dailyPassLimit; nothing about this number travels through saveData().
        async function savePassLimit() {
            if (!selectedSnapshotStudent) return;
            const msg = document.getElementById('passLimitMsg');
            const say = function (text, kind) {
                if (!msg) { if (text) alert(text); return; }
                msg.textContent = text;
                msg.className = 'sp-edit-msg' + (kind ? ' sp-edit-msg--' + kind : '');
            };

            const parsed = wcPassLimitArg((document.getElementById('passLimitInput') || {}).value);
            if (!parsed.ok) { say(parsed.message, 'err'); return; }

            const ctx = wcBellSession();
            if (!ctx) { say(wcNeedsMicrosoftMessage(), 'err'); return; }

            const number = String(selectedSnapshotStudent.studentNumber || selectedSnapshotStudent.id || '');
            const btn = document.getElementById('passLimitSaveBtn');
            if (btn) { btn.disabled = true; }
            say('Saving…');
            try {
                await ctx.auth.convexMutation('studentDetail:setPassLimit',
                    { studentNumber: number, limit: parsed.limit }, ctx.session.idToken);
            } catch (e) {
                say((e && e.message) || 'Could not save the limit.', 'err');
                return;
            } finally {
                if (btn) { btn.disabled = false; }
            }

            closePassLimitModal();
            // Re-read rather than patch a local copy: the count that sits beside
            // the limit comes from the server too, and one of the two being
            // fresh is how the pair started disagreeing in the first place.
            await updateSnapshotData();
        }

        // ============================================
        // CLAWPASS DATA RESET FUNCTIONS
        // ============================================
        
        function confirmClawPassReset() {
            // Show pass count in modal
            document.getElementById('resetPassCount').textContent = hallPasses.length;
            
            // Clear confirmation input
            document.getElementById('resetConfirmationInput').value = '';
            
            // Show modal
            document.getElementById('clawPassResetModal').classList.remove('hidden');
        }
        
        function closeClawPassResetModal() {
            document.getElementById('clawPassResetModal').classList.add('hidden');
            document.getElementById('resetConfirmationInput').value = '';
        }
        
        async function executeClawPassReset() {
            // WHAT THIS CAN AND CANNOT DO, said plainly, because it used to
            // claim otherwise. It offered to "permanently delete all hall pass
            // history" and then emptied the browser's pre-Convex array, which
            // since the kiosk was deleted holds nothing anybody can see. The
            // real record lives in Convex; a pass is a record of where a child
            // was, and there is deliberately no button that erases the school's
            // in one press. What is actually clearable from here is the
            // simulator and the per-student daily limits.
            const confirmation = (document.getElementById('resetConfirmationInput') || {}).value;
            if (confirmation !== 'DELETE') {
                alert('Type DELETE (in capitals) to confirm.');
                return;
            }
            const ok = await showConfirm(
                'This clears the Encounter Prevention simulator and the pre-Convex ' +
                'leftovers in this browser.\n\n' +
                'It does NOT delete the hall pass record. Passes are kept on the ' +
                'server as the account of where a child was; Pass History reads ' +
                'them and nothing here can erase them.\n\n' +
                'Continue?'
            );
            if (!ok) { closeClawPassResetModal(); return; }
            try {
                const leftovers = Array.isArray(hallPasses) ? hallPasses.length : 0;
                hallPasses = [];
                if (typeof wcSimPasses !== 'undefined') { wcSimPasses = []; wcSimStudents = []; }
                if (typeof detectedPatterns !== 'undefined') detectedPatterns = [];
                await saveData();
                closeClawPassResetModal();
                alert('Cleared the simulator and ' + leftovers + ' pre-Convex leftover' +
                      (leftovers === 1 ? '' : 's') + ' from this browser.\n\n' +
                      'The hall pass record on the server is untouched.');
                if (typeof updatePassHistory === 'function') updatePassHistory();
            } catch (e) {
                alert('Could not finish: ' + e.message);
            }
        }

        // ============================================
