        // Clear all test data
        function clearTestData() {
            // The simulator's own store, and nothing else. It never reached the
            // roster or the pass record, so there is nothing else to undo.
            const hadStudents = wcSimStudents.length;
            const hadPasses = wcSimPasses.length;
            wcSimStudents = [];
            wcSimPasses = [];
            detectedPatterns = [];
            if (typeof analyzeEncounterPatterns === 'function') analyzeEncounterPatterns();
            alert('Cleared ' + hadPasses + ' simulated pass' + (hadPasses === 1 ? '' : 'es') +
                  ' and ' + hadStudents + ' simulated student' + (hadStudents === 1 ? '' : 's') + '.');
        }
        
        // Analyze encounter patterns
        async function analyzeEncounterPatterns() {
            document.getElementById('patternAnalysisStatus').textContent = '🔄 Analyzing...';
            
            const timeRange = parseInt(document.getElementById('patternTimeRange').value);
            const cutoffDate = new Date();
            cutoffDate.setDate(cutoffDate.getDate() - timeRange);
            
            // Get passes in time range
            // TEST MODE READS THE SIMULATOR; LIVE MODE READS THE REAL RECORD.
            // Live mode used to filter the browser's pre-Convex array for rows
            // that were not test data, which since the kiosk was deleted is
            // always none: the screen said "No Patterns Detected" whatever the
            // school actually did. It reads hallPasses:history now, mapped onto
            // the shape the analysis below expects.
            let passesToAnalyze;
            if (encounterTestMode) {
                passesToAnalyze = wcSimPasses.filter(p => new Date(p.createdAt) >= cutoffDate);
            } else {
                const ctx = wcBellSession();
                if (!ctx) {
                    document.getElementById('patternAnalysisStatus').textContent =
                        'Sign in with Microsoft to analyse real passes.';
                    return;
                }
                try {
                    const res = await ctx.auth.convexQuery('hallPasses:history',
                        { limit: 200, sinceIso: cutoffDate.toISOString() }, ctx.session.idToken);
                    passesToAnalyze = (res.passes || []).map(function (p) {
                        return {
                            id: p.id,
                            studentId: p.studentNumber,
                            studentName: p.studentName,
                            destination: p.destination || p.reason || 'unknown',
                            createdAt: p.requestedAt,
                            status: p.state,
                            isTestData: false,
                        };
                    });
                } catch (e) {
                    document.getElementById('patternAnalysisStatus').textContent = e.message;
                    return;
                }
            }
            
            // Find overlaps
            const overlaps = [];
            for (let i = 0; i < passesToAnalyze.length; i++) {
                for (let j = i + 1; j < passesToAnalyze.length; j++) {
                    const pass1 = passesToAnalyze[i];
                    const pass2 = passesToAnalyze[j];
                    
                    if (pass1.studentId === pass2.studentId) continue;
                    if (pass1.destination !== pass2.destination) continue;
                    
                    const time1 = new Date(pass1.createdAt);
                    const time2 = new Date(pass2.createdAt);
                    const diffMinutes = Math.abs(time2 - time1) / 60000;
                    
                    if (diffMinutes <= 10) {
                        overlaps.push({
                            students: [pass1.studentId, pass2.studentId].sort(),
                            studentNames: [pass1.studentName, pass2.studentName],
                            location: pass1.destination,
                            timeDiff: diffMinutes,
                            date: pass1.createdAt
                        });
                    }
                }
            }
            
            // Group by student pairs
            const patterns = {};
            overlaps.forEach(overlap => {
                const key = overlap.students.join('_');
                if (!patterns[key]) {
                    patterns[key] = {
                        students: overlap.students,
                        studentNames: overlap.studentNames,
                        overlaps: []
                    };
                }
                patterns[key].overlaps.push(overlap);
            });
            
            // Calculate suspicion scores
            detectedPatterns = Object.values(patterns).map(pattern => {
                const score = calculateSuspicionScore(pattern);
                return { ...pattern, suspicionScore: score };
            }).sort((a, b) => b.suspicionScore - a.suspicionScore);
            
            displayPatterns();
            
            document.getElementById('patternAnalysisStatus').textContent = 
                `✅ Found ${detectedPatterns.length} pattern(s) in last ${timeRange} days`;
        }
        
        // Calculate suspicion score
        function calculateSuspicionScore(pattern) {
            const overlaps = pattern.overlaps;
            
            // Frequency (0-15 points)
            const frequency = overlaps.length;
            const frequencyScore = Math.min(frequency * 2, 15);
            
            // Consistency - same location? (0-10 points)
            const locations = overlaps.map(o => o.location);
            const uniqueLocations = [...new Set(locations)];
            const consistencyScore = uniqueLocations.length === 1 ? 10 : 5;
            
            // Location risk (0-5 points) - bathroom is highest risk
            const bathroomCount = locations.filter(l => l === 'bathroom').length;
            const locationScore = (bathroomCount / locations.length) * 5;
            
            // Timing tightness (0-5 points)
            const avgTimeDiff = overlaps.reduce((sum, o) => sum + o.timeDiff, 0) / overlaps.length;
            const timingScore = avgTimeDiff <= 3 ? 5 : (avgTimeDiff <= 5 ? 3 : 1);
            
            return Math.round(frequencyScore + consistencyScore + locationScore + timingScore);
        }
        
        // Display detected patterns
        function displayPatterns() {
            const container = document.getElementById('detectedPatternsContainer');
            
            if (detectedPatterns.length === 0) {
                container.innerHTML = `
                    <div style="background: white; padding: 40px; border-radius: 12px; text-align: center;">
                        <div style="font-size: 48px; margin-bottom: 15px;">📊</div>
                        <h3 style="color: #666; margin: 0;">No Patterns Detected</h3>
                        <p style="color: #999; margin-top: 10px;">No overlapping pass patterns found in the selected time range.</p>
                        ${encounterTestMode ? '<button class="btn" onclick="generateTestData()" style="margin-top: 20px;">🎲 Generate Test Data</button>' : ''}
                    </div>
                `;
                return;
            }
            
            const highSuspicion = detectedPatterns.filter(p => p.suspicionScore >= 25);
            const mediumSuspicion = detectedPatterns.filter(p => p.suspicionScore >= 15 && p.suspicionScore < 25);
            const lowSuspicion = detectedPatterns.filter(p => p.suspicionScore < 15);
            
            let html = '';
            
            // High suspicion patterns
            if (highSuspicion.length > 0) {
                html += '<h3 style="color: #ef4444; margin-bottom: 15px;">🔴 High Suspicion Patterns</h3>';
                highSuspicion.forEach(pattern => {
                    html += renderPatternCard(pattern, 'high');
                });
            }
            
            // Medium suspicion patterns
            if (mediumSuspicion.length > 0) {
                html += '<h3 style="color: #f59e0b; margin: 25px 0 15px 0;">🟡 Medium Suspicion Patterns</h3>';
                mediumSuspicion.forEach(pattern => {
                    html += renderPatternCard(pattern, 'medium');
                });
            }
            
            // Low suspicion patterns  
            if (lowSuspicion.length > 0) {
                html += '<h3 style="color: #10b981; margin: 25px 0 15px 0;">🟢 Low Suspicion Patterns</h3>';
                lowSuspicion.forEach(pattern => {
                    html += renderPatternCard(pattern, 'low');
                });
            }
            
            container.innerHTML = html;
        }
        
        // Render individual pattern card
        function renderPatternCard(pattern, level) {
            const borderColor = level === 'high' ? '#B3392F' : level === 'medium' ? '#f59e0b' : '#2E7D52';
            const bgColor = level === 'high' ? '#fee2e2' : level === 'medium' ? '#fef3c7' : '#d1fae5';
            
            const locations = pattern.overlaps.map(o => o.location);
            const uniqueLocations = [...new Set(locations)];
            const avgTime = (pattern.overlaps.reduce((sum, o) => sum + o.timeDiff, 0) / pattern.overlaps.length).toFixed(1);
            
            const locationCounts = {};
            locations.forEach(loc => {
                locationCounts[loc] = (locationCounts[loc] || 0) + 1;
            });
            
            const recommendation = level === 'high' 
                ? 'High frequency, consistent location, tight timing - likely coordinated.'
                : level === 'medium'
                ? 'Moderate frequency - may be coincidence. Monitor for 2 more weeks.'
                : 'Likely coincidence - no action needed.';
            
            let timeline = '';
            pattern.overlaps.slice(0, 7).forEach((overlap, idx) => {
                const date = new Date(overlap.date).toLocaleDateString();
                timeline += `<div style="padding: 8px; background: white; border-radius: 6px; margin-bottom: 6px;">
                    ${date} - ${overlap.location.charAt(0).toUpperCase() + overlap.location.slice(1)} (${overlap.timeDiff.toFixed(1)} min gap)
                </div>`;
            });
            
            if (pattern.overlaps.length > 7) {
                timeline += `<div style="color: #666; font-size: 13px; margin-top: 5px;">+ ${pattern.overlaps.length - 7} more occurrences</div>`;
            }
            
            return `
                <div style="background: white; padding: 25px; border-radius: 12px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); margin-bottom: 20px; border-left: 4px solid ${borderColor};">
                    <div style="display: flex; justify-content: space-between; align-items: start; margin-bottom: 20px;">
                        <div>
                            <h4 style="margin: 0 0 5px 0; font-size: 18px;">${pattern.studentNames[0]} & ${pattern.studentNames[1]}</h4>
                            <div style="font-size: 14px; color: #666;">Suspicion Score: ${pattern.suspicionScore} / 35</div>
                        </div>
                        <div style="background: ${bgColor}; color: ${borderColor}; padding: 8px 16px; border-radius: 20px; font-weight: 600; font-size: 14px;">
                            ${level.toUpperCase()}
                        </div>
                    </div>
                    
                    <div style="background: #f9fafb; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
                        <strong>📊 Statistics:</strong>
                        <div style="margin-top: 10px; display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px;">
                            <div>• ${pattern.overlaps.length} overlapping passes</div>
                            <div>• Avg gap: ${avgTime} minutes</div>
                            <div>• Locations: ${uniqueLocations.join(', ')}</div>
                        </div>
                    </div>
                    
                    <div style="margin-bottom: 15px;">
                        <strong>📅 Recent Timeline:</strong>
                        <div style="margin-top: 10px; max-height: 200px; overflow-y: auto;">
                            ${timeline}
                        </div>
                    </div>
                    
                    <div style="background: ${bgColor}; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
                        <strong>💡 Recommendation:</strong>
                        <div style="margin-top: 5px;">${recommendation}</div>
                    </div>
                    
                    <div style="display: flex; gap: 10px;">
                        <button class="btn" onclick='createGroupFromPattern(${JSON.stringify(pattern.students)}, "${pattern.studentNames[0]} & ${pattern.studentNames[1]}")' style="background: #10b981;">
                            🛡️ Create Prevention Group
                        </button>
                        ${level !== 'low' ? `<button class="btn btn-secondary" onclick="dismissPattern()">❌ Dismiss</button>` : ''}
                    </div>
                </div>
            `;
        }
        
        // Create prevention group from detected pattern
        function createGroupFromPattern(studentIds, suggestedName) {
            groupStudents = studentIds.map(id => students.find(s => s.id === id));
            document.getElementById('groupName').value = suggestedName;
            openCreateGroupModal();
        }
        
        // Open create/edit group modal
        function openCreateGroupModal() {
            encounterGroupToEdit = null;
            document.getElementById('groupModalTitle').textContent = 'Create Prevention Group';
            
            // Populate student dropdown
            const select = document.getElementById('addStudentSelect');
            select.innerHTML = '<option value="">Select student to add...</option>';
            
            let studentsToShow = encounterTestMode 
                ? students.filter(s => s.isTestData)
                : students.filter(s => !s.isTestData);
            
            studentsToShow.forEach(student => {
                const option = document.createElement('option');
                option.value = student.id;
                option.textContent = `${student.firstName} ${student.lastName} (${student.id})`;
                select.appendChild(option);
            });
            
            updateGroupStudentsList();
            document.getElementById('preventionGroupModal').classList.remove('hidden');
        }
        
        // Add student to group
        function addStudentToGroup() {
            const select = document.getElementById('addStudentSelect');
            const studentId = select.value;
            
            console.log('=== ADD STUDENT TO GROUP ===');
            console.log('Selected student ID:', studentId);
            
            if (!studentId) {
                console.log('No student ID selected');
                return;
            }
            
            const student = students.find(s => s.id === studentId);
            console.log('Found student:', student);
            
            if (!student) {
                console.log('Student not found in students array');
                return;
            }
            
            if (groupStudents.find(s => s.id === studentId)) {
                alert('This student is already in the group');
                return;
            }
            
            groupStudents.push(student);
            console.log('Student added. groupStudents now:', groupStudents);
            updateGroupStudentsList();
            select.value = '';
        }
        
        // Update group students list display
        function updateGroupStudentsList() {
            const container = document.getElementById('groupStudentsList');
            
            if (groupStudents.length === 0) {
                container.innerHTML = '<p style="color: #999; margin: 0;">No students selected</p>';
                return;
            }
            
            container.innerHTML = groupStudents.map(s => `
                <div style="display: flex; justify-content: space-between; align-items: center; padding: 10px; background: white; border-radius: 6px; margin-bottom: 8px;">
                    <span><strong>${s.firstName} ${s.lastName}</strong> (${s.id})</span>
                    <button onclick="removeStudentFromGroup('${s.id}')" style="background: #ef4444; color: white; border: none; padding: 5px 10px; border-radius: 4px; cursor: pointer;">Remove</button>
                </div>
            `).join('');
        }
        
        // Remove student from group
        function removeStudentFromGroup(studentId) {
            groupStudents = groupStudents.filter(s => s.id !== studentId);
            updateGroupStudentsList();
        }
        
        // Save prevention group
        async function savePreventionGroup() {
            console.log('=== SAVE PREVENTION GROUP ===');
            console.log('groupStudents:', groupStudents);
            
            const name = document.getElementById('groupName').value.trim();
            
            if (!name) {
                alert('Please enter a group name');
                return;
            }
            
            if (groupStudents.length < 2) {
                alert('Please add at least 2 students to the group');
                console.log('Not enough students - need at least 2, have:', groupStudents.length);
                return;
            }
            
            const timeWindow = parseInt(document.getElementById('blockTimeWindow').value);
            const locations = Array.from(document.querySelectorAll('.groupLocation:checked')).map(cb => cb.value);
            const monitorOnly = document.getElementById('monitorOnlyMode').checked;
            const reason = document.getElementById('groupReason').value.trim();
            
            const group = {
                id: encounterGroupToEdit?.id || `group_${Date.now()}`,
                name: name,
                students: groupStudents.map(s => s.id),
                rules: {
                    blockIfWithinMinutes: timeWindow,
                    locations: locations,
                    allDay: true
                },
                monitorOnly: monitorOnly,
                reason: reason,
                createdAt: encounterGroupToEdit?.createdAt || new Date().toISOString(),
                createdBy: currentUser.email,
                active: true,
                blockLog: encounterGroupToEdit?.blockLog || [],
                isTestData: encounterTestMode
            };
            
            console.log('Created group object:', group);
            console.log('Group students array:', group.students);
            
            if (encounterGroupToEdit) {
                const index = preventionGroups.findIndex(g => g.id === encounterGroupToEdit.id);
                preventionGroups[index] = group;
            } else {
                preventionGroups.push(group);
            }
            
            console.log('preventionGroups after save:', preventionGroups);
            
            await saveData();
            
            closePreventionGroupModal();
            updatePreventionGroupsDisplay();
            
            alert(`✅ Prevention Group ${encounterGroupToEdit ? 'Updated' : 'Created'}!\n\n` +
                  `Group: ${name}\n` +
                  `Students: ${groupStudents.length}\n` +
                  `Mode: ${monitorOnly ? 'Monitor Only' : 'Active Blocking'}`);
        }
        
        // Close prevention group modal
        function closePreventionGroupModal() {
            document.getElementById('preventionGroupModal').classList.add('hidden');
            groupStudents = [];
            encounterGroupToEdit = null;
        }
        
        // Update prevention groups display
        function updatePreventionGroupsDisplay() {
            const container = document.getElementById('preventionGroupsContainer');
            
            let groupsToShow = encounterTestMode
                ? preventionGroups.filter(g => g.isTestData)
                : preventionGroups.filter(g => !g.isTestData);
            
            if (groupsToShow.length === 0) {
                container.innerHTML = `
                    <div style="background: white; padding: 40px; border-radius: 12px; text-align: center;">
                        <div style="font-size: 48px; margin-bottom: 15px;">🛡️</div>
                        <h3 style="color: #666; margin: 0;">No Prevention Groups</h3>
                        <p style="color: #999; margin-top: 10px;">Create a prevention group to block coordinated pass attempts.</p>
                        <button class="btn" onclick="openCreateGroupModal()" style="margin-top: 20px; background: #10b981;">➕ Create New Group</button>
                    </div>
                `;
                return;
            }
            
            container.innerHTML = groupsToShow.map(group => {
                const studentNames = group.students
                    .map(id => students.find(s => s.id === id))
                    .filter(s => s)
                    .map(s => `${s.firstName} ${s.lastName}`)
                    .join(', ');
                
                const recentBlocks = group.blockLog?.slice(-3).reverse() || [];
                
                return `
                    <div style="background: white; padding: 25px; border-radius: 12px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); margin-bottom: 20px; border-left: 4px solid ${group.monitorOnly ? '#3b82f6' : '#B3392F'};">
                        <div style="display: flex; justify-content: space-between; align-items: start; margin-bottom: 15px;">
                            <div>
                                <h3 style="margin: 0 0 5px 0;">${group.name}</h3>
                                <div style="font-size: 14px; color: #666;">
                                    ${group.monitorOnly ? '👁️ Monitor Only' : '🔴 Active Blocking'} | Created ${new Date(group.createdAt).toLocaleDateString()}
                                </div>
                            </div>
                            <div style="display: flex; gap: 8px;">
                                <button class="btn btn-secondary" onclick='editPreventionGroup("${group.id}")' style="padding: 8px 16px;">✏️ Edit</button>
                                <button class="btn" onclick='deletePreventionGroup("${group.id}")' style="padding: 8px 16px; background: #ef4444;">🗑️</button>
                            </div>
                        </div>
                        
                        <div style="background: #f9fafb; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
                            <strong>Students:</strong> ${studentNames}
                        </div>
                        
                        <div style="background: #f9fafb; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
                            <strong>Rules:</strong>
                            <div style="margin-top: 8px;">
                                • Block if within ${group.rules.blockIfWithinMinutes} minutes
                                <br>• Locations: ${group.rules.locations.join(', ')}
                            </div>
                        </div>
                        
                        ${group.reason ? `
                            <div style="background: #fef3c7; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
                                <strong>Reason:</strong> ${group.reason}
                            </div>
                        ` : ''}
                        
                        ${recentBlocks.length > 0 ? `
                            <div style="margin-top: 15px;">
                                <strong>${group.monitorOnly ? '👁️ Monitored Events' : '🚨 Recent Blocks'} (Last 3):</strong>
                                <div style="margin-top: 10px;">
                                    ${recentBlocks.map(block => `
                                        <div style="padding: 10px; background: #f9fafb; border-radius: 6px; margin-bottom: 8px; font-size: 14px;">
                                            ${new Date(block.timestamp).toLocaleString()} - ${block.blockedStudent} ${group.monitorOnly ? 'would have been blocked' : 'blocked'} (${block.activeStudent} had active ${block.location} pass)
                                        </div>
                                    `).join('')}
                                </div>
                            </div>
                        ` : ''}
                    </div>
                `;
            }).join('');
        }
        
        // Edit prevention group
        function editPreventionGroup(groupId) {
            const group = preventionGroups.find(g => g.id === groupId);
            if (!group) return;
            
            encounterGroupToEdit = group;
            groupStudents = group.students
                .map(id => students.find(s => s.id === id))
                .filter(s => s);
            
            document.getElementById('groupModalTitle').textContent = 'Edit Prevention Group';
            document.getElementById('groupName').value = group.name;
            document.getElementById('blockTimeWindow').value = group.rules.blockIfWithinMinutes;
            document.getElementById('monitorOnlyMode').checked = group.monitorOnly;
            document.getElementById('groupReason').value = group.reason || '';
            
            // Set location checkboxes
            document.querySelectorAll('.groupLocation').forEach(cb => {
                cb.checked = group.rules.locations.includes(cb.value);
            });
            
            updateGroupStudentsList();
            
            // Populate student dropdown
            const select = document.getElementById('addStudentSelect');
            select.innerHTML = '<option value="">Select student to add...</option>';
            
            let studentsToShow = encounterTestMode 
                ? students.filter(s => s.isTestData)
                : students.filter(s => !s.isTestData);
            
            studentsToShow.forEach(student => {
                const option = document.createElement('option');
                option.value = student.id;
                option.textContent = `${student.firstName} ${student.lastName} (${student.id})`;
                select.appendChild(option);
            });
            
            document.getElementById('preventionGroupModal').classList.remove('hidden');
        }
        
        // Delete prevention group
        async function deletePreventionGroup(groupId) {
            const group = preventionGroups.find(g => g.id === groupId);
            if (!group) return;
            
            if (!await showConfirm(`Delete prevention group "${group.name}"?\n\nThis cannot be undone.`)) {
                return;
            }
            
            preventionGroups = preventionGroups.filter(g => g.id !== groupId);
            await saveData();
            
            updatePreventionGroupsDisplay();
            alert(`✅ Prevention group "${group.name}" deleted.`);
        }
        
        
        // Dismiss pattern (placeholder)
        function dismissPattern() {
            alert('Pattern dismissed (feature placeholder)');
        }

        // ============================================
        // END CLAW PASS FUNCTIONS
        // ============================================

        async function resetTeacherPassword(teacherId) {
            if (currentUser.role !== 'admin' && currentUser.role !== 'superadmin') {
                alert('Only admins can reset passwords');
                return;
            }

            const teacher = teachers.find(t => t.id === teacherId);
            if (!teacher) {
                alert('Teacher not found');
                return;
            }

            const newPassword = await showPrompt(`Reset password for ${teacher.name}\n\nEnter new password:`);
            
            if (!newPassword) {
                return; // User cancelled
            }

            if (newPassword.length < 4) {
                alert('Password must be at least 4 characters');
                return;
            }

            const confirmPassword = await showPrompt('Confirm new password:');
            
            if (newPassword !== confirmPassword) {
                alert('Passwords do not match. Please try again.');
                return;
            }

            // Update password
            teacher.password = newPassword;
            saveData();
            
            alert(`✅ Password reset successfully for ${teacher.name}\n\nNew password: ${newPassword}\n\nMake sure to share this with the teacher securely!`);
        }

        // ---------------------------------------------------------------
        // Add New Teacher modal.
        //
        // The form used to sit above the teachers list, so the first thing on
        // the page was a form used a handful of times a term while the list
        // people actually came for was pushed below the fold.
        //
        // The form markup itself is untouched: same ids, same addTeacher()
        // handler, same validation. Only its container changed.
        // ---------------------------------------------------------------
        function openAttendanceUploadModal() {
            const modal = document.getElementById('perfectAttendanceUploadModal');
            if (!modal) return;
            modal.classList.remove('hidden');
            modal.style.display = 'flex';
            // The week dropdown is filled by JS from currentWeek. It was
            // populated on page load while this lived inline; opening the modal
            // is now the moment it needs to be right, and currentWeek may have
            // moved since.
            // initPerfectAttendanceUploadUI fills the week dropdown from
            // currentWeek and cycleDuration. It ran once at page load while this
            // panel was inline; opening the modal is now the moment it has to be
            // right, and currentWeek moves during a session.
            if (typeof initPerfectAttendanceUploadUI === 'function') {
                try { initPerfectAttendanceUploadUI(); } catch (e) { console.warn('week list refresh failed', e); }
            }
        }

        function closeAttendanceUploadModal() {
            const modal = document.getElementById('perfectAttendanceUploadModal');
            if (!modal) return;
            modal.classList.add('hidden');
            modal.style.display = 'none';
        }

        document.addEventListener('click', (event) => {
            if (event.target && event.target.id === 'perfectAttendanceUploadModal') closeAttendanceUploadModal();
        });

        document.addEventListener('keydown', (event) => {
            if (event.key !== 'Escape') return;
            const modal = document.getElementById('perfectAttendanceUploadModal');
            if (modal && !modal.classList.contains('hidden')) closeAttendanceUploadModal();
        });

        // ---------------------------------------------------------------
        // Invite staff from the Entra directory.
        //
        // This replaces a form that asked an admin to type a name, a username,
        // an email and a CLEARTEXT PASSWORD, and then stored the password. That
        // field is the reason the Convex migration exists and this was the last
        // thing still creating them.
        //
        // There is no account to create. The person already has one, issued by
        // the organization. An invite is a GRANT: it writes the row saying which
        // role they get, and their next Microsoft sign-in matches on email and
        // finds it. Nothing secret is generated and there is no reset flow.
        // ---------------------------------------------------------------
        let staffSearchTimer = null;
        let staffChosen = null;

        function staffSearchEls() {
            return {
                input: document.getElementById('staffSearchInput'),
                status: document.getElementById('staffSearchStatus'),
                results: document.getElementById('staffSearchResults'),
                chosen: document.getElementById('staffInviteChosen'),
                name: document.getElementById('staffInviteName'),
                email: document.getElementById('staffInviteEmail'),
                role: document.getElementById('staffInviteRole'),
                age: document.getElementById('staffDirectoryAge'),
            };
        }

        /**
         * Debounced, because this fires on every keystroke and each one is a
         * round trip. 250ms is below the threshold where typing feels laggy and
         * well above the rate a person actually types.
         */
        function searchStaffDirectory() {
            const el = staffSearchEls();
            if (!el.input) return;
            clearTimeout(staffSearchTimer);
            const term = el.input.value.trim();

            if (term.length < 2) {
                el.results.style.display = 'none';
                el.status.textContent = term.length ? 'Keep typing...' : '';
                return;
            }
            el.status.textContent = 'Searching...';
            staffSearchTimer = setTimeout(() => runStaffSearch(term), 250);
        }

        async function runStaffSearch(term) {
            const el = staffSearchEls();
            try {
                const auth = window.WildcatAuth;
                const session = auth && auth.getSession();
                if (!session) throw new Error('Sign in with Microsoft to search the directory.');

                const data = await auth.convexQuery('staffInvites:searchDirectory',
                    { q: term, limit: 25 }, session.idToken);

                if (el.age && data.mirroredAt) {
                    el.age.textContent = new Date(data.mirroredAt).toLocaleString();
                }

                if (!data.results.length) {
                    el.results.style.display = 'none';
                    el.status.textContent =
                        `No match for "${term}" in ${data.directorySize || 0} staff accounts.`;
                    return;
                }

                el.status.textContent = `${data.results.length} match${data.results.length === 1 ? '' : 'es'}`;
                el.results.style.display = 'block';
                el.results.innerHTML = data.results.map(p => {
                    const safeName = String(p.name).replace(/"/g, '&quot;');
                    // Somebody who already has access is shown and flagged, not
                    // hidden. Hiding them makes an admin search again for a
                    // colleague they can see in Outlook and decide the search is
                    // broken.
                    const badge = p.alreadyHasAccess
                        ? '<span style="font-size:11px;background:#e2ede5;color:#2f6b45;padding:2px 8px;border-radius:3px;">has access</span>'
                        : '';
                    return `<div onclick="chooseStaff('${p.email}', &quot;${safeName}&quot;)"
                                 style="padding:10px 14px;border-bottom:1px solid #f1f1f1;cursor:pointer;display:flex;justify-content:space-between;gap:12px;align-items:center;"
                                 onmouseover="this.style.background='#f7f7f7'" onmouseout="this.style.background='#fff'">
                              <div style="min-width:0;">
                                <div style="font-weight:600;">${p.name}</div>
                                <div style="color:#6b7280;font-size:13px;overflow:hidden;text-overflow:ellipsis;">${p.email}${p.jobTitle ? ' &middot; ' + p.jobTitle : ''}</div>
                              </div>${badge}
                            </div>`;
                }).join('');
            } catch (err) {
                el.results.style.display = 'none';
                el.status.textContent = err.message;
            }
        }

        function chooseStaff(email, name) {
            staffChosen = { email, name };
            const el = staffSearchEls();
            el.results.style.display = 'none';
            el.chosen.style.display = 'block';
            el.name.textContent = name;
            el.email.textContent = email;
        }

        function clearStaffChoice() {
            staffChosen = null;
            const el = staffSearchEls();
            el.chosen.style.display = 'none';
            el.input.value = '';
            el.status.textContent = '';
        }

        async function sendStaffInvite() {
            if (!staffChosen) return;
            const el = staffSearchEls();
            const role = el.role.value;
            try {
                const auth = window.WildcatAuth;
                const session = auth && auth.getSession();
                if (!session) throw new Error('Sign in with Microsoft first.');

                const result = await auth.convexMutation('staffInvites:inviteStaff',
                    { email: staffChosen.email, role }, session.idToken);

                const what = result.outcome === 'invited'
                    ? `${staffChosen.name} now has ${role} access. They sign in with Microsoft, no password needed.`
                    : result.outcome === 'role-changed'
                        ? `${staffChosen.name} changed from ${result.previousRole} to ${role}.`
                        : `${staffChosen.name} already had ${role} access. Nothing changed.`;
                alert(what);

                // Refresh from the server rather than pushing a row into the
                // local array: the server decides the final shape, and guessing
                // it here is how the two drift.
                if (typeof refreshRosterFromConvex === 'function') {
                    await refreshRosterFromConvex('staff invite');
                }
                updateTeachersTable();
                clearStaffChoice();
                closeAddTeacherModal();
            } catch (err) {
                alert('Could not grant access: ' + err.message);
            }
        }

        function openAddTeacherModal() {
            const modal = document.getElementById('addTeacherModal');
            if (!modal) return;
            modal.classList.remove('hidden');
            modal.style.display = 'flex';
            clearStaffChoice();
            const first = document.getElementById('staffSearchInput');
            if (first) first.focus();
        }

        function closeAddTeacherModal() {
            const modal = document.getElementById('addTeacherModal');
            if (!modal) return;
            modal.classList.add('hidden');
            modal.style.display = 'none';
        }

        // Click the backdrop to dismiss, but only the backdrop. Without the
        // target check, a click that starts inside the form and drifts onto the
        // panel edge closes it and loses whatever was typed.
        document.addEventListener('click', (event) => {
            if (event.target && event.target.id === 'addTeacherModal') closeAddTeacherModal();
        });

        document.addEventListener('keydown', (event) => {
            if (event.key !== 'Escape') return;
            const modal = document.getElementById('addTeacherModal');
            if (modal && !modal.classList.contains('hidden')) closeAddTeacherModal();
        });

        function updateTeachersTable() {
            const tbody = document.getElementById('teachersTable');
            if (!tbody) {
                console.error('Teachers table body not found');
                return;
            }
            
            try {
                const view = paginate('teachers', teachers, true);
                renderPager('teachers', 'teachersTable', view);
                // Roles used to be solid pills in five unrelated colours —
                // crimson, indigo, green, another green, each with an emoji
                // inside it. The emoji forced the label to wrap out of the
                // pill and the row to grow to roughly 200px, so four staff
                // filled a screen. Roles are a category, not a severity: one
                // quiet chip, and the one that actually carries more power is
                // the only one that is tinted.
                const ROLE_CHIP = {
                    superadmin: ['Super Admin', 'wu-chip-warn'],
                    admin: ['Admin', ''],
                    campusaide: ['Campus Aide', ''],
                    pbis: ['PBIS Team', ''],
                    teacher: ['Teacher', '']
                };

                tbody.innerHTML = view.slice.map(t => {
                    const [roleLabel, roleClass] = ROLE_CHIP[t.role] || [String(t.role || 'unknown'), ''];
                    // "N/A" and "0" are answers. A missing username and an
                    // untallied award count are not, and they must not read
                    // like ones.
                    const username = t.username
                        ? escapeHtml(t.username)
                        : '<span class="wu-absent">no username</span>';
                    const email = t.email
                        ? escapeHtml(t.email)
                        : '<span class="wu-absent">no email on file</span>';
                    const awarded = (typeof t.ticketsAwarded === 'number')
                        ? String(t.ticketsAwarded)
                        : '<span class="wu-absent">not counted</span>';

                    return `
                    <tr>
                        <td class="wc-name">${escapeHtml(t.name || 'Unknown')}</td>
                        <td class="cell-muted">${username}</td>
                        <td class="cell-muted">${email}</td>
                        <td><span class="wu-chip ${roleClass}">${escapeHtml(roleLabel)}</span></td>
                        <td class="wc-money">${awarded}</td>
                        <td>
                            <div class="wc-row-actions">
                            <button class="wu-btn wc-btn-sm" onclick="editTeacher('${t.id}')">Edit</button>
                            ${t.id !== currentUser.id ? `
                                <button class="wu-btn wc-btn-sm" onclick="resetTeacherPassword('${t.id}')" title="Send this person a password reset">Reset</button>
                                <button class="wu-btn wc-btn-sm wc-btn-risk" onclick="deleteTeacher('${t.id}')">Delete</button>
                            ` : '<span class="wu-absent">this is you</span>'}
                            </div>
                        </td>
                    </tr>
                `}).join('');
            } catch (error) {
                console.error('Error updating teachers table:', error);
                tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; padding: 20px; color: #dc3545;">Error loading teachers. Please refresh the page.</td></tr>';
            }
        }

        function uploadFile() {
            const fileInput = document.getElementById('fileInput');
            const file = fileInput.files[0];
            
            if (!file) {
                alert('Please select a file first!');
                return;
            }

            const reader = new FileReader();
            reader.onload = function(e) {
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, {type: 'array'});
                const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
                
                // First, try reading as array (no headers)
                const arrayData = XLSX.utils.sheet_to_json(firstSheet, {header: 1});
                
                console.log('First 3 rows as arrays:', arrayData.slice(0, 3));
                
                // Check format type
                // New format: Has header row with "Student Number", "First Name", etc.
                const hasHeaders = arrayData[0] && 
                                  (arrayData[0].includes('Student Number') || 
                                   arrayData[0].includes('First Name'));
                
                if (hasHeaders) {
                    console.log('Detected: New PowerSchool format with headers');
                    importPowerSchoolWithHeaders(arrayData);
                } else {
                    // Old format: 6 columns, row 1 has student ID in column 1
                    const isPowerSchoolOld = arrayData.length >= 2 && 
                                             arrayData[1] && 
                                             arrayData[1].length === 6 &&
                                             /^\d+$/.test(String(arrayData[1][1] || '').trim());
                    
                    console.log('Detected as PowerSchool old format:', isPowerSchoolOld);
                    
                    if (isPowerSchoolOld) {
                        importPowerSchoolSchedule(arrayData);
                    } else {
                        // Try traditional student list import
                        importTraditionalCSV(workbook);
                    }
                }
            };
            reader.readAsArrayBuffer(file);
        }
        
        function importPowerSchoolWithHeaders(data) {
            // New PowerSchool format: [Student Number, First Name, Last Name, Grade, Course, Period, Teacher]
            const studentMap = new Map();
            const teacherSectionMap = new Map();
            
            console.log('Importing new PowerSchool format with headers');
            
            // Start with existing students to preserve their data
            students.forEach(student => {
                studentMap.set(student.id, {
                    ...student,  // Preserve all existing data (tickets, cash, history)
                    sections: [] // Reset sections - will be rebuilt from CSV
                });
            });
            
            // Skip header row (row 0)
            for (let i = 1; i < data.length; i++) {
                const row = data[i];
                if (!row || row.length < 7) continue;
                
                // Extract fields directly (already in correct format!)
                const studentId = String(row[0] || '').trim();
                const firstName = String(row[1] || '').trim();
                const lastName = String(row[2] || '').trim();
                const grade = String(row[3] || '').trim();
                const courseName = String(row[4] || '').trim();
                const periodRaw = String(row[5] || '').trim();
                const teacherName = String(row[6] || '').trim();
                
                // Debug first row
                if (i === 1) {
                    console.log('First student data:');
                    console.log('  Student ID:', studentId);
                    console.log('  First Name:', firstName);
                    console.log('  Last Name:', lastName);
                    console.log('  Grade:', grade);
                    console.log('  Course:', courseName);
                    console.log('  Period:', periodRaw);
                    console.log('  Teacher:', teacherName);
                }
                
                // Skip if missing critical data
                if (!studentId || !firstName || !lastName) continue;
                
                // Extract period from format like "P1(M-Fri)"
                const periodMatch = periodRaw.match(/([A-Z]+\d+)/);
                const period = periodMatch ? periodMatch[1] : periodRaw;
                
                // Parse teacher name (format: "Last, First")
                const teacherParts = teacherName.split(',').map(s => s.trim());
                const teacherLastName = teacherParts[0] || '';
                const teacherFirstName = teacherParts[1] || '';
                const teacherFullName = `${teacherFirstName} ${teacherLastName}`.trim();
                
                // Add student to map if new (preserve existing students)
                if (!studentMap.has(studentId)) {
                    const studentObj = {
                        id: studentId,
                        firstName: firstName,
                        lastName: lastName,
                        grade: grade,
                        pbisTickets: 0,
                        attendanceTickets: 0,
                        academicTickets: 0,
                        bigRaffleQualified: [],
                        weeksQualified: 0,
                        ticketHistory: [],
                        sections: []  // Initialize sections array for student schedules
                    };
                    
                    if (i === 1) {
                        console.log('First student object:', studentObj);
                    }
                    
                    studentMap.set(studentId, studentObj);
                } else {
                    // Update name and grade for existing students (in case they changed)
                    const existingStudent = studentMap.get(studentId);
                    existingStudent.firstName = firstName;
                    existingStudent.lastName = lastName;
                    existingStudent.grade = grade;
                }
                
                // Add this class to the student's sections array
                const student = studentMap.get(studentId);
                if (period && courseName) {
                    if (!student.sections) {
                        console.error('❌ Student has no sections array!', studentId, student);
                        student.sections = [];
                    }
                    student.sections.push({
                        period: period,
                        courseName: courseName,
                        teacherName: teacherFullName || teacherName,
                        teacherId: null  // Will be populated if we match to a teacher account
                    });
                    
                    // Debug first few sections
                    if (i <= 5) {
                        console.log(`Row ${i}: Added ${period} ${courseName} to student ${studentId}`);
                        console.log(`  Student now has ${student.sections.length} sections`);
                    }
                }
                
                // Build teacher section mappings
                if (teacherFullName && courseName && period) {
                    const sectionKey = `${teacherFullName}|${period}|${courseName}`;
                    if (!teacherSectionMap.has(teacherFullName)) {
                        teacherSectionMap.set(teacherFullName, new Map());
                    }
                    
                    const teacherSections = teacherSectionMap.get(teacherFullName);
                    if (!teacherSections.has(sectionKey)) {
                        teacherSections.set(sectionKey, {
                            sectionId: `${period}-${courseName.replace(/\s+/g, '')}`,
                            period: period,
                            courseName: courseName,
                            students: []
                        });
                    }
                    
                    const section = teacherSections.get(sectionKey);
                    if (!section.students.includes(studentId)) {
                        section.students.push(studentId);
                    }
                }
            }
            
            // Convert maps to arrays
            students = Array.from(studentMap.values());
            
            console.log('Total unique students:', students.length);
            console.log('Sample students with sections:', students.slice(0, 3));
            
            // Check how many students have sections
            const studentsWithSections = students.filter(s => s.sections && s.sections.length > 0);
            console.log(`✅ ${studentsWithSections.length} students have schedule data`);
            console.log(`❌ ${students.length - studentsWithSections.length} students have NO schedule data`);
            
            // Show a sample student's full data
            if (students.length > 0) {
                console.log('=== SAMPLE STUDENT ===');
                console.log(students[0]);
                if (students[0].sections) {
                    console.log(`  Has ${students[0].sections.length} classes:`, students[0].sections);
                }
            }
            
            // Save teacher section map globally
            csvScheduleData = teacherSectionMap;
            console.log('Saved CSV schedule data for', csvScheduleData.size, 'teachers');
            
            // Update existing teacher section assignments
            teachers.forEach(teacher => {
                matchTeacherToSections(teacher);
            });
            
            saveData();
            updateAllDisplays();
            updateCSVScheduleStatus();
            
            const teachersWithSections = teachers.filter(t => t.sections && t.sections.length > 0).length;
            alert(`✅ Successfully imported PowerSchool schedule!\n\n` +
                  `📚 ${students.length} students\n` +
                  `👥 ${teachersWithSections} teachers matched with class rosters\n\n` +
                  `✅ All existing ticket balances and cash preserved!\n` +
                  `Students now have their class schedules loaded for period detection!`);
        }
        
        function importPowerSchoolSchedule(data) {
            // PowerSchool format: [Student Name, Student ID, Course, Period, Teacher, Term]
            const studentMap = new Map();
            const teacherSectionMap = new Map();
            
            // Debug: Log first row
            console.log('First row of data:', data[0]);
            console.log('Second row of data:', data[1]);
            console.log('Total rows:', data.length);
            
            // Start with existing students to preserve their data
            students.forEach(student => {
                studentMap.set(student.id, {
                    ...student,  // Preserve all existing data (tickets, cash, history)
                    sections: [] // Reset sections - will be rebuilt from CSV
                });
            });
            
            // Skip first row if it's empty or header
            const startRow = (data[0] && data[0].every(cell => !cell || cell === '')) ? 1 : 0;
            console.log('Starting at row:', startRow);
            
            for (let i = startRow; i < data.length; i++) {
                const row = data[i];
                if (!row || row.length < 6) continue;
                
                // Extract and clean each field
                const fullName = String(row[0] || '').trim();
                const studentId = String(row[1] || '').trim();
                const courseName = String(row[2] || '').trim();
                const periodRaw = String(row[3] || '').trim();
                const teacherName = String(row[4] || '').trim();
                const term = String(row[5] || '').trim();
                
                // Debug: Log first student processing
                if (i === startRow) {
                    console.log('First student data:');
                    console.log('  Full Name:', fullName);
                    console.log('  Student ID:', studentId);
                    console.log('  Course:', courseName);
                    console.log('  Period:', periodRaw);
                    console.log('  Teacher:', teacherName);
                }
                
                // Skip if missing critical data
                if (!studentId || !fullName || studentId === '' || fullName === '') continue;
                
                // Parse student name (format: "Last, First Middle")
                const nameParts = fullName.split(',').map(s => s.trim());
                const lastName = nameParts[0] || '';
                const firstMiddle = nameParts[1] || '';
                const firstName = firstMiddle.split(' ')[0] || '';
                
                // Extract period from format like "P1(M-Fri)" or "A1(M-Fri)"
                const periodMatch = periodRaw.match(/([A-Z]+\d+)/);
                const period = periodMatch ? periodMatch[1] : periodRaw;
                
                // Parse teacher name (format: "Last, First")
                const teacherParts = teacherName.split(',').map(s => s.trim());
                const teacherLastName = teacherParts[0] || '';
                const teacherFirstName = teacherParts[1] || '';
                const teacherFullName = `${teacherFirstName} ${teacherLastName}`.trim();
                
                // Add student to map if new (preserve existing students)
                if (!studentMap.has(studentId)) {
                    // Infer grade from course name (look for numbers like "7B", "10B", "12")
                    let grade = '';
                    const gradeMatch = courseName.match(/\b(\d{1,2})[AB]?\b/);
                    if (gradeMatch) {
                        grade = gradeMatch[1];
                    }
                    
                    const studentObj = {
                        id: studentId,
                        firstName: firstName,
                        lastName: lastName,
                        grade: grade,
                        pbisTickets: 0,
                        attendanceTickets: 0,
                        academicTickets: 0,
                        bigRaffleQualified: [],
                        weeksQualified: 0,
                        ticketHistory: [],
                        sections: []  // Initialize sections array for student schedules
                    };
                    
                    // Debug: Log first student object
                    if (i === startRow) {
                        console.log('First student object created:', studentObj);
                    }
                    
                    studentMap.set(studentId, studentObj);
                } else {
                    // Update name and grade for existing students (in case they changed)
                    const existingStudent = studentMap.get(studentId);
                    existingStudent.firstName = firstName;
                    existingStudent.lastName = lastName;
                    // Update grade if we inferred one
                    const gradeMatch = courseName.match(/\b(\d{1,2})[AB]?\b/);
                    if (gradeMatch) {
                        existingStudent.grade = gradeMatch[1];
                    }
                }
                
                // Add this class to the student's sections array
                const student = studentMap.get(studentId);
                if (period && courseName) {
                    student.sections.push({
                        period: period,
                        courseName: courseName,
                        teacherName: teacherFullName || teacherName,
                        teacherId: null  // Will be populated if we match to a teacher account
                    });
                }
                
                // Build teacher section mappings (only if we have teacher and course info)
                if (teacherFullName && courseName && period) {
                    const sectionKey = `${teacherFullName}|${period}|${courseName}`;
                    if (!teacherSectionMap.has(teacherFullName)) {
                        teacherSectionMap.set(teacherFullName, new Map());
                    }
                    
                    const teacherSections = teacherSectionMap.get(teacherFullName);
                    if (!teacherSections.has(sectionKey)) {
                        teacherSections.set(sectionKey, {
                            sectionId: `${period}-${courseName.replace(/\s+/g, '')}`,
                            period: period,
                            courseName: courseName,
                            students: []
                        });
                    }
                    
                    const section = teacherSections.get(sectionKey);
                    if (!section.students.includes(studentId)) {
                        section.students.push(studentId);
                    }
                }
            }
            
            // Convert maps to arrays
            students = Array.from(studentMap.values());
            
            console.log('Total unique students:', students.length);
            console.log('Sample students:', students.slice(0, 3));
            
            // Save teacher section map globally for future use
            csvScheduleData = teacherSectionMap;
            console.log('Saved CSV schedule data for', csvScheduleData.size, 'teachers');
            
            // Update existing teacher section assignments
            teachers.forEach(teacher => {
                matchTeacherToSections(teacher);
            });
            
            saveData();
            updateAllDisplays();
            updateCSVScheduleStatus();
            
            const teachersWithSections = teachers.filter(t => t.sections && t.sections.length > 0).length;
            alert(`✅ Successfully imported PowerSchool schedule!\n\n` +
                  `📚 ${students.length} students\n` +
                  `👥 ${teachersWithSections} teachers matched with class rosters\n\n` +
                  `Teachers can now use period filtering!`);
        }
        
        // Function to match a teacher to their sections from CSV data
        function matchTeacherToSections(teacher) {
            console.log(`Attempting to match teacher: "${teacher.name}"`);
            
            // Try exact match first
            if (csvScheduleData.has(teacher.name)) {
                const sections = Array.from(csvScheduleData.get(teacher.name).values());
                teacher.sections = sections;
                console.log(`✅ Exact match: ${teacher.name} → ${sections.length} sections`);
                return true;
            }
            
            // Try case-insensitive match
            for (const [csvTeacherName, sectionMap] of csvScheduleData.entries()) {
                if (csvTeacherName.toLowerCase() === teacher.name.toLowerCase()) {
                    const sections = Array.from(sectionMap.values());
                    teacher.sections = sections;
                    console.log(`✅ Case-insensitive match: "${teacher.name}" matched to "${csvTeacherName}" → ${sections.length} sections`);
                    return true;
                }
            }
            
            // Try fuzzy match (handle slight variations)
            const normalizedTeacherName = teacher.name.toLowerCase().replace(/[^a-z]/g, '');
            for (const [csvTeacherName, sectionMap] of csvScheduleData.entries()) {
                const normalizedCSVName = csvTeacherName.toLowerCase().replace(/[^a-z]/g, '');
                if (normalizedCSVName === normalizedTeacherName) {
                    const sections = Array.from(sectionMap.values());
                    teacher.sections = sections;
                    console.log(`✅ Fuzzy match: "${teacher.name}" matched to "${csvTeacherName}" → ${sections.length} sections`);
                    return true;
                }
            }
            
            // No match found
            teacher.sections = [];
            console.log(`❌ No match found for "${teacher.name}"`);
            console.log('Available CSV teachers:', Array.from(csvScheduleData.keys()).slice(0, 5), '...');
            return false;
        }
        
        
        // Update CSV schedule status display
        function updateCSVScheduleStatus() {
            const statusElement = document.getElementById('csvScheduleStatus');
            if (statusElement) {
                if (csvScheduleData.size > 0) {
                    statusElement.textContent = `Yes (${csvScheduleData.size} teachers in CSV)`;
                    statusElement.style.color = '#4CAF50';
                    statusElement.style.fontWeight = 'bold';
                } else {
                    statusElement.textContent = 'No';
                    statusElement.style.color = '#999';
                }
            }
        }
        
        function importTraditionalCSV(workbook) {
            const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(firstSheet);
            
            // Try to detect column names (case-insensitive)
            const firstRow = jsonData[0];
            const keys = Object.keys(firstRow);
            
            // Find ID column
            const idCol = keys.find(k => 
                k.toLowerCase().includes('student') && k.toLowerCase().includes('id') ||
                k.toLowerCase() === 'id' ||
                k.toLowerCase() === 'studentid' ||
                k.toLowerCase() === 'student_id'
            ) || keys[0];
            
            // Find first name column
            const firstNameCol = keys.find(k => 
                k.toLowerCase().includes('first') && k.toLowerCase().includes('name') ||
                k.toLowerCase() === 'firstname' ||
                k.toLowerCase() === 'first_name' ||
                k.toLowerCase() === 'fname'
            );
            
            // Find last name column
            const lastNameCol = keys.find(k => 
                k.toLowerCase().includes('last') && k.toLowerCase().includes('name') ||
                k.toLowerCase() === 'lastname' ||
                k.toLowerCase() === 'last_name' ||
                k.toLowerCase() === 'lname'
            );
            
            // Find full name column if first/last not found
            const fullNameCol = keys.find(k => 
                k.toLowerCase() === 'name' ||
                k.toLowerCase() === 'student name' ||
                k.toLowerCase() === 'studentname' ||
                k.toLowerCase() === 'full name' ||
                k.toLowerCase() === 'fullname'
            );
            
            // Find grade column
            const gradeCol = keys.find(k => 
                k.toLowerCase() === 'grade' ||
                k.toLowerCase().includes('grade')
            );
            
            // Build a map of existing students by ID so we preserve their ticket data
            const existingById = new Map();
            students.forEach(s => existingById.set(String(s.id), s));

            students = jsonData.map((row, index) => {
                let firstName = '';
                let lastName = '';
                
                // Try to get first and last name
                if (firstNameCol && lastNameCol) {
                    firstName = row[firstNameCol] || '';
                    lastName = row[lastNameCol] || '';
                } else if (fullNameCol) {
                    // Split full name
                    const fullName = (row[fullNameCol] || '').trim().split(/\s+/);
                    firstName = fullName[0] || '';
                    lastName = fullName.slice(1).join(' ') || '';
                }
                
                const id = String(row[idCol] || `STU${String(index + 1).padStart(3, '0')}`);
                const existing = existingById.get(id);
                
                if (existing) {
                    // Existing student, preserve ALL their ticket data, only update name/grade/homeroom
                    return {
                        ...existing,
                        firstName: firstName || existing.firstName,
                        lastName: lastName || existing.lastName,
                        grade: gradeCol ? (row[gradeCol] || existing.grade) : existing.grade,
                        homeroom: row['Homeroom'] || row['homeroom'] || existing.homeroom || ''
                    };
                }
                
                // Brand new student
                return {
                    id: id,
                    firstName: firstName,
                    lastName: lastName,
                    grade: gradeCol ? row[gradeCol] : '',
                    homeroom: row['Homeroom'] || row['homeroom'] || '',
                    pbisTickets: 0,
                    attendanceTickets: 0,
                    academicTickets: 0,
                    bigRaffleQualified: [],
                    weeksQualified: 0,
                    ticketHistory: []
                };
            });
            
            // Add back any existing students who were NOT in the CSV (don't silently drop them)
            const importedIds = new Set(students.map(s => String(s.id)));
            existingById.forEach((existing, id) => {
                if (!importedIds.has(id)) {
                    students.push(existing);
                }
            });

            saveData();
            updateAllDisplays();
            alert(`Successfully imported ${students.length} students!`);
        }

        // ============================================================
        // PERFECT ATTENDANCE UPLOAD
        // Admin uploads a CSV of students with perfect attendance for
        // a week. Each listed student receives 1 Attendance ticket.
        // Duplicate-safe: students who already have a Perfect Attendance
        // ticket for the selected week are skipped.
        // ============================================================
        let perfectAttendancePreview = null; // Holds parsed+validated data between preview and confirm

        function initPerfectAttendanceUploadUI() {
            // Populate the week dropdown based on currentWeek + cycleDuration.
            // Perfect Attendance is usually uploaded for the week that JUST ENDED, so we
            // label both the current week and the previous week clearly to reduce the
            // chance of picking the wrong one (a past mismatch caused empty raffle pools).
            const weekSelect = document.getElementById('perfectAttendanceWeek');
            if (!weekSelect) return;
            weekSelect.innerHTML = '';
            const maxWeek = cycleDuration || 5;
            for (let w = 1; w <= maxWeek; w++) {
                const opt = document.createElement('option');
                opt.value = String(w);
                let label = `Week ${w}`;
                if (w === currentWeek) label += ' (Current week)';
                else if (w === currentWeek - 1) label += ' (Last week: most common)';
                opt.textContent = label;
                if (w === currentWeek) opt.selected = true;
                weekSelect.appendChild(opt);
            }
            // Default the date to today (admin can change)
            const dateInput = document.getElementById('perfectAttendanceDate');
            if (dateInput && !dateInput.value) {
                dateInput.value = new Date().toISOString().split('T')[0];
            }
        }

        function parsePerfectAttendanceCSV(text) {
            // Normalize line endings
            const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
            if (lines.length === 0) return { headers: [], rows: [] };

            // Simple CSV parser that handles quoted fields (names contain commas)
            function splitCsvLine(line) {
                const out = [];
                let cur = '';
                let inQuotes = false;
                for (let i = 0; i < line.length; i++) {
                    const ch = line[i];
                    if (ch === '"') {
                        if (inQuotes && line[i + 1] === '"') {
                            // Escaped quote
                            cur += '"';
                            i++;
                        } else {
                            inQuotes = !inQuotes;
                        }
                    } else if (ch === ',' && !inQuotes) {
                        out.push(cur);
                        cur = '';
                    } else {
                        cur += ch;
                    }
                }
                out.push(cur);
                return out.map(s => s.trim());
            }

            const headers = splitCsvLine(lines[0]).map(h => h.trim());
            const rows = [];
            for (let i = 1; i < lines.length; i++) {
                if (!lines[i].trim()) continue;
                const cols = splitCsvLine(lines[i]);
                const obj = {};
                headers.forEach((h, idx) => { obj[h] = cols[idx] !== undefined ? cols[idx] : ''; });
                rows.push(obj);
            }
            return { headers, rows };
        }

        function findPerfectAttendanceColumn(headers, candidates) {
            // Case-insensitive header match
            const lowerHeaders = headers.map(h => h.toLowerCase().trim());
            for (const cand of candidates) {
                const idx = lowerHeaders.indexOf(cand.toLowerCase());
                if (idx >= 0) return headers[idx];
            }
            return null;
        }

        function previewPerfectAttendance() {
            const fileInput = document.getElementById('perfectAttendanceFile');
            const weekSelect = document.getElementById('perfectAttendanceWeek');
            const dateInput = document.getElementById('perfectAttendanceDate');

            if (!fileInput || !fileInput.files || fileInput.files.length === 0) {
                alert('Please select a CSV file first.');
                return;
            }
            if (!weekSelect || !weekSelect.value) {
                alert('Please select a week.');
                return;
            }
            if (!dateInput || !dateInput.value) {
                alert('Please select the week-of date.');
                return;
            }

            const file = fileInput.files[0];
            const reader = new FileReader();
            reader.onload = function(e) {
                const text = e.target.result;
                const { headers, rows } = parsePerfectAttendanceCSV(text);

                if (rows.length === 0) {
                    alert('The CSV appears to be empty or could not be parsed.');
                    return;
                }

                // Locate the Student ID column
                const idCol = findPerfectAttendanceColumn(headers, [
                    'Student ID', 'StudentID', 'Student_ID', 'Student Number',
                    'StudentNumber', 'Student_Number', 'ID'
                ]);

                if (!idCol) {
                    alert(`Could not find a Student ID column. Found headers: ${headers.join(', ')}\n\nExpected one of: Student ID, Student Number, or ID.`);
                    return;
                }

                // Optional columns for verification
                const nameCol = findPerfectAttendanceColumn(headers, ['Name', 'Student Name', 'Full Name']);
                const gradeCol = findPerfectAttendanceColumn(headers, ['Grade Level', 'Grade']);

                const selectedWeek = parseInt(weekSelect.value);
                const weekOfDate = dateInput.value;

                // Categorize each row
                const matched = [];     // Will receive a ticket
                const alreadyAwarded = []; // Already has Perfect Attendance for this week, skip
                const unmatched = [];   // Student ID not in the system
                const invalid = [];     // Row missing an ID

                rows.forEach(row => {
                    const rawId = (row[idCol] || '').toString().trim();
                    if (!rawId) {
                        invalid.push({ row, reason: 'Missing Student ID' });
                        return;
                    }
                    const student = students.find(s => s.id === rawId);
                    if (!student) {
                        unmatched.push({
                            id: rawId,
                            name: nameCol ? (row[nameCol] || '') : '',
                            grade: gradeCol ? (row[gradeCol] || '') : ''
                        });
                        return;
                    }

                    // Check if already awarded Perfect Attendance for this week
                    // Look at ticket history, not counters, counters can include
                    // other Attendance awards (being on time, etc.)
                    const hist = student.ticketHistory || [];
                    const alreadyHasIt = hist.some(h => {
                        if (h.category !== 'Attendance') return false;
                        if (h.week !== selectedWeek) return false;
                        const reason = (h.reason || '').toString();
                        return reason.toLowerCase().includes('perfect attendance');
                    });

                    if (alreadyHasIt) {
                        alreadyAwarded.push({ student });
                    } else {
                        matched.push({ student });
                    }
                });

                // Store for the confirm step
                perfectAttendancePreview = {
                    matched, alreadyAwarded, unmatched, invalid,
                    selectedWeek, weekOfDate,
                    csvFileName: file.name
                };

                // Build the modal body
                const modalBody = document.getElementById('perfectAttendanceModalBody');
                const formatDate = (iso) => {
                    try {
                        const d = new Date(iso + 'T00:00:00');
                        return d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
                    } catch (e) { return iso; }
                };

                let html = `
                    <div style="background: #f0fdf4; border-left: 4px solid #10b981; padding: 15px 18px; border-radius: 8px; margin-bottom: 20px;">
                        <div style="font-size: 13px; color: #065f46; margin-bottom: 4px;">File: <b>${file.name}</b></div>
                        <div style="font-size: 13px; color: #065f46;">Awarding for: <b>Week ${selectedWeek}</b> (Week of ${formatDate(weekOfDate)})</div>
                    </div>

                    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; margin-bottom: 20px;">
                        <div style="background: #d1fae5; padding: 15px; border-radius: 8px; text-align: center;">
                            <div style="font-size: 28px; font-weight: 700; color: #065f46;">${matched.length}</div>
                            <div style="font-size: 12px; color: #065f46; text-transform: uppercase; letter-spacing: 1px;">To award</div>
                        </div>
                        <div style="background: #fef3c7; padding: 15px; border-radius: 8px; text-align: center;">
                            <div style="font-size: 28px; font-weight: 700; color: #92400e;">${alreadyAwarded.length}</div>
                            <div style="font-size: 12px; color: #92400e; text-transform: uppercase; letter-spacing: 1px;">Already have it</div>
                        </div>
                        <div style="background: #fee2e2; padding: 15px; border-radius: 8px; text-align: center;">
                            <div style="font-size: 28px; font-weight: 700; color: #991b1b;">${unmatched.length}</div>
                            <div style="font-size: 12px; color: #991b1b; text-transform: uppercase; letter-spacing: 1px;">Unmatched</div>
                        </div>
                        <div style="background: #f3f4f6; padding: 15px; border-radius: 8px; text-align: center;">
                            <div style="font-size: 28px; font-weight: 700; color: #374151;">${invalid.length}</div>
                            <div style="font-size: 12px; color: #374151; text-transform: uppercase; letter-spacing: 1px;">Invalid rows</div>
                        </div>
                    </div>
                `;

                if (unmatched.length > 0) {
                    html += `
                        <div style="margin-bottom: 18px;">
                            <div style="font-weight: 600; color: #991b1b; margin-bottom: 8px; font-size: 14px;">⚠️ Unmatched students (${unmatched.length}), these IDs are not in the system and will be skipped:</div>
                            <div style="background: #fef2f2; padding: 10px 14px; border-radius: 6px; max-height: 120px; overflow-y: auto; font-size: 12px; color: #7f1d1d;">
                                ${unmatched.map(u => `ID ${u.id}${u.name ? ' — ' + u.name : ''}${u.grade ? ' (Grade ' + u.grade + ')' : ''}`).join('<br>')}
                            </div>
                        </div>
                    `;
                }

                if (alreadyAwarded.length > 0) {
                    html += `
                        <div style="margin-bottom: 18px;">
                            <div style="font-weight: 600; color: #92400e; margin-bottom: 8px; font-size: 14px;">Already have Perfect Attendance for Week ${selectedWeek} (${alreadyAwarded.length}), will be skipped:</div>
                            <div style="background: #fffbeb; padding: 10px 14px; border-radius: 6px; max-height: 120px; overflow-y: auto; font-size: 12px; color: #78350f;">
                                ${alreadyAwarded.map(a => `${a.student.firstName} ${a.student.lastName} (Grade ${a.student.grade})`).join('<br>')}
                            </div>
                        </div>
                    `;
                }

                if (matched.length > 0) {
                    html += `
                        <div style="margin-bottom: 10px;">
                            <div style="font-weight: 600; color: #065f46; margin-bottom: 8px; font-size: 14px;">✓ Will receive 1 Attendance ticket (${matched.length}):</div>
                            <div style="background: #f0fdf4; padding: 10px 14px; border-radius: 6px; max-height: 200px; overflow-y: auto; font-size: 12px; color: #065f46;">
                                ${matched.map(m => `${m.student.firstName} ${m.student.lastName} (Grade ${m.student.grade})`).join('<br>')}
                            </div>
                        </div>
                    `;
                } else {
                    html += `
                        <div style="background: #f3f4f6; padding: 15px; border-radius: 8px; text-align: center; color: #6b7280; font-size: 14px;">
                            No tickets to award. All students in the CSV either already have Perfect Attendance for this week, or are unmatched.
                        </div>
                    `;
                }

                modalBody.innerHTML = html;

                // Disable confirm if nothing to award
                const confirmBtn = document.getElementById('perfectAttendanceConfirmBtn');
                if (confirmBtn) {
                    if (matched.length === 0) {
                        confirmBtn.disabled = true;
                        confirmBtn.style.opacity = '0.5';
                        confirmBtn.style.cursor = 'not-allowed';
                    } else {
                        confirmBtn.disabled = false;
                        confirmBtn.style.opacity = '1';
                        confirmBtn.style.cursor = 'pointer';
                        confirmBtn.textContent = `Confirm & Award ${matched.length} Ticket${matched.length === 1 ? '' : 's'}`;
                    }
                }

                // Show the modal
                document.getElementById('perfectAttendanceModal').style.display = 'flex';
            };
            reader.onerror = function() {
                alert('Error reading file.');
            };
            reader.readAsText(file);
        }

        function closePerfectAttendanceModal() {
            document.getElementById('perfectAttendanceModal').style.display = 'none';
        }

        async function confirmPerfectAttendance() {
            if (!perfectAttendancePreview || perfectAttendancePreview.matched.length === 0) {
                alert('Nothing to award.');
                return;
            }
            const { matched, selectedWeek, weekOfDate, csvFileName } = perfectAttendancePreview;

            // Format the date for the ticket reason
            const dateLabel = (() => {
                try {
                    const d = new Date(weekOfDate + 'T00:00:00');
                    return d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
                } catch (e) {
                    return weekOfDate;
                }
            })();
            const ticketReason = `Perfect Attendance - Week of ${dateLabel}`;

            // Disable the button to prevent double-submit
            const confirmBtn = document.getElementById('perfectAttendanceConfirmBtn');
            if (confirmBtn) {
                confirmBtn.disabled = true;
                confirmBtn.textContent = 'Awarding...';
                confirmBtn.style.opacity = '0.6';
            }

            // Award 1 Attendance ticket to each matched student
            const awardTimestamp = new Date().toISOString();
            matched.forEach(({ student }, idx) => {
                if (!student.ticketHistory) student.ticketHistory = [];

                // Stagger timestamps by 1ms to keep entryIds unique within the batch
                const ts = new Date(Date.now() + idx).toISOString();

                student.attendanceTickets = (student.attendanceTickets || 0) + 1;
                student.ticketHistory.push({
                    timestamp: ts,
                    teacher: currentUser.name,
                    teacherId: currentUser.id,
                    category: 'Attendance',
                    tickets: 1,
                    reason: ticketReason,
                    week: selectedWeek,
                    cycle: getCurrentCycleNumber()
                });

                // Audit log entry, pass selectedWeek so the audit entry's week matches
                // the ticket-history entry's week. Previously this used currentWeek, which
                // diverged from the history when awarding for a past week and broke raffle pools.
                addToAuditLog('Awarded Tickets', student.id, 'Attendance', 1, ticketReason, null, selectedWeek);
            });

            // Single save at the end — one Firebase save for the whole batch
            try {
                await saveData();
                closePerfectAttendanceModal();
                updateAllDisplays();
                alert(`✅ Awarded Perfect Attendance to ${matched.length} student${matched.length === 1 ? '' : 's'} for Week ${selectedWeek}.`);
            } catch (err) {
                console.error('Perfect Attendance save failed:', err);
                alert(`⚠️ Save encountered an error. Tickets are in local memory and will sync on next save.\n\nError: ${err?.message || err}`);
                if (confirmBtn) {
                    confirmBtn.disabled = false;
                    confirmBtn.textContent = 'Retry Save';
                    confirmBtn.style.opacity = '1';
                }
            }

            // Clear preview state
            perfectAttendancePreview = null;
        }

