        /**
         * The students a teacher should see today: currently enrolled only.
         *
         * Convex holds 734 students and the current term's roster holds 646. The
         * other 88 are prior year students who are kept rather than deleted,
         * because a transferred student still has a balance and a roster gap is
         * not proof a person ceased to exist. They simply do not belong on a page
         * used to award tickets today.
         *
         * `enrolled` is computed server side from psRoster, which is replaced
         * wholesale on every sync and therefore only ever holds the current term.
         *
         * The test is `!== false`, not truthy. A student record predating this
         * flag is an UNKNOWN, and hiding an unknown is how a real child silently
         * disappears from a teacher's list. Unknowns show; only an explicit false
         * hides.
         *
         * One function rather than the same filter at each call site, because the
         * fourth call site is the one that forgets.
         */
        function enrolledStudents() {
            return students.filter(s => s.enrolled !== false);
        }

        function updateStudentsTable() {
            // Reset search box and cache
            const searchBox = document.getElementById('studentSearchBox');
            if (searchBox) searchBox.value = '';
            filteredStudentsCache = [];
            currentSort = { column: null, direction: 'asc' };
            
            // Reset sort arrows
            document.querySelectorAll('.sort-arrow').forEach(arrow => {
                arrow.textContent = '↕';
                arrow.style.opacity = '0.3';
            });
            
            const tbody = document.getElementById('studentsTableBody');
            if (students.length === 0) {
                tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; padding: 40px; color: #999;">No students loaded. Upload a file to get started!</td></tr>';
                return;
            }

            // CURRENTLY ENROLLED ONLY.
            //
            // Convex holds 734 students and the current term's roster holds 646.
            // The other 88 are prior year students who are kept, not deleted,
            // because a transferred student still has a balance. They do not
            // belong on a page teachers use to award tickets today.
            //
            // `enrolled` is computed server side from psRoster, which is replaced
            // wholesale on every sync and therefore only ever holds the current
            // term. The check is `=== false` rather than falsy so that a student
            // record predating this flag still shows up: an unflagged student is
            // an unknown, and hiding an unknown is how a real child silently
            // disappears from a teacher's list.
            let filteredStudents = enrolledStudents();

            if (currentGradeFilter !== 'all') {
                filteredStudents = filteredStudents.filter(s => {
                    const grade = parseInt(s.grade) || 'Unknown';
                    return grade.toString() === currentGradeFilter;
                });
            }

            if (filteredStudents.length === 0) {
                tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; padding: 40px; color: #999;">No students found for the selected grade level.</td></tr>';
                return;
            }

            renderStudentTable(filteredStudents);
        }
        
        let currentStudentView = 'grade'; // 'grade' or 'all'
        let currentGradeFilter = 'all'; // Track which grade is selected
        
        // The grade filter is a row of chips now, not a <select>. Same state,
        // same single call site: the chips pass their value in, and the old
        // no-argument call still works if anything anywhere still makes it.
        //
        // A chip row rather than a styled dropdown because a teacher scanning
        // 623 rows wants grade 9 in one click, and because a keyboard reaches
        // every grade without opening a menu first.
        function filterByGrade(value) {
            if (typeof value === 'string') {
                currentGradeFilter = value;
            } else {
                const dropdown = document.getElementById('gradeFilterDropdown');
                currentGradeFilter = dropdown ? dropdown.value : 'all';
            }

            document.querySelectorAll('#studentGradeChips .wu-filter').forEach(chip => {
                chip.setAttribute('aria-pressed',
                    String(chip.dataset.grade === currentGradeFilter));
            });

            // Always use table view
            updateStudentsTable();
        }
        
        // ============================================
        // ENHANCED TABLE FEATURES
        // ============================================
        
        let currentSort = { column: null, direction: 'asc' };
        let filteredStudentsCache = [];
        
        // Search students by name or ID
        function searchStudents() {
            console.log('=== SEARCH FUNCTION CALLED ===');
            
            const searchBox = document.getElementById('studentSearchBox');
            console.log('Search box element:', searchBox);
            
            const searchTerm = searchBox ? searchBox.value.toLowerCase().trim() : '';
            console.log('Search term:', searchTerm);
            console.log('Total students:', students.length);
            console.log('Current grade filter:', currentGradeFilter);
            
            // Start with the currently enrolled, not every student on record.
            let filteredStudents = enrolledStudents();
            console.log('Starting with students:', filteredStudents.length);
            
            // Apply grade filter first
            if (currentGradeFilter !== 'all') {
                filteredStudents = filteredStudents.filter(s => {
                    const grade = parseInt(s.grade) || 'Unknown';
                    return grade.toString() === currentGradeFilter;
                });
                console.log('After grade filter:', filteredStudents.length);
            }
            
            // Apply search filter
            if (searchTerm) {
                console.log('Applying search filter for:', searchTerm);
                filteredStudents = filteredStudents.filter(s => {
                    const fullName = `${s.firstName} ${s.lastName}`.toLowerCase();
                    const id = (s.id || '').toString().toLowerCase();
                    const matches = fullName.includes(searchTerm) || id.includes(searchTerm);
                    if (matches) {
                        console.log('Match found:', fullName, id);
                    }
                    return matches;
                });
                console.log('After search filter:', filteredStudents.length);
            }
            
            // Cache and render
            filteredStudentsCache = filteredStudents;
            console.log('Calling renderStudentTable with', filteredStudents.length, 'students');
            renderStudentTable(filteredStudents);
            
            console.log(`✅ Search complete: "${searchTerm}" | Grade: ${currentGradeFilter} | Found: ${filteredStudents.length} students`);
        }
        
        // Sort table by column
        function sortTable(column) {
            // Toggle direction if same column, otherwise default to ascending
            if (currentSort.column === column) {
                currentSort.direction = currentSort.direction === 'asc' ? 'desc' : 'asc';
            } else {
                currentSort.column = column;
                currentSort.direction = 'asc';
            }
            
            // Update sort arrows
            document.querySelectorAll('.sort-arrow').forEach(arrow => {
                arrow.textContent = '↕';
                arrow.style.opacity = '0.3';
            });
            const arrow = document.getElementById(`sort-${column}`);
            if (arrow) {
                arrow.textContent = currentSort.direction === 'asc' ? '↑' : '↓';
                arrow.style.opacity = '1';
            }
            
            // Get current filtered students (from search/grade filter)
            let studentsToSort = filteredStudentsCache.length > 0 ? [...filteredStudentsCache] : enrolledStudents();
            if (currentGradeFilter !== 'all' && filteredStudentsCache.length === 0) {
                studentsToSort = enrolledStudents().filter(s => {
                    const grade = parseInt(s.grade) || 'Unknown';
                    return grade.toString() === currentGradeFilter;
                });
            }
            
            // Sort
            studentsToSort.sort((a, b) => {
                let aVal, bVal;
                
                switch(column) {
                    case 'id':
                        aVal = a.id;
                        bVal = b.id;
                        break;
                    case 'name':
                        aVal = `${a.firstName} ${a.lastName}`;
                        bVal = `${b.firstName} ${b.lastName}`;
                        break;
                    case 'grade':
                        aVal = parseInt(a.grade) || 0;
                        bVal = parseInt(b.grade) || 0;
                        break;
                    case 'pbis':
                        aVal = a.pbisTickets || 0;
                        bVal = b.pbisTickets || 0;
                        break;
                    case 'attendance':
                        aVal = a.attendanceTickets || 0;
                        bVal = b.attendanceTickets || 0;
                        break;
                    case 'academic':
                        aVal = a.academicTickets || 0;
                        bVal = b.academicTickets || 0;
                        break;
                    case 'total':
                        aVal = (a.pbisTickets || 0) + (a.attendanceTickets || 0) + (a.academicTickets || 0);
                        bVal = (b.pbisTickets || 0) + (b.attendanceTickets || 0) + (b.academicTickets || 0);
                        break;
                    default:
                        return 0;
                }
                
                if (typeof aVal === 'string') {
                    return currentSort.direction === 'asc' 
                        ? aVal.localeCompare(bVal)
                        : bVal.localeCompare(aVal);
                } else {
                    return currentSort.direction === 'asc' 
                        ? aVal - bVal
                        : bVal - aVal;
                }
            });
            
            renderStudentTable(studentsToSort);
        }
        
        // Render student table (separated from filtering logic)
        // ---------------------------------------------------------------
        // Pagination.
        //
        // The roster went from 446 to 646 when the app started reading the SIS
        // through Convex, and every one of those rows was being written into the
        // DOM at once. Both tables share this so they cannot drift apart in
        // behaviour, which is what happens when the second one is copied from
        // the first and then fixed in only one place.
        //
        // State is keyed by table id rather than held in two globals, for the
        // same reason.
        // ---------------------------------------------------------------
        const PAGE_SIZE = 50;
        // Per-table overrides. A dense roster reads fine at 50; a detail list
        // (the hall-pass history) wants fewer, taller rows, so it takes 25.
        // Anything not listed uses PAGE_SIZE.
        const PAGE_SIZES = { passHistory: 25 };
        const pageSizeFor = (key) => PAGE_SIZES[key] || PAGE_SIZE;
        const pagerState = {};

        /**
         * The slice to draw, plus the controls under it.
         *
         * `rows` is the FULL filtered list, not a page. Callers keep passing
         * everything they already had and this decides what is visible, so
         * search, sort and grade filtering did not have to learn about paging.
         *
         * Page resets to 1 whenever the list changes, which is what somebody
         * expects after typing in a search box. Paging itself passes keepPage.
         */
        function paginate(key, rows, keepPage) {
            const size = pageSizeFor(key);
            const state = pagerState[key] || (pagerState[key] = { page: 1 });
            const pages = Math.max(1, Math.ceil(rows.length / size));
            if (!keepPage) state.page = 1;
            // Deleting the last student on the last page must not strand the
            // view on a page that no longer exists.
            if (state.page > pages) state.page = pages;
            const start = (state.page - 1) * size;
            return {
                slice: rows.slice(start, start + size),
                page: state.page,
                pages,
                total: rows.length,
                from: rows.length === 0 ? 0 : start + 1,
                to: Math.min(start + size, rows.length),
            };
        }

        /**
         * Move one table to a page and redraw it through its own renderer.
         *
         * Every paginated renderer takes a keepPage flag and, when it is true,
         * re-reads its own search/filter inputs and rebuilds the SAME filtered
         * set before slicing — so paging never fights the filters, it just moves
         * the window over whatever they narrowed to.
         */
        function goToPage(key, page) {
            const state = pagerState[key];
            if (!state) return;
            state.page = page;
            switch (key) {
                case 'students':    renderStudentTable(lastStudentRows, true); break;
                case 'teachers':    updateTeachersTable(); break;
                case 'cash':        updateCashTable(true); break;
                case 'tickets':     updateTicketsTable(true); break;
                case 'audit':       updateAuditLogTable(true); break;
                case 'cashAudit':   updateCashAuditLogTable(true); break;
                case 'login':       updateLoginActivityTable(true); break;
                case 'bigRaffle':   updateBigRaffleTable(true); break;
                case 'passHistory': updatePassHistory(true); break;
                default: break;
            }
        }

        /**
         * Controls drawn under a table, into a container created on demand.
         *
         * Created rather than required in index.html so this works for every
         * table without touching markup, and so a table that has not been
         * paginated yet simply has no controls instead of a broken layout.
         *
         * Styled with the shared wu- primitives: the buttons are .wu-btn (whose
         * hover already lives in a (hover: hover) gate, so nothing sticks on a
         * tablet), the bar is .wu-pager in wildcat-ui.css. Compact on purpose —
         * one line, no tall control bar eating the rows above the fold.
         *
         * Hidden entirely on a single page: a pager that always says "Page 1 of
         * 1" is noise, and a table that already fits shows none.
         */
        function renderPager(key, containerAfterId, info) {
            const table = document.getElementById(containerAfterId);
            if (!table) return;
            const host = table.closest('table') || table;
            const id = key + 'Pager';
            let bar = document.getElementById(id);
            if (!bar) {
                bar = document.createElement('div');
                bar.id = id;
                bar.className = 'wu-pager';
                host.parentNode.insertBefore(bar, host.nextSibling);
            }
            if (!info || info.pages <= 1) {
                bar.innerHTML = '';
                bar.style.display = 'none';
                return;
            }
            bar.style.display = 'flex';
            const btn = (label, page, disabled, aria) =>
                `<button type="button" class="wu-btn wc-btn-sm" onclick="goToPage('${key}', ${page})"` +
                `${disabled ? ' disabled' : ''} aria-label="${aria}">${label}</button>`;
            bar.innerHTML =
                `<span class="wu-pager__count">${info.from}–${info.to} of ${info.total}</span>` +
                `<span class="wu-pager__nav">` +
                btn('‹ Prev', info.page - 1, info.page === 1, 'Previous page') +
                `<span class="wu-pager__page">Page ${info.page} of ${info.pages}</span>` +
                btn('Next ›', info.page + 1, info.page === info.pages, 'Next page') +
                `</span>`;
        }

        /** The full list last handed to renderStudentTable, so paging can redraw. */
        let lastStudentRows = [];

        function renderStudentTable(studentsToRender, keepPage) {
            const tbody = document.getElementById('studentsTableBody');

            lastStudentRows = studentsToRender;

            if (studentsToRender.length === 0) {
                tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; padding: 40px; color: #999;">No students found matching your criteria.</td></tr>';
                renderPager('students', 'studentsTableBody', { pages: 1 });
                const t0 = document.getElementById('totalStudents');
                const q0 = document.getElementById('qualifiedStudents');
                if (t0) t0.textContent = '0';
                if (q0) q0.textContent = '0';
                return;
            }

            const view = paginate('students', studentsToRender, keepPage);
            renderPager('students', 'studentsTableBody', view);

            tbody.innerHTML = view.slice.map(s => {
                // Check if student currently has all 3 ticket types (real-time qualification)
                const hasAllThreeTickets = s.pbisTickets > 0 && s.attendanceTickets > 0 && s.academicTickets > 0;
                
                // Generate category status indicators
                const pbisColor = s.pbisTickets > 0 ? '#B3392F' : '#e5e7eb';  // Red if has tickets, gray if not
                const attendanceColor = s.attendanceTickets > 0 ? '#2E7D52' : '#e5e7eb';  // Green if has tickets, gray if not
                const academicColor = s.academicTickets > 0 ? '#3b82f6' : '#e5e7eb';  // Blue if has tickets, gray if not
                
                // Determine status display.
                //
                // The three states used to be a green gradient pill that
                // pulsed, a blue pill, and an amber gradient pill that also
                // pulsed — plus three 16px shadowed dots for everyone else.
                // On 623 rows that is 623 animations and five different
                // colours competing with the data. The states are the same;
                // they just stopped shouting.
                const dots = (on) => `<span class="qual-dot${on ? ' qual-dot-on' : ''}"></span>`;
                let statusHTML = '';
                if (isQualifiedForJackpot(s) && hasAllThreeTickets) {
                    statusHTML = '<span class="qualified-badge wc-badge-locked">&#127942; Locked in</span>';
                } else if (isQualifiedForJackpot(s)) {
                    statusHTML = '<span class="qualified-badge">Qualified</span>';
                } else if (hasAllThreeTickets) {
                    statusHTML = '<span class="qualified-badge wc-badge-track">On track</span>';
                } else {
                    statusHTML = `<span class="qual-dots" title="PBIS · Attendance · Academic">${
                        dots(s.pbisTickets > 0)}${dots(s.attendanceTickets > 0)}${dots(s.academicTickets > 0)}</span>`;
                }

                const cnt = (n, label) =>
                    `<span class="ticket-badge${(Number(n) || 0) > 0 ? ' wc-has' : ''}" title="${label}">${Number(n) || 0}</span>`;

                return `
                <tr class="wc-student-row" onclick="openStudentProfile('${s.id}')" tabindex="0"
                    role="button" aria-label="Open ${escapeHtml(s.firstName)} ${escapeHtml(s.lastName)}"
                    onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openStudentProfile('${s.id}')}">
                    <td>${s.id}</td>
                    <td>
                        <span class="student-link">${escapeHtml(s.firstName)} ${escapeHtml(s.lastName)}</span>
                    </td>
                    <td>${(s.grade === undefined || s.grade === null || s.grade === '')
                            ? '<span class="wu-absent">not on file</span>' : escapeHtml(String(s.grade))}</td>
                    <td>${cnt(s.pbisTickets, 'PBIS')}</td>
                    <td>${cnt(s.attendanceTickets, 'Attendance')}</td>
                    <td>${cnt(s.academicTickets, 'Academic')}</td>
                    <td>${statusHTML}</td>
                </tr>
            `;
            }).join('');

            // The two figures above the table. They are markup-only elements
            // that no code has ever written to, so they have been reading a
            // hard-coded "0" on every roster this app has ever shown — the
            // exact failure the app-wide rule forbids: a missing value
            // rendering as a real one. They count the rows actually on
            // screen, so they answer the filter the teacher just applied.
            const totalEl = document.getElementById('totalStudents');
            const qualEl = document.getElementById('qualifiedStudents');
            if (totalEl) totalEl.textContent = String(studentsToRender.length);
            if (qualEl) qualEl.textContent = String(studentsToRender.filter(isQualifiedForJackpot).length);

            // First paint of the roster only. This function also runs on
            // every keystroke of the search box and on every ticket award;
            // a stagger there would make the table flash under a teacher's
            // hands. The guard is keyed on the tbody, which is not
            // replaced by the innerHTML above.
            wcRows(tbody, 12);
        }
        
        // Export to Excel
        function exportToExcel() {
            // Get current filtered/sorted students
            let studentsToExport = filteredStudentsCache.length > 0 ? filteredStudentsCache : students;
            if (currentGradeFilter !== 'all' && filteredStudentsCache.length === 0) {
                studentsToExport = students.filter(s => {
                    const grade = parseInt(s.grade) || 'Unknown';
                    return grade.toString() === currentGradeFilter;
                });
            }
            
            if (studentsToExport.length === 0) {
                alert('No students to export!');
                return;
            }
            
            // Create CSV content
            const headers = ['Student ID', 'First Name', 'Last Name', 'Grade', 'PBIS Tickets', 'Attendance Tickets', 'Academic Tickets', 'Total Tickets', 'Qualified for Big Raffle'];
            const csvContent = [
                headers.join(','),
                ...studentsToExport.map(s => {
                    const total = (s.pbisTickets || 0) + (s.attendanceTickets || 0) + (s.academicTickets || 0);
                    return [
                        s.id,
                        s.firstName,
                        s.lastName,
                        s.grade,
                        s.pbisTickets || 0,
                        s.attendanceTickets || 0,
                        s.academicTickets || 0,
                        total,
                        isQualifiedForJackpot(s) ? 'Yes' : 'No'
                    ].join(',');
                })
            ].join('\n');
            
            // Download file
            const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
            const link = document.createElement('a');
            const url = URL.createObjectURL(blob);
            link.setAttribute('href', url);
            link.setAttribute('download', `students_week${currentWeek}_${new Date().toISOString().split('T')[0]}.csv`);
            link.style.visibility = 'hidden';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            
            showSuccessToast('📥 Student data exported to Excel!');
        }
        
        // ============================================
        // DATA VISUALIZATION CHARTS
        // ============================================
        
        let ticketPieChart = null;
        let ticketsByGradeChart = null;
        
        function updateCharts() {
            updateTicketPieChart();
            updateTicketsByGradeChart();
        }
        
        function updateTicketPieChart() {
            const ctx = document.getElementById('ticketPieChart');
            if (!ctx) return;
            
            // Calculate totals
            let totalPBIS = 0;
            let totalAttendance = 0;
            let totalAcademic = 0;
            
            students.forEach(s => {
                totalPBIS += s.pbisTickets || 0;
                totalAttendance += s.attendanceTickets || 0;
                totalAcademic += s.academicTickets || 0;
            });
            
            // Destroy existing chart
            if (ticketPieChart) {
                ticketPieChart.destroy();
            }
            
            // Create new chart
            ticketPieChart = new Chart(ctx, {
                type: 'doughnut',
                data: {
                    labels: ['PBIS Behaviors', 'Perfect Attendance', 'Academics'],
                    datasets: [{
                        data: [totalPBIS, totalAttendance, totalAcademic],
                        backgroundColor: [
                            'rgba(47, 103, 167, 0.85)',
                            'rgba(12, 68, 124, 0.85)',
                            'rgba(201, 196, 78, 0.9)'
                        ],
                        borderColor: [
                            'rgba(47, 103, 167, 1)',
                            'rgba(12, 68, 124, 1)',
                            'rgba(201, 196, 78, 1)'
                        ],
                        borderWidth: 2
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: true,
                    plugins: {
                        legend: {
                            position: 'bottom',
                            labels: {
                                padding: 15,
                                font: {
                                    size: 12
                                }
                            }
                        },
                        tooltip: {
                            callbacks: {
                                label: function(context) {
                                    const label = context.label || '';
                                    const value = context.parsed || 0;
                                    const total = context.dataset.data.reduce((a, b) => a + b, 0);
                                    const percentage = ((value / total) * 100).toFixed(1);
                                    return `${label}: ${value} tickets (${percentage}%)`;
                                }
                            }
                        }
                    }
                }
            });
        }
        
        function updateTicketsByGradeChart() {
            const ctx = document.getElementById('ticketsByGradeChart');
            if (!ctx) return;
            
            // Calculate tickets by grade
            const gradeData = {};
            students.forEach(s => {
                const grade = s.grade || 'Unknown';
                if (!gradeData[grade]) {
                    gradeData[grade] = { pbis: 0, attendance: 0, academic: 0 };
                }
                gradeData[grade].pbis += s.pbisTickets || 0;
                gradeData[grade].attendance += s.attendanceTickets || 0;
                gradeData[grade].academic += s.academicTickets || 0;
            });
            
            // Sort grades
            const grades = Object.keys(gradeData).sort((a, b) => {
                const aNum = parseInt(a);
                const bNum = parseInt(b);
                if (isNaN(aNum)) return 1;
                if (isNaN(bNum)) return -1;
                return aNum - bNum;
            });
            
            // Destroy existing chart
            if (ticketsByGradeChart) {
                ticketsByGradeChart.destroy();
            }
            
            // Create new chart
            ticketsByGradeChart = new Chart(ctx, {
                type: 'bar',
                data: {
                    labels: grades.map(g => `Grade ${g}`),
                    datasets: [
                        {
                            label: 'PBIS',
                            data: grades.map(g => gradeData[g].pbis),
                            backgroundColor: 'rgba(47, 103, 167, 0.85)',
                            borderColor: 'rgba(47, 103, 167, 1)',
                            borderWidth: 2
                        },
                        {
                            label: 'Attendance',
                            data: grades.map(g => gradeData[g].attendance),
                            backgroundColor: 'rgba(12, 68, 124, 0.85)',
                            borderColor: 'rgba(12, 68, 124, 1)',
                            borderWidth: 2
                        },
                        {
                            label: 'Academic',
                            data: grades.map(g => gradeData[g].academic),
                            backgroundColor: 'rgba(201, 196, 78, 0.9)',
                            borderColor: 'rgba(201, 196, 78, 1)',
                            borderWidth: 2
                        }
                    ]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: true,
                    scales: {
                        y: {
                            beginAtZero: true,
                            ticks: {
                                stepSize: 1
                            }
                        }
                    },
                    plugins: {
                        legend: {
                            position: 'bottom',
                            labels: {
                                padding: 10,
                                font: {
                                    size: 12
                                }
                            }
                        }
                    }
                }
            });
        }
        
        // ============================================
        // STUDENT PROFILE MODAL
        // ============================================
        
        // The student the modal is currently open on, and a monotonic counter so
        // a slow Profile fetch for student A can never paint into student B's
        // modal. A teacher clicking down a class list is exactly the pattern
        // that produces that race, and the wrong child's absences under the
        // right child's name is not a bug anybody would report as one.
        let spStudent = null;
        let spRequestSeq = 0;
        let spLoadedFor = null;

        function openStudentProfile(studentId) {
            const student = students.find(s => s.id === studentId);
            if (!student) {
                alert('Student not found!');
                return;
            }

            spStudent = student;
            spRequestSeq += 1;
            spLoadedFor = null;
            switchStudentProfileTab('points');
            const body = document.getElementById('spProfileBody');
            if (body) body.innerHTML = '';

            // Show modal
            document.getElementById('studentProfileModal').style.display = 'block';
            document.body.style.overflow = 'hidden';

            // Populate header
            const totalTickets = (student.pbisTickets || 0) + (student.attendanceTickets || 0) + (student.academicTickets || 0);
            const initials = `${student.firstName.charAt(0)}${student.lastName.charAt(0)}`;
            
            // Initials in a tinted circle, never a photograph. The reference
            // leans on student avatars; we have no student photos, and putting
            // a child's face on a screen that gets projected in a classroom is
            // a decision nobody at this school has made.
            // The pill this lands in is white now, so an absent grade uses the
            // ordinary faint colour rather than a white-on-blue override.
            const gradeText = (student.grade === undefined || student.grade === null || student.grade === '')
                ? '<span class="wu-absent" style="font-size:inherit;">grade not on file</span>'
                : `Grade ${student.grade}`;

            // 05-student-detail-staff-view: the school is the display title,
            // the person is the white pill under it. The pill's chevron goes
            // to the Profile tab, which is a real destination — a chevron on
            // a control that does nothing is worse than no chevron.
            document.getElementById('profileHeader').innerHTML = `
                <h2 class="wu-identity-title"><span class="wu-line">Westbrook</span><span class="wu-line">Academy</span></h2>
                <button type="button" class="wu-person" onclick="switchStudentProfileTab('profile')"
                        aria-label="Open this student's profile">
                    <span class="wu-avatar" aria-hidden="true">${initials}</span>
                    <span class="wu-person-main">
                        <span class="wu-person-name">${student.firstName} ${student.lastName}</span>
                        <span class="wu-person-sub">${gradeText} &middot; ID ${student.id}</span>
                    </span>
                    <span class="wu-person-chev" aria-hidden="true">&#8250;</span>
                </button>
                ${isQualifiedForJackpot(student)
                    ? '<span class="sp-head-badge">&#127942; Qualified for Wildcat Jackpot</span>'
                    : ''}
            `;
            
            // Calculate badges
            const badges = [];
            const lifetimeTickets = (student.ticketHistory || []).reduce((sum, entry) => sum + (entry.amount || 1), 0);
            if (lifetimeTickets >= 100) badges.push({ emoji: '💯', label: '100+ Lifetime Tickets', color: '#f59e0b' });
            else if (lifetimeTickets >= 50) badges.push({ emoji: '⭐', label: '50+ Lifetime Tickets', color: '#3b82f6' });
            else if (lifetimeTickets >= 25) badges.push({ emoji: '🌟', label: '25+ Lifetime Tickets', color: '#2E7D52' });
            
            const weeksQualified = (student.ticketHistory || []).filter(entry => entry.reason && entry.reason.includes('Qualified')).length;
            if (weeksQualified >= 5) badges.push({ emoji: '🔥', label: '5-Week Streak', color: '#B3392F' });
            if ((student.attendanceTickets || 0) >= 5) badges.push({ emoji: '📅', label: 'Perfect Attendance', color: '#2E7D52' });
            if (totalTickets >= 5) badges.push({ emoji: '🎯', label: 'Weekly Goal Achieved', color: 'var(--wc-blue)' });
            
            if (badges.length > 0) {
                document.getElementById('profileBadges').innerHTML = `
                    <p class="wu-eyebrow" style="margin: 0 0 10px;">Achievements</p>
                    <div style="display: flex; gap: 12px; flex-wrap: wrap;">
                        ${badges.map(badge => `
                            <div style="background: ${badge.color}; color: white; padding: 12px 20px; border-radius: 25px; font-weight: 600; font-size: 14px; display: flex; align-items: center; gap: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1);">
                                <span style="font-size: 20px;">${badge.emoji}</span>
                                ${badge.label}
                            </div>
                        `).join('')}
                    </div>
                `;
            } else {
                // Quiet. It was a centred italic sentence with 20px of padding
                // sitting between the identity card and the figures, which is
                // the loudest position on the screen for the one thing on it
                // that is not a fact about this student.
                document.getElementById('profileBadges').innerHTML =
                    '<p class="wu-absent" style="margin:0;">No achievements unlocked yet.</p>';
            }
            
            // Every open is a different student, so every open is genuinely
            // a first arrival for these three tiles even though the
            // elements themselves persist. Clearing the marker is what
            // says so; without it only the first student of the session
            // would count up.
            if (window.wcMotion) {
                window.wcMotion.resetCount(
                    '#profileTotalTickets, #profileWeeksQualified, #profileLifetimeTickets');
            }
            wcCount('profileTotalTickets', totalTickets);
            wcCount('profileWeeksQualified', weeksQualified);
            wcCount('profileLifetimeTickets', lifetimeTickets);

            // ---- The hero gauge, as 05 sets it -----------------------
            // Weeks this student has kept, against the length of the cycle.
            // bigRaffleQualified is the array the app actually stores, so both
            // rings come off one fact rather than two guesses.
            //
            // A cycle length nobody has configured is not a cycle length of
            // zero: with no duration there is nothing to be a fraction OF, and
            // the arc stays empty rather than reading as a perfect score.
            const spDuration = (typeof cycleDuration === 'number' && cycleDuration > 0) ? cycleDuration : null;
            const spWeekNow = (typeof currentWeek === 'number') ? currentWeek : null;
            const spKept = Array.isArray(student.bigRaffleQualified)
                ? student.bigRaffleQualified.length
                : (student.bigRaffleQualified === true ? 1 : 0);
            const spSoFar = (spWeekNow === null || spDuration === null)
                ? null : Math.max(0, Math.min(spWeekNow, spDuration));
            const spMissed = (spSoFar === null) ? null : Math.max(0, spSoFar - spKept);

            wcSetGauge(document.getElementById('profileGauge'),
                spDuration === null ? null : Math.min(1, spKept / spDuration),
                spDuration === null
                    ? 'Weeks qualified this cycle: no cycle length set'
                    : `Qualified in ${spKept} of ${spDuration} weeks this cycle`);

            const spLegs = document.getElementById('profileGaugeLegs');
            if (spLegs) {
                spLegs.innerHTML = spDuration === null
                    ? '<p class="wu-absent">No cycle length has been set, so weeks cannot be counted against one.</p>'
                    : '<div class="wu-subrings">' +
                        wcSubring('Weeks kept', 'of ' + spDuration, spKept, 'good') +
                        wcSubring('Weeks missed', spSoFar === null ? 'no week set' : 'of ' + spSoFar, spMissed, 'bad') +
                      '</div>';
            }
            
            // Discipline is run by admins and the PBIS team, not only by the
            // superadmin. Gating a student's referral history to superadmin hid
            // it from exactly the people who act on it.
            const studentReferrals = behaviorReferrals.filter(r => r.studentId === studentId);
            const canSeeReferralHistory = currentUser &&
                ['admin', 'superadmin', 'pbis'].indexOf(currentUser.role) !== -1;
            if (canSeeReferralHistory && studentReferrals.length > 0) {
                // Add referral count to stats
                const statsGrid = document.querySelector('#studentProfileModal .content > div:nth-child(2)');
                if (statsGrid) {
                    statsGrid.innerHTML += `
                        <div style="background: #fef3c7; padding: 20px; border-radius: 12px; text-align: center; border: 2px solid #f59e0b;">
                            <div style="font-size: 36px; font-weight: 700; color: #d97706;" id="profileReferralCount">${studentReferrals.length}</div>
                            <div style="color: #92400e; font-size: 14px; margin-top: 5px;">Behavior Referrals</div>
                        </div>
                    `;
                }
            }
            
            const history = student.ticketHistory || [];
            if (history.length > 0) {
                document.getElementById('profileTicketHistory').innerHTML = history.slice().reverse().map(entry => {
                    const date = new Date(entry.timestamp).toLocaleDateString();
                    const time = new Date(entry.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
                    let icon = '🎫', bgColor = '#f3f4f6';
                    if (entry.category === 'pbis') { icon = '🎯'; bgColor = 'rgba(47, 103, 167, 0.12)'; }
                    else if (entry.category === 'attendance') { icon = '📅'; bgColor = 'rgba(16, 185, 129, 0.1)'; }
                    else if (entry.category === 'academics') { icon = '📚'; bgColor = 'rgba(59, 130, 246, 0.1)'; }
                    
                    return `
                        <div style="background: ${bgColor}; padding: 15px; border-radius: 8px; margin-bottom: 12px; border-left: 3px solid var(--wc-blue);">
                            <div style="display: flex; justify-content: space-between; align-items: start;">
                                <div style="display: flex; align-items: center; gap: 10px;">
                                    <span style="font-size: 24px;">${icon}</span>
                                    <div>
                                        <div style="font-weight: 600; color: #333;">${entry.reason || 'Ticket Awarded'}</div>
                                        <div style="font-size: 13px; color: #666; margin-top: 3px;">${date} at ${time} • by ${entry.teacher || 'Teacher'}</div>
                                    </div>
                                </div>
                                <div style="background: var(--wc-blue-mist); color: var(--wc-blue-deep); padding: 4px 12px; border-radius: 999px; font-weight: 650; font-size: 13px; font-variant-numeric: tabular-nums;">+${entry.amount || 1}</div>
                            </div>
                        </div>
                    `;
                }).join('');
            } else {
                document.getElementById('profileTicketHistory').innerHTML = '<div style="text-align: center; padding: 40px; color: #999;">No ticket history yet. Start earning tickets! 🎟️</div>';
            }
        }
        
        function closeStudentProfile() {
            document.getElementById('studentProfileModal').style.display = 'none';
            document.body.style.overflow = 'auto';
            // Bumped so a fetch still in flight cannot paint into the next
            // student's modal after this one is dismissed.
            spRequestSeq += 1;
            spStudent = null;
            spLoadedFor = null;
        }

        document.addEventListener('click', function(event) {
            const modal = document.getElementById('studentProfileModal');
            if (event.target === modal) closeStudentProfile();
        });

        // ============================================
        // STUDENT PROFILE MODAL: TABS
        //
        // Two tabs. "Points" is what this student earned and is the modal
        // exactly as it was. "Profile" is who this student is, and every number
        // on it comes from studentDetail:get, which is staff gated on the
        // server. Nothing on the Profile tab is computed from the local
        // `students` array: that array is a cache the browser can hold after a
        // legacy password login, and a teacher standing over a desk reading a
        // stale absence count out loud is the failure this avoids.
        // ============================================

        function switchStudentProfileTab(which) {
            const isProfile = which === 'profile';
            const pane = {
                points: document.getElementById('spPanePoints'),
                profile: document.getElementById('spPaneProfile'),
            };
            const tab = {
                points: document.getElementById('spTabPoints'),
                profile: document.getElementById('spTabProfile'),
            };
            if (!pane.points || !pane.profile) return;

            pane.points.style.display = isProfile ? 'none' : 'block';
            pane.profile.style.display = isProfile ? 'block' : 'none';

            [['points', !isProfile], ['profile', isProfile]].forEach(([k, on]) => {
                if (!tab[k]) return;
                tab[k].classList.toggle('sp-tab-active', on);
                tab[k].setAttribute('aria-selected', on ? 'true' : 'false');
            });

            // A tab strip inside a modal is a pane swap, same as the
            // sidebar: 180ms, on the pane, not on the button.
            wcPane(isProfile ? pane.profile : pane.points);

            // Fetched when the tab is first opened rather than when the modal
            // opens, so clicking down a class list does not fire a staff-gated
            // query per student nobody looked at.
            if (isProfile) loadStudentProfileTab();
        }

        /** `{available:false, reason}` rendered as a reason, never as a blank. */
        function spMissing(reason) {
            return '<p class="sp-missing">' + escapeHtml(reason ||
                'This is not available and no reason was given, which is itself ' +
                'worth reporting.') + '</p>';
        }

        /** One big number a teacher can find without reading a paragraph. */
        function spStat(label, value, foot, extraClass) {
            const known = value !== null && value !== undefined;
            return '' +
                '<div class="wc-card wc-stat sp-stat' + (extraClass ? ' ' + extraClass : '') + '">' +
                    '<div class="stat-label">' + escapeHtml(label) + '</div>' +
                    '<div class="stat-num' + (known ? '' : ' sp-num-unknown') + '">' +
                        (known ? escapeHtml(String(value)) : 'Not on file') +
                    '</div>' +
                    (foot ? '<div class="stat-foot">' + escapeHtml(foot) + '</div>' : '') +
                '</div>';
        }

        function spRow(label, value, missingReason, wide) {
            const known = value !== null && value !== undefined && value !== '';
            return '' +
                '<div class="sp-field' + (wide ? ' sp-field-wide' : '') + '">' +
                    '<div class="sp-field-label">' + escapeHtml(label) + '</div>' +
                    '<div class="sp-field-value' + (known ? '' : ' sp-field-unknown') + '">' +
                        (known ? escapeHtml(String(value))
                               : escapeHtml(missingReason || 'Not on file')) +
                    '</div>' +
                '</div>';
        }

        function spWhen(iso) {
            if (!iso) return null;
            try {
                return new Date(iso).toLocaleString();
            } catch (e) {
                return String(iso);
            }
        }

        async function loadStudentProfileTab() {
            const body = document.getElementById('spProfileBody');
            const student = spStudent;
            if (!body || !student) return;

            // Already painted for this student. Re-fetching on every tab click
            // would hammer a staff-gated query for a screen that has not
            // changed.
            if (spLoadedFor === student.id) return;

            const number = String(student.studentNumber || '').trim();

            // NO KEY, NO QUERY. An empty student number is a real index bucket
            // in Convex, not a no-op, and looking one up returns whichever
            // records an import wrote without a number. Roughly a third of the
            // roster has incomplete SIS identity today, so this path is the
            // common one, not the edge case.
            if (!number) {
                body.innerHTML = '<div class="wc-card sp-card">' +
                    '<div class="panel-head"><span class="panel-icon">🪪</span><h3>Profile</h3></div>' +
                    spMissing('This student has no PowerSchool student number on ' +
                        'their record, so their schedule, attendance and behavior ' +
                        'cannot be looked up. The office can add it in PowerSchool.') +
                    '</div>';
                spLoadedFor = student.id;
                return;
            }

            const auth = window.WildcatAuth;
            const session = auth && auth.getSession && auth.getSession();
            if (!session) {
                body.innerHTML = '<div class="wc-card sp-card">' +
                    '<div class="panel-head"><span class="panel-icon">🔐</span><h3>Profile</h3></div>' +
                    spMissing('Sign in with your school Microsoft account to read ' +
                        'this student\'s PowerSchool record. The Profile tab reads ' +
                        'live SIS data and is gated on the server, so the legacy ' +
                        'password login cannot open it.') +
                    '</div>';
                return; // NOT cached: signing in should be enough to retry.
            }

            const seq = ++spRequestSeq;
            body.innerHTML = '<div class="wc-card sp-card sp-loading">Loading this student\'s record...</div>';

            let detail;
            try {
                detail = await auth.convexQuery('studentDetail:get', { studentNumber: number }, session.idToken);
            } catch (err) {
                if (seq !== spRequestSeq) return;
                body.innerHTML = '<div class="wc-card sp-card">' +
                    '<div class="panel-head"><span class="panel-icon">⚠️</span><h3>Profile</h3></div>' +
                    spMissing((err && err.message) || 'This student could not be loaded.') +
                    '</div>';
                return;
            }

            // A newer click won. Painting now would put this student's record
            // under another student's name.
            if (seq !== spRequestSeq) return;

            body.innerHTML = renderStudentProfileTab(detail);
            spLoadedFor = student.id;

            // Data arriving on screen for the first time, after a network
            // round trip — the one case the standard actually asks for an
            // entrance. The cards stagger in.
            //
            // The NUMBERS on this tab deliberately do not count up. These
            // are absence counts and behaviour counts, and this screen is
            // read standing over a desk with the student watching, often
            // out loud. "Days absent: three... seven... eleven" is a
            // sentence no one should be able to say because of an
            // animation. The Points tab counts; this one states.
            if (window.wcMotion) {
                window.wcMotion.enter(body.querySelectorAll('.sp-card'), {
                    type: 'rise', max: 6
                });
            }
        }

        /**
         * studentDetail:get -> the Profile tab.
         *
         * Pure string building from the response, so what renders is exactly
         * what the server was willing to say. Every panel carries its own
         * `available` flag and its own reason, and a false one prints the reason
         * instead of a number. There is deliberately no `|| 0` and no `|| '--'`
         * anywhere below: an invented zero reads as a measurement.
         */
        // Save an edited meal / cafeteria number from the student profile. Admin
        // only on the server (studentDetail:setMealPin); the input only renders
        // for an admin in the first place.
        async function saveStudentMealPin(studentNumber) {
            const input = document.getElementById('spMealPinInput');
            const msg = document.getElementById('spMealPinMsg');
            const btn = document.querySelector('.sp-save-btn');
            if (!input) return;
            const ctx = wcBellSession();
            if (!ctx) { if (msg) { msg.textContent = wcNeedsMicrosoftMessage(); } return; }
            const value = input.value.trim();
            if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
            if (msg) { msg.textContent = ''; msg.className = 'sp-edit-msg'; }
            try {
                await ctx.auth.convexMutation('studentDetail:setMealPin',
                    { studentNumber: studentNumber, mealPin: value }, ctx.session.idToken);
                if (msg) { msg.textContent = value ? 'Saved.' : 'Cleared.'; msg.className = 'sp-edit-msg sp-edit-msg--ok'; }
            } catch (e) {
                if (msg) { msg.textContent = (e && e.message) || 'Could not save.'; msg.className = 'sp-edit-msg sp-edit-msg--err'; }
            } finally {
                if (btn) { btn.disabled = false; btn.textContent = 'Save'; }
            }
        }
        window.saveStudentMealPin = saveStudentMealPin;

        function renderStudentProfileTab(d) {
            const id = (d && d.identity) || {};
            const out = [];

            // ---- Identity -------------------------------------------------
            const email = id.email || {};
            const role = (d && d.viewedAs && d.viewedAs.role) || '';
            const canEditMeal = role === 'admin' || role === 'superadmin';
            const mealPin = id.mealPin || '';
            const mealRow = canEditMeal
                ? '<div class="sp-field sp-field--edit">' +
                    '<span class="sp-label">Meal / cafeteria number</span>' +
                    '<span class="sp-edit">' +
                        '<input type="text" id="spMealPinInput" class="sp-input" value="' + escapeHtml(mealPin) + '" placeholder="e.g. 4073" maxlength="24" inputmode="numeric">' +
                        '<button type="button" class="btn sp-save-btn" onclick="saveStudentMealPin(\'' + escapeHtml(id.studentNumber || '') + '\')">Save</button>' +
                    '</span>' +
                    '<span id="spMealPinMsg" class="sp-edit-msg" aria-live="polite"></span>' +
                  '</div>'
                : spRow('Meal / cafeteria number', mealPin || null, 'Not on file yet.');
            out.push(
                '<div class="wc-card sp-card">' +
                    '<div class="panel-head"><span class="panel-icon">🪪</span><h3>Identity</h3></div>' +
                    '<div class="sp-fields">' +
                        spRow('Full name', [id.firstName, id.lastName].filter(Boolean).join(' ')) +
                        spRow('Student number', id.studentNumber) +
                        spRow('Grade level', id.grade) +
                        spRow('School email',
                            email.available ? email.address : null,
                            email.reason, true) +
                        mealRow +
                    '</div>' +
                    (id.archivedAt
                        ? '<p class="sp-flag">Archived on ' + escapeHtml(spWhen(id.archivedAt) || id.archivedAt) +
                          '. This student is no longer on the synced roster.</p>'
                        : '') +
                '</div>');

            // ---- Promise Time ---------------------------------------------
            // Its own card, above the timetable, because it is the section a
            // teacher opens this tab to find. One row among seven is a row a
            // teacher has to search for.
            const pt = (d && d.sis && d.sis.promiseTime) || { available: false, reason: null };
            out.push(
                '<div class="wc-card sp-card sp-promise">' +
                    '<div class="panel-head"><span class="panel-icon">⭐</span><h3>Promise Time</h3></div>' +
                    (pt.available
                        ? pt.sections.map(function (s) {
                            return '<div class="sp-promise-row">' +
                                '<div class="sp-promise-teacher">' +
                                    escapeHtml(s.teacher || 'Teacher not on the synced row') +
                                '</div>' +
                                '<div class="sp-promise-meta">' +
                                    escapeHtml(s.courseName || 'Course name not on the synced row') +
                                    (s.period ? ' &middot; Period ' + escapeHtml(s.period) : '') +
                                    (s.term ? ' &middot; ' + escapeHtml(s.term) : '') +
                                '</div>' +
                            '</div>';
                        }).join('')
                        : spMissing(pt.reason)) +
                '</div>');

            // ---- Attendance -------------------------------------------------
            const att = (d && d.attendance) || { available: false, reason: null };
            out.push(
                '<div class="wc-card sp-card">' +
                    '<div class="panel-head"><span class="panel-icon">📅</span><h3>Attendance</h3></div>' +
                    (att.available
                        ? '<div class="stat-grid sp-stat-grid">' +
                              spStat('Days absent, this term', att.daysAbsentTerm) +
                              spStat('Days absent, year to date', att.daysAbsentYtd) +
                              spStat('Days tardy, this term', att.daysTardyTerm) +
                          '</div>' +
                          (att.lastSyncedAt
                            ? '<p class="panel-hint">From PowerSchool, synced ' +
                              escapeHtml(spWhen(att.lastSyncedAt)) + '.</p>'
                            : '')
                        : spMissing(att.reason)) +
                '</div>');

            // ---- Behavior ---------------------------------------------------
            // THREE states from the server, and only "covered" may be rendered
            // as a number. A student with no behavior record must not read as a
            // clean one, so "unknown" and "denied" print their reason and no
            // count at all.
            const beh = (d && d.behavior) || { status: 'unknown', reason: null };
            let behBody;
            if (beh.status === 'covered') {
                // NOT named `window`. A `const window` here shadows the global
                // inside this block, and every browser API on it with it.
                const behWindow = beh.window
                    ? 'Log entries between ' + escapeHtml(beh.window.start) + ' and ' + escapeHtml(beh.window.end) + '.'
                    : null;
                behBody =
                    '<div class="stat-grid sp-stat-grid">' +
                        spStat('Log entries in the synced window', beh.totalEntries,
                               beh.totalEntries === 0 ? 'None on file for this window' : null,
                               beh.totalEntries === 0 ? '' : 'sp-stat-flag') +
                    '</div>' +
                    (beh.byType && beh.byType.length
                        ? '<table class="wc-table sp-table"><thead><tr>' +
                            '<th>Type</th><th class="th-center">Entries</th><th>Most recent</th>' +
                          '</tr></thead><tbody>' +
                          beh.byType.map(function (t) {
                              return '<tr class="wc-row">' +
                                  '<td class="cell-strong">' + escapeHtml(t.logTypeName) + '</td>' +
                                  '<td class="cell-center">' + escapeHtml(String(t.count)) + '</td>' +
                                  '<td class="cell-muted">' +
                                      (t.lastEntryDate ? escapeHtml(t.lastEntryDate) : 'No date on the entry') +
                                  '</td>' +
                              '</tr>';
                          }).join('') +
                          '</tbody></table>'
                        : '<p class="panel-hint">No log entries for this student in the synced window.</p>') +
                    (beh.unmappedTypes && beh.unmappedTypes.length
                        ? '<p class="sp-flag">' + escapeHtml(beh.unmappedTypes.length) +
                          ' entry type(s) could not be resolved to a PowerSchool name and are ' +
                          'shown by their raw code.</p>'
                        : '') +
                    (behWindow ? '<p class="panel-hint">' + behWindow +
                        (beh.syncedAt ? ' Synced ' + escapeHtml(spWhen(beh.syncedAt)) + '.' : '') +
                        '</p>' : '');
            } else {
                behBody = spMissing(beh.reason ||
                    'No behavior sync has covered a window yet, so nothing is known ' +
                    'about this student\'s log entries. This is not a clean record.');
            }
            out.push(
                '<div class="wc-card sp-card">' +
                    '<div class="panel-head"><span class="panel-icon">📓</span><h3>Behavior</h3>' +
                        '<span class="sp-badge sp-badge-' + escapeHtml(beh.status) + '">' +
                            escapeHtml(beh.status === 'covered' ? 'From PowerSchool'
                                     : beh.status === 'denied' ? 'Not permitted' : 'Not synced') +
                        '</span>' +
                    '</div>' +
                    behBody +
                '</div>');

            // ---- Wildcat Cash -----------------------------------------------
            const cash = (d && d.cash) || { available: false, reason: null };
            out.push(
                '<div class="wc-card sp-card">' +
                    '<div class="panel-head"><span class="panel-icon">💵</span><h3>Wildcat Cash</h3></div>' +
                    (cash.available
                        ? '<div class="stat-grid sp-stat-grid">' +
                              spStat('Balance', '$' + cash.balance) +
                              spStat('Earned, lifetime', cash.earned === null ? null : '$' + cash.earned) +
                              spStat('Spent, lifetime', cash.spent === null ? null : '$' + cash.spent) +
                          '</div>'
                        : spMissing(cash.reason)) +
                '</div>');

            // ---- Schedule ----------------------------------------------------
            const sched = (d && d.sis && d.sis.schedule) || { available: false, reason: null };
            out.push(
                '<div class="wc-card sp-card table-card sp-card-table">' +
                    '<div class="panel-head sp-table-head">' +
                        '<span class="panel-icon">🗓️</span><h3>Schedule</h3>' +
                        (sched.available
                            ? '<span class="sp-count">' + escapeHtml(String(sched.count)) + ' sections</span>'
                            : '') +
                    '</div>' +
                    (sched.available
                        ? '<table class="wc-table sp-table"><thead><tr>' +
                              '<th class="th-center">Period</th><th>Course</th><th>Teacher</th><th>Term</th>' +
                          '</tr></thead><tbody>' +
                          sched.rows.map(function (r) {
                              const isPT = /\bpromise\s*time\b/i.test(String(r.courseName || ''));
                              return '<tr class="wc-row' + (isPT ? ' sp-row-promise' : '') + '">' +
                                  '<td class="cell-center cell-strong">' +
                                      (r.period ? escapeHtml(r.period) : '<span class="cell-empty">n/a</span>') +
                                  '</td>' +
                                  '<td class="cell-strong">' +
                                      (r.courseName ? escapeHtml(r.courseName) : '<span class="cell-empty">Not named on the synced row</span>') +
                                  '</td>' +
                                  '<td class="cell-muted">' +
                                      (r.teacher ? escapeHtml(r.teacher) : '<span class="cell-empty">Not on the synced row</span>') +
                                  '</td>' +
                                  '<td class="cell-muted">' +
                                      (r.term ? escapeHtml(r.term) : '<span class="cell-empty">n/a</span>') +
                                  '</td>' +
                              '</tr>';
                          }).join('') +
                          '</tbody></table>'
                        : '<div class="sp-card-pad">' + spMissing(sched.reason) + '</div>') +
                '</div>');

            // Brief Phase 6 point 2: every screen says where the data came from
            // and when. `viewedAs` is here too, so a teacher can tell whether
            // they are reading this as the teacher of record or as an admin.
            const asOf = spWhen(d && d.sis && d.sis.lastSyncedAt);
            const seen = (d && d.viewedAs) || {};
            out.push('<p class="sp-foot">' +
                (asOf ? 'PowerSchool schedule synced ' + escapeHtml(asOf) + '. ' : 'No schedule sync on record. ') +
                (seen.scope ? 'You are seeing this as ' + escapeHtml(seen.role || 'staff') +
                    ' (' + escapeHtml(seen.scope) + ').' : '') +
                '</p>');

            return out.join('');
        }
        
        // ============================================
        // SCHOOL BRANDING FUNCTIONS
        // ============================================
        
        function handleLogoUpload(input) {
            const file = input.files[0];
            if (!file) return;
            
            // Check file size (max 500KB)
            if (file.size > 500000) {
                alert('⚠️ Logo file is too large!\n\nPlease use an image under 500KB.');
                input.value = '';
                return;
            }
            
            // Convert to base64
            const reader = new FileReader();
            reader.onload = function(e) {
                const logoPreview = document.getElementById('logoPreview');
                const logoPreviewImg = document.getElementById('logoPreviewImg');
                
                logoPreviewImg.src = e.target.result;
                logoPreview.style.display = 'flex';
                logoPreview.style.alignItems = 'center';
                logoPreview.style.gap = '10px';
                
                // Store in temp (not saved until Save Branding clicked)
                schoolBranding.logoBase64 = e.target.result;
            };
            reader.readAsDataURL(file);
        }
        
        function removeLogo() {
            document.getElementById('brandingLogoUpload').value = '';
            document.getElementById('logoPreview').style.display = 'none';
            schoolBranding.logoBase64 = '';
        }
        
        // Sync color picker with hex input
        document.addEventListener('DOMContentLoaded', function() {
            const colorInputs = [
                {picker: 'brandingPrimaryColor', hex: 'brandingPrimaryColorHex'},
                {picker: 'brandingSecondaryColor', hex: 'brandingSecondaryColorHex'},
                {picker: 'brandingAccentColor', hex: 'brandingAccentColorHex'}
            ];
            
            colorInputs.forEach(({picker, hex}) => {
                const pickerEl = document.getElementById(picker);
                const hexEl = document.getElementById(hex);
                
                if (pickerEl && hexEl) {
                    pickerEl.addEventListener('input', (e) => {
                        hexEl.value = e.target.value;
                    });
                    
                    hexEl.addEventListener('input', (e) => {
                        if (/^#[0-9A-F]{6}$/i.test(e.target.value)) {
                            pickerEl.value = e.target.value;
                        }
                    });
                }
            });
        });
        
        function previewBranding() {
            // Get values from inputs
            const tempBranding = {
                schoolName: document.getElementById('brandingSchoolName').value,
                mascot: document.getElementById('brandingMascot').value || 'Wildcat',
                logoBase64: schoolBranding.logoBase64,
                colors: {
                    primary: document.getElementById('brandingPrimaryColor').value,
                    secondary: document.getElementById('brandingSecondaryColor').value,
                    accent: document.getElementById('brandingAccentColor').value
                },
                terminology: {
                    cashName: document.getElementById('brandingCashName').value || 'Wildcat Cash',
                    jackpotName: document.getElementById('brandingJackpotName').value || 'Wildcat Jackpot',
                    passName: document.getElementById('brandingPassName').value || 'ClawPass'
                }
            };
            
            // Apply temporarily
            applyBranding(tempBranding);
            
            showSuccessToast('👁️ Preview applied! Click "Save Branding" to make it permanent.');
        }
        
        async function saveBranding() {
            const confirmed = await showConfirm(
                '💾 Save School Branding\n\n' +
                'This will apply your custom branding to the entire system for ALL users.\n\n' +
                'Are you sure you want to save these changes?'
            );
            
            if (!confirmed) return;
            
            // Update global branding object
            schoolBranding = {
                schoolName: document.getElementById('brandingSchoolName').value,
                mascot: document.getElementById('brandingMascot').value || 'Wildcat',
                logoBase64: schoolBranding.logoBase64,
                colors: {
                    primary: document.getElementById('brandingPrimaryColor').value,
                    secondary: document.getElementById('brandingSecondaryColor').value,
                    accent: document.getElementById('brandingAccentColor').value
                },
                terminology: {
                    cashName: document.getElementById('brandingCashName').value || 'Wildcat Cash',
                    jackpotName: document.getElementById('brandingJackpotName').value || 'Wildcat Jackpot',
                    passName: document.getElementById('brandingPassName').value || 'ClawPass'
                }
            };
            
            // Apply branding
            applyBranding(schoolBranding);
            
            // Save to database
            saveData();
            
            showSuccessToast('✅ School branding saved successfully!');
        }
        
        async function resetBrandingToDefault() {
            const confirmed = await showConfirm(
                '🔄 Reset to Default Branding\n\n' +
                'This will remove all custom branding and restore the default Wildcat theme.\n\n' +
                'Are you sure you want to reset?'
            );
            
            if (!confirmed) return;
            
            // Reset to defaults
            schoolBranding = {
                schoolName: '',
                mascot: 'Wildcat',
                logoBase64: '',
                colors: {
                    primary: '#667eea',
                    secondary: '#764ba2',
                    accent: '#2E7D52'
                },
                terminology: {
                    cashName: 'Wildcat Cash',
                    jackpotName: 'Wildcat Jackpot',
                    passName: 'ClawPass'
                }
            };
            
            // Clear form fields
            document.getElementById('brandingSchoolName').value = '';
            document.getElementById('brandingMascot').value = 'Wildcat';
            document.getElementById('brandingPrimaryColor').value = '#667eea';
            document.getElementById('brandingPrimaryColorHex').value = '#667eea';
            document.getElementById('brandingSecondaryColor').value = '#764ba2';
            document.getElementById('brandingSecondaryColorHex').value = '#764ba2';
            document.getElementById('brandingAccentColor').value = '#2E7D52';
            document.getElementById('brandingAccentColorHex').value = '#2E7D52';
            document.getElementById('brandingCashName').value = '';
            document.getElementById('brandingJackpotName').value = '';
            document.getElementById('brandingPassName').value = '';
            
            // Remove logo
            removeLogo();
            
            // Apply default branding
            applyBranding(schoolBranding);
            
            // Save to database
            saveData();
            
            showSuccessToast('✅ Branding reset to default!');
            
            // Reload page to ensure everything is back to normal
            setTimeout(() => {
                location.reload();
            }, 1500);
        }
        
        function applyBranding(branding) {
            console.log('🎨 Applying branding:', branding);
            
            // Apply colors via CSS variables
            document.documentElement.style.setProperty('--brand-primary', branding.colors.primary);
            document.documentElement.style.setProperty('--brand-secondary', branding.colors.secondary);
            document.documentElement.style.setProperty('--brand-accent', branding.colors.accent);
            
            // Update ALL gradient backgrounds (inline styles)
            const gradients = document.querySelectorAll('[style*="linear-gradient"]');
            gradients.forEach(el => {
                const currentStyle = el.getAttribute('style');
                if (currentStyle && (currentStyle.includes('667eea') || currentStyle.includes('764ba2'))) {
                    const newStyle = currentStyle
                        .replace(/667eea/g, branding.colors.primary.replace('#', ''))
                        .replace(/764ba2/g, branding.colors.secondary.replace('#', ''));
                    el.setAttribute('style', newStyle);
                }
            });
            
            // Update all buttons with gradient class
            document.querySelectorAll('.btn-gradient').forEach(btn => {
                btn.style.background = `linear-gradient(135deg, ${branding.colors.primary} 0%, ${branding.colors.secondary} 100%)`;
            });
            
            // Update dashboard stat cards gradient borders
            document.querySelectorAll('.dashboard-stat-card').forEach(card => {
                if (card.querySelector('::before')) {
                    const style = document.createElement('style');
                    style.textContent = `.dashboard-stat-card::before { background: linear-gradient(90deg, ${branding.colors.primary} 0%, ${branding.colors.secondary} 100%) !important; }`;
                    document.head.appendChild(style);
                }
            });
            
            // The roster's table header and its ticket counts USED to be
            // repainted here with a two-colour gradient built from the
            // branding colours, as inline styles — which outrank every
            // stylesheet in the app.
            //
            // A table header is chrome, not a brand surface. Painting it a
            // gradient is what made the roster unreadable enough to be worth
            // redesigning, and doing it inline meant no stylesheet could
            // undo it. Branding still owns what branding is: the school name,
            // the logo, the terminology, and the accent on controls above.
            //
            // (.ticket-badge.pbis no longer exists either: the counts are
            // figures now, and a count is not a place for a brand colour.)
            
            // Update school name in header (if exists)
            const headerTitle = document.querySelector('h1');
            if (headerTitle && branding.schoolName) {
                if (!headerTitle.dataset.originalText) {
                    headerTitle.dataset.originalText = headerTitle.textContent;
                }
                headerTitle.textContent = branding.schoolName;
            }
            
            // Replace terminology throughout page
            replaceTerminology(branding.terminology);
            
            // Apply logo if exists
            if (branding.logoBase64) {
                applyLogo(branding.logoBase64);
            }
            
            console.log('✅ Branding applied successfully!');
        }
        
        function replaceTerminology(terminology) {
            // This will be called to replace text throughout the page
            // For now, we'll update specific known elements
            // In production, you'd want to be more selective to avoid breaking things
            
            // Update mode toggle if exists
            const cashModeLabel = document.querySelector('[onclick="toggleMode(true)"]');
            if (cashModeLabel) {
                cashModeLabel.innerHTML = cashModeLabel.innerHTML.replace('Wildcat Cash', terminology.cashName);
            }
            
            // Update jackpot references
            document.querySelectorAll('*').forEach(el => {
                if (el.childNodes.length === 1 && el.childNodes[0].nodeType === 3) { // Text node only
                    let text = el.textContent;
                    if (text.includes('Wildcat Jackpot')) {
                        el.textContent = text.replace(/Wildcat Jackpot/g, terminology.jackpotName);
                    }
                    if (text.includes('Wildcat Cash')) {
                        el.textContent = text.replace(/Wildcat Cash/g, terminology.cashName);
                    }
                    if (text.includes('ClawPass')) {
                        el.textContent = text.replace(/ClawPass/g, terminology.passName);
                    }
                }
            });
        }
        
        function applyLogo(logoBase64) {
            // Add logo to header
            let logoContainer = document.getElementById('schoolLogoContainer');
            if (!logoContainer) {
                logoContainer = document.createElement('div');
                logoContainer.id = 'schoolLogoContainer';
                logoContainer.style.cssText = 'position: absolute; top: 20px; left: 20px; z-index: 1000;';
                document.body.appendChild(logoContainer);
            }
            
            logoContainer.innerHTML = `<img src="${logoBase64}" alt="School Logo" style="max-height: 60px; max-width: 150px;">`;
        }
        
        function loadBrandingSettings() {
            // Load branding into form fields
            if (schoolBranding) {
                document.getElementById('brandingSchoolName').value = schoolBranding.schoolName || '';
                document.getElementById('brandingMascot').value = schoolBranding.mascot || 'Wildcat';
                document.getElementById('brandingPrimaryColor').value = schoolBranding.colors.primary;
                document.getElementById('brandingPrimaryColorHex').value = schoolBranding.colors.primary;
                document.getElementById('brandingSecondaryColor').value = schoolBranding.colors.secondary;
                document.getElementById('brandingSecondaryColorHex').value = schoolBranding.colors.secondary;
                document.getElementById('brandingAccentColor').value = schoolBranding.colors.accent;
                document.getElementById('brandingAccentColorHex').value = schoolBranding.colors.accent;
                document.getElementById('brandingCashName').value = schoolBranding.terminology.cashName !== 'Wildcat Cash' ? schoolBranding.terminology.cashName : '';
                document.getElementById('brandingJackpotName').value = schoolBranding.terminology.jackpotName !== 'Wildcat Jackpot' ? schoolBranding.terminology.jackpotName : '';
                document.getElementById('brandingPassName').value = schoolBranding.terminology.passName !== 'ClawPass' ? schoolBranding.terminology.passName : '';
                
                // Show logo preview if exists
                if (schoolBranding.logoBase64) {
                    document.getElementById('logoPreviewImg').src = schoolBranding.logoBase64;
                    document.getElementById('logoPreview').style.display = 'flex';
                    document.getElementById('logoPreview').style.alignItems = 'center';
                    document.getElementById('logoPreview').style.gap = '10px';
                }
                
                // Apply branding
                applyBranding(schoolBranding);
            }
        }
        
        
        

        function updateTicketsTable(keepPage) {
            const tbody = document.getElementById('ticketsTableBody');
            const periodFilter = document.getElementById('periodFilter');
            const gradeFilter = document.getElementById('gradeFilter');
            const selectedPeriod = periodFilter ? periodFilter.value : '';
            const selectedGrade = gradeFilter ? gradeFilter.value : '';
            
            console.log('=== UPDATE TICKETS TABLE ===');
            console.log('Selected period:', selectedPeriod);
            console.log('Selected grade:', selectedGrade);
            
            // Update dynamic header
            const classHeader = document.getElementById('classHeader');
            const classHeaderTitle = document.getElementById('classHeaderTitle');
            const classHeaderSubtitle = document.getElementById('classHeaderSubtitle');
            const classHeaderCount = document.getElementById('classHeaderCount');
            
            // Enrolled only: this is the count a teacher reads at the top of
            // the page they award tickets from.
            let displayStudents = enrolledStudents();
            let headerTitle = 'All Students';
            let headerSubtitle = 'Select students to award tickets';
            
            // Campus Aides filter by grade; they see the whole school either way.
            if (currentUser && currentUser.role === 'campusaide') {
                if (selectedGrade) {
                    displayStudents = displayStudents.filter(s => s.grade == selectedGrade);
                    headerTitle = `Grade ${selectedGrade} (Campus Aide)`;
                    headerSubtitle = `${displayStudents.length} students in grade ${selectedGrade}`;
                } else {
                    headerTitle = 'All Students (Campus Aide)';
                    headerSubtitle = 'You have access to all students';
                }
            } else {
                // SIS SCOPING, THE SAME CALL AWARD CASH MAKES.
                //
                // This read `currentUser.sections` and matched with
                // `section.students.includes(s.id)`. Both halves were wrong,
                // and they hid each other:
                //
                //   1. currentUser.sections is the legacy CSV field. Nothing
                //      in the PowerSchool path has ever written it -- every
                //      staff row in Convex has `sections: []`. So the whole
                //      branch was unreachable and EVERY period showed the
                //      whole school. updatePeriodFilter says this about the
                //      dropdown in its own comment; the table it filters was
                //      never moved across with it.
                //
                //   2. Even reached, `.includes(s.id)` compares an app id to
                //      the SIS section's student OBJECTS. scopeStudents joins
                //      on studentNumber, which is the key both sides share.
                //
                // Invisible until today, because the dropdown was empty too:
                // with nothing to select, nobody could see that selecting did
                // nothing. Fixing the dropdown is what exposed this.
                //
                // scopeStudents also corrects the failure direction. The old
                // code applied its filter only when sections existed, so a
                // teacher with no roster fell through to the entire school --
                // absent data reading as unrestricted. Now no roster means no
                // students, with a reason attached.
                const scoped = window.WildcatRoster.scopeStudents({
                    students: displayStudents,
                    role: currentUser && currentUser.role,
                    roster: activeTeacherRoster(),
                    sectionId: selectedPeriod || null
                });
                displayStudents = scoped.students;
                headerTitle = window.WildcatRoster.scopeLabel(
                    scoped, activeTeacherRoster(), selectedPeriod || null) || headerTitle;
                headerSubtitle = scoped.reason
                    || `${displayStudents.length} student${displayStudents.length === 1 ? '' : 's'}`;
                console.log(`Scope: ${scoped.scope}, ${displayStudents.length} student(s)` +
                    (scoped.reason ? ` -- ${scoped.reason}` : ''));
            }
            
            console.log('Displaying', displayStudents.length, 'students');

            // Search cooperates with the period/grade filter above and with
            // paging below: it narrows the SET here (so the header count and the
            // page math both see the searched list), rather than hiding already
            // rendered rows, which would only ever search the visible page.
            const ticketSearch = (document.getElementById('searchTickets')?.value || '').toLowerCase().trim();
            if (ticketSearch) {
                displayStudents = displayStudents.filter(s =>
                    `${s.firstName} ${s.lastName}`.toLowerCase().includes(ticketSearch) ||
                    String(s.id).toLowerCase().includes(ticketSearch)
                );
            }

            // Show/update header
            if (classHeader) {
                classHeader.style.display = 'block';
                if (classHeaderTitle) classHeaderTitle.textContent = headerTitle;
                if (classHeaderSubtitle) classHeaderSubtitle.textContent = headerSubtitle;
                if (classHeaderCount) classHeaderCount.textContent = displayStudents.length;
            }

            // Page the filtered, searched set.
            const ticketView = paginate('tickets', displayStudents, keepPage);
            renderPager('tickets', 'ticketsTableBody', ticketView);

            // Render table — calm palette: blue is the single accent,
            // count pills are quiet (mist when >0, gray when 0), row styling via CSS.
            tbody.innerHTML = ticketView.slice.map((s) => {
                const pill = (n) => `<span class="count-pill ${n > 0 ? 'count-pill-on' : ''}">${n}</span>`;
                const dot = (n, label) => `<span class="qual-dot ${n > 0 ? 'qual-dot-on' : ''}" title="${label}"></span>`;
                return `
                <tr class="wc-row">
                    <td class="checkbox-cell">
                        <input type="checkbox" class="student-checkbox" data-id="${s.id}" style="cursor: pointer; width: 18px; height: 18px;">
                    </td>
                    <td class="cell-muted">${s.id}</td>
                    <td>
                        <a href="javascript:void(0)" onclick="openStudentProfile('${s.id}')" class="student-link">${s.firstName} ${s.lastName}</a>
                    </td>
                    <td class="cell-center">${pill(s.pbisTickets)}</td>
                    <td class="cell-center">${pill(s.attendanceTickets)}</td>
                    <td class="cell-center">${pill(s.academicTickets)}</td>
                    <td class="cell-center">
                        ${s.bigRaffleQualified ?
                            '<span class="qualified-badge">✓ Qualified</span>' :
                            `<span class="qual-dots">${dot(s.pbisTickets, 'PBIS')}${dot(s.attendanceTickets, 'Attendance')}${dot(s.academicTickets, 'Academic')}</span>`
                        }
                    </td>
                </tr>
            `;
            }).join('');
        }
        
        /**
         * Why the period list is empty, when it is.
         *
         * "All Students" on its own is indistinguishable from a broken lookup,
         * and that ambiguity cost two rounds of "it still doesn't work". The
         * dropdown now says which of the three it is, so the next report names
         * a cause instead of a symptom.
         */
        function periodFilterNote(sections) {
            if (sections && sections.length) return '';
            if (sisRosterState === 'loading') {
                return '<option value="" disabled>Loading your classes…</option>';
            }
            if (sisRosterState === 'failed') {
                return '<option value="" disabled>Classes unavailable: ' +
                    escapeHtml(sisRosterError || 'roster lookup failed') + '</option>';
            }
            const who = isPreviewingTeacher()
                ? ((currentUser && currentUser.name) || 'that person')
                : 'you';
            return '<option value="" disabled>No classes in PowerSchool for ' +
                escapeHtml(who) + '</option>';
        }

        // Bounded auto-retry. A roster that failed once — which happens when
        // this runs before Microsoft sign-in resolves — stayed failed for the
        // whole visit, with the period list empty and no way back.
        let periodFilterFetchTried = false;
        function resetPeriodFilterFetch() { periodFilterFetchTried = false; }

        function updatePeriodFilter() {
            const periodFilterSection = document.getElementById('periodFilterSection');
            const periodFilter = document.getElementById('periodFilter');
            
            console.log('=== UPDATE PERIOD FILTER ===');
            console.log('User role:', currentUser?.role);
            console.log('User sections:', currentUser?.sections);
            
            // Campus Aides see all students - show grade filter
            if (currentUser && currentUser.role === 'campusaide') {
                console.log('Campus Aide - showing grade filter');
                if (periodFilterSection) {
                    periodFilterSection.style.display = 'block';
                    
                    // Get unique grades from all students
                    const uniqueGrades = [...new Set(students.map(s => s.grade))].sort((a, b) => a - b);
                    
                    periodFilterSection.innerHTML = `
                        <div class="panel-head"><span class="panel-icon">👁️</span><h3>Campus Aide Access</h3></div>
                        <p class="panel-hint" style="margin: 0 0 12px 0;">✓ You have access to all ${students.length} students</p>
                        <label class="field-label">Filter by Grade</label>
                        <select id="gradeFilter" onchange="updateTicketsTable()" class="wc-select">
                            <option value="">All Grades</option>
                            ${uniqueGrades.map(grade => `<option value="${grade}">Grade ${grade}</option>`).join('')}
                        </select>
                    `;
                }
                return;
            }
            
            // SECTIONS COME FROM THE SIS, NOT FROM currentUser.sections.
            //
            // That field is written by exactly one thing: the legacy CSV
            // import, which matched teachers to schedules BY NAME. Nothing in
            // the PowerSchool path has ever written it. So it has been empty
            // for everybody since the CSV era ended, this function took the
            // early return every time, and the period filter has been hidden
            // for every user on every load — admin and teacher alike.
            //
            // Award Cash was moved onto the SIS roster when a teacher reported
            // seeing only "All students". This is the same bug in the raffle
            // tab, and it is fixed the same way, through the same helpers, so
            // the two screens cannot disagree about what a period is.
            const sections = window.WildcatRoster.sectionsFrom(activeTeacherRoster());
            const seesAll = window.WildcatRoster.seesEveryStudent(currentUser && currentUser.role);

            // SHOWN, never hidden. Hiding the control made an unmatched roster
            // look like a missing feature, which is how this went unnoticed:
            // there was nothing on screen to report.
            if (periodFilterSection) periodFilterSection.style.display = 'block';

            if (periodFilter) {
                const totalStudents = students.length;
                // EVERY ROLE GETS BOTH: the whole school, and their own classes.
                //
                // It was either/or, and that is wrong for the most common case
                // in this school — somebody who teaches AND administers. A
                // superadmin who teaches three sections got "All Students" and
                // no way to narrow to their own. scopeStudents already honours
                // a chosen section for every role, so the only thing missing
                // was offering it.
                periodFilter.innerHTML =
                    `<option value="">All Students (${totalStudents})</option>` +
                    periodFilterNote(sections);

                // sectionsFrom already classifies and labels each block, so the
                // list reads "Promise Time" and "Period 3" rather than raw
                // PowerSchool slot numbers. The hand-written periodOrder array
                // this replaces listed A1/P1/HPU codes that the SIS does not
                // use, so it sorted nothing and every section fell to the end.
                sections.forEach(section => {
                    const option = document.createElement('option');
                    option.value = section.sectionId;
                    option.textContent = `${section.label} (${(section.students || []).length})`;
                    periodFilter.appendChild(option);
                });

                console.log(`Period filter: ${sections.length} section(s)` +
                    (seesAll ? ' (you see every student)' : ''));
            }

            // Paint from cache first, then fetch and repaint. The roster is
            // only loaded when Award Cash opens, so in Raffle mode it may not
            // be there yet, and awaiting would leave a blank control.
            // Retries a FAILED roster too, not only an untouched one. The old
            // guard tested 'idle', so a lookup that failed before sign-in
            // resolved was never attempted again. At most one retry per
            // context, so a repaint cannot loop on a broken connection.
            if (!activeTeacherRoster() && sisRosterState !== 'loading'
                && !periodFilterFetchTried && !isPreviewingTeacher()) {
                periodFilterFetchTried = true;
                loadTeacherRosterFromSIS(true).then(() => updatePeriodFilter());
            }
        }
        
        function filterByPeriod() {
            updateTicketsTable();
            
            // Show indicator of what's filtered
            const periodFilter = document.getElementById('periodFilter');
            if (periodFilter && periodFilter.value) {
                const selectedOption = periodFilter.options[periodFilter.selectedIndex];
                console.log('Filtering by:', selectedOption.textContent);
            }
        }

        function updateStats() {
            // ENROLLED ONLY, on both lines.
            //
            // `students` carries every row, enrolled and former, and it has to:
            // saveData stitches nonEnrolledStudents back on, so a filtered
            // array anywhere near the save path deletes 115 children's ticket
            // histories out of the stored document. The filtering belongs at
            // the READ, which is here.
            //
            // Counting the raw array put 738 on a tile that a teacher reads as
            // "how many students are at this school". 623 are. The other 115
            // left, and they are kept so their balances and histories survive,
            // not so they can be counted twice.
            //
            // The jackpot tile had the same denominator problem, which is worse
            // than a wrong number: it is a wrong number that looks like a
            // participation rate.
            const roster = enrolledStudents();
            const qualified = roster.filter(s => isQualifiedForJackpot(s)).length;
            // Counts up the first time the roster lands, snaps every time
            // after. updateStats is inside updateAllDisplays, which runs on
            // every single ticket award — a tile that re-counted on each of
            // those would be showing a teacher a wrong number hundreds of
            // times a day. See the MOTION BRIDGE note at the end of this
            // file.
            wcCount('totalStudents', roster.length);
            wcCount('qualifiedStudents', qualified);
            wcCount('bigRaffleQualified', qualified);
        }

        function updateBigRaffleTable(keepPage) {
            const tbody = document.getElementById('bigRaffleTable');
            // Same pool as the #bigRaffleQualified tile above it, which
            // updateStats writes. A table that lists more rows than the number
            // printed over it is the version of this bug somebody notices.
            const qualified = enrolledStudents().filter(s => isQualifiedForJackpot(s));

            if (qualified.length === 0) {
                tbody.innerHTML = '<tr><td colspan="5" class="rank-empty">No students qualified yet</td></tr>';
                renderPager('bigRaffle', 'bigRaffleTable', { pages: 1 });
                return;
            }
            
            // Get current sort (if exists)
            const currentSort = window.bigRaffleSortBy || 'entries';
            const currentDirection = window.bigRaffleSortDirection || 'desc';
            
            // Sort based on current criteria
            qualified.sort((a, b) => {
                let comparison = 0;
                
                if (currentSort === 'id') {
                    comparison = a.id.localeCompare(b.id);
                } else if (currentSort === 'name') {
                    const nameA = `${a.lastName} ${a.firstName}`.toLowerCase();
                    const nameB = `${b.lastName} ${b.firstName}`.toLowerCase();
                    comparison = nameA.localeCompare(nameB);
                } else if (currentSort === 'grade') {
                    comparison = parseInt(a.grade) - parseInt(b.grade);
                } else if (currentSort === 'weeks') {
                    comparison = (a.weeksQualified || 0) - (b.weeksQualified || 0);
                } else if (currentSort === 'entries') {
                    comparison = (a.weeksQualified || 0) - (b.weeksQualified || 0);
                }
                
                return currentDirection === 'asc' ? comparison : -comparison;
            });

            // Sort the whole qualified pool above, then page it here.
            const raffleView = paginate('bigRaffle', qualified, keepPage);
            renderPager('bigRaffle', 'bigRaffleTable', raffleView);

            tbody.innerHTML = raffleView.slice.map(s => {
                const grade = parseInt(s.grade);
                
                // Check audit log for bonus entries for THIS student
                const bonusEntries = auditLog.filter(entry => 
                    entry.studentId === s.id && 
                    entry.action === 'Weekly Leaderboard Bonus'
                ).length;
                
                const hasBonus = bonusEntries > 0;
                
                // Use bigRaffleQualified array length (number of weeks qualified)
                const weeksQualified = Array.isArray(s.bigRaffleQualified) ? s.bigRaffleQualified.length : 0;
                
                let entriesDisplay = `${weeksQualified} ${weeksQualified === 1 ? 'entry' : 'entries'}`;
                if (hasBonus) {
                    entriesDisplay += ` <span class="bonus-chip">🏆 +${bonusEntries} BONUS</span>`;
                }
                
                return `
                    <tr class="wc-row${hasBonus ? ' row-bonus' : ''}">
                        <td>${s.id}</td>
                        <td>${s.firstName} ${s.lastName}</td>
                        <td style="text-align: center;">${grade}</td>
                        <td style="text-align: center;">${weeksQualified}</td>
                        <td>${entriesDisplay}</td>
                    </tr>
                `;
            }).join('');
        }
        
        function sortBigRaffleTable(column) {
            // Toggle direction if clicking same column
            if (window.bigRaffleSortBy === column) {
                window.bigRaffleSortDirection = window.bigRaffleSortDirection === 'asc' ? 'desc' : 'asc';
            } else {
                window.bigRaffleSortBy = column;
                window.bigRaffleSortDirection = column === 'name' || column === 'id' ? 'asc' : 'desc';
            }
            
            // Update header arrows
            document.querySelectorAll('#bigRaffleTable').forEach(table => {
                const headers = table.parentElement.parentElement.querySelectorAll('th');
                headers.forEach(h => {
                    h.classList.remove('sort-asc', 'sort-desc');
                });
            });
            
            const headerMap = {
                'id': 0,
                'name': 1,
                'grade': 2,
                'weeks': 3,
                'entries': 4
            };
            
            const headerIndex = headerMap[column];
            const table = document.getElementById('bigRaffleTable').parentElement.parentElement;
            const header = table.querySelectorAll('th')[headerIndex];
            header.classList.add(window.bigRaffleSortDirection === 'asc' ? 'sort-asc' : 'sort-desc');
            
            updateBigRaffleTable();
        }


        function searchTicketsTable() {
            // Re-render through the data path so search narrows the FULL roster
            // (all pages), not just the rows currently on screen. updateTicketsTable
            // reads #searchTickets itself and resets to page 1.
            updateTicketsTable();
        }

        function toggleSelectAll() {
            const selectAll = document.getElementById('selectAll');
            const checkboxes = document.querySelectorAll('.student-checkbox');
            checkboxes.forEach(cb => cb.checked = selectAll.checked);
        }

        // ============================================
        // UPDATE RAFFLE DASHBOARD STATS
        // ============================================
        function updateDashboardStats() {
            // Enrolled only, for the same reason updateStats uses it: the
            // students array holds everyone the app has ever seen, including
            // students who have left, whose records are kept so their balances
            // and histories survive rather than so they can be counted. A
            // departed student could otherwise be shown as this week's top
            // earner, and the qualified count included people who are not here.
            const roster = enrolledStudents();

            // Calculate total tickets awarded this week
            let totalTickets = 0;
            roster.forEach(s => {
                totalTickets += (s.pbisTickets || 0) + (s.attendanceTickets || 0) + (s.academicTickets || 0);
            });

            // Count qualified students
            const qualifiedCount = roster.filter(s => isQualifiedForJackpot(s)).length;

            // Find top earner
            let topEarner = { name: '-', total: 0 };
            roster.forEach(s => {
                const studentTotal = (s.pbisTickets || 0) + (s.attendanceTickets || 0) + (s.academicTickets || 0);
                if (studentTotal > topEarner.total) {
                    topEarner = {
                        name: `${s.firstName} ${s.lastName}`,
                        total: studentTotal
                    };
                }
            });
            
            // Calculate tickets awarded by current user
            let yourTickets = 0;
            if (currentUser && currentUser.email) {
                students.forEach(s => {
                    if (s.ticketHistory && Array.isArray(s.ticketHistory)) {
                        s.ticketHistory.forEach(entry => {
                            if (entry.awardedBy === currentUser.email) {
                                yourTickets += entry.amount || 1;
                            }
                        });
                    }
                });
            }
            
            // Update dashboard elements
            const dashTotalTickets = document.getElementById('dashTotalTickets');
            const dashQualifiedStudents = document.getElementById('dashQualifiedStudents');
            const dashTopEarner = document.getElementById('dashTopEarner');
            const dashYourTickets = document.getElementById('dashYourTickets');
            
            if (dashTotalTickets) {
                dashTotalTickets.textContent = totalTickets;
                dashTotalTickets.classList.add('animated');
            }
            
            if (dashQualifiedStudents) {
                dashQualifiedStudents.textContent = qualifiedCount;
                dashQualifiedStudents.classList.add('animated');
            }
            
            if (dashTopEarner) {
                dashTopEarner.textContent = topEarner.total > 0 ? `${topEarner.name.split(' ')[0]} (${topEarner.total})` : '-';
                dashTopEarner.classList.add('animated');
                dashTopEarner.style.fontSize = topEarner.total > 0 ? '28px' : '42px';
            }
            
            if (dashYourTickets) {
                dashYourTickets.textContent = yourTickets;
                dashYourTickets.classList.add('animated');
            }
            
            // Update charts
            updateCharts();
        }

        async function awardTicketsToSelected() {
            const category = document.getElementById('categorySelect').value;
            const amount = parseInt(document.getElementById('ticketAmount').value);
            const reason = document.getElementById('ticketReason').value.trim();
            const subcategory = document.getElementById('subcategorySelect').value;
            const checkboxes = document.querySelectorAll('.student-checkbox:checked');
            
            // Validate ticket amount
            if (isNaN(amount) || amount < 1 || amount > 5) {
                alert('⚠️ Invalid ticket amount!\n\nYou must award between 1 and 5 tickets.');
                document.getElementById('ticketAmount').value = 1; // Reset to default
                return;
            }
            
            if (checkboxes.length === 0) {
                alert('Please select at least one student!');
                return;
            }

            // Require subcategory for PBIS and Academics
            if ((category === 'pbis' || category === 'academics') && !subcategory) {
                alert('Please select a subcategory!');
                return;
            }

            // Require reason for PBIS and Academics
            if ((category === 'pbis' || category === 'academics') && !reason) {
                alert('Please provide a reason for this ticket award!');
                return;
            }

            const categoryName = category === 'pbis' ? 'PBIS' : 
                                category === 'attendance' ? 'Attendance' : 'Academics';

            // Track this award for UNDO functionality
            const awardedStudents = [];

            checkboxes.forEach(cb => {
                const studentId = cb.dataset.id;
                const student = students.find(s => s.id === studentId);
                if (student) {
                    console.log(`🎫 Awarding ${amount} ${categoryName} ticket(s) to ${student.firstName} ${student.lastName} (ID: ${student.id})`);
                    console.log(`   Before: PBIS=${student.pbisTickets || 0}, Att=${student.attendanceTickets || 0}, Acad=${student.academicTickets || 0}`);
                    
                    // Store current state before awarding
                    const previousState = {
                        studentId: student.id,
                        pbisTickets: student.pbisTickets,
                        attendanceTickets: student.attendanceTickets,
                        academicTickets: student.academicTickets,
                        ticketHistoryLength: student.ticketHistory ? student.ticketHistory.length : 0
                    };
                    
                    if (category === 'pbis') student.pbisTickets += amount;
                    else if (category === 'attendance') student.attendanceTickets += amount;
                    else if (category === 'academics') student.academicTickets += amount;
                    
                    console.log(`   After:  PBIS=${student.pbisTickets || 0}, Att=${student.attendanceTickets || 0}, Acad=${student.academicTickets || 0}`);
                    
                    // Add to student's history
                    if (!student.ticketHistory) student.ticketHistory = [];
                    student.ticketHistory.push({
                        timestamp: new Date().toISOString(),
                        category: categoryName,
                        subcategory: subcategory || null,
                        tickets: amount,
                        reason: reason || 'Perfect Attendance',
                        teacher: currentUser.name,
                        week: currentWeek,             // Week within the current cycle (1-5)
                        cycle: getCurrentCycleNumber()  // Which cycle this entry belongs to
                    });
                    
                    awardedStudents.push(previousState);
                    
                    // Log the action with subcategory and period info
                    const logReason = subcategory ? `${subcategory}: ${reason}` : (reason || 'Perfect Attendance');
                    
                    // Find which period/section this student belongs to for the current teacher
                    let periodInfo = null;
                    console.log('=== AWARD TICKETS DEBUG ===');
                    console.log('Looking up period for student:', student.id, student.firstName, student.lastName);
                    console.log('Current user sections:', currentUser.sections);
                    
                    if (currentUser.sections && currentUser.sections.length > 0) {
                        for (const section of currentUser.sections) {
                            console.log('Checking section:', section.period, section.courseName);
                            console.log('Section has students?', section.students?.length);
                            if (section.students) {
                                console.log('Section student IDs:', section.students.map(s => s.id));
                            }
                            
                            if (section.students && section.students.some(s => s.id === student.id)) {
                                periodInfo = {
                                    period: section.period,
                                    courseName: section.courseName
                                };
                                console.log('✅ FOUND period info:', periodInfo);
                                break;
                            }
                        }
                    } else {
                        console.log('❌ Current user has no sections!');
                    }
                    
                    if (!periodInfo) {
                        console.log('❌ Period info not found for this student');
                    }
                    
                    addToAuditLog('Awarded Tickets', studentId, categoryName, amount, logReason, periodInfo);
                }
            });

            // Update teacher's ticket count
            const teacher = teachers.find(t => t.id === currentUser.id);
            const previousTeacherTickets = teacher ? teacher.ticketsAwarded : 0;
            if (teacher) {
                teacher.ticketsAwarded += (amount * checkboxes.length);
            }

            // Store this award for UNDO
            lastAwardAction = {
                students: awardedStudents,
                category: category,
                amount: amount,
                teacherId: currentUser.id,
                teacherPreviousTickets: previousTeacherTickets,
                auditLogCount: auditLog.length // Track how many audit entries to remove
            };

            console.log(`💾 About to save ${checkboxes.length} ticket award(s)`);
            const studentsWithTicketsBeforeSave = students.filter(s => s.pbisTickets > 0 || s.attendanceTickets > 0 || s.academicTickets > 0).length;
            console.log(`   Students with tickets before save: ${studentsWithTicketsBeforeSave}`);
            
            // Coalesced, but STILL awaited: requestSave resolves only once a
            // save carrying this award has actually landed, so the guarantee
            // the old comment describes is unchanged, not traded away.
            await requestSave('Ticket award');
            
            // Verify after save completes
            setTimeout(() => {
                const studentsWithTicketsAfterSave = students.filter(s => s.pbisTickets > 0 || s.attendanceTickets > 0 || s.academicTickets > 0).length;
                console.log(`✅ Save completed. Students with tickets after save: ${studentsWithTicketsAfterSave}`);
                if (studentsWithTicketsAfterSave < studentsWithTicketsBeforeSave) {
                    console.error(`❌ WARNING: Lost ${studentsWithTicketsBeforeSave - studentsWithTicketsAfterSave} students with tickets during save!`);
                }
            }, 2000);
            
            // CRITICAL: Wait for Firebase save to complete before updating UI
            // This prevents a second save from overwriting with stale data
            setTimeout(() => {
                updateAllDisplays();
                updateDashboardStats(); // Update animated dashboard
                document.getElementById('selectAll').checked = false;
                document.getElementById('ticketReason').value = ''; // Clear reason field
                document.getElementById('subcategorySelect').value = ''; // Clear subcategory
                
                // Show UNDO button
                const undoButton = document.getElementById('undoAwardButton');
                if (undoButton) {
                    undoButton.style.display = 'inline-block';
                }
                
                // Show success toast with animation
                showSuccessToast(`✅ Awarded ${amount} ticket(s) to ${checkboxes.length} student(s)!`);
                
                // Trigger confetti animation
                triggerConfetti();
                
                alert(`✅ Awarded ${amount} ticket(s) to ${checkboxes.length} student(s)!\n\nClick "UNDO" if this was a mistake.`);
            }, 1000); // 1 second delay to ensure save completes
        }
        
        // Show success toast notification
        function showSuccessToast(message) {
            const toast = document.createElement('div');
            toast.className = 'success-toast';
            toast.textContent = message;
            document.body.appendChild(toast);
            
            setTimeout(() => {
                toast.style.opacity = '0';
                toast.style.transform = 'translateX(400px)';
                setTimeout(() => toast.remove(), 500);
            }, 3000);
        }
        
        // Trigger confetti animation
        function triggerConfetti() {
            const colors = ['#667eea', '#764ba2', '#2E7D52', '#3b82f6', '#f59e0b', '#B3392F', '#ec4899'];
            const shapes = ['circle', 'square'];
            
            // Create 80 confetti pieces
            for (let i = 0; i < 80; i++) {
                setTimeout(() => {
                    const confetti = document.createElement('div');
                    const shape = shapes[Math.floor(Math.random() * shapes.length)];
                    const size = Math.random() * 15 + 10; // 10-25px
                    
                    confetti.style.position = 'fixed';
                    confetti.style.width = size + 'px';
                    confetti.style.height = size + 'px';
                    confetti.style.background = colors[Math.floor(Math.random() * colors.length)];
                    confetti.style.left = Math.random() * 100 + '%';
                    confetti.style.top = '-50px';
                    confetti.style.borderRadius = shape === 'circle' ? '50%' : '0';
                    confetti.style.pointerEvents = 'none';
                    confetti.style.zIndex = '9999';
                    confetti.style.opacity = '0.9';
                    
                    // Random rotation and animation duration
                    const duration = Math.random() * 2 + 3; // 3-5 seconds
                    const rotation = Math.random() * 720 + 360; // 360-1080 degrees
                    const drift = Math.random() * 200 - 100; // -100 to 100px horizontal drift
                    
                    confetti.style.animation = `confetti-fall ${duration}s linear`;
                    confetti.style.setProperty('--drift', drift + 'px');
                    confetti.style.setProperty('--rotation', rotation + 'deg');
                    
                    document.body.appendChild(confetti);
                    
                    setTimeout(() => confetti.remove(), duration * 1000);
                }, i * 15); // Stagger the confetti
            }
        }

        // UNDO last ticket award
        async function undoLastAward() {
            if (!lastAwardAction) {
                alert('No recent award to undo!');
                return;
            }
            
            const confirmed = await showConfirm(
                `⚠️ UNDO Last Award\n\n` +
                `This will reverse the last ticket award for ${lastAwardAction.students.length} student(s).\n\n` +
                `Are you sure you want to undo?`
            );
            
            if (!confirmed) return;
            
            // Restore each student's previous state
            for (const prevState of lastAwardAction.students) {
                const student = students.find(s => s.id === prevState.studentId);
                if (student) {
                    // Restore ticket counts
                    student.pbisTickets = prevState.pbisTickets;
                    student.attendanceTickets = prevState.attendanceTickets;
                    student.academicTickets = prevState.academicTickets;
                    
                    // Tombstone the ticket history entries added by the award, then remove
                    if (student.ticketHistory && student.ticketHistory.length > prevState.ticketHistoryLength) {
                        const addedEntries = student.ticketHistory.slice(prevState.ticketHistoryLength);
                        for (const h of addedEntries) {
                            const tid = ensureEntryId(h);
                            await persistTombstone(tid, currentUser.name || 'admin', `Undo last award: ${h.reason || ''}`, 'ticket');
                        }
                        student.ticketHistory = student.ticketHistory.slice(0, prevState.ticketHistoryLength);
                    }
                }
            }
            
            // Restore teacher's ticket count
            const teacher = teachers.find(t => t.id === lastAwardAction.teacherId);
            if (teacher) {
                teacher.ticketsAwarded = lastAwardAction.teacherPreviousTickets;
            }
            
            // Tombstone audit log entries added by the award, then remove
            const entriesToRemove = auditLog.length - lastAwardAction.auditLogCount;
            if (entriesToRemove > 0) {
                const removedEntries = auditLog.slice(lastAwardAction.auditLogCount, lastAwardAction.auditLogCount + entriesToRemove);
                for (const e of removedEntries) {
                    const aid = ensureEntryId(e);
                    await persistTombstone(aid, currentUser.name || 'admin', `Undo last award: ${e.action} - ${e.reason || ''}`, 'audit');
                }
                auditLog.splice(lastAwardAction.auditLogCount, entriesToRemove);
            }
            
            // Add a new audit log entry for the UNDO action
            const categoryName = lastAwardAction.category === 'pbis' ? 'PBIS' : 
                                lastAwardAction.category === 'attendance' ? 'Attendance' : 'Academics';
            
            const undoEntry = {
                timestamp: new Date().toISOString(),
                action: '↩️ UNDID Award',
                studentId: 'Multiple',
                studentName: `${lastAwardAction.students.length} student(s)`,
                category: categoryName,
                tickets: lastAwardAction.amount,
                reason: `Reversed ticket award for ${lastAwardAction.students.length} student(s)`,
                teacher: currentUser.name,
                teacherId: currentUser.id,
                period: null,
                courseName: null
            };
            
            auditLog.push(undoEntry);
            console.log('UNDO audit entry created:', undoEntry);
            console.log('Audit log now has', auditLog.length, 'entries');
            
            // Clear the undo action
            lastAwardAction = null;
            
            // Hide UNDO button
            const undoButton = document.getElementById('undoAwardButton');
            if (undoButton) {
                undoButton.style.display = 'none';
            }
            
            await saveData();
            updateAllDisplays();
            updateDashboardStats(); // Update animated dashboard
            
            alert('✅ Award successfully undone!');
        }

        // Toggle raffle buttons based on category selection.
        // Attendance uses separate MS and HS buttons (MS often finishes their tickets later,
        // so admin may need to draw HS first and come back for MS). PBIS and Academics use
        // the single Draw Winner button as before.
        function updateRaffleControls() {
            const category = document.getElementById('raffleCategory')?.value;
            const singleBtn = document.getElementById('raffleDrawBtn');
            const msBtn = document.getElementById('raffleDrawMSBtn');
            const hsBtn = document.getElementById('raffleDrawHSBtn');
            if (!singleBtn || !msBtn || !hsBtn) return;

            if (category === 'attendance') {
                singleBtn.style.display = 'none';
                msBtn.style.display = '';
                hsBtn.style.display = '';
            } else {
                singleBtn.style.display = '';
                msBtn.style.display = 'none';
                hsBtn.style.display = 'none';
            }
        }

        function drawWinner(school) {
            const category = document.getElementById('raffleCategory').value;
            
            const categoryName = category === 'pbis' ? 'PBIS Behaviors' : 
                                category === 'attendance' ? 'Perfect Attendance' : 'Academics';
            
            // PBIS draws 2 MS + 2 HS combined — unaffected by the school arg
            if (category === 'pbis') {
                drawPBISByGrade(categoryName);
                return;
            }

            // Attendance: drawn per school. Button provides 'MS' or 'HS'.
            if (category === 'attendance') {
                if (school !== 'MS' && school !== 'HS') {
                    alert('Please use the Middle School or High School button.');
                    return;
                }
                drawBySchoolSingle(category, categoryName, school);
                return;
            }

            // Academics: unchanged — draw MS then HS
            drawBySchool(category, categoryName);
        }

        // Draw a single winner for ONE school (Attendance only, per admin request).
        // Independent of the MS+HS combined flow — can be run separately at different times.
        async function drawBySchoolSingle(category, categoryName, school) {
            // Enrolled only. A prior year student who transferred out could
            // otherwise be drawn as a winner, and the prize would go to a child
            // who is not at this school.
            const roster = enrolledStudents();
            const pool = school === 'MS'
                ? roster.filter(s => s.grade >= 6 && s.grade <= 8)
                : roster.filter(s => s.grade >= 9 && s.grade <= 12);

            let eligible = [];
            if (category === 'attendance') {
                eligible = pool.filter(s => (s.attendanceTickets || 0) > 0);
            }
            // (extensible for future single-school categories)

            const schoolLabel = school === 'MS' ? 'Middle School' : 'High School';

            if (eligible.length === 0) {
                alert(`No eligible students for ${categoryName} in ${schoolLabel}!`);
                return;
            }

            // Prevent re-drawing the same school for the same week+category.
            // Weekly raffles already draw one winner per school, so a duplicate
            // here is almost certainly a mistake. Admin can override if needed.
            const alreadyDrawn = weeklyWinners.some(w =>
                w.week === currentWeek &&
                w.category === categoryName &&
                w.school === schoolLabel
            );
            if (alreadyDrawn) {
                const proceed = await showConfirm(
                    `A ${schoolLabel} winner for ${categoryName} has already been drawn this week.\n\n` +
                    `Drawing again will add a second winner. Are you sure you want to continue?`
                );
                if (!proceed) return;
            }

            showRaffleSpinner(eligible, schoolLabel, (winner) => {
                weeklyWinners.push({
                    week: currentWeek,
                    category: categoryName,
                    school: schoolLabel,
                    student: winner,
                    date: new Date().toLocaleDateString()
                });

                addToAuditLog('Raffle Winner', winner.id, `${categoryName} - ${schoolLabel}`, null, null);

                saveData();
                displaySingleWinner(winner, categoryName, schoolLabel);
                updateWinnersList();
                updateAllDisplays();
                triggerConfetti();
            });
        }
        
        function drawPBISByGrade(categoryName) {
            // PBIS draws 2 winners from Middle School (grades 6-8) and 2 from High School (grades 9-12).
            // Same student cannot win twice in one drawing (draws are without replacement).
            const pbisRoster = enrolledStudents();
            const middleSchool = pbisRoster.filter(s => {
                const g = parseInt(s.grade);
                return g >= 6 && g <= 8 && (s.pbisTickets || 0) > 0;
            });
            const highSchool = pbisRoster.filter(s => {
                const g = parseInt(s.grade);
                return g >= 9 && g <= 12 && (s.pbisTickets || 0) > 0;
            });

            if (middleSchool.length === 0 && highSchool.length === 0) {
                alert('No eligible students for PBIS in either school!');
                return;
            }

            // Build the sequence of draws: up to 2 MS, then up to 2 HS
            // If a pool doesn't have enough eligible students, we skip the extra draws in that pool
            const drawPlan = [];
            if (middleSchool.length >= 1) drawPlan.push({ pool: 'MS', label: 'Middle School Winner 1 of 2' });
            if (middleSchool.length >= 2) drawPlan.push({ pool: 'MS', label: 'Middle School Winner 2 of 2' });
            if (highSchool.length >= 1)   drawPlan.push({ pool: 'HS', label: 'High School Winner 1 of 2' });
            if (highSchool.length >= 2)   drawPlan.push({ pool: 'HS', label: 'High School Winner 2 of 2' });

            // Track winners to prevent duplicates in the same drawing
            const msRemaining = [...middleSchool];
            const hsRemaining = [...highSchool];
            const allWinners = [];

            let drawIndex = 0;
            function drawNext() {
                if (drawIndex >= drawPlan.length) {
                    // All draws done
                    saveData();
                    displayPBISWinners(allWinners, categoryName);
                    updateWinnersList();
                    updateAllDisplays();
                    triggerConfetti();
                    return;
                }

                const step = drawPlan[drawIndex];
                const pool = step.pool === 'MS' ? msRemaining : hsRemaining;

                if (pool.length === 0) {
                    // Pool exhausted mid-drawing (shouldn't happen given our plan, but safe fallback)
                    drawIndex++;
                    drawNext();
                    return;
                }

                showRaffleSpinner(pool, step.label, (winner) => {
                    // Determine the grade-aware sub-label for audit entries
                    const schoolLabel = step.pool === 'MS' ? 'Middle School' : 'High School';
                    const gradeLabel = `Grade ${winner.grade}`;

                    weeklyWinners.push({
                        week: currentWeek,
                        category: categoryName,
                        school: schoolLabel,
                        grade: winner.grade,
                        winnerLabel: step.label,
                        student: winner,
                        date: new Date().toLocaleDateString()
                    });

                    allWinners.push({ winner, school: schoolLabel, label: step.label });

                    addToAuditLog(
                        'Raffle Winner',
                        winner.id,
                        `${categoryName} - ${gradeLabel} (${step.label})`,
                        null,
                        null
                    );

                    // Remove winner from the remaining pool so they can't win twice
                    const idx = pool.findIndex(s => s.id === winner.id);
                    if (idx >= 0) pool.splice(idx, 1);

                    drawIndex++;
                    setTimeout(() => drawNext(), 2000);
                });
            }

            drawNext();
        }

        function displayPBISWinners(winners, categoryName) {
            const display = document.getElementById('winnerDisplay');

            let html = '<div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 20px; margin-top: 20px;">';

            winners.forEach(({ winner, school, label }) => {
                // Winner reveal is projected to students — it stays celebratory,
                // but on school colours: deep blue card, gold accents, MS/HS as a badge.
                html += `
                    <div class="winner-card">
                        <span class="winner-school">🏫 ${school}</span>
                        <h3 class="winner-label">${label}</h3>
                        <div class="winner-name-box">
                            <div class="winner-name">${winner.firstName} ${winner.lastName}</div>
                            <div class="winner-meta">Grade ${winner.grade} • ID: ${winner.id}</div>
                        </div>
                        <div class="winner-cat">Category: ${categoryName}</div>
                        <div class="winner-date">${new Date().toLocaleDateString()}</div>
                    </div>
                `;
            });

            html += '</div>';
            display.innerHTML = html;
        }
        
        function drawBySchool(category, categoryName) {
            // Separate students by school
            const middleSchool = students.filter(s => s.grade >= 6 && s.grade <= 8);
            const highSchool = students.filter(s => s.grade >= 9 && s.grade <= 12);
            
            let msEligible = [];
            let hsEligible = [];

            // Filter by category for each school
            if (category === 'attendance') {
                msEligible = middleSchool.filter(s => s.attendanceTickets > 0);
                hsEligible = highSchool.filter(s => s.attendanceTickets > 0);
            } else if (category === 'academics') {
                msEligible = middleSchool.filter(s => s.academicTickets > 0);
                hsEligible = highSchool.filter(s => s.academicTickets > 0);
            }

            if (msEligible.length === 0 && hsEligible.length === 0) {
                alert('No eligible students for this category in either school!');
                return;
            }

            // Draw Middle School winner if eligible students exist
            if (msEligible.length > 0) {
                showRaffleSpinner(msEligible, 'Middle School', (msWinner) => {
                    weeklyWinners.push({
                        week: currentWeek,
                        category: categoryName,
                        school: 'Middle School',
                        student: msWinner,
                        date: new Date().toLocaleDateString()
                    });

                    addToAuditLog('Raffle Winner', msWinner.id, `${categoryName} - Middle School`, null, null);
                    
                    // Draw High School winner if eligible students exist
                    if (hsEligible.length > 0) {
                        setTimeout(() => {
                            showRaffleSpinner(hsEligible, 'High School', (hsWinner) => {
                                weeklyWinners.push({
                                    week: currentWeek,
                                    category: categoryName,
                                    school: 'High School',
                                    student: hsWinner,
                                    date: new Date().toLocaleDateString()
                                });

                                addToAuditLog('Raffle Winner', hsWinner.id, `${categoryName} - High School`, null, null);

                                saveData();
                                displayBothWinners(msWinner, hsWinner, categoryName);
                                updateWinnersList();
                                updateAllDisplays();
                                triggerConfetti();
                            });
                        }, 2000); // Delay between raffles
                    } else {
                        // Only MS winner
                        saveData();
                        displaySingleWinner(msWinner, categoryName, 'Middle School');
                        updateWinnersList();
                        updateAllDisplays();
                        triggerConfetti();
                    }
                });
            } else if (hsEligible.length > 0) {
                // Only HS has eligible students
                showRaffleSpinner(hsEligible, 'High School', (hsWinner) => {
                    weeklyWinners.push({
                        week: currentWeek,
                        category: categoryName,
                        school: 'High School',
                        student: hsWinner,
                        date: new Date().toLocaleDateString()
                    });

                    addToAuditLog('Raffle Winner', hsWinner.id, `${categoryName} - High School`, null, null);

                    saveData();
                    displaySingleWinner(hsWinner, categoryName, 'High School');
                    updateWinnersList();
                    updateAllDisplays();
                    triggerConfetti();
                });
            }
        }
        
        
        // Animated raffle spinner with school label
        function showRaffleSpinner(eligibleStudents, schoolName, callback) {
            const display = document.getElementById('winnerDisplay');
            
            // Create spinner overlay with school name
            display.innerHTML = `
                <div style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); padding: 50px; border-radius: 16px; box-shadow: 0 8px 30px rgba(0,0,0,0.3); text-align: center;">
                    <div style="background: rgba(255,255,255,0.2); padding: 10px 20px; border-radius: 20px; display: inline-block; margin-bottom: 20px;">
                        <span style="color: white; font-weight: 600; font-size: 18px;">🏫 ${schoolName}</span>
                    </div>
                    <h2 style="color: white; margin-bottom: 30px; font-size: 32px;">🎰 Drawing Winner...</h2>
                    <div id="spinnerName" style="background: white; padding: 30px; border-radius: 12px; font-size: 36px; font-weight: 700; color: #667eea; min-height: 80px; display: flex; align-items: center; justify-content: center;">
                        ...
                    </div>
                </div>
            `;
            
            const spinnerName = document.getElementById('spinnerName');
            let spinCount = 0;
            const totalSpins = 30; // Number of name changes
            const initialDelay = 50; // Start fast
            
            function spin() {
                if (spinCount < totalSpins) {
                    // Show random student name
                    const randomStudent = eligibleStudents[Math.floor(Math.random() * eligibleStudents.length)];
                    spinnerName.textContent = `${randomStudent.firstName} ${randomStudent.lastName}`;
                    
                    // Gradually slow down
                    const delay = initialDelay + (spinCount * 8); // Gets slower
                    spinCount++;
                    
                    setTimeout(spin, delay);
                } else {
                    // Final winner
                    const winner = eligibleStudents[Math.floor(Math.random() * eligibleStudents.length)];
                    spinnerName.textContent = `${winner.firstName} ${winner.lastName}`;
                    spinnerName.style.animation = 'pulse 0.5s ease 3';
                    
                    setTimeout(() => callback(winner), 1500);
                }
            }
            
            spin();
        }

