        function updateDashboard() {
            // Get selected grades
            const selectedGrades = Array.from(document.querySelectorAll('.grade-filter-checkbox:checked'))
                .map(cb => cb.value);
            
            if (selectedGrades.length === 0) {
                // No grades selected - show zeros
                document.getElementById('avgBehaviorsPerStudent').textContent = '0.0';
                document.getElementById('avgPositivityRatio').textContent = '0%';
                document.getElementById('avgDollarsPerStudent').textContent = '$0';
                document.getElementById('dashTotalStudents').textContent = '0';
                document.getElementById('dashTotalPositive').textContent = '0';
                document.getElementById('dashTotalNegative').textContent = '0';
                document.getElementById('dashTotalAwarded').textContent = '$0';
                document.getElementById('dashTotalDeducted').textContent = '$0';
                document.getElementById('dashTotalCirculation').textContent = '$0';
                return;
            }
            
            // Enrolled only, then by grade.
            //
            // This counted the raw students array, which holds everyone the app
            // has ever seen: students who have left, and prior-year records
            // kept deliberately so their balances and histories survive. A
            // teacher reads "Total Students" as "how many students are here",
            // so counting the archived ones makes the tile wrong, and makes
            // every average below it wrong too, because filteredStudents.length
            // is the denominator for behaviours per student and dollars per
            // student.
            //
            // updateStats already learned this lesson for the raffle tiles.
            // This dashboard was missed.
            const filteredStudents = enrolledStudents()
                .filter(s => selectedGrades.includes(String(s.grade)));
            
            if (filteredStudents.length === 0) {
                // No students in selected grades
                document.getElementById('avgBehaviorsPerStudent').textContent = '0.0';
                document.getElementById('avgPositivityRatio').textContent = '0%';
                document.getElementById('avgDollarsPerStudent').textContent = '$0';
                document.getElementById('dashTotalStudents').textContent = '0';
                document.getElementById('dashTotalPositive').textContent = '0';
                document.getElementById('dashTotalNegative').textContent = '0';
                document.getElementById('dashTotalAwarded').textContent = '$0';
                document.getElementById('dashTotalDeducted').textContent = '$0';
                document.getElementById('dashTotalCirculation').textContent = '$0';
                return;
            }
            
            // Calculate metrics
            let totalPositiveBehaviors = 0;
            let totalNegativeBehaviors = 0;
            let totalBalance = 0;
            let totalAwarded = 0;
            let totalDeducted = 0;
            
            filteredStudents.forEach(student => {
                if (!student.wildcatCashTransactions) return;
                
                student.wildcatCashTransactions.forEach(txn => {
                    // Check for positive or negative type (behavior transactions)
                    if (txn.type === 'positive' || txn.type === 'negative') {
                        if (txn.amount > 0) {
                            totalPositiveBehaviors++;
                            totalAwarded += txn.amount;
                        } else if (txn.amount < 0) {
                            totalNegativeBehaviors++;
                            totalDeducted += Math.abs(txn.amount);
                        }
                    }
                });
                
                totalBalance += (student.wildcatCashBalance || 0);
            });
            
            const totalBehaviors = totalPositiveBehaviors + totalNegativeBehaviors;
            
            // Calculate averages
            const avgBehaviors = totalBehaviors / filteredStudents.length;
            const positivityRatio = totalBehaviors > 0 ? (totalPositiveBehaviors / totalBehaviors * 100) : 0;
            const avgBalance = totalBalance / filteredStudents.length;
            
            // Update dashboard
            document.getElementById('avgBehaviorsPerStudent').textContent = avgBehaviors.toFixed(1);
            document.getElementById('avgPositivityRatio').textContent = positivityRatio.toFixed(1) + '%';
            document.getElementById('avgDollarsPerStudent').textContent = '$' + Math.round(avgBalance).toLocaleString();
            
            document.getElementById('dashTotalStudents').textContent = filteredStudents.length;
            document.getElementById('dashTotalPositive').textContent = totalPositiveBehaviors;
            document.getElementById('dashTotalNegative').textContent = totalNegativeBehaviors;
            document.getElementById('dashTotalAwarded').textContent = '$' + Math.round(totalAwarded).toLocaleString();
            document.getElementById('dashTotalDeducted').textContent = '$' + Math.round(totalDeducted).toLocaleString();
            document.getElementById('dashTotalCirculation').textContent = '$' + Math.round(totalBalance).toLocaleString();
        }

        // ========================================
        // TEACHER INTERACTIONS ANALYTICS
        // ========================================

        function updateTeacherInteractions() {
            console.log('Updating Teacher Interactions analytics...');
            
            // Analyze teacher activity from wildcatCashTransactions
            const teacherStats = {};
            
            // Initialize stats for all teachers
            teachers.forEach(teacher => {
                teacherStats[teacher.id] = {
                    name: teacher.name,
                    totalInteractions: 0,
                    positiveCount: 0,
                    negativeCount: 0,
                    totalAwarded: 0,
                    totalDeducted: 0,
                    studentsImpacted: new Set()
                };
            });
            
            // Aggregate data from all student transactions
            students.forEach(student => {
                if (student.wildcatCashTransactions && student.wildcatCashTransactions.length > 0) {
                    student.wildcatCashTransactions.forEach(txn => {
                        // Check for teacherId field (from Award Cash) OR addedBy/removedBy (from Add/Remove Cash)
                        const teacherId = txn.teacherId || txn.addedBy || txn.removedBy;
                        
                        // Find teacher by ID or username (Add/Remove Cash uses username)
                        let matchedTeacher = null;
                        for (const teacher of teachers) {
                            if (teacher.id === teacherId || teacher.username === teacherId) {
                                matchedTeacher = teacher;
                                break;
                            }
                        }
                        
                        if (!matchedTeacher || !teacherStats[matchedTeacher.id]) return;
                        
                        const stats = teacherStats[matchedTeacher.id];
                        stats.totalInteractions++;
                        stats.studentsImpacted.add(student.id);
                        
                        if (txn.type === 'positive') {
                            stats.positiveCount++;
                            stats.totalAwarded += Math.abs(txn.amount);
                        } else if (txn.type === 'negative') {
                            stats.negativeCount++;
                            stats.totalDeducted += Math.abs(txn.amount);
                        }
                    });
                }
            });
            
            // Calculate summary stats
            let totalPositive = 0;
            let totalNegative = 0;
            let activeTeacherCount = 0;
            
            Object.values(teacherStats).forEach(stats => {
                if (stats.totalInteractions > 0) {
                    activeTeacherCount++;
                    totalPositive += stats.positiveCount;
                    totalNegative += stats.negativeCount;
                }
            });
            
            const overallPositivityRatio = (totalPositive + totalNegative) > 0 
                ? (totalPositive / (totalPositive + totalNegative) * 100) 
                : 0;
            
            // Update summary cards
            document.getElementById('teacherInteractionsActiveCount').textContent = activeTeacherCount;
            document.getElementById('teacherInteractionsTotalPositive').textContent = totalPositive.toLocaleString();
            document.getElementById('teacherInteractionsTotalNegative').textContent = totalNegative.toLocaleString();
            document.getElementById('teacherInteractionsPositivityRatio').textContent = overallPositivityRatio.toFixed(1) + '%';
            
            // Update teacher activity table
            updateTeacherActivityTable(teacherStats);
            
            // Update intervention students table
            updateInterventionStudents();
            
            // Update detailed interactions table
            updateTeacherInteractionDetails();
            
            // Populate teacher filter dropdown
            populateTeacherFilterDropdown();
        }

        function updateTeacherActivityTable(teacherStats) {
            const tbody = document.getElementById('teacherActivityTableBody');
            
            // Convert to array and sort by total interactions (descending)
            const sortedTeachers = Object.values(teacherStats)
                .filter(stats => stats.totalInteractions > 0)
                .sort((a, b) => b.totalInteractions - a.totalInteractions);
            
            if (sortedTeachers.length === 0) {
                tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; padding: 40px; color: #999;">No teacher activity recorded yet</td></tr>';
                return;
            }
            
            tbody.innerHTML = sortedTeachers.map(stats => {
                const positivityRatio = stats.totalInteractions > 0 
                    ? (stats.positiveCount / stats.totalInteractions * 100) 
                    : 0;
                
                const positivityColor = positivityRatio >= 70 ? '#2E7D52' : 
                                       positivityRatio >= 50 ? '#f59e0b' : '#B3392F';
                
                return `
                    <tr>
                        <td style="font-weight: 600;">${stats.name}</td>
                        <td style="text-align: center; font-weight: 600;">${stats.totalInteractions}</td>
                        <td style="text-align: center; color: #10b981; font-weight: 600;">${stats.positiveCount}</td>
                        <td style="text-align: center; color: #ef4444; font-weight: 600;">${stats.negativeCount}</td>
                        <td style="text-align: center; color: ${positivityColor}; font-weight: 700; font-size: 16px;">
                            ${positivityRatio.toFixed(1)}%
                        </td>
                        <td style="text-align: center; color: #10b981;">$${stats.totalAwarded.toLocaleString()}</td>
                        <td style="text-align: center; color: #ef4444;">$${stats.totalDeducted.toLocaleString()}</td>
                        <td style="text-align: center;">${stats.studentsImpacted.size}</td>
                    </tr>
                `;
            }).join('');
        }

        function updateInterventionStudents() {
            const tbody = document.getElementById('interventionStudentsTableBody');
            
            // Identify students needing intervention
            // Criteria: 5+ negative behaviors OR balance < $1000 OR total deducted > $2000
            const flaggedStudents = students.filter(student => {
                if (!student.wildcatCashTransactions) return false;
                
                const negativeCount = student.wildcatCashTransactions.filter(t => t.type === 'negative').length;
                const balance = student.wildcatCashBalance || 0;
                const totalDeducted = student.wildcatCashDeducted || 0;
                
                return negativeCount >= 5 || balance < 1000 || totalDeducted > 2000;
            }).sort((a, b) => {
                // Sort by most concerning (lowest balance or most deductions)
                const aScore = (a.wildcatCashBalance || 0) - (a.wildcatCashDeducted || 0);
                const bScore = (b.wildcatCashBalance || 0) - (b.wildcatCashDeducted || 0);
                return aScore - bScore;
            });
            
            if (flaggedStudents.length === 0) {
                tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; padding: 40px; color: #10b981; font-weight: 600;">✅ No students currently flagged for intervention</td></tr>';
                return;
            }
            
            tbody.innerHTML = flaggedStudents.map(student => {
                const negativeCount = student.wildcatCashTransactions.filter(t => t.type === 'negative').length;
                const balance = student.wildcatCashBalance || 0;
                const totalDeducted = student.wildcatCashDeducted || 0;
                
                // Find teachers who have interacted with this student
                const teachersSet = new Set();
                student.wildcatCashTransactions.forEach(txn => {
                    const teacherId = txn.teacherId || txn.addedBy || txn.removedBy;
                    // Match by ID or username
                    const teacher = teachers.find(t => t.id === teacherId || t.username === teacherId);
                    if (teacher) teachersSet.add(teacher.name);
                });
                const primaryTeachers = Array.from(teachersSet).slice(0, 3).join(', ');
                
                const balanceColor = balance < 500 ? '#B3392F' : balance < 1500 ? '#f59e0b' : '#2E7D52';
                
                return `
                    <tr style="background: ${balance < 500 ? 'rgba(239, 68, 68, 0.05)' : 'white'};">
                        <td style="font-weight: 600;">${student.firstName} ${student.lastName}</td>
                        <td style="text-align: center;">${student.grade}</td>
                        <td style="text-align: center; color: ${balanceColor}; font-weight: 700; font-size: 16px;">
                            $${balance.toLocaleString()}
                        </td>
                        <td style="text-align: center; color: #ef4444; font-weight: 600;">$${totalDeducted.toLocaleString()}</td>
                        <td style="text-align: center; color: #ef4444; font-weight: 700; font-size: 16px;">
                            ${negativeCount}
                        </td>
                        <td style="font-size: 13px;">${primaryTeachers || 'None'}</td>
                        <td style="text-align: center;">
                            <button class="btn btn-secondary" onclick="viewStudentCashDetails('${student.id}')" style="padding: 6px 12px; font-size: 12px;">
                                View Details
                            </button>
                        </td>
                    </tr>
                `;
            }).join('');
        }

        function updateTeacherInteractionDetails() {
            const tbody = document.getElementById('teacherInteractionDetailsTableBody');
            
            // Get filter values
            const selectedTeacher = document.getElementById('teacherInteractionFilterTeacher').value;
            const selectedType = document.getElementById('teacherInteractionFilterType').value;
            const searchText = document.getElementById('teacherInteractionFilterStudent').value.toLowerCase();
            
            // Collect all transactions
            const allTransactions = [];
            students.forEach(student => {
                if (student.wildcatCashTransactions) {
                    student.wildcatCashTransactions.forEach(txn => {
                        allTransactions.push({
                            ...txn,
                            studentId: student.id,
                            studentName: `${student.firstName} ${student.lastName}`,
                            grade: student.grade
                        });
                    });
                }
            });
            
            console.log('=== TEACHER INTERACTIONS DEBUG ===');
            console.log('Total transactions:', allTransactions.length);
            console.log('Sample transaction:', allTransactions[0]);
            console.log('Teachers array:', teachers);
            console.log('Current user:', currentUser);
            
            // Filter transactions
            let filteredTransactions = allTransactions.filter(txn => {
                // Filter by teacher - check teacherId, addedBy, or removedBy
                const teacherId = txn.teacherId || txn.addedBy || txn.removedBy;
                if (selectedTeacher) {
                    // Match by ID directly, or find teacher by username and compare IDs
                    const teacher = teachers.find(t => t.id === selectedTeacher);
                    const matches = teacherId === selectedTeacher || 
                                  (teacher && teacher.username === teacherId);
                    if (!matches) return false;
                }
                
                // Filter by type
                if (selectedType === 'positive' && txn.type !== 'positive') return false;
                if (selectedType === 'negative' && txn.type !== 'negative') return false;
                
                // Filter by student name
                if (searchText && !txn.studentName.toLowerCase().includes(searchText)) return false;
                
                return true;
            });
            
            // Sort by timestamp (most recent first)
            filteredTransactions.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
            
            // Limit to 100 most recent
            filteredTransactions = filteredTransactions.slice(0, 100);
            
            if (filteredTransactions.length === 0) {
                tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; padding: 40px; color: #999;">No interactions match the current filters</td></tr>';
                return;
            }
            
            tbody.innerHTML = filteredTransactions.map(txn => {
                // Get teacher name - prefer stored teacherName, fallback to looking up by ID or username
                let teacherName = txn.teacherName;
                if (!teacherName) {
                    const teacherId = txn.teacherId || txn.addedBy || txn.removedBy;
                    // Try to find teacher by ID or username (Add/Remove Cash uses username)
                    const teacher = teachers.find(t => t.id === teacherId || t.username === teacherId);
                    teacherName = teacher ? teacher.name : `Unknown (${teacherId})`;
                }
                
                const date = new Date(txn.timestamp);
                const formattedDate = date.toLocaleDateString() + ' ' + date.toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'});
                
                const typeColor = txn.type === 'positive' ? '#2E7D52' : '#B3392F';
                const typeBadge = txn.type === 'positive' ? 'Positive' : 'Negative';
                const amountDisplay = txn.type === 'positive' ? `+$${Math.abs(txn.amount)}` : `-$${Math.abs(txn.amount)}`;
                
                return `
                    <tr>
                        <td style="font-size: 13px; color: #666;">${formattedDate}</td>
                        <td>${teacherName}</td>
                        <td style="font-weight: 600;">${txn.studentName}</td>
                        <td style="text-align: center;">${txn.grade}</td>
                        <td>${txn.behaviorName || '-'}</td>
                        <td style="text-align: center;">
                            <span style="padding: 4px 10px; border-radius: 12px; font-size: 12px; font-weight: 600; background: ${typeColor}; color: white;">
                                ${typeBadge}
                            </span>
                        </td>
                        <td style="text-align: center; color: ${typeColor}; font-weight: 700; font-size: 16px;">
                            ${amountDisplay}
                        </td>
                        <td style="font-size: 13px;">${txn.notes || '-'}</td>
                    </tr>
                `;
            }).join('');
        }

        function populateTeacherFilterDropdown() {
            const dropdown = document.getElementById('teacherInteractionFilterTeacher');
            
            // Get unique teachers who have made transactions
            const activeTeachers = new Set();
            students.forEach(student => {
                if (student.wildcatCashTransactions) {
                    student.wildcatCashTransactions.forEach(txn => {
                        const teacherId = txn.teacherId || txn.addedBy || txn.removedBy;
                        if (!teacherId) return;
                        
                        // Find the teacher by ID or username and add their ID to the set
                        const teacher = teachers.find(t => t.id === teacherId || t.username === teacherId);
                        if (teacher) activeTeachers.add(teacher.id);
                    });
                }
            });
            
            // Build dropdown options
            const options = ['<option value="">All Teachers</option>'];
            teachers.forEach(teacher => {
                if (activeTeachers.has(teacher.id)) {
                    options.push(`<option value="${teacher.id}">${teacher.name}</option>`);
                }
            });
            
            dropdown.innerHTML = options.join('');
        }

        function viewStudentCashDetails(studentId) {
            // Switch to Student Accounts tab and focus on this student
            switchTab('studentAccounts');
            
            // Scroll to and highlight the student's row
            setTimeout(() => {
                const rows = document.querySelectorAll('#studentAccountsTableBody tr');
                rows.forEach(row => {
                    if (row.dataset.studentId === studentId) {
                        row.style.background = 'rgba(47, 103, 167, 0.12)';
                        row.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        setTimeout(() => {
                            row.style.background = '';
                        }, 3000);
                    }
                });
            }, 100);
        }

        // ========================================
        // DISCIPLINE MODE FUNCTIONS
        // ========================================

        function switchDisciplineTab(subtab) {
            // Panes are hidden via the .hidden class, which is `display:none
            // !important` — inline styles cannot override it, so visibility MUST
            // be toggled by class here.
            document.querySelectorAll('.discipline-subtab').forEach(tab => tab.classList.add('hidden'));

            document.querySelectorAll('.subtab-button').forEach(btn => {
                btn.style.background = '#f5f5f5';
                btn.style.color = '#333';
            });

            const PANES = {
                submit:    { pane: 'behaviorSubmit',    btn: 'submitTabBtn' },
                review:    { pane: 'behaviorReview',    btn: 'reviewTabBtn' },
                closed:    { pane: 'behaviorClosed',    btn: null },
                detention: { pane: 'behaviorDetention', btn: 'detentionTabBtn' },
                history:   { pane: 'behaviorHistory',   btn: 'historyDisciplineTabBtn' },
                analytics: { pane: 'behaviorAnalytics', btn: 'analyticsDisciplineTabBtn' }
            };
            const target = PANES[subtab];
            if (!target) { console.warn('switchDisciplineTab: unknown subtab', subtab); return; }

            // CHECKED HERE TOO, not only when the buttons are drawn. A stale
            // button, a restored tab from a previous session, or a call from
            // the console must not open Analytics or Student History for a
            // teacher. Demographics lives inside Analytics, so this is the
            // check that keeps a child's grade, sex and race breakdown away
            // from someone who may only file referrals.
            if (!window.WildcatDiscipline.canOpenDisciplineTab(currentUser && currentUser.role, subtab)) {
                console.warn(`[discipline] ${subtab} is not available to your access level.`);
                switchDisciplineTab('submit');
                return;
            }

            const paneEl = document.getElementById(target.pane);
            if (paneEl) {
                paneEl.classList.remove('hidden');
                paneEl.style.display = '';   // clear any stale inline display
            }
            if (target.btn) {
                const btn = document.getElementById(target.btn);   // null-safe
                if (btn) { btn.style.background = '#f59e0b'; btn.style.color = 'white'; }
            }

            // Mark the matching sidebar item active
            document.querySelectorAll('#modeSubNav .tab').forEach(b => b.classList.remove('active'));
            const sideBtn = document.getElementById(`sideSub_discipline_${subtab}`);
            if (sideBtn) sideBtn.classList.add('active');

            // Per-tab data loading
            if (subtab === 'submit') {
                resetReferralRosterFetch();
                populateReferralStudentDropdown();
                if (typeof populateReferringStaffDropdown === 'function') populateReferringStaffDropdown();
                const now = new Date();
                const dateInput = document.getElementById('referralDate');
                const timeInput = document.getElementById('referralTime');
                if (dateInput && !dateInput.value) dateInput.value = now.toISOString().split('T')[0];
                if (timeInput && !timeInput.value) timeInput.value = now.toTimeString().slice(0, 5);
                if (typeof updateInterventionCount === 'function') updateInterventionCount();
            } else if (subtab === 'review') {
                updateReferralReviewTable();
            } else if (subtab === 'closed') {
                if (typeof updateClosedReferralsList === 'function') updateClosedReferralsList();
            } else if (subtab === 'detention') {
                if (typeof initializeDetentionForm === 'function') initializeDetentionForm();
                if (typeof updateDetentionLists === 'function') updateDetentionLists();
            } else if (subtab === 'history') {
                populateHistoryStudentDropdown();
            } else if (subtab === 'analytics') {
                updateReferralAnalytics();
                switchAnalyticsTab(analyticsTab);
            }
        }

        // At most one roster fetch per visit to the referral form, so a
        // failed lookup cannot loop on a broken connection.
        let referralRosterFetchTried = false;
        function resetReferralRosterFetch() { referralRosterFetchTried = false; }

        /**
         * The student picker on the referral form: narrow, search, pick.
         *
         * EVERY ENROLLED STUDENT STAYS REACHABLE. Confirmed with the owner
         * 2026-09-04. A referral is written for what somebody did, and most of
         * what gets referred happens in a corridor, a stairwell or the yard,
         * between an adult and a child who have never shared a timetable.
         * Scoping this to a roster the way Award Cash is scoped would make the
         * commonest referral impossible to file, and would leave the seven
         * teachers who have no PowerSchool sections unable to file at all.
         *
         * So the period filter is a SHORTCUT, never a restriction: it defaults
         * to All Students and every narrowing option sits alongside that rather
         * than replacing it. Award Cash is the opposite -- there the roster is
         * the boundary -- and the two must not be "made consistent" with each
         * other, because they are answering different questions.
         *
         * ENROLLED ONLY. `students` carries the 139 leavers so their balances
         * and histories survive; a referral filed against a child who has left
         * is a record nobody can act on.
         */
        function populateReferralStudentDropdown() {
            const select = document.getElementById('referralStudentSelect');
            if (!select) return;
            const scopeSel = document.getElementById('referralStudentScope');
            const searchEl = document.getElementById('referralStudentSearch');
            const hint = document.getElementById('referralStudentHint');

            const roster = activeTeacherRoster();
            const sections = window.WildcatRoster.sectionsFrom(roster);
            const everyone = enrolledStudents();

            // ---- The scope control, rebuilt in place ------------------------
            // Kept on the value the user chose. Rebuilding drops a section that
            // no longer exists, which is correct: silently keeping a stale
            // selection would filter against nothing and read as "no students".
            if (scopeSel) {
                const wanted = scopeSel.value;
                let html = `<option value="">All students (${everyone.length})</option>`;
                if (sections.length) {
                    const mine = window.WildcatRoster.studentNumbersFor(roster, null);
                    const mineCount = everyone.filter(st =>
                        mine[String(st.studentNumber || '').trim()] === true).length;
                    html += `<option value="__mine">My students (${mineCount})</option>`;
                    sections.forEach(sec => {
                        html += `<option value="${sec.sectionId}">` +
                                `${sec.label} (${(sec.students || []).length})</option>`;
                    });
                }
                scopeSel.innerHTML = html;
                scopeSel.value = wanted;
                if (scopeSel.selectedIndex < 0) scopeSel.value = '';
            }

            // ---- Narrow ----------------------------------------------------
            const scope = scopeSel ? scopeSel.value : '';
            let pool = everyone;
            if (scope === '__mine' || (scope && scope !== '')) {
                const picked = window.WildcatRoster.studentNumbersFor(
                    roster, scope === '__mine' ? null : scope);
                pool = everyone.filter(st =>
                    picked[String(st.studentNumber || '').trim()] === true);
            }

            // ---- Search ----------------------------------------------------
            // Name in either order, plus the id a teacher reads off a screen.
            const q = (searchEl ? searchEl.value : '').toLowerCase().trim();
            if (q) {
                pool = pool.filter(st => {
                    const first = String(st.firstName || '').toLowerCase();
                    const last = String(st.lastName || '').toLowerCase();
                    return `${first} ${last}`.includes(q)
                        || `${last}, ${first}`.includes(q)
                        || String(st.id || '').toLowerCase().includes(q)
                        || String(st.studentNumber || '').toLowerCase().includes(q);
                });
            }

            const sorted = [...pool].sort((a, b) =>
                `${a.lastName}, ${a.firstName}`.toLowerCase()
                    .localeCompare(`${b.lastName}, ${b.firstName}`.toLowerCase()));

            // ---- Rebuild, without losing a choice already made --------------
            // A teacher who picks a child and then types in the search box must
            // not have the selection silently cleared underneath them.
            const chosen = select.value;
            select.innerHTML = '<option value="">Search and select a student...</option>' +
                sorted.map(st =>
                    `<option value="${st.id}">${st.lastName}, ${st.firstName} (Grade ${st.grade})</option>`
                ).join('');
            if (chosen && sorted.some(st => String(st.id) === String(chosen))) {
                select.value = chosen;
            }

            if (hint) {
                hint.textContent = sorted.length
                    ? `${sorted.length} student${sorted.length === 1 ? '' : 's'} listed. ` +
                      'Any student in the school can be referred.'
                    : (q ? 'No student matches that search.' : 'No students in that class.');
            }

            // The roster is fetched by Award Cash, so in Discipline it may not
            // be here yet. Paint from what exists, then fetch and repaint --
            // awaiting would leave the form blank on a network round trip.
            if (!roster && sisRosterState !== 'loading'
                && !referralRosterFetchTried && !isPreviewingTeacher()) {
                referralRosterFetchTried = true;
                loadTeacherRosterFromSIS(true).then(() => populateReferralStudentDropdown());
            }
        }

        /**
         * Student History, admin and PBIS only (see disciplineTabsFor).
         *
         * Enrolled only, matching the referral form. Looking up the discipline
         * history of a child who left is not a thing this screen is for, and
         * the leavers are only in `students` so their balances survive.
         */
        function populateHistoryStudentDropdown() {
            const select = document.getElementById('historyStudentSelect');
            const sortedStudents = [...enrolledStudents()].sort((a, b) => {
                const aName = `${a.lastName}, ${a.firstName}`.toLowerCase();
                const bName = `${b.lastName}, ${b.firstName}`.toLowerCase();
                return aName.localeCompare(bName);
            });
            
            select.innerHTML = '<option value="">Select a student...</option>' + 
                sortedStudents.map(s => 
                    `<option value="${s.id}">${s.lastName}, ${s.firstName} (Grade ${s.grade})</option>`
                ).join('');
        }


        // ============================================================
        // REFERRALS (rebuilt to mirror the Office Referral Form)
        //
        // Severity was removed deliberately: severity is now carried by
        // the behaviour label itself ("Habitual…", "Repeated…"), and
        // analytics rank by behaviour frequency (top 10) instead.
        //
        // Referring staff defaults to the logged-in user; admins and
        // superadmins may file on another staff member's behalf.
        // ============================================================


        // ============================================================
        // Instant feedback for referral actions.
        //
        // saveData() writes eight documents sequentially (transactions plus
        // 50ms spacing), so awaiting it before confirming took several
        // seconds — long enough that staff re-clicked Submit and filed
        // duplicates. These actions now confirm immediately and persist in
        // the background, surfacing an error only if the save actually fails.
        // ============================================================

        // ============================================================
        // PRINTABLE REFERRAL DOCUMENT
        //
        // Opens a branded, print-ready page in a new window and triggers the
        // browser print dialog, where "Save as PDF" produces the file. Done
        // this way rather than with a PDF library so the document uses the
        // real Visuelt font and the school logo already in the page, with no
        // extra dependency and no font-embedding step.
        // ============================================================

        function getSchoolLogoSrc() {
            const img = document.querySelector('.topbar-logo');
            if (img && img.src) return img.src;
            if (schoolBranding && schoolBranding.logoBase64) return schoolBranding.logoBase64;
            return '';
        }

        async function printReferral(referralId) {
            const r = (behaviorReferrals || []).find(x => x.id === referralId);
            if (!r) { alert('⚠️ Referral not found'); return; }
            const student = (students || []).find(s => s.id === r.studentId) || {};
            const esc = escapeHtml;

            const fmtDate = (d) => {
                if (!d) return '—';
                const dt = new Date(String(d).length <= 10 ? d + 'T12:00:00' : d);
                return isNaN(dt) ? esc(d) : dt.toLocaleDateString('en-US',
                    { year: 'numeric', month: 'long', day: 'numeric' });
            };
            const statusText = r.status === 'closed'
                ? (r.loopClosed ? 'Resolved: loop closed' : 'Resolved')
                : 'Open: awaiting administrator';

            const interventions = (r.interventions || []);
            const closingActions = (r.closingActions || []);
            const logo = getSchoolLogoSrc();
            const fileName = `Referral_${(r.studentName || 'Student').replace(/[^A-Za-z0-9]+/g, '_')}_${r.date || ''}`;

            const row = (label, value) =>
                `<div class="f"><div class="fl">${label}</div><div class="fv">${value || '—'}</div></div>`;

            const doc = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>${esc(fileName)}</title>
<style>
  @font-face { font-family:'Visuelt'; src:url('fonts/VisueltPro-Regular.woff') format('woff'); font-weight:400 500; }
  @font-face { font-family:'Visuelt'; src:url('fonts/VisueltPro-Bold.woff') format('woff'); font-weight:700; }
  * { box-sizing:border-box; }
  body { font-family:'Visuelt','Figtree',-apple-system,sans-serif; color:#0E0E0E; margin:0; padding:38px 44px; font-size:12.5px; line-height:1.5; }
  .head { display:flex; align-items:center; gap:16px; border-bottom:3px solid #2F67A7; padding-bottom:14px; margin-bottom:6px; }
  .head img { height:56px; width:auto; }
  .head h1 { font-size:19px; margin:0; font-weight:700; color:#0E0E0E; }
  .head h2 { font-size:13.5px; margin:3px 0 0; font-weight:500; color:#2F67A7; letter-spacing:.03em; text-transform:uppercase; }
  .gen { font-size:10.5px; color:#5F5E5A; margin:0 0 22px; }
  .sec { margin-bottom:20px; }
  .sec-title { font-size:11px; font-weight:700; letter-spacing:.09em; text-transform:uppercase;
               color:#fff; background:#2F67A7; padding:6px 12px; border-radius:4px; margin-bottom:12px; }
  .grid { display:grid; grid-template-columns:1fr 1fr; gap:11px 26px; }
  .f { border-bottom:1px solid #e3e8ef; padding-bottom:6px; }
  .fl { font-size:9.5px; font-weight:700; letter-spacing:.07em; text-transform:uppercase; color:#5F5E5A; margin-bottom:2px; }
  .fv { font-size:13px; font-weight:500; }
  .block { border:1px solid #e3e8ef; border-left:3px solid #2F67A7; border-radius:6px; padding:11px 14px; background:#fafbfd; }
  ul.list { margin:0; padding-left:18px; }
  ul.list li { margin-bottom:4px; }
  .none { color:#8a94a3; font-style:italic; }
  .sigs { display:grid; grid-template-columns:1fr 1fr 1fr; gap:26px; margin-top:32px; }
  .sig { border-top:1.5px solid #0E0E0E; padding-top:6px; }
  .sig-l { font-size:9.5px; font-weight:700; letter-spacing:.07em; text-transform:uppercase; color:#5F5E5A; }
  .sig-d { font-size:10px; color:#8a94a3; margin-top:14px; }
  .foot { margin-top:34px; padding-top:10px; border-top:1px solid #e3e8ef;
          font-size:9.5px; color:#8a94a3; display:flex; justify-content:space-between; }
  .pill { display:inline-block; padding:2px 9px; border-radius:999px; font-size:10.5px; font-weight:700;
          background:#E6F1FB; color:#0C447C; }
  @media print { body { padding:0; } @page { margin:16mm; } }
</style></head><body>
  <div class="head">
    ${logo ? `<img src="${logo}" alt="">` : ''}
    <div>
      <h1>Westbrook Middle &amp; High School</h1>
      <h2>Behavioral Referral Report</h2>
    </div>
  </div>
  <p class="gen">Generated: ${new Date().toLocaleDateString('en-US', { year:'numeric', month:'long', day:'numeric' })}</p>

  <div class="sec">
    <div class="sec-title">Student Details</div>
    <div class="grid">
      ${row('Full Name', esc(r.studentName))}
      ${row('Student ID', esc(r.studentId))}
      ${row('Grade', esc(r.studentGrade || student.grade || ''))}
      ${row('School', esc(r.school || ''))}
      ${row('Referring Staff', esc(r.referredBy))}
      ${row('Status', `<span class="pill">${esc(statusText)}</span>`)}
    </div>
  </div>

  <div class="sec">
    <div class="sec-title">Incident Information</div>
    <div class="grid">
      ${row('Date of Incident', fmtDate(r.date))}
      ${row('Time', esc(r.time || ''))}
      ${row('Location', esc(r.location || ''))}
      ${row('Behavior / Violation', esc(r.behavior || r.behaviorType || ''))}
    </div>
  </div>

  <div class="sec">
    <div class="sec-title">Incident Description</div>
    <div class="block">${esc(r.description) || '<span class="none">No description recorded</span>'}</div>
  </div>

  <div class="sec">
    <div class="sec-title">Interventions Prior to Referral</div>
    <div class="block">
      ${r.severeBypass
        ? '<div class="severe-flag"><strong>Too severe for classroom interventions.</strong> ' +
          'Immediate removal was warranted.</div>' : ''}
      ${interventions.length
        ? `<ul class="list">${interventions.map(i => `<li>${esc(i)}</li>`).join('')}</ul>`
        : (r.severeBypass
            ? '<span class="none">None attempted, by design.</span>'
            : '<span class="none">None recorded</span>')}
    </div>
  </div>

  ${r.additionalActions ? `<div class="sec">
    <div class="sec-title">Additional Actions / Notes</div>
    <div class="block">${esc(r.additionalActions)}</div>
  </div>` : ''}

  ${r.status === 'closed' ? `<div class="sec">
    <div class="sec-title">Resolution</div>
    <div class="block">
      <strong>${r.resolutionType === 'no_action' ? 'No action required' : 'Action taken'}</strong>
      ${closingActions.length ? `<ul class="list" style="margin-top:6px;">${closingActions.map(a => `<li>${esc(a)}</li>`).join('')}</ul>` : ''}
      ${r.adminNotes ? `<div style="margin-top:8px;">${esc(r.adminNotes)}</div>` : ''}
      <div style="margin-top:8px; font-size:11px; color:#5F5E5A;">
        Closed by ${esc(r.closedBy || '—')}${r.closedAt ? ' on ' + fmtDate(r.closedAt) : ''}
      </div>
    </div>
  </div>` : ''}

  <div class="sigs">
    <div class="sig"><div class="sig-l">Student Signature</div><div class="sig-d">Date: ______________</div></div>
    <div class="sig"><div class="sig-l">Parent / Guardian Signature</div><div class="sig-d">Date: ______________</div></div>
    <div class="sig"><div class="sig-l">Administrator Signature</div><div class="sig-d">Date: ______________</div></div>
  </div>

  <div class="foot">
    <span>Westbrook Referral System</span>
    <span>Referral ${esc(r.id)} &middot; Page 1 of 1</span>
  </div>
</body></html>`;

            const w = window.open('', '_blank');
            if (!w) {
                alert('⚠️ Your browser blocked the pop-up.\n\nAllow pop-ups for this site, then try again.');
                return;
            }
            w.document.write(doc);
            w.document.close();
            w.document.title = fileName;
            // Give the font and logo a moment to load before printing.
            setTimeout(() => { try { w.focus(); w.print(); } catch (e) { console.warn(e); } }, 450);
        }


        // ============================================================
        // IN-APP DIALOGS
        //
        // Replaces the browser's alert() / await showConfirm() / await showPrompt(), which are
        // unstyled, say "wildcatraffle.com says", and block the page.
        //
        // window.alert is overridden so all ~216 existing calls are restyled
        // without touching their call sites. Messages beginning with ✅ become
        // a non-blocking toast; anything else opens a dialog that must be
        // acknowledged, which preserves the original "stop and read" intent.
        //
        // await showConfirm() and await showPrompt() cannot be overridden the same way — they
        // return a value synchronously and a styled dialog cannot — so those
        // call sites use `await showConfirm(...)` / `await showPrompt(...)`.
        // ============================================================



        // ============================================================
        // WILDCAT CASH — DATA ENGINE
        //
        // Rebuilt because the previous model wrote every transaction TWICE
        // (once onto the student record inside `main`, once into a global
        // array inside `secondary`). At ~150 transactions/day that added
        // roughly 4x the 1MB document limit to `main` per school year.
        //
        // Model now:
        //   • Source of truth = weekly documents `cash_tx_YYYY_Www`
        //     (~750 transactions/week ≈ 113KB, never fills up). Weekly rather
        //     than one-document-per-transaction because the app loads all data
        //     at startup: 27,000 individual reads x 49 staff would blow past
        //     Firestore's daily read quota. Weekly docs ≈ 36 reads/year.
        //   • Student record keeps ONLY balance + counters, so balances render
        //     without loading any history.
        //   • student.wildcatCashTransactions is rebuilt in memory on load for
        //     the existing read paths, and stripped again before saving `main`.
        //
        // Rules (set with the school):
        //   • Everyone starts at $0 and earns from scratch.
        //   • Deductions may take a balance negative — the student owes it back.
        //   • All staff may award and deduct.
        // ============================================================

        function cashWeekKey(ts) {
            const s = String(ts || new Date().toISOString());
            const m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
            if (!m) return 'unknown';
            const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
            const day = d.getUTCDay() || 7;
            d.setUTCDate(d.getUTCDate() + 4 - day);
            const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
            const week = Math.ceil(((d - yearStart) / 86400000 + 1) / 7);
            return `${d.getUTCFullYear()}_W${String(week).padStart(2, '0')}`;
        }

        function getKnownCashWeekKeys() {
            const keys = [];
            const now = new Date();
            for (let i = 0; i < 60; i++) {
                const k = cashWeekKey(new Date(now.getTime() - i * 7 * 86400000).toISOString());
                if (k !== 'unknown' && keys.indexOf(k) === -1) keys.push(k);
            }
            return keys;
        }

        function ensureCashFields(student) {
            if (!student) return null;
            if (typeof student.wildcatCashBalance !== 'number')  student.wildcatCashBalance = 0;
            if (typeof student.wildcatCashEarned !== 'number')   student.wildcatCashEarned = 0;
            if (typeof student.wildcatCashSpent !== 'number')    student.wildcatCashSpent = 0;
            if (typeof student.wildcatCashDeducted !== 'number') student.wildcatCashDeducted = 0;
            if (!Array.isArray(student.wildcatCashTransactions)) student.wildcatCashTransactions = [];
            if (!Array.isArray(student.wildcatCashRewardsRedeemed)) student.wildcatCashRewardsRedeemed = [];
            // Legacy fields retired: cashBalance / cashTransactions.
            if ('cashBalance' in student) delete student.cashBalance;
            if ('cashTransactions' in student) delete student.cashTransactions;
            return student;
        }

        // THE single place a cash transaction is created. Every award, deduction
        // and redemption goes through here so the shape stays consistent and the
        // analytics can rely on it.
        function recordCashTransaction(opts) {
            const student = ensureCashFields(opts.student);
            if (!student) return null;

            const amount = Number(opts.amount) || 0;
            const actor = currentUser || {};
            const now = new Date().toISOString();

            student.wildcatCashBalance += amount;
            if (opts.kind === 'redeem')      student.wildcatCashSpent += Math.abs(amount);
            else if (amount > 0)             student.wildcatCashEarned += amount;
            else                             student.wildcatCashDeducted += Math.abs(amount);

            const tx = {
                id: 'txn_' + Date.now() + '_' + Math.random().toString(36).slice(2, 9),
                timestamp: now,
                studentId: student.id,
                studentName: `${student.firstName} ${student.lastName}`,
                studentGrade: student.grade || '',
                school: (parseInt(student.grade, 10) >= 9) ? 'High School' : 'Middle School',
                // Teacher identity is recorded on EVERY transaction: the point of
                // this log is knowing who is participating, not just the balance.
                teacherId: actor.id || '',
                teacherUsername: actor.username || '',
                teacherName: actor.name || actor.username || 'Unknown',
                kind: opts.kind || (amount >= 0 ? 'award' : 'deduct'),
                type: amount >= 0 ? 'positive' : 'negative',
                behaviorId: opts.behaviorId || '',
                behaviorName: opts.behaviorName || '',
                amount: amount,
                notes: opts.notes || '',
                balanceAfter: student.wildcatCashBalance
            };

            cashTransactions.push(tx);
            student.wildcatCashTransactions.push(tx);
            return tx;
        }

        // Derive a balance from history — the previous model only ever
        // incremented, so a failed save desynced a student permanently with
        // nothing able to detect it (28 students had already drifted).
        function recalculateCashBalance(student) {
            ensureCashFields(student);
            const txs = cashTransactions.filter(t => t.studentId === student.id);
            let bal = 0, earned = 0, spent = 0, deducted = 0;
            txs.forEach(t => {
                const a = Number(t.amount) || 0;
                bal += a;
                if (t.kind === 'redeem') spent += Math.abs(a);
                else if (a > 0) earned += a;
                else deducted += Math.abs(a);
            });
            return { balance: bal, earned, spent, deducted, count: txs.length };
        }


        // Rebuild the per-student view from the single source of truth.
        function distributeCashTransactions() {
            const byStudent = {};
            (cashTransactions || []).forEach(t => {
                (byStudent[t.studentId] = byStudent[t.studentId] || []).push(t);
            });
            (students || []).forEach(s => {
                ensureCashFields(s);
                s.wildcatCashTransactions = byStudent[s.id] || [];
            });
        }


        // ============================================================
        // CASH TEST DATA
        //
        // The analytics that matter here — who is participating, who is being
        // overlooked — cannot be validated by clicking a few buttons. This
        // seeds enough volume to check them, and deliberately builds in the
        // patterns the reports are supposed to surface:
        //   • a teacher who awards nothing
        //   • a teacher who only deducts (inverted positive:negative ratio)
        //   • students nobody has recognised
        //   • a couple of clear overperformers
        // Everything created is prefixed TEST- and removable in one action.
        // ============================================================

        const CASH_TEST_PREFIX = 'TEST-';

        function seedCashTestData() {
            if (!wildcatCashBehaviors || !wildcatCashBehaviors.length) {
                alert('⚠️ No cash behaviors configured.\n\nAdd behaviors in Settings first.');
                return;
            }
            const positives = wildcatCashBehaviors.filter(b => b.points > 0);
            const negatives = wildcatCashBehaviors.filter(b => b.points < 0);
            if (!positives.length || !negatives.length) {
                alert('⚠️ Need at least one positive and one negative behavior configured.');
                return;
            }

            const firsts = ['Ava','Liam','Mia','Noah','Zoe','Eli','Nora','Kai','Luna','Owen',
                            'Iris','Cruz','Sage','Milo','Wren','Otto','Vera','Dax','Cleo','Rex',
                            'Juno','Finn','Lyra','Ezra','Nova','Rhys','Tess','Beau','Isla','Jude'];
            const grades = [6,7,8,9,10,11,12];

            // 30 test students
            const made = [];
            firsts.forEach((f, i) => {
                const id = CASH_TEST_PREFIX + String(1000 + i);
                if (students.find(s => s.id === id)) return;
                const s = {
                    id, firstName: f, lastName: 'Testcase',
                    grade: String(grades[i % grades.length]),
                    pbisTickets: 0, attendanceTickets: 0, academicTickets: 0,
                    bigRaffleQualified: [], weeksQualified: 0,
                    ticketHistory: [], sections: []
                };
                ensureCashFields(s);
                students.push(s);
                made.push(s);
            });

            // Teachers to attribute transactions to, including a silent one
            const staff = (teachers || []).slice(0, 5);
            if (!staff.length) { alert('⚠️ No teachers found to attribute transactions to.'); return; }
            const silent = staff[staff.length - 1];              // awards nothing
            const negativeHeavy = staff[0];                       // mostly deductions
            const givers = staff.filter(t => t !== silent);

            const realActor = currentUser;
            const daysBack = 21;
            let created = 0;

            made.forEach((student, idx) => {
                // Every 6th student is deliberately left with nothing, so the
                // "forgotten students" report has something real to find.
                if (idx % 6 === 0) return;
                const isOverperformer = (idx % 10 === 3);
                const n = isOverperformer ? 14 : 2 + (idx % 5);

                for (let k = 0; k < n; k++) {
                    const actor = givers[(idx + k) % givers.length];
                    const negativeBias = (actor === negativeHeavy) ? 0.7 : 0.15;
                    const goNegative = Math.random() < negativeBias;
                    const pool = goNegative ? negatives : positives;
                    const behavior = pool[Math.floor(Math.random() * pool.length)];

                    // Impersonate the attributed teacher so teacherId is realistic.
                    currentUser = actor;
                    const tx = recordCashTransaction({
                        student,
                        amount: behavior.points,
                        behaviorId: behavior.id,
                        behaviorName: behavior.name,
                        notes: 'Seeded test data',
                        kind: behavior.points >= 0 ? 'award' : 'deduct'
                    });
                    if (tx) {
                        // Back-date across the last three weeks so weekly
                        // partitioning and date filters get exercised.
                        const d = new Date();
                        d.setDate(d.getDate() - Math.floor(Math.random() * daysBack));
                        d.setHours(8 + Math.floor(Math.random() * 8), Math.floor(Math.random() * 60));
                        tx.timestamp = d.toISOString();
                        created++;
                    }
                }
            });
            currentUser = realActor;

            // Balances were accumulated in timestamp-agnostic order; recompute.
            students.forEach(s => {
                if (String(s.id).startsWith(CASH_TEST_PREFIX)) {
                    const c = recalculateCashBalance(s);
                    s.wildcatCashBalance = c.balance;
                    s.wildcatCashEarned = c.earned;
                    s.wildcatCashSpent = c.spent;
                    s.wildcatCashDeducted = c.deducted;
                }
            });
            cashTransactions.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));
            distributeCashTransactions();

            if (typeof updateCashTable === 'function') updateCashTable();
            if (typeof updateAllDisplays === 'function') updateAllDisplays();
            saveData();

            showToast(`✅ Seeded ${made.length} test students and ${created} transactions\nIncludes a silent teacher, a deduction-heavy teacher, and unrecognised students`, 'success', 7000);
        }

        async function clearCashTestData() {
            const testIds = students.filter(s => String(s.id).startsWith(CASH_TEST_PREFIX)).map(s => s.id);
            if (!testIds.length) { alert('No test data found.'); return; }
            const ok = await showConfirm(
                `Remove all test data?\n\n${testIds.length} test students and every transaction attached to them will be deleted.\n\nReal students and their transactions are not touched.`,
                { danger: true, confirmLabel: 'Remove test data' });
            if (!ok) return;

            students = students.filter(s => !String(s.id).startsWith(CASH_TEST_PREFIX));
            cashTransactions = cashTransactions.filter(t => !String(t.studentId).startsWith(CASH_TEST_PREFIX));
            distributeCashTransactions();
            if (typeof updateCashTable === 'function') updateCashTable();
            if (typeof updateAllDisplays === 'function') updateAllDisplays();
            await saveData();
            showToast(`✅ Removed ${testIds.length} test students and their transactions`, 'success');
        }

        // ============================================================
        // SAVING INDICATOR
        //
        // Several actions must await saveData() before confirming — awarding
        // tickets, for instance, warns in-code that returning early risks a
        // stale overwrite. Rather than weaken that, this shows the click
        // registered immediately: a pill appears under the top bar for the
        // duration of the save, so the gap before the confirmation no longer
        // looks like nothing happened.
        // ============================================================
        function showSavingIndicator(on) {
            // Never over the login screen. The app dual-writes on boot and on a
            // roster refresh, and that fired this pill while nobody was signed
            // in — so the first thing a visitor saw was the login screen wearing
            // a "Saving…" tag, which is the exact noise the owner called out.
            // The pill is an acknowledgement for a signed-in user standing over
            // a control; logged out, there is nothing to acknowledge. The full
            // screen sign-in wait is the loader's job, not this.
            const signedIn = (typeof currentUser !== 'undefined' && currentUser)
                || (typeof currentStudent !== 'undefined' && currentStudent);
            const onLogin = !document.getElementById('loginScreen')?.classList.contains('hidden');
            if (on && (!signedIn || onLogin)) return;

            let el = document.getElementById('wcSaving');
            if (!el) {
                el = document.createElement('div');
                el.id = 'wcSaving';
                el.className = 'wc-saving';
                el.innerHTML = '<span class="wc-saving-dot"></span><span>Saving…</span>';
                document.body.appendChild(el);
            }
            clearTimeout(el._hide);
            if (on) {
                el.classList.add('wc-saving-show');
            } else {
                // Brief minimum on-screen time so it doesn't flicker on fast saves.
                el._hide = setTimeout(() => el.classList.remove('wc-saving-show'), 220);
            }
        }

        // ============================================================
        // STANDARD LOADER
        //
        // The one full-screen loader for the whole app. Any page-level wait
        // routes through showLoader()/hideLoader(): signing in (the moment the
        // owner called out, where the login screen used to flash back with a
        // "Saving…" pill), booting the roster, opening the student portal.
        //
        // NOT for the tiny inline "Saving…" pill above — that is an
        // acknowledgement on a control a teacher is standing over, and a
        // full-screen takeover there would be worse, not better. The pill
        // stays; this covers whole-screen transitions.
        //
        // The overlay markup lives in index.html so it is in the DOM before this
        // file runs. The gif's src is set on first show, so a visitor who never
        // signs in never pays 1.9MB for it.
        //
        // Idempotent by construction: show twice is one overlay, hide twice is a
        // no-op. A hard failsafe lifts it after 20s so a caller that forgets to
        // hide (or a data load that never returns) can never trap the user
        // behind it.
        // ============================================================
        function showLoader(message, opts) {
            const el = document.getElementById('wildcatLoader');
            if (!el) return;
            const img = document.getElementById('wildcatLoaderMascot');
            if (img && !img.getAttribute('src')) img.setAttribute('src', 'assets/wildcat-loader.gif');
            const msg = document.getElementById('wildcatLoaderMsg');
            if (msg) msg.textContent = (message == null || message === '') ? 'Loading…' : String(message);
            el.classList.add('is-on');
            el.setAttribute('aria-hidden', 'false');
            el.setAttribute('aria-busy', 'true');
            document.body.classList.add('wc-loading');
            // Minimum on-screen time. The load screen is held a set beat so it
            // reads as a deliberate handoff (and the running-wildcat animation is
            // actually seen) rather than flashing by. The default is 4s across the
            // whole app; a caller can override with opts.minMs (e.g. 0 to hide the
            // instant its work is done).
            showLoader._shownAt = Date.now();
            showLoader._minMs = (opts && typeof opts.minMs === 'number') ? opts.minMs : 4000;
            clearTimeout(showLoader._minHideTimer);
            clearTimeout(showLoader._failsafe);
            showLoader._failsafe = setTimeout(function () {
                console.warn('[loader] auto-hid after 20s; a caller never called hideLoader()');
                showLoader._minMs = 0; // never let the minimum outlast the failsafe
                hideLoader();
            }, 20000);
        }
        function hideLoader() {
            // Honour the minimum on-screen time before actually hiding. The
            // remaining time is deferred once; the deferred call clears the
            // minimum so it hides for real rather than re-deferring forever.
            const remaining = (showLoader._minMs || 0) - (Date.now() - (showLoader._shownAt || 0));
            if (remaining > 0) {
                clearTimeout(showLoader._minHideTimer);
                showLoader._minHideTimer = setTimeout(function () {
                    showLoader._minMs = 0;
                    hideLoader();
                }, remaining);
                return;
            }
            clearTimeout(showLoader._failsafe);
            clearTimeout(showLoader._minHideTimer);
            const el = document.getElementById('wildcatLoader');
            if (!el) return;
            el.classList.remove('is-on');
            el.setAttribute('aria-hidden', 'true');
            el.removeAttribute('aria-busy');
            document.body.classList.remove('wc-loading');
        }
        window.showLoader = showLoader;
        window.hideLoader = hideLoader;

        /**
         * On a staff redirect return, Microsoft sends the browser back to this
         * page carrying an auth code in the hash, and wildcat-auth.js processes
         * it asynchronously before establishTeacherSession() swaps in the app.
         * Cover the login screen for that whole window so it never flashes.
         *
         * establishTeacherSession() hides the loader on success. A FAILED
         * redirect finishes inside wildcat-auth.js, which cannot reach
         * hideLoader(), so this also watches for the staff error text (or the
         * app appearing, or a 15s cap) and lifts the overlay itself — a failed
         * sign-in must be readable, never sealed behind the wildcat.
         */
        function maybeCoverRedirectSignIn() {
            const hash = String(window.location.hash || '');
            if (!/[#&](code|error|id_token|access_token)=/.test(hash)) return;
            showLoader('Signing you in…');
            const started = Date.now();
            const watch = setInterval(function () {
                const main = document.getElementById('mainApp');
                const appUp = main && !main.classList.contains('hidden');
                const errEl = document.getElementById('entraSignInError');
                const errShown = errEl && errEl.textContent.trim() !== '';
                if (appUp || errShown || Date.now() - started > 15000) {
                    clearInterval(watch);
                    if (!appUp) hideLoader();
                }
            }, 200);
        }

        function _wcDialogHost() {
            let host = document.getElementById('wcDialogRoot');
            if (!host) {
                host = document.createElement('div');
                host.id = 'wcDialogRoot';
                document.body.appendChild(host);
            }
            return host;
        }

        function _wcKindOf(message) {
            const m = String(message || '');
            if (m.indexOf('✅') === 0 || m.indexOf('🎉') === 0) return 'success';
            if (m.indexOf('❌') === 0) return 'error';
            if (m.indexOf('⚠️') === 0 || m.indexOf('⚠') === 0) return 'warning';
            return 'info';
        }

        function _wcFormat(message) {
            // Preserve line breaks from the original alert() strings, and let the
            // first line stand as a heading when the message has several lines.
            const parts = String(message == null ? '' : message).split('\n');
            const head = escapeHtml(parts[0]).replace(_WC_LEAD_ICON, '');
            const rest = parts.slice(1).filter(l => l.trim() !== '');
            return {
                title: head,
                body: rest.map(l => `<p>${escapeHtml(l)}</p>`).join('')
            };
        }

        // Leading status emoji are stripped before display because the dialog
        // shows its own icon. Note ⚠️ is TWO code points (U+26A0 + U+FE0F), so a
        // single-character class would leave the variation selector behind.
        const _WC_LEAD_ICON = /^(?:[\u2705\u274C\u26A0\u2139\u{1F389}\u{1F512}\u{1F4CB}\u{1F550}\uFE0F]|\s)+/u;

        const WC_ICONS = { success: '✅', error: '❌', warning: '⚠️', info: 'ℹ️', question: '❓' };

        function showToast(message, kind, ms) {
            let t = document.getElementById('wcToast');
            if (!t) {
                t = document.createElement('div');
                t.id = 'wcToast';
                document.body.appendChild(t);
            }
            const k = kind || 'success';
            const text = String(message || '').replace(_WC_LEAD_ICON, '').split('\n').filter(Boolean);
            t.className = `wc-toast wc-toast-${k} wc-toast-show`;
            t.innerHTML = `<span class="wc-toast-icon">${WC_ICONS[k] || ''}</span>
                           <span class="wc-toast-text"><strong>${escapeHtml(text[0] || '')}</strong>${
                               text.length > 1 ? `<span class="wc-toast-sub">${escapeHtml(text.slice(1).join(' '))}</span>` : ''
                           }</span>`;
            clearTimeout(t._timer);
            t._timer = setTimeout(() => { t.className = 'wc-toast'; }, ms || 4200);
        }

        function _wcDialog({ kind, title, body, buttons, input }) {
            return new Promise(resolve => {
                const host = _wcDialogHost();
                const k = kind || 'info';
                host.innerHTML = `
                    <div class="wc-dialog-backdrop" id="wcDialogBackdrop">
                        <div class="wc-dialog wc-dialog-${k}" role="dialog" aria-modal="true">
                            <div class="wc-dialog-head">
                                <span class="wc-dialog-icon">${WC_ICONS[k] || WC_ICONS.info}</span>
                                <h3 class="wc-dialog-title">${title || ''}</h3>
                            </div>
                            ${body ? `<div class="wc-dialog-body">${body}</div>` : ''}
                            ${input ? `<div class="wc-dialog-input">
                                <input type="${input.type || 'text'}" id="wcDialogInput"
                                       class="wc-input" placeholder="${escapeHtml(input.placeholder || '')}"
                                       value="${escapeHtml(input.value || '')}">
                            </div>` : ''}
                            <div class="wc-dialog-actions">
                                ${buttons.map((b, i) => `
                                    <button class="btn wc-dialog-btn ${b.cls || ''}" data-i="${i}">${escapeHtml(b.label)}</button>
                                `).join('')}
                            </div>
                        </div>
                    </div>`;

                const backdrop = document.getElementById('wcDialogBackdrop');
                const inputEl = document.getElementById('wcDialogInput');
                const finish = (val) => {
                    host.innerHTML = '';
                    document.removeEventListener('keydown', onKey);
                    resolve(val);
                };
                const onKey = (e) => {
                    if (e.key === 'Escape') {
                        const cancelIdx = buttons.findIndex(b => b.value === false || b.value === null);
                        finish(cancelIdx >= 0 ? buttons[cancelIdx].value : (buttons[0].value !== undefined ? buttons[0].value : undefined));
                    }
                    if (e.key === 'Enter' && input) {
                        const okBtn = buttons.find(b => b.value !== false && b.value !== null);
                        if (okBtn) finish(inputEl ? inputEl.value : okBtn.value);
                    }
                };
                document.addEventListener('keydown', onKey);

                host.querySelectorAll('.wc-dialog-btn').forEach(btn => {
                    btn.addEventListener('click', () => {
                        const b = buttons[parseInt(btn.dataset.i, 10)];
                        if (input && b.value !== false && b.value !== null) {
                            finish(inputEl ? inputEl.value : '');
                        } else {
                            finish(b.value);
                        }
                    });
                });
                backdrop.addEventListener('click', (e) => {
                    if (e.target === backdrop) {
                        const cancel = buttons.find(b => b.value === false || b.value === null);
                        if (cancel) finish(cancel.value);
                    }
                });
                setTimeout(() => {
                    if (inputEl) { inputEl.focus(); inputEl.select(); }
                    else {
                        const primary = host.querySelector('.wc-dialog-btn:last-child');
                        if (primary) primary.focus();
                    }
                }, 60);
            });
        }

        // Drop-in replacement for alert(). Kept synchronous-looking so the ~216
        // existing call sites work untouched.
        function showAlert(message) {
            const kind = _wcKindOf(message);
            if (kind === 'success') { showToast(message, 'success'); return Promise.resolve(); }
            const { title, body } = _wcFormat(message);
            return _wcDialog({
                kind, title, body,
                buttons: [{ label: 'OK', value: true, cls: 'wc-btn-primary' }]
            });
        }

        function showConfirm(message, opts) {
            opts = opts || {};
            const { title, body } = _wcFormat(message);
            const kind = opts.kind || (_wcKindOf(message) === 'info' ? 'question' : _wcKindOf(message));
            return _wcDialog({
                kind, title, body,
                buttons: [
                    { label: opts.cancelLabel || 'Cancel', value: false, cls: 'wc-btn-cancel' },
                    { label: opts.confirmLabel || 'Confirm', value: true,
                      cls: opts.danger ? 'wc-btn-danger' : 'wc-btn-primary' }
                ]
            });
        }

        function showPrompt(message, opts) {
            opts = opts || {};
            const { title, body } = _wcFormat(message);
            return _wcDialog({
                kind: opts.kind || 'question', title, body,
                input: { type: opts.type || 'text', placeholder: opts.placeholder || '', value: opts.value || '' },
                buttons: [
                    { label: 'Cancel', value: null, cls: 'wc-btn-cancel' },
                    { label: opts.confirmLabel || 'OK', value: true, cls: 'wc-btn-primary' }
                ]
            });
        }

        // Override the browser dialog so every existing alert() is restyled.
        window.alert = showAlert;

        function showReferralToast(message, kind) {
            // Kept for the referral flows; now routed through the shared toast.
            showToast(String(message).replace(/<[^>]+>/g, ''), kind === 'warn' ? 'warning' : 'success');
        }

        function setButtonBusy(btn, busy, busyLabel) {
            if (!btn) return;
            if (busy) {
                btn._label = btn.innerHTML;
                btn.disabled = true;
                btn.classList.add('btn-busy');
                btn.innerHTML = busyLabel || 'Working…';
            } else {
                btn.disabled = false;
                btn.classList.remove('btn-busy');
                if (btn._label) btn.innerHTML = btn._label;
            }
        }

        // ---- Coalesced saves -------------------------------------------
        //
        // saveData() writes the whole `main` document in a transaction, and
        // Firestore sustains roughly ONE write per second to a single
        // document. With fifty teachers awarding tickets in the same assembly
        // that document is a contended hotspot: transactions retry, some fail,
        // and saves stop sticking under exactly the load that matters most.
        //
        // Requests are coalesced so a burst becomes one write. The queue lives
        // in wildcat-savequeue.js with its guarantees and its tests; the short
        // version is that a caller's promise still settles only when a save
        // that INCLUDED their change has landed, so the toasts below stay
        // honest rather than reporting a write that has not happened.
        //
        // Built lazily, so a failure to load the module degrades to saving
        // directly rather than to not saving at all.
        var _saveQueue = null;
        function saveQueue() {
            if (_saveQueue) return _saveQueue;
            if (!window.WildcatSaveQueue) return null;
            _saveQueue = window.WildcatSaveQueue.create({
                save: function () { return saveData(); },
                onError: function (err, attempt) {
                    console.error(
                        `❌ Coalesced save failed (attempt ${attempt}):`,
                        (err && err.code) || '', (err && err.message) || err);
                }
            });
            return _saveQueue;
        }

        /** Ask for a save. Resolves once a save including this change lands. */
        function requestSave(reason) {
            const q = saveQueue();
            if (!q) return Promise.resolve(saveData());
            return q.request(reason);
        }

        /** Write everything outstanding NOW. For a closing tab, and for the
         *  actions that must not be deferred: a reset, a year rollover, a role
         *  change. Those keep calling saveData() directly. */
        function flushSaves() {
            return _saveQueue ? _saveQueue.flush() : Promise.resolve(null);
        }

        // Deferring a write opens a window where work exists only in memory,
        // so it has to be closed on the way out. visibilitychange is the one
        // that fires reliably on iOS, where beforeunload frequently does not;
        // pagehide catches the desktop close. Both are needed and neither is
        // sufficient alone.
        document.addEventListener('visibilitychange', function () {
            if (document.visibilityState === 'hidden') flushSaves();
        });
        window.addEventListener('pagehide', function () { flushSaves(); });

        // ================================================================
        // TEACHER VIEW — admins only, read-only, and honest about its limits.
        //
        // WHAT IT IS. An admin loads the app as a member of staff would find
        // it: their tabs, their class periods, their students. It answers "why
        // can't Ms Rivera see her periods in Award Cash" without borrowing her
        // password or waiting on a test account from IT.
        //
        // WHAT IT IS NOT, AND THIS MATTERS.
        //
        // It is a PREVIEW OF THE SCREEN, not a test of server permissions. The
        // browser is still holding the ADMIN's Convex token, so anything the
        // server decides — the race aggregate's small-group guard, restricted
        // field access — still answers as admin. A teacher hitting the same
        // screen may see LESS than this shows. Never conclude from this view
        // that a teacher can see something; conclude only that the layout and
        // the roster scope look right.
        //
        // Client-side role gates DO follow the preview, because they read
        // currentUser, which is swapped. That is most of the UI.
        //
        // READ-ONLY, ENFORCED AT THE CHOKEPOINT. saveData() refuses while a
        // preview is running. Writing as somebody else would put their name on
        // an award or a referral in the audit log, and this is a discipline
        // system: a falsified attribution is worse than a missing feature.
        // Guarding saveData covers all 102 call sites at once rather than
        // trusting each of them.
        //
        // The preview is NEVER persisted. saveSession() is not called, so a
        // refresh always lands back as the real admin.
        // ================================================================

        /** The real signed-in admin while a preview is running, else null. */
        let realUser = null;

        function isPreviewingTeacher() { return realUser !== null; }

        /** Tab visibility for a role. Only ever narrows or restores; it does
         *  not touch modes, which the preview deliberately leaves alone. */
        function applyPreviewVisibility(role) {
            const narrow = (role === 'teacher' || role === 'campusaide' || role === 'pbis');
            const superOnly = (role === 'superadmin');
            document.querySelectorAll('.admin-only')
                .forEach(t => t.classList.toggle('disabled', narrow));
            document.querySelectorAll('.super-admin-only')
                .forEach(t => t.classList.toggle('disabled', !superOnly));
            const weekControls = document.getElementById('weekControls');
            if (weekControls) weekControls.style.display = narrow ? 'none' : 'flex';
        }

        function populatePreviewTeacherSelect() {
            const sel = document.getElementById('previewTeacherSelect');
            if (!sel) return;
            const me = realUser || currentUser;
            const list = (teachers || [])
                .filter(t => t && String(t.id) !== String(me && me.id))
                .sort((a, b) => String(a.name || '').localeCompare(String(b.name || '')));
            sel.innerHTML = list.length
                ? list.map(t => `<option value="${escapeHtml(String(t.id))}">` +
                    `${escapeHtml(t.name || t.username || 'Unnamed')}, ` +
                    `${escapeHtml(getFriendlyRoleName(t.role) || t.role || '')}</option>`).join('')
                : '<option value="">No other staff to view as</option>';
        }

        function startTeacherPreview() {
            // Gated here as well as in the markup. Hiding a control is a
            // courtesy; this is the check.
            const me = realUser || currentUser;
            if (!me || (me.role !== 'admin' && me.role !== 'superadmin')) {
                showToast('Only administrators can use teacher view.', 'error');
                return;
            }
            if (isPreviewingTeacher()) return;   // never nest a preview

            const sel = document.getElementById('previewTeacherSelect');
            const id = sel && sel.value;
            const target = (teachers || []).find(t => String(t.id) === String(id));
            if (!target) { showToast('Pick a staff member first.', 'error'); return; }

            realUser = me;
            // A COPY, so nothing done while previewing can reach the real
            // teacher record in memory.
            currentUser = Object.assign({}, target);
            applyPreviewVisibility(currentUser.role);
            renderPreviewBanner();

            const nameEl = document.getElementById('currentUserName');
            const roleEl = document.getElementById('currentUserRole');
            if (nameEl) nameEl.textContent = currentUser.name || '';
            if (roleEl) roleEl.textContent = getFriendlyRoleName(currentUser.role);

            console.log(`👁️ Teacher view: showing the app as ${currentUser.name} (${currentUser.role}). Saves are blocked.`);
            switchTab('tickets');

            // Their ACTUAL class periods, from an admin-only query that names
            // them. Without this the screen changes role but the roster stays
            // the admin's, because teacherRoster resolves from the caller's
            // token and takes no argument — which is exactly the case this
            // whole feature exists to reproduce.
            loadPreviewRoster(currentUser.email).then(() => {
                // Redraw whatever is showing now that the roster has arrived.
                if (typeof switchTab === 'function') switchTab('tickets');
            });
        }

        async function loadPreviewRoster(email) {
            previewRoster = null;
            previewRosterError = null;
            resetPeriodFilterFetch();
            const auth = window.WildcatAuth;
            // The ADMIN's session, deliberately: the query is admin-gated and
            // the admin is the one asking.
            const session = auth && auth.getSession && auth.getSession();
            if (!auth || !session) {
                previewRosterError = 'Teacher view needs a Microsoft sign-in to read the roster.';
                console.warn('[teacher view] ' + previewRosterError);
                return null;
            }
            if (!email) {
                previewRosterError = 'That staff member has no email on their record, so their roster cannot be looked up.';
                console.warn('[teacher view] ' + previewRosterError);
                return null;
            }
            try {
                previewRoster = await auth.convexQuery(
                    'views_app:teacherRosterFor', { email: String(email) }, session.idToken);
                const n = (previewRoster && previewRoster.sectionCount) || 0;
                console.log(`👁️ Teacher view roster: ${n} section(s), ` +
                    `${(previewRoster && previewRoster.studentCount) || 0} student(s).` +
                    (previewRoster && previewRoster.reason ? ' ' + previewRoster.reason : ''));
            } catch (e) {
                previewRosterError = (e && e.message) || String(e);
                console.error('[teacher view] roster lookup failed:', previewRosterError);
            }
            return previewRoster;
        }

        function endTeacherPreview() {
            if (!isPreviewingTeacher()) return;
            currentUser = realUser;
            realUser = null;
            applyPreviewVisibility(currentUser.role);
            renderPreviewBanner();

            const nameEl = document.getElementById('currentUserName');
            const roleEl = document.getElementById('currentUserRole');
            if (nameEl) nameEl.textContent = currentUser.name || '';
            if (roleEl) roleEl.textContent = getFriendlyRoleName(currentUser.role);

            // Cleared, and the real roster is re-read rather than trusted.
            // This is the belt to the separate-variable braces: if preview code
            // ever does touch the cache, this still repairs it before saving is
            // re-enabled.
            previewRoster = null;
            previewRosterError = null;
            resetPeriodFilterFetch();
            if (typeof loadTeacherRosterFromSIS === 'function') {
                loadTeacherRosterFromSIS(true).catch(() => {});
            }

            console.log('👁️ Teacher view ended. Back as ' + currentUser.name + '.');
            switchTab('teachers');
        }

        function renderPreviewBanner() {
            let bar = document.getElementById('wcPreviewBar');
            if (!isPreviewingTeacher()) { if (bar) bar.remove(); return; }
            if (!bar) {
                bar = document.createElement('div');
                bar.id = 'wcPreviewBar';
                bar.className = 'wc-preview-bar';
                document.body.appendChild(bar);
            }
            // Deliberately loud and always on screen. An admin who forgets they
            // are in this view will report bugs that are not bugs, or worse,
            // conclude a teacher can see something they cannot.
            bar.innerHTML =
                '<span>👁️ <strong>Teacher view</strong>, showing the app as ' +
                escapeHtml(currentUser.name || '') + '. Read-only, and server permissions ' +
                'still answer as you.</span>' +
                '<button type="button" class="wc-preview-exit" onclick="endTeacherPreview()">Exit</button>';
        }

        function saveInBackground(label) {
            // Fire-and-report. Never blocks the UI.
            // saveData() catches its own errors and resolves either way, so the
            // outcome is read from the returned boolean rather than a rejection.
            return requestSave(label)
                .then(ok => {
                    if (ok === false) {
                        console.error(`❌ ${label} did not save`);
                        showReferralToast(
                            `<strong>Not saved.</strong> ${label} is still only on this device. Check your connection and reload before closing this tab.`,
                            'warn');
                    } else {
                        console.log(`✅ ${label} persisted`);
                    }
                })
                .catch(err => {
                    console.error(`❌ ${label} failed to save:`, err);
                    showReferralToast(
                        `<strong>Not saved.</strong> ${label} may not have persisted. Reload before closing this tab.`,
                        'warn');
                });
        }

        function populateReferringStaffDropdown() {
            const sel = document.getElementById('referralReferringStaff');
            const hint = document.getElementById('referringStaffHint');
            if (!sel) return;

            const me = (currentUser && (currentUser.name || currentUser.username)) || '';
            const isAdmin = !!(currentUser && (currentUser.role === 'admin' || currentUser.role === 'superadmin'));

            // Build the list so it ALWAYS contains the logged-in user. The previous
            // version emitted an empty "Select referring staff..." placeholder and
            // relied on a name match against the teachers array to mark an option
            // selected. When that match failed the box stayed on the empty option,
            // which then failed the required check and made submission impossible.
            let names = isAdmin
                ? (teachers || []).map(t => (t.name || t.username || '')).filter(Boolean)
                : [];
            if (me) names.push(me);
            names = Array.from(new Set(names)).sort((a, b) => a.localeCompare(b));

            if (!names.length) {
                sel.innerHTML = '<option value="">(staff list unavailable)</option>';
                sel.disabled = false;
                if (hint) hint.textContent = 'Could not load the staff list, the referral will be filed under your account.';
                console.warn('populateReferringStaffDropdown: no names available',
                             { me: me, role: currentUser && currentUser.role, teachers: (teachers || []).length });
                return;
            }

            sel.innerHTML = names.map(n =>
                `<option value="${escapeHtml(n)}">${escapeHtml(n)}</option>`).join('');
            // Select explicitly rather than via the `selected` attribute, so the
            // field always holds a real value.
            sel.value = (me && names.indexOf(me) !== -1) ? me : names[0];
            sel.disabled = false;  // never disabled — a disabled control is easy to
                                   // mistake for a broken one, and teachers only get
                                   // one entry anyway.

            if (hint) {
                hint.textContent = isAdmin
                    ? 'Defaults to you. You may file on another staff member\'s behalf.'
                    : 'Referrals are filed under your name.';
            }
        }

        // Intervention counter via delegation, so it works no matter how the
        // Submit screen was reached.
        document.addEventListener('change', function (e) {
            if (e.target && e.target.classList &&
                e.target.classList.contains('referral-intervention') &&
                typeof updateInterventionCount === 'function') {
                updateInterventionCount();
            }
        });

        function updateInterventionCount() {
            const n = document.querySelectorAll('.referral-intervention:checked').length;
            const el = document.getElementById('interventionCount');
            if (!el) return;

            // Severity answers the expectation; it does not fail it. The
            // banner says so plainly, because a teacher who has just removed a
            // violent student should not be reading "2 more expected".
            const severe = !!(document.getElementById('referralSevereBypass') || {}).checked;
            if (severe) {
                el.textContent = n
                    ? `✓ Immediate removal recorded, ${n} intervention${n === 1 ? '' : 's'} also logged`
                    : '✓ Immediate removal recorded, the 3-intervention expectation does not apply';
                el.className = 'intervention-banner intervention-banner-severe';
                return;
            }

            if (n === 0) {
                el.textContent = 'Select at least 3 interventions below';
                el.className = 'intervention-banner';
            } else if (n < 3) {
                el.textContent = `${n} of 3 selected, ${3 - n} more expected before referring`;
                el.className = 'intervention-banner intervention-banner-warn';
            } else {
                el.textContent = `✓ ${n} interventions selected`;
                el.className = 'intervention-banner intervention-banner-ok';
            }
        }

        function clearReferralForm() {
            // referralStudentScope and referralStudentSearch are in this list
            // deliberately. A period filter left over from the last referral
            // would silently narrow the next one, and the teacher filing it has
            // no reason to look at a control they did not just touch.
            ['referralStudentSelect','referralStudentScope','referralStudentSearch',
             'referralDate','referralTime','referralLocation',
             'referralBehaviorType','referralDescription','referralAdditionalActions'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.value = '';
            });
            populateReferralStudentDropdown();
            document.querySelectorAll('.referral-intervention').forEach(cb => { cb.checked = false; });
            const severeBox = document.getElementById('referralSevereBypass');
            if (severeBox) severeBox.checked = false;
            updateInterventionCount();
            const d = document.getElementById('referralDate');
            if (d) d.value = new Date().toISOString().split('T')[0];
            populateReferringStaffDropdown();
        }

        async function submitBehaviorReferral() {
            const studentId = (document.getElementById('referralStudentSelect') || {}).value || '';
            const date = (document.getElementById('referralDate') || {}).value || '';
            const time = (document.getElementById('referralTime') || {}).value || '';
            const location = (document.getElementById('referralLocation') || {}).value || '';
            const behavior = (document.getElementById('referralBehaviorType') || {}).value || '';
            const description = ((document.getElementById('referralDescription') || {}).value || '').trim();
            const additionalActions = ((document.getElementById('referralAdditionalActions') || {}).value || '').trim();
            let referringStaff = (document.getElementById('referralReferringStaff') || {}).value || '';
            if (!referringStaff) {
                // Last-resort fallback: we always know who is logged in, so an empty
                // dropdown must never be the thing that blocks a referral.
                referringStaff = (currentUser && (currentUser.name || currentUser.username)) || '';
                if (referringStaff) {
                    console.warn('Referring staff field was empty; defaulted to the logged-in user.');
                    if (typeof populateReferringStaffDropdown === 'function') populateReferringStaffDropdown();
                }
            }
            const interventions = Array.from(document.querySelectorAll('.referral-intervention:checked')).map(cb => cb.value);
            const severeBypass = !!(document.getElementById('referralSevereBypass') || {}).checked;

            // Required: student, date, behaviour, description, referring staff.
            if (!studentId)       { alert('⚠️ Please select a student'); return; }
            if (!date)            { alert('⚠️ Please select the date of the incident'); return; }
            if (!behavior)        { alert('⚠️ Please select the behavior/violation'); return; }
            if (!description)     { alert('⚠️ Please describe the incident'); return; }
            if (!referringStaff)  { alert('⚠️ Could not determine the referring staff member. Please reload and try again.'); return; }

            const student = students.find(s => s.id === studentId);
            if (!student) { alert('⚠️ Student not found'); return; }

            const grade = parseInt(student.grade, 10);
            const referral = {
                // Minted, not counted. `REF${referralIdCounter++}` came from a
                // per-browser counter, so two teachers filing at once both
                // produced the same id -- and the save path dedupes on id with
                // the STORED copy winning, so the second referral was thrown
                // away. See newReferralId for the incident.
                id: window.WildcatDiscipline.newReferralId(),
                studentId: studentId,
                // SNAPSHOT, like the demographics below. studentId may be a
                // legacy CSV value, while the SIS is keyed by student number,
                // so the race breakdown has to resolve one to the other. Doing
                // that through the live roster works only while the student is
                // enrolled: once they withdraw they drop off it and their
                // referrals become permanently unmatchable. Recorded here so
                // the referral carries its own answer.
                studentNumber: (student.studentNumber || ''),
                studentName: `${student.firstName} ${student.lastName}`,
                studentGrade: student.grade || '',
                school: (grade >= 9) ? 'High School' : 'Middle School',
                date: date,
                time: time,
                dateTime: time ? `${date}T${time}` : date,
                location: location,
                behavior: behavior,
                behaviorType: behavior,   // legacy alias so older readers keep working
                description: description,
                interventions: interventions,
                // WHY there were no interventions, which the count alone
                // cannot say. Zero used to be ambiguous: a teacher who skipped
                // the step and a teacher who removed a student mid-fight
                // produced identical records, and the analytics counted both
                // as "filed with none logged". They are different facts and
                // only one of them is a practice problem.
                severeBypass: severeBypass,
                additionalActions: additionalActions,
                referredBy: referringStaff,
                referredByUsername: currentUser.username,
                filedByUsername: currentUser.username,   // who actually typed it
                // RECORDED BECAUSE USERNAME NO LONGER EXISTS. The Convex
                // teacher record has no username field — that is what the
                // migration off cleartext passwords removed — so both fields
                // above write undefined for anyone signing in with Microsoft.
                // Without an email a teacher could not be shown their own
                // referrals, which is the whole point of the scoping.
                filedByEmail: (currentUser.email || ''),
                referredByEmail: (currentUser.email || ''),
                status: 'open',
                submittedAt: new Date().toISOString(),
                // closure
                resolutionType: '',
                closingActions: [],
                adminNotes: '',
                closedBy: '',
                closedAt: '',
                loopClosed: false,
                loopClosedBy: '',
                loopClosedAt: '',
                forwardedTo: [],
                // Read by wildcat-merge to decide which copy of a referral is
                // newer when two tabs both hold one.
                updatedAt: new Date().toISOString(),

                // SNAPSHOT, for the same reason a receipt records the price
                // paid. A referral is a record of an incident on a date, and a
                // student's grade changes every year, so reading it live in
                // September would silently relabel last spring's referrals.
                // Fields with no value are absent rather than "Unknown", so a
                // gap can be measured instead of becoming a category.
                demographics: window.WildcatDiscipline.snapshotDemographics(student)
            };

            const submitBtn = document.querySelector('.btn-referral-submit');
            setButtonBusy(submitBtn, true, 'Submitting…');

            behaviorReferrals.push(referral);

            // Confirm now; persist in the background.
            showReferralToast(
                `✅ <strong>Referral submitted</strong> for ${escapeHtml(referral.studentName)}, sent to administration for review.`, 'ok');
            clearReferralForm();
            if (typeof updateReferralReviewTable === 'function') updateReferralReviewTable();
            setButtonBusy(submitBtn, false);

            saveInBackground('Referral for ' + referral.studentName);
        }

        // Closure action list — mirrors the "Closing the Loop Options" checklist.
        // DETENTION_CLOSING_ACTION is wired to auto-create a Detention Tracker
        // record when checked, so admins don't have to enter it twice.
        const REFERRAL_CLOSING_ACTIONS = [
            "Notified parents/guardians promptly",
            "Scheduled a mandatory Parent-Conference",
            "Student conference was held to review the incident and reinforced behavior expectations",
            "Assigned the student to mandatory detention",
            "Facilitated a restorative circle / mediation",
            "Reviewed behavior history and existing support plans with the student",
            "Developed and assigned a Consequence Agreement",
            "Developed or revised a Behavior Intervention Plan (BIP)",
            "Ensured immediate safety of all students and staff",
            "Isolated and de-escalated the situation",
            "Contacted school police or emergency services if needed",
            "Conducted a thorough investigation and documented the incident"
        ];
        const DETENTION_CLOSING_ACTION = 'Assigned the student to mandatory detention';

        // SCOPED. A teacher sees their own referrals; admin and PBIS see the
        // school's. These two functions feed every referral table in the app,
        // so scoping here covers all of them at once rather than at each
        // render, where one missed call site is a privacy leak.
        function visibleReferrals() {
            return window.WildcatDiscipline.visibleReferrals(behaviorReferrals, currentUser);
        }
        function getOpenReferrals()   { return visibleReferrals().filter(r => r.status !== 'closed'); }
        function getClosedReferrals() { return visibleReferrals().filter(r => r.status === 'closed'); }

        function updateReferralReviewTable() {
            const tbody = document.getElementById('referralReviewTable');
            if (!tbody) return;
            const open = getOpenReferrals().slice().sort((a, b) =>
                new Date(b.submittedAt) - new Date(a.submittedAt));

            const countEl = document.getElementById('openReferralCount');
            if (countEl) countEl.textContent = open.length;

            if (!open.length) {
                tbody.innerHTML = `<tr><td colspan="6">
                    <div class="empty-state">
                        <div class="empty-icon">✅</div>
                        <div class="empty-title">No open referrals</div>
                        <div class="empty-sub">Everything submitted has been closed.</div>
                    </div></td></tr>`;
                return;
            }

            tbody.innerHTML = open.map(r => {
                const d = new Date(r.submittedAt);
                const ivCount = (r.interventions || []).length;
                return `
                <tr class="wc-row">
                    <td>
                        <div class="cell-strong">${escapeHtml(r.studentName)}</div>
                        <div class="cell-sub">${escapeHtml(r.school || '')} &middot; Grade ${escapeHtml(String(r.studentGrade || '—'))}</div>
                    </td>
                    <td><span class="cat-chip">${escapeHtml(r.behavior || r.behaviorType || '—')}</span></td>
                    <td class="cell-muted">${escapeHtml(r.location || '—')}</td>
                    <td>
                        <div class="cell-strong">${escapeHtml(r.date || '')}</div>
                        <div class="cell-sub">filed ${d.toLocaleDateString()}</div>
                    </td>
                    <td class="cell-center">
                        ${r.severeBypass
                            ? `<span class="count-pill count-pill-severe" title="Too severe for classroom interventions, immediate removal">severe</span>`
                            : `<span class="count-pill${ivCount >= 3 ? ' count-pill-on' : ''}" title="Interventions attempted before referring">${ivCount}</span>`}
                    </td>
                    <td>
                        <button class="btn btn-sm-blue" onclick="viewReferralDetails('${r.id}')">View</button>
                        <button class="btn btn-sm-pdf" onclick="printReferral('${r.id}')" title="Printable referral">📄</button>
                        <button class="btn btn-sm-close" onclick="openCloseReferralModal('${r.id}')">Close</button>
                    </td>
                </tr>`;
            }).join('');
        }

        function updateClosedReferralsList() {
            const host = document.getElementById('closedReferralsList');
            if (!host) return;
            const term = ((document.getElementById('searchClosedReferrals') || {}).value || '').toLowerCase();
            let closed = getClosedReferrals().slice().sort((a, b) =>
                new Date(b.closedAt || b.submittedAt) - new Date(a.closedAt || a.submittedAt));
            if (term) {
                closed = closed.filter(r =>
                    String(r.studentName || '').toLowerCase().includes(term) ||
                    String(r.studentId || '').toLowerCase().includes(term));
            }
            const countEl = document.getElementById('closedReferralCount');
            if (countEl) countEl.textContent = getClosedReferrals().length;

            if (!closed.length) {
                host.innerHTML = `<div class="empty-state">
                    <div class="empty-icon">📁</div>
                    <div class="empty-title">${term ? 'No matches' : 'No closed referrals yet'}</div>
                    <div class="empty-sub">${term ? 'Try a different name or ID.' : 'Closed referrals will appear here.'}</div>
                </div>`;
                return;
            }

            host.innerHTML = closed.map(r => {
                const actions = (r.closingActions || []);
                const loopBadge = r.loopClosed
                    ? '<span class="tag-ok">Loop closed</span>'
                    : `<button class="btn btn-sm-loop" onclick="openCloseLoopModal('${r.id}')">Loop pending, close it</button>`;
                return `
                <div class="wc-card closed-ref-card">
                    <div class="closed-ref-head">
                        <div>
                            <div class="closed-ref-name">✅ ${escapeHtml(r.studentName)}</div>
                            <div class="cell-sub">ID: ${escapeHtml(r.studentId)} &middot; incident ${escapeHtml(r.date || '')} &middot; closed ${r.closedAt ? new Date(r.closedAt).toLocaleDateString() : '—'}</div>
                        </div>
                        <div class="closed-ref-badges">
                            <button class="btn btn-sm-pdf" onclick="printReferral('${r.id}')">📄 PDF</button>
                            <span class="tag-ok">Closed</span>
                            ${r.resolutionType === 'no_action' ? '<span class="tag-neutral">No action required</span>' : '<span class="tag-info">Action taken</span>'}
                            ${loopBadge}
                        </div>
                    </div>
                    <div class="closed-ref-body">
                        <div class="closed-ref-label">Behavior</div>
                        <div class="closed-ref-val">${escapeHtml(r.behavior || r.behaviorType || '—')}</div>
                        ${actions.length ? `
                        <div class="closed-ref-label">Actions taken</div>
                        <ul class="closed-ref-actions">${actions.map(a => `<li>${escapeHtml(a)}</li>`).join('')}</ul>` : ''}
                        ${r.adminNotes ? `
                        <div class="closed-ref-label">Administrator notes</div>
                        <div class="closed-ref-note">${escapeHtml(r.adminNotes)}</div>` : ''}
                        <div class="closed-ref-foot">
                            <span>Referred by <strong>${escapeHtml(r.referredBy || '—')}</strong></span>
                            <span>Closed by <strong>${escapeHtml(r.closedBy || '—')}</strong></span>
                            ${(r.forwardedTo || []).length ? `<span>Summary sent to <strong>${(r.forwardedTo || []).length}</strong> staff</span>` : '<span>Summary not forwarded</span>'}
                        </div>
                    </div>
                </div>`;
            }).join('');
        }

        // ---------- Stage 1: close the referral ----------
        function openCloseReferralModal(referralId) {
            const r = (behaviorReferrals || []).find(x => x.id === referralId);
            if (!r) return;
            const modal = document.getElementById('closeReferralModal');
            const body = document.getElementById('closeReferralBody');
            if (!modal || !body) return;

            body.innerHTML = `
                <div class="modal-context">
                    <div><span class="ctx-label">Student</span><strong>${escapeHtml(r.studentName)}</strong></div>
                    <div><span class="ctx-label">Behavior</span>${escapeHtml(r.behavior || r.behaviorType || '—')}</div>
                    <div><span class="ctx-label">Incident date</span>${escapeHtml(r.date || '—')}</div>
                    <div><span class="ctx-label">Referred by</span>${escapeHtml(r.referredBy || '—')}</div>
                </div>
                ${r.description ? `<div class="modal-desc"><span class="ctx-label">Description</span>${escapeHtml(r.description)}</div>` : ''}

                <label class="field-label" style="margin-top:14px;">Resolution Type <span class="req">*</span></label>
                <div class="resolution-choice">
                    <label class="res-card">
                        <input type="radio" name="closeResolution" value="action_taken" checked>
                        <span class="res-title">Action Taken</span>
                        <span class="res-sub">Intervention or disciplinary action applied</span>
                    </label>
                    <label class="res-card">
                        <input type="radio" name="closeResolution" value="no_action">
                        <span class="res-title">No Action Required</span>
                        <span class="res-sub">Issue resolved without formal action</span>
                    </label>
                </div>

                <label class="field-label" style="margin-top:14px;">Actions taken (check all that apply)</label>
                <div class="check-grid check-grid-1">
                    ${REFERRAL_CLOSING_ACTIONS.map(a => {
                        const isDetention = (a === DETENTION_CLOSING_ACTION);
                        return `
                        <label class="check-item">
                            <input type="checkbox" class="closing-action" value="${escapeHtml(a)}"
                                   ${isDetention ? 'onchange="toggleDetentionDays(this)"' : ''}>
                            <span>${escapeHtml(a)}</span>
                        </label>` + (isDetention ? `
                        <div class="detention-days-row" id="detentionDaysRow" style="display:none;">
                            <label class="field-label" style="margin:0;">How many days of detention?</label>
                            <input type="number" id="detentionDaysForReferral" class="wc-input"
                                   value="1" min="1" max="20" step="1">
                            <span class="panel-hint" style="margin:0;">Added straight to the Detention Tracker.</span>
                        </div>` : '');
                    }).join('')}
                </div>

                <label class="field-label" style="margin-top:14px;">Administrator Notes</label>
                <textarea id="closeReferralNotes" rows="3" class="wc-input"
                    placeholder="Enter any additional notes or context about the resolution..."></textarea>

                <div class="modal-actions">
                    <button class="btn btn-secondary" onclick="closeModalById('closeReferralModal')">Cancel</button>
                    <button class="btn btn-referral-submit" onclick="confirmCloseReferral('${r.id}')">Close Referral</button>
                </div>`;
            openRefModal(modal.id);
        }

        async function confirmCloseReferral(referralId) {
            const r = (behaviorReferrals || []).find(x => x.id === referralId);
            if (!r) return;
            const resolution = (document.querySelector('input[name="closeResolution"]:checked') || {}).value || 'action_taken';
            const actions = Array.from(document.querySelectorAll('.closing-action:checked')).map(cb => cb.value);
            const notes = ((document.getElementById('closeReferralNotes') || {}).value || '').trim();

            if (resolution === 'action_taken' && !actions.length) {
                alert('⚠️ "Action Taken" needs at least one action checked.\n\nIf nothing formal was done, choose "No Action Required" instead.');
                return;
            }

            r.status = 'closed';
            r.updatedAt = new Date().toISOString();   // so a merge can order this edit
            r.resolutionType = resolution;
            r.closingActions = actions;
            r.adminNotes = notes;
            r.closedBy = currentUser.name;
            r.closedAt = new Date().toISOString();
            r.consequence = actions.join('; '); // legacy field kept populated

            // Auto-create a Detention Tracker record when that action is checked.
            // Days come from the inline field that appears with the checkbox, so
            // admins don't have to go and edit the tracker afterwards.
            let detentionMade = false, detentionDays = 0;
            if (actions.includes(DETENTION_CLOSING_ACTION)) {
                const daysEl = document.getElementById('detentionDaysForReferral');
                detentionDays = Math.max(1, Math.min(20, parseInt(daysEl && daysEl.value, 10) || 1));
                detentionMade = createDetentionFromReferral(r, detentionDays);
                r.detentionDays = detentionDays;
            }

            closeModalById('closeReferralModal');
            updateReferralReviewTable();
            updateClosedReferralsList();
            if (typeof updateDetentionLists === 'function') updateDetentionLists();

            showReferralToast(
                `✅ <strong>Referral closed</strong> for ${escapeHtml(r.studentName)}.` +
                (detentionMade ? ` 🕐 ${detentionDays} day${detentionDays === 1 ? '' : 's'} of detention added to the tracker.` : '') +
                ` Next: close the loop from Closed Referrals.`, 'ok');

            saveInBackground('Closing referral for ' + r.studentName);
        }

        function createDetentionFromReferral(r, days) {
            try {
                const student = students.find(s => s.id === r.studentId);
                if (!student) return false;
                const today = new Date().toISOString().split('T')[0];
                const totalDays = Math.max(1, Math.min(20, parseInt(days, 10) || 1));
                detentions.push({
                    id: 'detention_' + detentionIdCounter++,
                    studentId: r.studentId,
                    studentName: r.studentName,
                    grade: student.grade,
                    location: (detentionLocations && detentionLocations[0]) || 'Main Office',
                    dateAssigned: today,
                    totalDays: totalDays,
                    daysServed: 0,
                    daysRemaining: totalDays,
                    startDate: today,
                    reason: `Referral ${r.id}: ${r.behavior || r.behaviorType || 'behavior referral'}`,
                    status: 'active',
                    assignedBy: currentUser.name,
                    assignedAt: new Date().toISOString(),
                    servedDates: [],
                    completedAt: null,
                    sourceReferralId: r.id   // link back to the referral
                });
                return true;
            } catch (e) {
                console.error('Could not auto-create detention:', e);
                return false;
            }
        }

        // ---------- Stage 2: close the loop ----------
        function openCloseLoopModal(referralId) {
            const r = (behaviorReferrals || []).find(x => x.id === referralId);
            if (!r) return;
            const modal = document.getElementById('closeLoopModal');
            const body = document.getElementById('closeLoopBody');
            if (!modal || !body) return;

            const staff = (teachers || []).slice().sort((a, b) =>
                String(a.name || '').localeCompare(String(b.name || '')));

            body.innerHTML = `
                <div class="modal-context">
                    <div><span class="ctx-label">Student</span><strong>${escapeHtml(r.studentName)}</strong></div>
                    <div><span class="ctx-label">Original behavior</span>${escapeHtml(r.behavior || r.behaviorType || '—')}</div>
                    <div><span class="ctx-label">Incident date</span>${escapeHtml(r.date || '—')}</div>
                    <div><span class="ctx-label">Closed date</span>${r.closedAt ? new Date(r.closedAt).toLocaleDateString() : '—'}</div>
                </div>

                ${(r.closingActions || []).length ? `
                <div class="modal-desc">
                    <span class="ctx-label">Actions recorded at closing</span>
                    <ul class="closed-ref-actions">${r.closingActions.map(a => `<li>${escapeHtml(a)}</li>`).join('')}</ul>
                </div>` : ''}

                <label class="field-label" style="margin-top:14px;">Forward closing summary to staff (optional)</label>
                <input type="text" id="loopStaffSearch" class="wc-input" placeholder="🔍 Search staff by name..."
                       onkeyup="filterLoopStaff()">
                <div class="staff-picker" id="loopStaffList">
                    ${staff.map(t => `
                        <label class="check-item staff-row" data-name="${escapeHtml((t.name || '').toLowerCase())}">
                            <input type="checkbox" class="loop-staff" value="${escapeHtml(t.name || '')}">
                            <span>${escapeHtml(t.name || t.username || '')}</span>
                        </label>`).join('')}
                </div>
                <p class="panel-hint">The referring staff member is included automatically.</p>

                <label class="field-label" style="margin-top:14px;">Additional notes for the summary</label>
                <textarea id="loopNotes" rows="3" class="wc-input"
                    placeholder="Anything else staff should know..."></textarea>

                <div class="modal-actions">
                    <button class="btn btn-secondary" onclick="closeModalById('closeLoopModal')">Cancel</button>
                    <button class="btn btn-loop-close" onclick="confirmCloseLoop('${r.id}')">Close the Loop</button>
                </div>`;
            openRefModal(modal.id);
        }

        function filterLoopStaff() {
            const term = ((document.getElementById('loopStaffSearch') || {}).value || '').toLowerCase();
            document.querySelectorAll('#loopStaffList .staff-row').forEach(row => {
                row.style.display = (row.dataset.name || '').includes(term) ? '' : 'none';
            });
        }

        async function confirmCloseLoop(referralId) {
            const r = (behaviorReferrals || []).find(x => x.id === referralId);
            if (!r) return;
            const picked = Array.from(document.querySelectorAll('.loop-staff:checked')).map(cb => cb.value);
            const notes = ((document.getElementById('loopNotes') || {}).value || '').trim();

            const recipients = Array.from(new Set([r.referredBy, ...picked].filter(Boolean)));
            r.loopClosed = true;
            r.updatedAt = new Date().toISOString();   // so a merge can order this edit
            r.loopClosedBy = currentUser.name;
            r.loopClosedAt = new Date().toISOString();
            r.forwardedTo = recipients;
            if (notes) r.adminNotes = (r.adminNotes ? r.adminNotes + '\n\n' : '') + notes;

            closeModalById('closeLoopModal');
            updateClosedReferralsList();
            showReferralToast(
                `✅ <strong>Loop closed.</strong> Summary recorded for ${recipients.length} staff member${recipients.length === 1 ? '' : 's'}.`, 'ok');
            saveInBackground('Loop closure for ' + r.studentName);
        }

        function toggleDetentionDays(cb) {
            const row = document.getElementById('detentionDaysRow');
            if (!row) return;
            row.style.display = cb.checked ? 'flex' : 'none';
            if (cb.checked) {
                const el = document.getElementById('detentionDaysForReferral');
                if (el) { el.focus(); el.select(); }
            }
        }

        function closeModalById(id) {
            const m = document.getElementById(id);
            if (m) m.classList.add('hidden');
        }

        function openRefModal(id) {
            const m = document.getElementById(id);
            if (!m) return;
            m.classList.remove('hidden');
            const card = m.querySelector('.ref-modal-card');
            if (card) card.scrollTop = 0;
        }

        // Click the dark backdrop (not the card) or press Esc to dismiss.
        document.addEventListener('click', function (e) {
            if (e.target && e.target.classList && e.target.classList.contains('ref-modal')) {
                e.target.classList.add('hidden');
            }
        });
        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape') {
                document.querySelectorAll('.ref-modal:not(.hidden)').forEach(m => m.classList.add('hidden'));
            }
        });

        function viewReferralDetails(referralId) {
            const r = (behaviorReferrals || []).find(x => x.id === referralId);
            if (!r) { alert('⚠️ Referral not found'); return; }
            const modal = document.getElementById('referralDetailModal');
            const body = document.getElementById('referralDetailBody');
            if (!modal || !body) return;

            const iv = r.interventions || [];
            const ca = r.closingActions || [];
            body.innerHTML = `
                <div class="modal-context">
                    <div><span class="ctx-label">Student</span><strong>${escapeHtml(r.studentName)}</strong></div>
                    <div><span class="ctx-label">School / Grade</span>${escapeHtml(r.school || '—')} &middot; ${escapeHtml(String(r.studentGrade || '—'))}</div>
                    <div><span class="ctx-label">Behavior</span>${escapeHtml(r.behavior || r.behaviorType || '—')}</div>
                    <div><span class="ctx-label">Location</span>${escapeHtml(r.location || 'Not recorded')}</div>
                    <div><span class="ctx-label">Incident</span>${escapeHtml(r.date || '—')}${r.time ? ' at ' + escapeHtml(r.time) : ''}</div>
                    <div><span class="ctx-label">Referred by</span>${escapeHtml(r.referredBy || '—')}</div>
                </div>

                <div class="modal-desc">
                    <span class="ctx-label">Description of incident</span>
                    ${escapeHtml(r.description || 'None provided')}
                </div>

                <div class="modal-desc">
                    <span class="ctx-label">Interventions implemented (${iv.length})</span>
                    ${iv.length
                        ? `<ul class="closed-ref-actions">${iv.map(a => `<li>${escapeHtml(a)}</li>`).join('')}</ul>`
                        : '<span class="cell-empty">None logged before referring</span>'}
                </div>

                ${r.additionalActions ? `<div class="modal-desc">
                    <span class="ctx-label">Additional actions / notes</span>
                    ${escapeHtml(r.additionalActions)}
                </div>` : ''}

                ${r.status === 'closed' ? `<div class="modal-desc">
                    <span class="ctx-label">Resolution</span>
                    ${r.resolutionType === 'no_action' ? 'No action required' : 'Action taken'}
                    ${ca.length ? `<ul class="closed-ref-actions">${ca.map(a => `<li>${escapeHtml(a)}</li>`).join('')}</ul>` : ''}
                    ${r.adminNotes ? `<div class="closed-ref-note">${escapeHtml(r.adminNotes)}</div>` : ''}
                    <div class="cell-sub" style="margin-top:6px;">Closed by ${escapeHtml(r.closedBy || '—')}${r.loopClosed ? ' &middot; loop closed' : ' &middot; loop still pending'}</div>
                </div>` : '<div class="modal-desc"><span class="ctx-label">Status</span>Open: awaiting administrator</div>'}

                <div class="modal-actions">
                    <button class="btn btn-secondary" onclick="closeModalById('referralDetailModal')">Close</button>
                    <button class="btn btn-sm-pdf" onclick="printReferral('${r.id}')">📄 Download PDF</button>
                    ${r.status !== 'closed' ? `<button class="btn btn-referral-submit" onclick="closeModalById('referralDetailModal'); openCloseReferralModal('${r.id}')">Close this referral</button>` : ''}
                </div>`;
            openRefModal(modal.id);
        }

        function updateStudentReferralHistory() {
            const studentId = document.getElementById('historyStudentSelect').value;
            
            if (!studentId) {
                document.getElementById('studentReferralSummary').classList.add('hidden');
                document.getElementById('studentReferralHistoryContainer').classList.add('hidden');
                document.getElementById('noHistoryMessage').classList.add('hidden');
                return;
            }
            
            const student = students.find(s => s.id === studentId);
            if (!student) return;
            
            const studentReferrals = behaviorReferrals.filter(r => r.studentId === studentId);
            
            if (studentReferrals.length === 0) {
                document.getElementById('studentReferralSummary').classList.add('hidden');
                document.getElementById('studentReferralHistoryContainer').classList.add('hidden');
                document.getElementById('noHistoryMessage').classList.remove('hidden');
                return;
            }
            
            // Show summary
            document.getElementById('studentReferralSummary').classList.remove('hidden');
            document.getElementById('noHistoryMessage').classList.add('hidden');
            
            // Severity retired — summarise by status and closure instead.
            const minorCount = studentReferrals.filter(r => r.status !== 'closed').length;   // open
            const majorCount = studentReferrals.filter(r => r.status === 'closed').length;   // closed
            const severeCount = studentReferrals.filter(r => r.loopClosed).length;           // loop closed
            
            document.getElementById('summaryMinor').textContent = minorCount;
            document.getElementById('summaryMajor').textContent = majorCount;
            document.getElementById('summarySevere').textContent = severeCount;
            document.getElementById('summaryTotal').textContent = studentReferrals.length;
            
            // Show history table
            document.getElementById('studentReferralHistoryContainer').classList.remove('hidden');
            const tbody = document.getElementById('studentReferralHistoryBody');
            
            const sorted = [...studentReferrals].sort((a, b) => new Date(b.dateTime) - new Date(a.dateTime));
            
            tbody.innerHTML = sorted.map(ref => {
                const severityColor = ref.status === 'closed' ? '#2E7D52' : '#B7791F';
                
                return `
                    <tr style="border-bottom: 1px solid #e5e7eb;">
                        <td style="padding: 14px;">${new Date(ref.dateTime).toLocaleDateString()}</td>
                        <td style="padding: 14px;">${ref.behaviorType}</td>
                        <td style="padding: 14px; text-align: center;">
                            <span style="background: ${severityColor}; color: white; padding: 5px 12px; border-radius: 12px; font-size: 12px; font-weight: 600;">
                                ${ref.status === 'closed' ? 'Closed' : 'Open'}
                            </span>
                        </td>
                        <td style="padding: 14px;">${ref.location}</td>
                        <td style="padding: 14px;">${ref.referredBy}</td>
                        <td style="padding: 14px;">${ref.consequence || '<span style="color: #999;">Pending</span>'}</td>
                        <td style="padding: 14px; text-align: center;">
                            <button class="btn btn-sm-blue" onclick="viewReferralDetails('${ref.id}')">View</button>
                            <button class="btn btn-sm-pdf" onclick="printReferral('${ref.id}')" title="Open a printable referral (save as PDF)">📄 PDF</button>
                        </td>
                    </tr>
                `;
            }).join('');
        }


        // ============================================================
        // REFERRAL ANALYTICS TABS
        //
        // Each pane answers one question. The demographics pane is the one
        // that needs care: see wildcat-discipline.js for why every breakdown
        // there reports a rate against enrolment rather than a raw count.
        // ============================================================
        let analyticsTab = 'all';
        let trendGrain = 'week';

        function switchAnalyticsTab(tab) {
            analyticsTab = tab;
            document.querySelectorAll('.analytics-tabs .analytics-tab').forEach(b =>
                b.classList.toggle('active', b.dataset.atab === tab));
            document.querySelectorAll('.analytics-pane').forEach(p =>
                p.classList.toggle('hidden', p.dataset.apane !== tab));
            renderAnalyticsPane(tab);
        }

        function setTrendGrain(grain) {
            trendGrain = grain;
            const w = document.getElementById('trendGrainWeek');
            const m = document.getElementById('trendGrainMonth');
            if (w) w.classList.toggle('active', grain === 'week');
            if (m) m.classList.toggle('active', grain === 'month');
            renderAnalyticsPane('trends');
        }

        /**
         * Enrolment counts per value, the denominator every demographic rate
         * needs. Built from the CURRENT roster, which is the right population:
         * "who is enrolled now" is what a disproportionality figure compares
         * referrals against.
         */
        function enrollmentBy(dimension) {
            const out = {};
            enrolledStudents().forEach(s => {
                let v = null;
                if (dimension === 'grade') v = s.grade;
                else if (dimension === 'school') v = s.school;
                else if (dimension === 'sex') v = s.sex || s.gender;
                else if (dimension === 'race') v = s.race;
                else if (dimension === 'iep') v = s.iep;
                v = String(v == null ? '' : v).trim();
                if (v) out[v] = (out[v] || 0) + 1;
            });
            return out;
        }

        function renderAnalyticsPane(tab) {
            // Scoped, even though the analytics tab is already closed to
            // teachers. Two independent reasons a teacher cannot see the
            // demographic breakdown is the same standard the restricted-field
            // policy holds itself to, and it costs nothing: for admin and PBIS
            // this returns every referral.
            const all = visibleReferrals();
            if (tab === 'trends')       return renderReferralTrend(all);
            if (tab === 'behaviors')    return renderReferralBehaviors(all);
            if (tab === 'demographics') return renderReferralDemographics(all);
            if (tab === 'closed')       return renderClosedAnalytics(all);
        }

        function renderReferralTrend(all) {
            const el = document.getElementById('referralTrend');
            if (!el) return;
            const t = window.WildcatDiscipline.trend(all, trendGrain);
            if (!t.points.length) {
                el.innerHTML = '<p class="panel-hint">No referrals yet.</p>';
                return;
            }
            const max = Math.max.apply(null, t.points.map(p => p.count)) || 1;
            el.innerHTML = `
                <div class="wc-card">
                    <table class="wc-table"><thead><tr>
                        <th>${trendGrain === 'month' ? 'Month' : 'Week'}</th><th>Referrals</th><th></th>
                    </tr></thead><tbody>
                    ${t.points.map(p => `
                        <tr${p.count === 0 ? ' class="trend-quiet"' : ''}>
                            <td>${escapeHtml(p.key)}</td>
                            <td><strong>${p.count}</strong></td>
                            <td style="width:60%;">
                                <div class="popularity-bar">
                                    <span style="width:${Math.round((p.count / max) * 100)}%"></span>
                                </div>
                            </td>
                        </tr>`).join('')}
                    </tbody></table>
                </div>`;
        }

        function renderReferralBehaviors(all) {
            const el = document.getElementById('referralBehaviors');
            if (!el) return;
            const rows = window.WildcatDiscipline.behaviorBreakdown(all);
            if (!rows.length) {
                el.innerHTML = '<p class="panel-hint">No referrals yet.</p>';
                return;
            }
            const max = rows[0].count || 1;
            el.innerHTML = `
                <div class="wc-card">
                    <table class="wc-table"><thead><tr>
                        <th>Behavior</th><th>Referrals</th><th>Students</th><th>Share</th><th></th>
                    </tr></thead><tbody>
                    ${rows.map(r => `
                        <tr>
                            <td>${escapeHtml(r.behavior)}</td>
                            <td><strong>${r.count}</strong></td>
                            <td>${r.uniqueStudents}</td>
                            <td>${Math.round(r.share * 100)}%</td>
                            <td style="width:40%;">
                                <div class="popularity-bar">
                                    <span style="width:${Math.round((r.count / max) * 100)}%"></span>
                                </div>
                            </td>
                        </tr>`).join('')}
                    </tbody></table>
                </div>`;
        }

        // Race comes from the SERVER, cached per open of the tab.
        let raceAggregate = null;

        // studentNumber, not studentId: a referral's studentId may be a legacy
        // CSV value, while psRestricted and psRoster are keyed by student
        // number. Shared by the aggregate and the admin verification view so
        // the two cannot disagree about which student a referral belongs to.
        function referralStudentNumber(r) {
            if (r && r.studentNumber) return String(r.studentNumber);
            const s = (students || []).find(x => String(x.id) === String(r && r.studentId));
            return s && s.studentNumber ? String(s.studentNumber) : '';
        }

        function referralStudentNumbers(referrals) {
            return (referrals || []).map(referralStudentNumber).filter(Boolean);
        }

        async function loadRaceAggregate(referrals) {
            const auth = window.WildcatAuth;
            const session = auth && auth.getSession && auth.getSession();
            // NOT a permissions refusal, and it must not be reported as one.
            // Username login carries no Convex identity, so every Convex call
            // 401s. Reporting that as "Not available to you" reads as "your
            // role is not allowed to see this", which sends an admin off to
            // check role settings that were never the problem. It cost a round
            // of debugging already.
            if (!auth || !session) {
                return {
                    allowed: false, needsSignIn: true,
                    reason: 'Race comes from the SIS, which needs a Microsoft sign-in. ' +
                            'This session is signed in with a username, so the request ' +
                            'carries no identity and the server refuses it. Sign in with ' +
                            'Microsoft to see this breakdown.'
                };
            }

            // The join happens on the server, but the server cannot see
            // referrals: they are still in Firestore and race is in Convex.
            // So this sends the student NUMBERS it already holds and gets
            // COUNTS back. No race value ever crosses back to this page.
            //
            // studentNumber, not studentId: a referral's studentId may be a
            // legacy CSV value, and psRestricted is keyed by student number.
            const numbers = referralStudentNumbers(referrals);

            try {
                return await auth.convexQuery('disciplineAggregates:byRace',
                    { studentNumbers: numbers }, session.idToken);
            } catch (e) {
                const msg = (e && e.message) || String(e);
                // A 401 is the same situation as holding no session: a token
                // that expired or was rejected, not a decision about the role.
                // Told apart here so the card can say which, because the two
                // need opposite responses from the reader.
                if (/\b401\b|unauthor/i.test(msg)) {
                    return {
                        allowed: false, needsSignIn: true,
                        reason: 'The Microsoft sign-in for this session has expired or was ' +
                                'rejected by the server. Sign out and sign back in with Microsoft.'
                    };
                }
                return { allowed: false, reason: msg };
            }
        }

        function renderReferralDemographics(all) {
            const el = document.getElementById('referralDemographics');
            if (!el) return;
            const D = window.WildcatDiscipline;
            // Race is NOT in this list: it is never derived from referral
            // snapshots, because a child's race must not be written into the
            // app blob. It is fetched from the server and rendered separately
            // below.
            const dims = ['grade', 'school', 'sex', 'iep'];

            // SEX IS RESOLVED FROM THE ROSTER WHEN THE REFERRAL HAS NONE.
            //
            // Referrals record demographics AT FILING TIME, and every referral
            // filed before Students.Gender was synced carries no sex at all.
            // Left alone, this panel would read 0% coverage for months while
            // the answer sat in the roster the whole time.
            //
            // Safe for sex in a way it would NOT be for grade. Grade is
            // snapshotted precisely because it changes every August, so reading
            // it live would relabel last spring's referrals. Sex is not a
            // point-in-time attribute of an incident, so the current record is
            // the right answer rather than a guess. GRADE IS DELIBERATELY NOT
            // BACKFILLED THIS WAY.
            //
            // Display only. Nothing is written back to the referral: a stored
            // snapshot stays whatever was true when it was taken.
            let resolvedSex = 0;
            const rows = (all || []).map(r => {
                const already = r && r.demographics && String(r.demographics.sex || '').trim();
                if (already) return r;
                const num = referralStudentNumber(r);
                const st = (students || []).find(x =>
                    (num && String(x.studentNumber) === num) ||
                    String(x.id) === String(r && r.studentId));
                const sex = st && String(st.sex || st.gender || '').trim();
                if (!sex) return r;
                resolvedSex += 1;
                return Object.assign({}, r, {
                    demographics: Object.assign({}, r.demographics || {}, { sex: sex })
                });
            });

            el.innerHTML = dims.map(dim => {
                const all = rows;
                const avail = D.availability(all, dim);

                // Unavailable dimensions are SHOWN, with what would unblock
                // them. Hiding them would let a reader conclude the school
                // does not track this, rather than that it is withheld.
                if (!avail.available) {
                    return `
                        <div class="wc-card demo-card is-unavailable">
                            <div class="demo-head">
                                <h3>${escapeHtml(avail.label)}</h3>
                                <span class="demo-flag">${avail.restricted ? 'Restricted' : 'Not collected yet'}</span>
                            </div>
                            <p class="panel-hint">${escapeHtml(avail.unblock || 'No data for this field yet.')}</p>
                        </div>`;
                }

                const out = D.breakdownBy(all, dim, enrollmentBy(dim));
                const coverage = Math.round(avail.coverage * 100);
                return `
                    <div class="wc-card demo-card">
                        <div class="demo-head">
                            <h3>${escapeHtml(out.label)}</h3>
                            <span class="receipt-meta">
                                ${out.counted} of ${avail.total} referrals carry this (${coverage}%)
                                ${out.missing ? ` &middot; ${out.missing} without a value` : ''}
                            </span>
                        </div>
                        ${!out.hasDenominator ? `
                            <p class="panel-hint demo-warn">
                                No enrolment figures for this field, so shares below are counts only.
                                A count is not a rate: do not read a tall bar as over-representation.
                            </p>` : ''}
                        <table class="wc-table"><thead><tr>
                            <th>${escapeHtml(out.label)}</th><th>Referrals</th>
                            <th>Share of referrals</th>
                            ${out.hasDenominator ? '<th>Share of enrolment</th><th>Index</th>' : ''}
                        </tr></thead><tbody>
                        ${out.rows.map(r => `
                            <tr>
                                <td>${escapeHtml(D.displayValue(dim, r.value))}</td>
                                <td><strong>${r.count}</strong></td>
                                <td>${Math.round(r.shareOfReferrals * 100)}%</td>
                                ${out.hasDenominator ? `
                                    <td>${r.shareOfEnrollment === null ? '—' : Math.round(r.shareOfEnrollment * 100) + '%'}</td>
                                    <td>${r.suppressed
                                        ? `<span class="receipt-meta" title="Fewer than ${out.smallGroupThreshold} enrolled: a rate here would be noise and could identify a student.">withheld</span>`
                                        : r.tooFewReferrals
                                        ? `<span class="receipt-meta demo-thin" title="An index over ${r.count} referral${r.count === 1 ? '' : 's'} measures the size of the sample, not the school. It appears at ${out.minReferralsForIndex}.">too few</span>`
                                        : (r.index === null ? '—' :
                                           `<span class="${r.index >= 1.5 ? 'demo-over' : ''}">${r.index.toFixed(2)}</span>`)}</td>` : ''}
                            </tr>`).join('')}
                        </tbody></table>
                        ${out.hasDenominator ? `
                            <p class="receipt-meta demo-legend">
                                Index 1.00 is proportionate. 2.00 means referred at twice the rate
                                enrolment predicts. Groups under ${out.smallGroupThreshold} enrolled are withheld.
                                An index needs at least ${out.minReferralsForIndex} referrals in the group:
                                below that the ratio measures the size of the sample rather than the
                                school, so it reads "too few" instead of printing a number nobody
                                could defend.
                            </p>` : ''}
                        ${dim === 'sex' && resolvedSex ? `
                            <p class="receipt-meta demo-legend">
                                ${resolvedSex} referral${resolvedSex === 1 ? '' : 's'} filed before sex was
                                synced from PowerSchool, so ${resolvedSex === 1 ? 'its' : 'their'} value is
                                read from the student's current record rather than from the referral.
                                Grade is never filled in this way, because grade changes every year.
                            </p>` : ''}
                    </div>`;
            }).join('');

            // Race, from the server. Rendered after the rest so the panel is
            // useful immediately rather than waiting on a round trip.
            const raceHost = document.createElement('div');
            raceHost.id = 'referralRaceCard';
            raceHost.innerHTML = '<div class="wc-card demo-card"><p class="panel-hint">Loading race breakdown…</p></div>';
            el.appendChild(raceHost);

            loadRaceAggregate(all).then(res => {
                raceAggregate = res;
                renderRaceCard(raceHost, res, all);
            });
        }

        function renderRaceCard(host, res, all) {
            if (!host) return;
            const D = window.WildcatDiscipline;

            // Sign-in first, because it is not a permissions answer and the
            // reader's next action is completely different.
            if (res && res.needsSignIn) {
                host.innerHTML = `
                    <div class="wc-card demo-card is-unavailable">
                        <div class="demo-head"><h3>Race / Ethnicity</h3>
                            <span class="demo-flag">Microsoft sign-in needed</span></div>
                        <p class="panel-hint">${escapeHtml(res.reason || '')}</p>
                    </div>`;
                return;
            }

            if (!res || res.allowed === false) {
                host.innerHTML = `
                    <div class="wc-card demo-card is-unavailable">
                        <div class="demo-head"><h3>Race / Ethnicity</h3>
                            <span class="demo-flag">Not available to you</span></div>
                        <p class="panel-hint">${escapeHtml((res && res.reason) || 'Unavailable.')}</p>
                    </div>`;
                return;
            }
            if (res.tooFew) {
                host.innerHTML = `
                    <div class="wc-card demo-card is-unavailable">
                        <div class="demo-head"><h3>Race / Ethnicity</h3>
                            <span class="demo-flag">Too few students</span></div>
                        <p class="panel-hint">${escapeHtml(res.reason || '')}</p>
                    </div>`;
                return;
            }
            if (res.loaded === false) {
                host.innerHTML = `
                    <div class="wc-card demo-card is-unavailable">
                        <div class="demo-head"><h3>Race / Ethnicity</h3>
                            <span class="demo-flag">Not loaded</span></div>
                        <p class="panel-hint">${escapeHtml(res.reason || '')}</p>
                    </div>`;
                return;
            }

            const rows = res.rows || [];
            const shown = rows.filter(r => !r.suppressed);
            host.innerHTML = `
                <div class="wc-card demo-card">
                    <div class="demo-head">
                        <h3>Race / Ethnicity</h3>
                        <span class="receipt-meta">
                            ${res.counted} referral${res.counted === 1 ? '' : 's'} matched
                            ${res.unmatched ? ` &middot; ${res.unmatched} with no race record` : ''}
                            ${res.groupsWithheld ? ` &middot; ${res.groupsWithheld} group(s) withheld` : ''}
                        </span>
                    </div>
                    <p class="panel-hint">
                        Served by the server as counts only. No student's race is sent to this page.
                    </p>
                    <table class="wc-table"><thead><tr>
                        <th>Race / Ethnicity</th><th>Referrals</th><th>Share of referrals</th>
                        <th>Share of enrolment</th><th>Index</th>
                    </tr></thead><tbody>
                    ${rows.map(r => `
                        <tr>
                            <td>${escapeHtml(r.code)}</td>
                            <td>${r.suppressed ? '<span class="receipt-meta">withheld</span>' : `<strong>${r.count}</strong>`}</td>
                            <td>${r.suppressed ? '—' : Math.round(r.shareOfReferrals * 100) + '%'}</td>
                            <td>${r.suppressed ? '—' : Math.round(r.shareOfEnrollment * 100) + '%'}</td>
                            <td>${r.suppressed
                                ? `<span class="receipt-meta" title="Fewer than ${res.smallGroupThreshold} enrolled: withheld by the server.">withheld</span>`
                                : r.tooFewReferrals
                                ? `<span class="receipt-meta demo-thin" title="An index over ${r.count} referral${r.count === 1 ? '' : 's'} measures the size of the sample, not the school. It appears at ${res.minReferralsForIndex}.">too few</span>`
                                : (r.index === null ? '—'
                                   : `<span class="${r.index >= 1.5 ? 'demo-over' : ''}">${r.index.toFixed(2)}</span>`)}</td>
                        </tr>`).join('')}
                    </tbody></table>
                    <p class="receipt-meta demo-legend">
                        Index 1.00 is proportionate. 2.00 means referred at twice the rate enrolment
                        predicts. Groups under ${res.smallGroupThreshold} enrolled are withheld by the
                        server, not hidden by this page. An index needs at least
                        ${res.minReferralsForIndex} referrals in the group: below that the ratio
                        measures how few referrals there are rather than anything about the school.
                        A student of two or more races is
                        counted under each, so totals can exceed the referral count. Categories
                        are the federal reporting groups; PowerSchool's detailed CALPADS
                        subcodes are rolled up.
                    </p>
                    ${res.unmappedStudents ? `
                        <p class="receipt-meta demo-legend">
                            ${res.unmappedStudents} student${res.unmappedStudents === 1 ? '' : 's'}
                            carr${res.unmappedStudents === 1 ? 'ies' : 'y'} a race code this app does not
                            recognise (${(res.unmappedCodes || []).map(escapeHtml).join(', ')}), so
                            ${res.unmappedStudents === 1 ? 'it is' : 'they are'} not counted above.
                        </p>` : ''}
                    ${res.unknownEthnicity ? `
                        <p class="receipt-meta demo-legend">
                            ${res.unknownEthnicity} student${res.unknownEthnicity === 1 ? '' : 's'}
                            ${res.unknownEthnicity === 1 ? 'has' : 'have'} no answer to the
                            Hispanic/Latino question in the SIS, so
                            ${res.unknownEthnicity === 1 ? 'it is' : 'they are'} categorised by race
                            code alone. That is a sync gap, not a finding. A large number here
                            means the ethnicity field is not coming through.
                        </p>` : ''}
                </div>`;

            appendRaceVerification(host, all);
        }

        // ADMIN ONLY: the per-referral rows behind the chart.
        //
        // WHY THIS SHOWS INDIVIDUAL RACE WHEN NOTHING ELSE DOES.
        //
        // Asked for on 2026-08-20, for one reason: an aggregate nobody can
        // check is not trustworthy, and the first version of this chart WAS
        // wrong — it read race codes and ignored the Hispanic/Latino question,
        // so a school with no White students reported White. The admin spotted
        // it from knowing the school and had no way to confirm it.
        //
        // Gated twice. This function hides the button for anyone who is not an
        // admin, and the server refuses the query outright with requireAdmin,
        // so hiding the button is a courtesy rather than the control. PBIS was
        // given counts and only counts; this is the permission they were not
        // given.
        function appendRaceVerification(host, all) {
            const role = (currentUser && currentUser.role) || '';
            if (role !== 'admin' && role !== 'superadmin') return;
            const card = host.querySelector('.demo-card');
            if (!card) return;

            const wrap = document.createElement('div');
            wrap.className = 'race-verify';
            wrap.innerHTML = `
                <button type="button" class="btn-secondary race-verify-btn">
                    Verify these counts
                </button>
                <p class="receipt-meta">
                    Administrators only. Opens the referral-by-referral rows behind the chart,
                    with each student's race and Hispanic/Latino answer exactly as PowerSchool
                    holds it, so the totals above can be checked against the roster. Behind a
                    click because it puts named children's race on screen.
                </p>
                <div class="race-verify-out"></div>`;
            card.appendChild(wrap);

            const btn = wrap.querySelector('.race-verify-btn');
            const out = wrap.querySelector('.race-verify-out');
            btn.addEventListener('click', function () {
                setButtonBusy(btn, true, 'Loading…');
                out.innerHTML = '<p class="panel-hint">Loading the rows behind the numbers…</p>';
                loadRaceVerification(all).then(function (v) {
                    setButtonBusy(btn, false);
                    renderRaceVerification(out, all, v);
                });
            });
        }

        async function loadRaceVerification(referrals) {
            const auth = window.WildcatAuth;
            const session = auth && auth.getSession && auth.getSession();
            if (!auth || !session) {
                return {
                    allowed: false, needsSignIn: true,
                    reason: 'This reads the SIS, which needs a Microsoft sign-in. ' +
                            'A username session carries no identity for the server to check.'
                };
            }
            try {
                return await auth.convexQuery('disciplineAggregates:raceVerification',
                    { studentNumbers: referralStudentNumbers(referrals) }, session.idToken);
            } catch (e) {
                const msg = (e && e.message) || String(e);
                if (/\b401\b|unauthor/i.test(msg)) {
                    return { allowed: false, needsSignIn: true,
                        reason: 'The Microsoft sign-in for this session has expired. Sign out and back in.' };
                }
                return { allowed: false, reason: msg };
            }
        }

        function renderRaceVerification(out, referrals, v) {
            if (!out) return;
            if (!v || v.allowed === false) {
                out.innerHTML = `<p class="panel-hint">${escapeHtml((v && v.reason) || 'Unavailable.')}</p>`;
                return;
            }

            const byNumber = {};
            (v.rows || []).forEach(function (r) { byNumber[r.studentNumber] = r; });

            // ONE ROW PER REFERRAL, because the chart counts referrals. A
            // per-student list would not reconcile against it for any student
            // with two referrals, which is exactly the case worth checking.
            const lines = (referrals || []).slice().sort(function (a, b) {
                return new Date(b.submittedAt) - new Date(a.submittedAt);
            }).map(function (r) {
                const num = referralStudentNumber(r);
                return { referral: r, number: num, info: num ? byNumber[num] : null };
            });

            // The reconciliation. Counted the same way the server counts: a
            // referral adds one to EVERY category its student reports under.
            const tally = {};
            lines.forEach(function (l) {
                ((l.info && l.info.reported) || []).forEach(function (c) {
                    tally[c] = (tally[c] || 0) + 1;
                });
            });
            const noRecord = lines.filter(function (l) { return !l.info || !l.info.reported.length; }).length;

            const why = function (info) {
                if (!info) return 'No SIS record';
                if (info.basis === 'ethnicity') return 'Hispanic/Latino, ethnicity is asked first and overrides race';
                if (info.basis === 'race') return 'Not Hispanic/Latino, so categorised by race code';
                if (!info.hasRecord) return 'No restricted record synced for this student';
                return 'No usable race code or ethnicity answer';
            };

            out.innerHTML = `
                <div class="wc-card race-verify-card">
                    <p class="receipt-meta">
                        ${lines.length} referral${lines.length === 1 ? '' : 's'}
                        &middot; restricted data, admins only &middot; do not export or screenshot
                    </p>
                    <table class="wc-table"><thead><tr>
                        <th>Referral</th><th>Student</th><th>Gr.</th><th>Status</th>
                        <th>Counted as</th><th>Hispanic/Latino?</th><th>Race code(s)</th><th>Why</th>
                    </tr></thead><tbody>
                    ${lines.map(function (l) {
                        const i = l.info;
                        const eth = !i ? '—'
                            : i.ethnicity === 'hispanic' ? 'Yes'
                            : i.ethnicity === 'not' ? 'No'
                            : '<span class="receipt-meta" title="Never answered in the SIS">Not answered</span>';
                        const codes = i && i.raceCodes.length
                            ? i.raceCodes.map(function (c, n) {
                                  const lab = i.raceLabels[n];
                                  return escapeHtml(c) + (lab ? ' <span class="receipt-meta">(' + escapeHtml(lab) + ')</span>' : '');
                              }).join(', ')
                            : '<span class="receipt-meta">none</span>';
                        return `
                        <tr${(!i || !i.reported.length) ? ' class="demo-gap"' : ''}>
                            <td>${escapeHtml(l.referral.id || '')}</td>
                            <td>${escapeHtml(l.referral.studentName || ((i && (i.firstName + ' ' + i.lastName)) || 'Unknown'))}</td>
                            <td>${escapeHtml((i && i.gradeLevel) || l.referral.studentGrade || '')}</td>
                            <td>${l.referral.status === 'closed' ? 'Closed' : '<strong>Open</strong>'}</td>
                            <td>${i && i.reported.length
                                    ? i.reported.map(escapeHtml).join(' + ')
                                    : '<span class="receipt-meta">not counted</span>'}</td>
                            <td>${eth}</td>
                            <td>${codes}</td>
                            <td class="receipt-meta">${escapeHtml(why(i))}</td>
                        </tr>`;
                    }).join('')}
                    </tbody></table>

                    <div class="race-verify-tally">
                        <div class="sh-detail-head">These rows add up to</div>
                        ${Object.keys(tally).sort(function (a, b) { return tally[b] - tally[a]; })
                            .map(function (k) {
                                return '<div class="sh-detail-row"><span>' + escapeHtml(k) +
                                       '</span><span>' + tally[k] + '</span></div>';
                            }).join('')}
                        ${noRecord ? '<div class="sh-detail-row"><span>Not counted (no race record)</span><span>' +
                                     noRecord + '</span></div>' : ''}
                    </div>
                    <p class="receipt-meta demo-legend">
                        Compare this list with the chart above: the numbers should match exactly,
                        except where the chart withheld a group under ${escapeHtml(String(
                            (raceAggregate && raceAggregate.smallGroupThreshold) || 10))} enrolled.
                        A student of two or more races adds one to each of their categories, so
                        the totals here can exceed the referral count.
                    </p>
                </div>`;
        }

        function renderClosedAnalytics(all) {
            const el = document.getElementById('referralClosedAnalytics');
            if (!el) return;
            const closed = all.filter(r => r && r.status === 'closed');
            if (!closed.length) {
                el.innerHTML = '<p class="panel-hint">No referrals have been closed yet.</p>';
                return;
            }
            const byResolution = {};
            let loopClosed = 0;
            let totalDays = 0, timed = 0;
            closed.forEach(r => {
                const res = String(r.resolutionType || '').trim() || 'Not recorded';
                byResolution[res] = (byResolution[res] || 0) + 1;
                if (r.loopClosed) loopClosed += 1;
                const a = new Date(r.submittedAt), b = new Date(r.closedAt);
                if (!isNaN(a) && !isNaN(b) && b >= a) { totalDays += (b - a) / 864e5; timed += 1; }
            });
            const rows = Object.keys(byResolution)
                .map(k => ({ resolution: k, count: byResolution[k] }))
                .sort((a, b) => b.count - a.count);

            el.innerHTML = `
                <div class="receipt-summary">
                    <span class="receipt-stat"><strong>${closed.length}</strong> closed</span>
                    <span class="receipt-stat"><strong>${loopClosed}</strong> loop closed</span>
                    <span class="receipt-stat"><strong>${timed ? (totalDays / timed).toFixed(1) : '—'}</strong> avg days to close</span>
                </div>
                <div class="wc-card">
                    <table class="wc-table"><thead><tr><th>Resolution</th><th>Referrals</th><th>Share</th></tr></thead><tbody>
                    ${rows.map(r => `
                        <tr><td>${escapeHtml(r.resolution)}</td><td><strong>${r.count}</strong></td>
                        <td>${Math.round((r.count / closed.length) * 100)}%</td></tr>`).join('')}
                    </tbody></table>
                </div>`;
        }

        function updateReferralAnalytics() {
            // Severity was dropped; the school tracks its TOP BEHAVIOURS instead,
            // which is more actionable ("Habitual Defiance is our #1") than a
            // Minor/Major/Severe split.
            const all = visibleReferrals();
            const open = getOpenReferrals();
            const now = new Date();
            const weekAgo = new Date(now.getTime() - 7 * 864e5);
            const thisWeek = all.filter(r => new Date(r.submittedAt) >= weekAgo);
            const uniqueStudents = new Set(all.map(r => r.studentId)).size;

            const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
            set('analyticsTotalReferrals', all.length);
            set('analyticsThisWeek', thisWeek.length);
            set('analyticsPending', open.length);
            set('analyticsStudents', uniqueStudents);

            const rank = (arr, key) => {
                const counts = {};
                arr.forEach(r => {
                    const k = (typeof key === 'function' ? key(r) : r[key]) || 'Not recorded';
                    counts[k] = (counts[k] || 0) + 1;
                });
                return Object.entries(counts).sort((a, b) => b[1] - a[1]);
            };

            const barList = (rows, total, limit) => {
                if (!rows.length) return '<p class="cell-empty">No data yet</p>';
                const top = rows.slice(0, limit || 10);
                const max = top[0][1] || 1;
                return top.map(([label, n], i) => `
                    <div class="rank-bar-row">
                        <div class="rank-bar-top">
                            <span class="rank-bar-label"><span class="rank-bar-num">${i + 1}</span>${escapeHtml(label)}</span>
                            <span class="rank-bar-count">${n}<span class="rank-bar-pct"> · ${total ? Math.round(n / total * 100) : 0}%</span></span>
                        </div>
                        <div class="sh-track"><div class="sh-fill sh-mid" style="width:${(n / max * 100).toFixed(1)}%"></div></div>
                    </div>`).join('');
            };

            const behaviours = rank(all, r => r.behavior || r.behaviorType);
            const locations = rank(all, 'location');
            const staff = rank(all, 'referredBy');

            const host = document.getElementById('behaviorTypeChart');
            if (host) {
                host.innerHTML =
                    `<div class="analytics-block">
                        <h4 class="chart-title">Top 10 Behaviors</h4>
                        ${barList(behaviours, all.length, 10)}
                     </div>
                     <div class="analytics-block">
                        <h4 class="chart-title">Where incidents happen</h4>
                        ${barList(locations, all.length, 7)}
                     </div>
                     <div class="analytics-block">
                        <h4 class="chart-title">Referrals by staff member</h4>
                        ${barList(staff, all.length, 10)}
                     </div>
                     <div class="analytics-block">
                        <h4 class="chart-title">Intervention practice</h4>
                        ${(() => {
                            if (!all.length) return '<p class="cell-empty">No data yet</p>';
                            // Severe removals are EXCLUDED from the denominator,
                            // not counted as failures. Judging a teacher who
                            // removed a violent student against a three-step
                            // expectation that could not apply makes the figure
                            // a measure of how many emergencies happened.
                            const severe = all.filter(r => r.severeBypass).length;
                            const eligible = all.filter(r => !r.severeBypass);
                            const withThree = eligible.filter(r => (r.interventions || []).length >= 3).length;
                            const none = eligible.filter(r => !(r.interventions || []).length).length;
                            const pct = eligible.length ? Math.round(withThree / eligible.length * 100) : null;
                            return `<div class="mini-grid">
                                <div class="mini-tile"><div class="mini-label">Met the 3-intervention expectation</div><div class="mini-num">${pct === null ? '—' : pct + '%'}</div></div>
                                <div class="mini-tile${none ? ' mini-tile-warn' : ''}"><div class="mini-label">Filed with none logged</div><div class="mini-num">${none}</div></div>
                                <div class="mini-tile"><div class="mini-label">Too severe for interventions</div><div class="mini-num">${severe}</div></div>
                                <div class="mini-tile"><div class="mini-label">Closed &amp; loop closed</div><div class="mini-num">${all.filter(r => r.loopClosed).length}</div></div>
                            </div>`;
                        })()}
                     </div>`;
            }
        }
        
        // ========================================
        // DETENTION TRACKER FUNCTIONS
        // ========================================
        
        let currentDetentionLevel = 'ms'; // 'ms' or 'hs'
        
        function initializeDetentionForm() {
            // Set today's date as default
            const today = new Date().toISOString().split('T')[0];
            document.getElementById('detentionDateAssigned').value = today;
            document.getElementById('detentionStartDate').value = today;
            
            // Populate location dropdown
            const locationSelect = document.getElementById('detentionLocation');
            locationSelect.innerHTML = '<option value="">Select location...</option>' +
                detentionLocations.map(loc => `<option value="${loc}">${loc}</option>`).join('');
            
            // Populate reason dropdown
            const reasonSelect = document.getElementById('detentionReason');
            reasonSelect.innerHTML = '<option value="">Select reason...</option>' +
                detentionReasons.map(reason => `<option value="${reason}">${reason}</option>`).join('');
        }
        
        function switchDetentionLevel(level) {
            currentDetentionLevel = level;
            
            // Update button styles
            document.querySelectorAll('.detention-level-btn').forEach(btn => {
                btn.style.background = '#f5f5f5';
                btn.style.color = '#333';
            });
            
            const activeBtn = document.getElementById(level === 'ms' ? 'detentionMSBtn' : 'detentionHSBtn');
            if (level === 'ms') {
                activeBtn.style.background = 'linear-gradient(135deg, #ff9800 0%, #f57c00 100%)';
            } else {
                activeBtn.style.background = 'linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)';
            }
            activeBtn.style.color = 'white';
            
            // Refresh detention lists
            updateDetentionLists();
        }
        
        function searchStudentsForDetention() {
            const searchTerm = document.getElementById('detentionStudentSearch').value.trim().toLowerCase();
            const resultsDiv = document.getElementById('detentionStudentResults');
            
            if (searchTerm.length < 2) {
                resultsDiv.style.display = 'none';
                return;
            }
            
            // Filter by current detention level (MS or HS)
            const filteredStudents = students.filter(s => {
                const grade = parseInt(s.grade);
                const levelMatch = currentDetentionLevel === 'ms' ? (grade >= 6 && grade <= 8) : (grade >= 9 && grade <= 12);
                
                if (!levelMatch) return false;
                
                const fullName = `${s.firstName} ${s.lastName}`.toLowerCase();
                const reverseName = `${s.lastName} ${s.firstName}`.toLowerCase();
                const studentId = (s.studentId || '').toLowerCase();
                
                return fullName.includes(searchTerm) || reverseName.includes(searchTerm) || studentId.includes(searchTerm);
            });
            
            if (filteredStudents.length === 0) {
                resultsDiv.innerHTML = '<div style="padding: 10px; color: #999;">No students found</div>';
                resultsDiv.style.display = 'block';
                return;
            }
            
            resultsDiv.innerHTML = filteredStudents.slice(0, 10).map(s => `
                <div onclick="selectDetentionStudent('${s.id}')" style="padding: 10px; cursor: pointer; border-bottom: 1px solid #eee; transition: background 0.2s;" onmouseover="this.style.background='#f5f5f5'" onmouseout="this.style.background='white'">
                    <strong>${s.firstName} ${s.lastName}</strong>
                    <small style="color: #666; margin-left: 10px;">Grade ${s.grade} ${s.studentId ? '• ID: ' + s.studentId : ''}</small>
                </div>
            `).join('');
            
            resultsDiv.style.display = 'block';
        }
        
        function selectDetentionStudent(studentId) {
            const student = students.find(s => s.id === studentId);
            if (!student) return;
            
            document.getElementById('selectedDetentionStudentId').value = studentId;
            document.getElementById('selectedDetentionStudentName').textContent = `${student.firstName} ${student.lastName} (Grade ${student.grade})`;
            document.getElementById('selectedDetentionStudent').style.display = 'block';
            document.getElementById('detentionStudentResults').style.display = 'none';
            document.getElementById('detentionStudentSearch').value = '';
        }
        
        function clearDetentionStudentSelection() {
            document.getElementById('selectedDetentionStudentId').value = '';
            document.getElementById('selectedDetentionStudent').style.display = 'none';
            document.getElementById('detentionStudentSearch').value = '';
        }
        
        function assignDetention() {
            const studentId = document.getElementById('selectedDetentionStudentId').value;
            const location = document.getElementById('detentionLocation').value;
            const dateAssigned = document.getElementById('detentionDateAssigned').value;
            const totalDays = parseInt(document.getElementById('detentionTotalDays').value);
            const startDate = document.getElementById('detentionStartDate').value;
            const reason = document.getElementById('detentionReason').value.trim();
            
            // Validation
            if (!studentId) {
                alert('⚠️ Please select a student');
                return;
            }
            if (!location) {
                alert('⚠️ Please select a location');
                return;
            }
            if (!dateAssigned) {
                alert('⚠️ Please enter the date detention was assigned');
                return;
            }
            if (!totalDays || totalDays < 1) {
                alert('⚠️ Please enter a valid number of days (1-30)');
                return;
            }
            if (!startDate) {
                alert('⚠️ Please enter the start date');
                return;
            }
            if (!reason) {
                alert('⚠️ Please enter a reason for detention');
                return;
            }
            
            const student = students.find(s => s.id === studentId);
            if (!student) return;
            
            // Create detention record
            const detention = {
                id: 'detention_' + detentionIdCounter++,
                studentId: studentId,
                studentName: `${student.firstName} ${student.lastName}`,
                grade: student.grade,
                location: location,
                dateAssigned: dateAssigned,
                totalDays: totalDays,
                daysServed: 0,
                daysRemaining: totalDays,
                startDate: startDate,
                reason: reason,
                status: 'active', // 'active' or 'completed'
                assignedBy: currentUser.name,
                assignedAt: new Date().toISOString(),
                servedDates: [], // Array of dates when detention was served
                completedAt: null
            };
            
            detentions.push(detention);
            saveData();
            
            // Clear form
            clearDetentionStudentSelection();
            document.getElementById('detentionLocation').value = '';
            document.getElementById('detentionDateAssigned').value = '';
            document.getElementById('detentionTotalDays').value = '1';
            document.getElementById('detentionStartDate').value = '';
            document.getElementById('detentionReason').value = '';
            
            updateDetentionLists();
            
            showSuccessToast(`✅ Detention assigned to ${student.firstName} ${student.lastName}`);
        }
        
        function updateDetentionLists() {
            // Filter detentions by current level (MS or HS)
            const levelDetentions = detentions.filter(d => {
                const grade = parseInt(d.grade);
                return currentDetentionLevel === 'ms' ? (grade >= 6 && grade <= 8) : (grade >= 9 && grade <= 12);
            });
            
            const active = levelDetentions.filter(d => d.status === 'active');
            const completed = levelDetentions.filter(d => d.status === 'completed');
            
            // Update counts
            document.getElementById('activeDetentionCount').textContent = `${active.length} Active`;
            document.getElementById('completedDetentionCount').textContent = `${completed.length} Completed`;
            
            // Render active detentions
            const activeList = document.getElementById('activeDetentionsList');
            if (active.length === 0) {
                activeList.innerHTML = '<p style="text-align: center; color: #999; padding: 40px;">No active detentions</p>';
            } else {
                activeList.innerHTML = active.map(d => renderDetentionCard(d, true)).join('');
            }
            
            // Render completed detentions
            const completedList = document.getElementById('completedDetentionsList');
            if (completed.length === 0) {
                completedList.innerHTML = '<p style="text-align: center; color: #999; padding: 40px;">No completed detentions</p>';
            } else {
                completedList.innerHTML = completed.map(d => renderDetentionCard(d, false)).join('');
            }
        }
        
        function renderDetentionCard(detention, isActive) {
            const progressPercent = detention.totalDays > 0 ? (detention.daysServed / detention.totalDays * 100) : 0;
            
            return `
                <div style="border: 2px solid ${isActive ? '#B3392F' : '#28a745'}; border-radius: 8px; padding: 20px; margin-bottom: 15px; background: ${isActive ? '#fff5f5' : '#f0fdf4'};">
                    <div style="display: flex; justify-content: space-between; align-items: start; margin-bottom: 15px;">
                        <div>
                            <h4 style="margin: 0 0 5px 0; color: #333;">${detention.studentName}</h4>
                            <small style="color: #666;">Grade ${detention.grade} • Assigned ${new Date(detention.dateAssigned).toLocaleDateString()}</small>
                        </div>
                        <div style="text-align: right;">
                            <div style="padding: 6px 12px; background: ${isActive ? '#B3392F' : '#28a745'}; color: white; border-radius: 20px; font-size: 12px; font-weight: 600; margin-bottom: 5px;">
                                ${isActive ? 'ACTIVE' : 'COMPLETED'}
                            </div>
                            <small style="color: #666;">ID: ${detention.id.split('_')[1]}</small>
                        </div>
                    </div>
                    
                    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin-bottom: 15px;">
                        <div>
                            <small style="color: #666;">Location</small>
                            <div style="font-weight: 600;">${detention.location}</div>
                        </div>
                        <div>
                            <small style="color: #666;">Start Date</small>
                            <div style="font-weight: 600;">${new Date(detention.startDate).toLocaleDateString()}</div>
                        </div>
                        <div>
                            <small style="color: #666;">Days Served</small>
                            <div style="font-weight: 600; color: ${isActive ? '#B3392F' : '#28a745'};">${detention.daysServed} / ${detention.totalDays}</div>
                        </div>
                        <div>
                            <small style="color: #666;">Remaining</small>
                            <div style="font-weight: 600;">${detention.daysRemaining} days</div>
                        </div>
                    </div>
                    
                    <div style="margin-bottom: 15px;">
                        <small style="color: #666;">Reason</small>
                        <div style="margin-top: 5px;">${detention.reason}</div>
                    </div>
                    
                    <!-- Progress Bar -->
                    <div style="background: #e0e0e0; border-radius: 10px; height: 20px; overflow: hidden; margin-bottom: 15px;">
                        <div style="background: ${isActive ? 'linear-gradient(90deg, #dc3545, #c82333)' : 'linear-gradient(90deg, #28a745, #218838)'}; height: 100%; width: ${progressPercent}%; transition: width 0.3s; display: flex; align-items: center; justify-content: center; color: white; font-size: 11px; font-weight: 600;">
                            ${progressPercent.toFixed(0)}%
                        </div>
                    </div>
                    
                    <div style="display: flex; gap: 10px;">
                        ${isActive ? `
                            <button onclick="markDetentionDay('${detention.id}')" style="flex: 1; padding: 10px; background: #28a745; color: white; border: none; border-radius: 6px; cursor: pointer; font-weight: 600;">
                                ✅ Mark Day Served
                            </button>
                            <button onclick="editDetention('${detention.id}')" style="padding: 10px 20px; background: #ffc107; color: #333; border: none; border-radius: 6px; cursor: pointer; font-weight: 600;">
                                ✏️ Edit
                            </button>
                        ` : `
                            <div style="flex: 1; padding: 10px; background: #28a745; color: white; border-radius: 6px; text-align: center; font-weight: 600;">
                                ✅ Completed ${detention.completedAt ? new Date(detention.completedAt).toLocaleDateString() : ''}
                            </div>
                        `}
                        <button onclick="viewDetentionDetails('${detention.id}')" style="padding: 10px 20px; background: #667eea; color: white; border: none; border-radius: 6px; cursor: pointer; font-weight: 600;">
                            👁️ Details
                        </button>
                    </div>
                </div>
            `;
        }
        
        async function markDetentionDay(detentionId) {
            const detention = detentions.find(d => d.id === detentionId);
            if (!detention || detention.status !== 'active') return;
            
            const today = new Date().toISOString().split('T')[0];
            
            // Initialize attendance records if not exists
            if (!detention.attendanceRecords) {
                detention.attendanceRecords = [];
            }
            
            // Check if already marked today
            const existingRecord = detention.attendanceRecords.find(r => r.date === today);
            if (existingRecord) {
                alert(`⚠️ Attendance already marked for today as: ${existingRecord.status}\n\nDate: ${new Date(today).toLocaleDateString()}`);
                return;
            }
            
            // Ask for attendance status
            const attendance = await showConfirm(
                `📋 DETENTION ATTENDANCE\n\n` +
                `Student: ${detention.studentName}\n` +
                `Date: ${new Date(today).toLocaleDateString()}\n\n` +
                `Was the student PRESENT for detention today?\n\n` +
                `Click OK for PRESENT\n` +
                `Click Cancel for ABSENT`
            );
            
            const status = attendance ? 'present' : 'absent';
            
            // Record attendance
            detention.attendanceRecords.push({
                date: today,
                status: status,
                markedBy: currentUser.name,
                markedAt: new Date().toISOString()
            });
            // Read by wildcat-merge to decide which copy of a detention is
            // newer when two tabs both hold one. Without it a stale tab's copy
            // ties on stamps and can win, undoing this attendance mark.
            detention.updatedAt = new Date().toISOString();
            
            // Only increment days served if PRESENT
            if (status === 'present') {
                detention.daysServed++;
                detention.daysRemaining = detention.totalDays - detention.daysServed;
                detention.servedDates.push(today);
                
                // Check if completed
                if (detention.daysServed >= detention.totalDays) {
                    detention.status = 'completed';
                    detention.completedAt = new Date().toISOString();
                    showSuccessToast(`🎉 ${detention.studentName} has completed their detention!`);
                } else {
                    showSuccessToast(`✅ PRESENT - Day marked for ${detention.studentName} (${detention.daysServed}/${detention.totalDays})`);
                }
            } else {
                // Absent - no credit for the day
                showSuccessToast(`⚠️ ABSENT - ${detention.studentName} was marked absent. No credit given.`);
            }
            
            saveData();
            updateDetentionLists();
        }
        
        async function editDetention(detentionId) {
            const detention = detentions.find(d => d.id === detentionId);
            if (!detention) return;
            
            const newDays = await showPrompt(`Edit total detention days for ${detention.studentName}\n\nCurrent: ${detention.totalDays} days\nServed: ${detention.daysServed} days\n\nEnter new total days (must be >= days served):`, detention.totalDays);
            
            if (newDays === null) return; // Cancelled
            
            const parsedDays = parseInt(newDays);
            if (isNaN(parsedDays) || parsedDays < detention.daysServed) {
                alert('⚠️ Invalid number. Total days must be at least ' + detention.daysServed);
                return;
            }
            
            detention.totalDays = parsedDays;
            detention.daysRemaining = parsedDays - detention.daysServed;
            
            // Reactivate if was completed but days increased
            if (detention.status === 'completed' && detention.daysRemaining > 0) {
                detention.status = 'active';
                detention.completedAt = null;
            }
            
            saveData();
            updateDetentionLists();
            showSuccessToast(`✅ Detention updated for ${detention.studentName}`);
        }
        
        function viewDetentionDetails(detentionId) {
            const detention = detentions.find(d => d.id === detentionId);
            if (!detention) return;
            
            const servedDatesText = detention.servedDates.length > 0 
                ? detention.servedDates.map(d => new Date(d).toLocaleDateString()).join(', ')
                : 'None yet';
            
            // Build attendance record text
            let attendanceText = '';
            if (detention.attendanceRecords && detention.attendanceRecords.length > 0) {
                attendanceText = '\n\nAttendance Records:\n' + detention.attendanceRecords.map(r => 
                    `${new Date(r.date).toLocaleDateString()}: ${r.status.toUpperCase()}`
                ).join('\n');
            }
            
            alert(
                `📋 DETENTION DETAILS\n\n` +
                `Student: ${detention.studentName}\n` +
                `Grade: ${detention.grade}\n\n` +
                `Location: ${detention.location}\n` +
                `Date Assigned: ${new Date(detention.dateAssigned).toLocaleDateString()}\n` +
                `Start Date: ${new Date(detention.startDate).toLocaleDateString()}\n\n` +
                `Total Days: ${detention.totalDays}\n` +
                `Days Served: ${detention.daysServed}\n` +
                `Days Remaining: ${detention.daysRemaining}\n\n` +
                `Status: ${detention.status.toUpperCase()}\n` +
                (detention.completedAt ? `Completed: ${new Date(detention.completedAt).toLocaleDateString()}\n\n` : '\n') +
                `Reason: ${detention.reason}\n\n` +
                `Dates Served:\n${servedDatesText}` +
                attendanceText + `\n\n` +
                `Assigned By: ${detention.assignedBy}\n` +
                `Assigned At: ${new Date(detention.assignedAt).toLocaleString()}`
            );
        }
        
        // ========================================
        // DETENTION SETTINGS FUNCTIONS
        // ========================================
        
        function openDetentionSettings() {
            updateDetentionSettingsLists();
            document.getElementById('detentionSettingsModal').style.display = 'flex';
        }
        
        function closeDetentionSettings() {
            document.getElementById('detentionSettingsModal').style.display = 'none';
            // Refresh dropdowns in main form
            initializeDetentionForm();
        }
        
        function updateDetentionSettingsLists() {
            // Update locations list
            const locationsList = document.getElementById('detentionLocationsList');
            locationsList.innerHTML = detentionLocations.map((loc, index) => `
                <div style="display: flex; justify-content: space-between; align-items: center; padding: 10px; background: #f5f5f5; border-radius: 6px; margin-bottom: 8px;">
                    <span>${loc}</span>
                    <button onclick="removeDetentionLocation(${index})" style="padding: 4px 12px; background: #dc3545; color: white; border: none; border-radius: 4px; cursor: pointer;">Remove</button>
                </div>
            `).join('');
            
            // Update reasons list
            const reasonsList = document.getElementById('detentionReasonsList');
            reasonsList.innerHTML = detentionReasons.map((reason, index) => `
                <div style="display: flex; justify-content: space-between; align-items: center; padding: 10px; background: #f5f5f5; border-radius: 6px; margin-bottom: 8px;">
                    <span>${reason}</span>
                    <button onclick="removeDetentionReason(${index})" style="padding: 4px 12px; background: #dc3545; color: white; border: none; border-radius: 4px; cursor: pointer;">Remove</button>
                </div>
            `).join('');
        }
        
        function addDetentionLocation() {
            const input = document.getElementById('newDetentionLocation');
            const newLocation = input.value.trim();
            
            if (!newLocation) {
                alert('⚠️ Please enter a location name');
                return;
            }
            
            if (detentionLocations.includes(newLocation)) {
                alert('⚠️ This location already exists');
                return;
            }
            
            detentionLocations.push(newLocation);
            input.value = '';
            updateDetentionSettingsLists();
            saveData();
            showSuccessToast(`✅ Location "${newLocation}" added`);
        }
        
        async function removeDetentionLocation(index) {
            const location = detentionLocations[index];
            if (await showConfirm(`Remove location "${location}"?`)) {
                detentionLocations.splice(index, 1);
                updateDetentionSettingsLists();
                saveData();
                showSuccessToast(`✅ Location "${location}" removed`);
            }
        }
        
        function addDetentionReason() {
            const input = document.getElementById('newDetentionReason');
            const newReason = input.value.trim();
            
            if (!newReason) {
                alert('⚠️ Please enter a reason');
                return;
            }
            
            if (detentionReasons.includes(newReason)) {
                alert('⚠️ This reason already exists');
                return;
            }
            
            detentionReasons.push(newReason);
            input.value = '';
            updateDetentionSettingsLists();
            saveData();
            showSuccessToast(`✅ Reason "${newReason}" added`);
        }
        
        async function removeDetentionReason(index) {
            const reason = detentionReasons[index];
            if (await showConfirm(`Remove reason "${reason}"?`)) {
                detentionReasons.splice(index, 1);
                updateDetentionSettingsLists();
                saveData();
                showSuccessToast(`✅ Reason "${reason}" removed`);
            }
        }

        function exportReferralReport() {
            // EXPORTS WHAT THE EXPORTER MAY SEE, not the whole table. A file
            // leaves the app and gets mailed around, so an unscoped export is
            // the most durable way to leak a discipline record.
            const behaviorReferrals = visibleReferrals();
            if (behaviorReferrals.length === 0) {
                alert('No referral data to export');
                return;
            }
            
            // Create workbook
            const wb = XLSX.utils.book_new();
            
            // Prepare data
            const data = behaviorReferrals.map(r => ({
                'Referral ID': r.id,
                'Date': new Date(r.dateTime).toLocaleDateString(),
                'Time': new Date(r.dateTime).toLocaleTimeString(),
                'Student Name': r.studentName,
                'Behavior Type': r.behaviorType,
                'Interventions Attempted': (r.interventions || []).length,
                'Too Severe For Interventions': r.severeBypass ? 'Yes' : 'No',
                'Resolution': r.resolutionType === 'no_action' ? 'No action required' : (r.status === 'closed' ? 'Action taken' : ''),
                'Closing Actions': (r.closingActions || []).join('; '),
                'Loop Closed': r.loopClosed ? 'Yes' : 'No',
                'Location': r.location,
                'Description': r.description,
                'Referred By': r.referredBy,
                'Status': r.status,
                'Consequence': r.consequence || '',
                'Admin Notes': r.adminNotes || '',
                'Reviewed By': r.reviewedBy || '',
                'Tickets Deducted': r.ticketsDeducted || 0,
                'Cash Deducted': r.cashDeducted || 0,
                'Parent Notified': r.parentNotified ? 'Yes' : 'No'
            }));
            
            // Create worksheet
            const ws = XLSX.utils.json_to_sheet(data);
            
            // Add to workbook
            XLSX.utils.book_append_sheet(wb, ws, 'Behavior Referrals');
            
            // Generate file
            const filename = `Behavior_Referrals_${new Date().toISOString().split('T')[0]}.xlsx`;
            XLSX.writeFile(wb, filename);
            
            alert('✅ Referral report exported successfully!');
        }


        // ============================================================
        // MOTION BRIDGE
        //
        // The only place script.js talks to wildcat-motion.js. Every
        // helper below no-ops if that file did not load, so motion is
        // strictly additive: pull the <script> tag and the app is the app.
        //
        // WHERE MOTION IS *NOT* APPLIED, AND WHY.
        // rb-standards.md opens with a frequency table: 100+ times a day
        // gets no animation ever, tens of times a day gets it drastically
        // reduced, occasional gets standard animation, rare gets delight.
        // This is an operations app. A teacher awards tickets in bursts all
        // day, searches the roster constantly, and switches tabs
        // constantly. So:
        //
        //   · Award Tickets, Award Cash, the student checkbox grid and
        //     every button in the award path get NO entrance, NO spark and
        //     NO reveal. They are the 100+/day column. They keep only the
        //     :active press response, which is an acknowledgement rather
        //     than an animation.
        //   · The stat tiles and the leaderboard count UP the first time
        //     their numbers arrive and SNAP for every award after that. A
        //     count-up on the 200th ticket of the day would be a wrong
        //     number on screen, twice a minute, for no reason.
        //   · Search results never animate. renderStudentTable runs on
        //     every keystroke; the row stagger is keyed to the table's
        //     first paint and stays off for the rest of the session.
        //   · The sidebar buttons themselves get nothing. What changed is
        //     the pane, so the pane is what moves.
        // ============================================================

        /** Set a number, counting it up only if this is its first arrival. */
        function wcCount(id, value) {
            const el = typeof id === 'string' ? document.getElementById(id) : id;
            if (!el) return;
            if (window.wcMotion) window.wcMotion.count(el, value);
            else el.textContent = value;
        }

        /** Stagger a table body's rows, on its first paint only. */
        function wcRows(id, max) {
            if (!window.wcMotion) return;
            const el = typeof id === 'string' ? document.getElementById(id) : id;
            if (!el) return;
            window.wcMotion.stagger(el, {
                selector: ':scope > tr',
                type: 'row',
                max: typeof max === 'number' ? max : 12
            });
        }

        /** Count every [data-wcm-count] inside a container, first paint only. */
        function wcNums(id) {
            if (!window.wcMotion) return;
            const el = typeof id === 'string' ? document.getElementById(id) : id;
            if (el) window.wcMotion.countAll(el);
        }

        /** Crossfade a pane that has just been revealed. */
        function wcPane(el) {
            if (window.wcMotion && el) window.wcMotion.pane(el);
        }

        function wcInitMotion() {
            const m = window.wcMotion;
            if (!m) return;

            // --- Modals -------------------------------------------------
            // Marked, not rewired. The open/close code is untouched: the
            // CSS transitions `display` itself with @starting-style and
            // allow-discrete, which rb-standards.md recommends by name for
            // "entry without JS". This app has five different ways of
            // showing a modal, and threading a JS timing dance through all
            // of them is how a dialog ends up stuck on screen.
            document.querySelectorAll('.modal, .ref-modal').forEach(function (overlay) {
                overlay.classList.add('wcm-modal');
                const card = overlay.querySelector(':scope > .modal-content, :scope > .ref-modal-card');
                if (card) card.classList.add('wcm-modal-card');
            });

            const profile = document.getElementById('studentProfileModal');
            if (profile) {
                profile.classList.add('wcm-modal');
                const card = profile.firstElementChild;
                if (card) {
                    card.classList.add('wcm-modal-card');
                    // Replaces an inline `animation: slideInUp 0.4s ease`:
                    // 400ms is over the doc's 300ms ceiling for UI, `ease`
                    // is the wrong curve for something entering, and 30px
                    // of travel on a 900px card reads as a jump. The class
                    // above lands it at 260ms on the strong ease-out from
                    // 0.97 and 6px.
                    card.style.animation = 'none';
                }
            }

            // --- Click spark --------------------------------------------
            // The raffle draw, and only the raffle draw. It happens once a
            // week, it is the one moment in this app that is a celebration
            // rather than a task, and it is the exact "rare / first-time"
            // row of the frequency table. Sparks on the award button — a
            // control pressed hundreds of times a day — would be the same
            // component used as a defect.
            m.clickSpark('.btn-draw', { sparkColor: '#E6E280' });

            // --- Press feedback -----------------------------------------
            // scale(0.97) / 160ms, straight out of rb-standards.md. This is
            // the one thing that IS allowed on a hot control, because it is
            // the response to a press rather than an animation played at
            // the user.
            m.press('.btn, .sp-tab, .subtab-button, .wp-btn, .wu-filter, .wu-day, .wu-tile-arrow');
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', wcInitMotion);
        } else {
            wcInitMotion();
        }


        // ============================================================
        // THE SHELL, AND THE DASHBOARD
        // ------------------------------------------------------------
        // Reference: docs/design-reference.md (the Notasnet school
        // dashboard, chosen 2026-08-15). Two patterns from it live here
        // because they need JS: the nav rail's icon squares, and the
        // dashboard itself.
        // ============================================================

        // Leading emoji of a label, as one grapheme cluster including ZWJ
        // sequences — 👨‍🏫 is three code points and must not be cut in half.
        const WC_LEAD_EMOJI = /^\s*((?:\p{Extended_Pictographic}(?:\uFE0F|\p{Emoji_Modifier})?(?:\u200D\p{Extended_Pictographic}(?:\uFE0F|\p{Emoji_Modifier})?)*)+)\s*/u;

        /**
         * Split a label's leading emoji into its own element.
         *
         * The reference puts every nav item's icon in its own square, so the
         * label is not doing the work of being findable. Every nav item in
         * this app already carries an emoji at the front of its text — but as
         * a text node, which CSS cannot reach. Rather than rewrite twenty
         * buttons in the markup and every `innerHTML` that builds more of
         * them at runtime, this splits them where they are.
         *
         * Idempotent: it marks what it has done and never runs twice on the
         * same element, because it is called from switchTab().
         */
        function wcSplitLeadingEmoji(el, iconClass, labelClass) {
            if (!el || el.dataset.wcSplit === '1') return;
            // A SPRITE ICON IN FRONT OF THE WORDS is the new shape of every
            // shell button: <svg class="wc-icon"> then text. It gets the same
            // tile the emoji used to, so the rail's geometry does not change
            // with the glyph set. Checked first, because textContent cannot
            // see an <svg> and the emoji match below would find nothing.
            const lead = el.firstElementChild;
            if (lead && lead.tagName === 'svg' && lead.classList.contains('wc-icon')) {
                const words = (el.textContent || '').trim();
                if (!words) return;
                el.dataset.wcSplit = '1';
                el.textContent = '';
                const tile = document.createElement('span');
                tile.className = iconClass;
                tile.setAttribute('aria-hidden', 'true');
                tile.appendChild(lead);
                const label = document.createElement('span');
                label.className = labelClass;
                label.textContent = words;
                el.appendChild(tile);
                el.appendChild(label);
                return;
            }
            const raw = el.textContent || '';
            const m = raw.match(WC_LEAD_EMOJI);
            el.dataset.wcSplit = '1';
            if (!m) return;
            const rest = raw.slice(m[0].length).trim();
            if (!rest) return;
            el.textContent = '';
            const icon = document.createElement('span');
            icon.className = iconClass;
            icon.setAttribute('aria-hidden', 'true');
            icon.textContent = m[1];
            const label = document.createElement('span');
            label.className = labelClass;
            label.textContent = rest;
            el.appendChild(icon);
            el.appendChild(label);
        }

        /**
         * Give the sidebar the reference's rail shape, and keep aria-current
         * in step with the .active class the rest of the app already sets.
         *
         * NOTHING here touches visibility or permissions. `.admin-only`,
         * `.super-admin-only` and every display toggle are left exactly as
         * they were; this only rearranges the inside of a button.
         */
        function wcDecorateShell() {
            document.querySelectorAll('#appSidebar .tab').forEach(btn => {
                wcSplitLeadingEmoji(btn, 'wu-rail-icon', 'nav-label');
                btn.classList.add('wu-rail-item');
                if (btn.classList.contains('active')) btn.setAttribute('aria-current', 'page');
                else btn.removeAttribute('aria-current');
            });
            document.querySelectorAll('#mainApp .page-title').forEach(h => {
                wcSplitLeadingEmoji(h, 'page-ico', 'page-word');
            });

            // The topbar avatar. Initials of the name the app has already
            // written beside it, never a photograph. Recomputed each time
            // rather than cached, because establishTeacherSession writes the
            // name after this may first have run.
            const av = document.getElementById('topbarAvatar');
            const nameEl = document.getElementById('currentUserName');
            if (av && nameEl) av.textContent = wcInitials(nameEl.textContent);

            try { wcRenderSidebarBanner(); } catch (e) { /* cosmetic only */ }
            try { wcRenderRailDots(); } catch (e) { /* cosmetic only */ }

            // A nav group whose every item is hidden by the current mode still
            // drew its heading: the word "Insights" over nothing. The items are
            // hidden by CSS rules (body.cash-mode #dataTab and friends), not by
            // inline styles, so only a computed style can tell.
            //
            // This hides the GROUP, never an item. Nothing here decides who
            // may see what: .admin-only, .super-admin-only and the mode rules
            // are still the only things that gate a nav item, and this reads
            // their result rather than adding to it.
            //
            // #modeNav and #modeSubNav are excluded on purpose: their
            // visibility is owned by updateSidebarModeUI(), which hides them
            // when no mode is chosen even though their buttons are perfectly
            // visible. Touching them here would put the mode nav back.
            document.querySelectorAll('#appSidebar .sidebar-nav:not(#modeNav):not(#modeSubNav)').forEach(nav => {
                const anyVisible = [...nav.querySelectorAll(':scope > .tab')]
                    .some(t => getComputedStyle(t).display !== 'none');
                nav.style.display = anyVisible ? '' : 'none';
                const label = nav.previousElementSibling;
                if (label && label.classList.contains('sidebar-label')) {
                    label.style.display = anyVisible ? '' : 'none';
                }
            });
        }

        /** Up to two initials, or an em dash when there is no name to read. */
        function wcInitials(name) {
            const parts = String(name || '').trim().split(/\s+/).filter(Boolean);
            if (!parts.length) return '—';
            return parts.slice(0, 2).map(p => p.charAt(0).toUpperCase()).join('');
        }

        /**
         * The unread dot.
         *
         * 01-side-nav-layout puts a small red dot on one nav item, and the
         * only honest thing in this app to put one on is a hall pass REQUEST
         * that is waiting on somebody: it is addressed to a person, it has not
         * been answered, and answering it is a thing they came here to do.
         *
         * The dot is REMOVED as well as added on every pass. An indicator that
         * is always lit is not an indicator, and one that is left behind after
         * the last request is answered is worse than none.
         */
        function wcRenderRailDots() {
            // THE DOT NEVER LIT. It counted `hallPasses`, the pre-Convex array
            // the deleted Student Kiosk used to fill, on a `status` field that
            // Convex does not write either (the column is `state`). So the one
            // indicator in the app that says "a child is waiting on you" could
            // not light for any real request, and a teacher only found out by
            // opening the mode and looking.
            //
            // wcPassBoard.rows is the live board, already scoped: a teacher's
            // own classes for a teacher, the school for anybody wider. That
            // scoping is done once, on the server, by whichever of liveBoard /
            // myClassBoard was asked — doing it a second time here off
            // currentUser.id was the other half of the bug, since a Convex row
            // carries the teacher's EMAIL and never a legacy roster id.
            const board = (typeof wcPassBoard === 'object' && wcPassBoard) ? wcPassBoard : {};
            const rows = Array.isArray(board.rows) ? board.rows : [];
            const mine = rows.filter(function (p) {
                return p && String(p.state || '').toLowerCase() === 'requested';
            }).length;

            // The place a request is answered is Claw Pass -> My Class. When
            // that mode is not open, the mode card is the way to it.
            wcRailDot(document.getElementById('sideSub_hallpass_myClass'), mine > 0);
            const modeCard = document.getElementById('modeCard');
            const inHallPass = document.body.classList.contains('hallpass-mode');
            wcRailDot(modeCard, mine > 0 && !inHallPass);
        }

        function wcRailDot(el, on) {
            if (!el) return;
            const had = el.querySelector(':scope > .wu-rail-dot');
            if (on && !had) {
                const dot = document.createElement('span');
                dot.className = 'wu-rail-dot';
                dot.setAttribute('aria-hidden', 'true');
                el.appendChild(dot);
            } else if (!on && had) {
                had.remove();
            }
        }

        /**
         * The banner slot at the foot of the rail.
         *
         * 01 calls it "seasonal banner space — for announcements or school
         * campaigns". The reference fills it with an upsell; there is nothing
         * to sell in a school system, so it carries the one school-wide notice
         * this app actually owns — which cycle and week the school is in, and
         * what happens at the end of the week.
         *
         * It never invents one. With no cycle set it says so, in the same
         * voice every other missing value in this app uses.
         */
        function wcRenderSidebarBanner() {
            const el = document.getElementById('sidebarBanner');
            if (!el) return;
            const cyc = (typeof currentCycle === 'object' && currentCycle) ? currentCycle.cycleNumber : null;
            const wk = (typeof currentWeek === 'number') ? currentWeek : null;
            const dur = (typeof cycleDuration === 'number' && cycleDuration) ? cycleDuration : null;
            const isAdmin = currentUser && (currentUser.role === 'admin' || currentUser.role === 'superadmin');

            if (cyc === null || cyc === undefined || wk === null || dur === null) {
                el.innerHTML =
                    '<p class="sidebar-banner-eyebrow">Westbrook Academy</p>' +
                    '<p class="sidebar-banner-title">School notices</p>' +
                    '<p class="wu-absent">No cycle has been set, so there is nothing to announce here yet.</p>';
                return;
            }

            el.innerHTML =
                '<p class="sidebar-banner-eyebrow">Westbrook Academy</p>' +
                '<p class="sidebar-banner-title">Cycle ' + escapeHtml(String(cyc)) +
                    ' &middot; Week ' + escapeHtml(String(wk)) + ' of ' + escapeHtml(String(dur)) + '</p>' +
                '<p class="sidebar-banner-body">Every ticket count resets when the week is ended.</p>' +
                (isAdmin
                    ? '<button type="button" class="sidebar-banner-link admin-only" onclick="switchTab(\'settings\')">' +
                      'Cycle settings <span aria-hidden="true">&#8594;</span></button>'
                    : '');
        }

        // ------------------------------------------------------------
        // DASHBOARD
        // ------------------------------------------------------------

        // Which day the feed is scoped to. An ISO date, or null for today.
        let wcDashDay = null;
        // Which category of activity the feed is showing. 'all' or a key from
        // wcFeedCat(). Reset on nothing: a filter the user chose survives a
        // re-render, which is the whole point of a filter.
        let wcFeedFilter = 'all';

        function wcIsoDay(d) {
            const dt = (d instanceof Date) ? d : new Date(d);
            if (isNaN(dt)) return '';
            return `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}-${String(dt.getDate()).padStart(2, '0')}`;
        }

        function wcClock(hhmm) {
            if (!hhmm || typeof hhmm !== 'string') return '';
            const [h, m] = hhmm.split(':').map(Number);
            if (isNaN(h)) return hhmm;
            const suffix = h >= 12 ? 'PM' : 'AM';
            const hour = h % 12 === 0 ? 12 : h % 12;
            return `${hour}:${String(m || 0).padStart(2, '0')} ${suffix}`;
        }

        function wcWhen(iso) {
            const then = new Date(iso);
            if (isNaN(then)) return '';
            const mins = Math.round((Date.now() - then.getTime()) / 60000);
            if (mins < 1) return 'just now';
            if (mins < 60) return `${mins}m ago`;
            const hrs = Math.round(mins / 60);
            if (hrs < 24) return `${hrs}h ago`;
            return then.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
        }

        /** The students this user may award to, or null if that is unknowable. */
        function wcMyRoster() {
            const all = (typeof enrolledStudents === 'function') ? enrolledStudents() : [];
            if (!currentUser) return null;
            if (currentUser.role !== 'teacher') return all;
            const sections = Array.isArray(currentUser.sections) ? currentUser.sections : [];
            // A teacher with no sections is not a teacher with zero students.
            // It means the SIS has not matched them yet, and "0" would be a
            // lie that reads as "your classes are empty".
            if (sections.length === 0) return null;
            const ids = new Set();
            sections.forEach(s => (s.students || []).forEach(id => ids.add(String(id))));
            return all.filter(s => ids.has(String(s.id)));
        }

        function wcTile(label, value, opts) {
            const o = opts || {};
            const arrow = o.onclick
                ? `<button type="button" class="wu-tile-arrow" aria-label="${escapeHtml(o.arrowLabel || label)}" onclick="${o.onclick}">&#8599;</button>`
                : '';
            const body = (value === null || value === undefined)
                ? `<div class="wu-tile-figure"><span class="wu-absent">${escapeHtml(o.absent || 'no data')}</span></div>`
                : `<div class="wu-tile-figure ${o.tone ? 'wu-tile-' + o.tone : ''}">${escapeHtml(String(value))}</div>`;
            return `<div class="wu-tile">${arrow}<div class="wu-tile-label">${escapeHtml(label)}</div>${body}</div>`;
        }

        /**
         * Drive an arc gauge.
         *
         * `rate` is 0..1, or null when there is nothing measured. Null is not
         * zero: a gauge sitting at the far left with a rounded yellow cap on
         * it would read as "measured, and none", which is a different fact
         * from "not measured". .wu-gauge-empty takes the caps away.
         */
        function wcSetGauge(el, rate, label) {
            if (!el) return;
            const known = (rate !== null && rate !== undefined && !isNaN(rate));
            const v = known ? Math.max(0, Math.min(1, rate)) : 0;
            el.style.setProperty('--wu-gauge', v.toFixed(3));
            el.classList.toggle('wu-gauge-empty', !known || v <= 0);
            if (label) el.setAttribute('aria-label', label);
        }

        /** One of the two ringed sub-figures that sit under a gauge. */
        function wcSubring(kicker, name, value, tone) {
            const fig = (value === null || value === undefined)
                ? `<span class="wu-ring"><span class="wu-absent" style="font-size:11px;">&mdash;</span></span>`
                : `<span class="wu-ring ${tone ? 'wu-ring-' + tone : ''}">${escapeHtml(String(value))}</span>`;
            return `<div class="wu-subring">
                        <span class="wu-subring-label">${escapeHtml(kicker)}<b>${escapeHtml(name)}</b></span>
                        ${fig}
                    </div>`;
        }

        /**
         * Which category an audit entry belongs to.
         *
         * The feed's chips and its coloured tags both come from here, so a
         * chip can never select a category no card can be in. Order matters:
         * "UNDID Award" is a reversal before it is an award.
         */
        function wcFeedCat(entry) {
            const a = String((entry && entry.action) || '');
            if (/undid|undo|revers|removed|deduct/i.test(a)) return { key: 'undo', label: 'Reversed', tag: 'wu-tag-undo', icon: '&#8630;' };
            if (/winner|jackpot|raffle/i.test(a))            return { key: 'win',  label: 'Winner',   tag: 'wu-tag-win',  icon: '&#127942;' };
            if (/cash|balance|redeem|purchase|store/i.test(a)) return { key: 'cash', label: 'Wildcat Cash', tag: 'wu-tag-cash', icon: '&#128176;' };
            if (/hall pass|claw pass/i.test(a))              return { key: 'pass', label: 'Claw Pass', tag: 'wu-tag-pass', icon: '&#127915;' };
            if (/referral|discipline|detention/i.test(a))    return { key: 'flag', label: 'Discipline', tag: 'wu-tag-flag', icon: '&#128681;' };
            return { key: 'award', label: 'Tickets', tag: 'wu-tag-award', icon: '&#127903;' };
        }

        /* ============================================================
           WHO IS OUT, RIGHT NOW.

           `hallPasses:liveBoard` has existed for a while and nothing ever
           called it, so the one question a dashboard should answer on sight
           - is anybody out, and for how long - could only be answered by
           opening another screen.

           Two rules this board lives by:

           1. It counts locally. The server sends elapsed minutes as a float
              computed at query time; printing that gives you
              "0.22198333333333334 min" frozen until a refresh. Given the
              approval time, the browser ticks it.
           2. It says when it is incomplete. A board that silently stops at
              its cap is a board missing a child who is out of the building,
              which is the one thing it exists never to do.
           ============================================================ */

        var wcPassBoard = { rows: [], elsewhere: [], whole: false, truncated: [], poll: null, tick: null, at: 0 };

        /* Seconds -> M:SS, or H:MM:SS once an hour has gone. Named for the
           elapsed sense: wcClock already exists and formats a time of DAY. */
        function wcElapsedClock(totalSeconds) {
            var t = Math.max(0, Math.floor(totalSeconds));
            var h = Math.floor(t / 3600);
            var m = Math.floor((t % 3600) / 60);
            var sec = t % 60;
            var pad = function (n) { return String(n).padStart(2, '0'); };
            return h > 0 ? h + ':' + pad(m) + ':' + pad(sec) : m + ':' + pad(sec);
        }

        /* The moment a pass started running, as epoch ms. Prefers the real
           timestamp; falls back to the server's figure so a row still counts
           on a deployment that has not shipped approvedAt yet. */
        function wcPassStartMs(row) {
            /* A pass still waiting has not started going anywhere, so what
               matters is how long the REQUEST has sat. Once approved, the
               clock is time out of class. Two different questions, and the
               row says which one it is answering. */
            var stamp = row.state === 'requested'
                ? (row.requestedAt || null)
                : (row.outAt || row.approvedAt || null);
            if (stamp) {
                var parsed = Date.parse(stamp);
                if (isFinite(parsed)) return parsed;
            }
            if (typeof row.elapsedMinutes === 'number' && isFinite(row.elapsedMinutes)) {
                return (row.fetchedAt || Date.now()) - row.elapsedMinutes * 60000;
            }
            return null;
        }

        /* What the state MEANS, in the words a teacher would use. The raw
           machine states are not for reading: "out" and "requested" are the
           difference between a child in a corridor and one still sitting in
           your room with a hand up. */
        function wcPassState(row) {
            // The three live states, in the words a teacher would use. The raw
            // names are not for reading: "requested" and "out" are the
            // difference between a child still in your room with a hand up and
            // one already in a corridor.
            if (row.overdue) return { label: 'Overdue', tone: 'bad' };
            if (row.state === 'requested') return { label: 'Waiting on you', tone: 'wait' };
            if (row.state === 'active') return { label: 'Approved, not gone yet', tone: 'ok' };
            if (row.state === 'out') return { label: 'Out', tone: 'ok' };
            return { label: row.state || 'Open', tone: 'ok' };
        }

        /** One row of the board. */
        function wcPassRowHtml(row, now) {
            var st = wcPassState(row);
            var startMs = wcPassStartMs(row);
            var clock = startMs === null ? '\u2014' : wcElapsedClock((now - startMs) / 1000);

            /* The course label often already carries the period, so appending
               it again gave "Test Class \u00b7 Period 1 \u00b7 Period 1". Only add
               it when the name does not already say it. */
            var course = row.courseName || '';
            var periodText = row.period ? 'Period ' + row.period : '';
            var where = periodText && course.indexOf(periodText) === -1
                ? [course, periodText].filter(Boolean).join(' \u00b7 ')
                : (course || periodText);

            return '' +
              '<div class="wc-pass-row wc-pass-' + st.tone + '">' +
                '<div class="wc-pass-who">' +
                  '<span class="wc-pass-name">' + wcEsc(row.studentName || 'Unknown') + '</span>' +
                  '<span class="wc-pass-meta">' + wcEsc(where || 'No lesson recorded') + '</span>' +
                '</div>' +
                '<div class="wc-pass-state">' +
                  '<span class="wc-pass-badge">' + wcEsc(st.label) + '</span>' +
                '</div>' +
                '<div class="wc-pass-clock" data-start="' + (startMs === null ? '' : startMs) + '"' +
                  ' title="' + (row.state === 'requested' ? 'Waiting this long' : 'Out this long') + '">' +
                  clock +
                '</div>' +
              '</div>';
        }

        function wcRenderPassRows() {
            var list = document.getElementById('dashPassList');
            var chip = document.getElementById('dashPassChip');
            var sub = document.getElementById('dashPassSub');
            var panel = document.getElementById('dashPassPanel');
            if (!list || !panel) return;

            var rows = wcPassBoard.rows || [];
            var elsewhere = wcPassBoard.elsewhere || [];
            var whole = !!wcPassBoard.whole;
            panel.hidden = false;

            if (chip) {
                // The count a chip shows must be the count of what is on
                // screen, or it reads as a board that is hiding something.
                var counted = rows.concat(elsewhere);
                var overdue = counted.filter(function (r) { return r.overdue; }).length;
                chip.textContent = counted.length === 0
                    ? 'All in'
                    : counted.length + ' out' + (overdue ? ' \u00b7 ' + overdue + ' overdue' : '');
                chip.className = 'wu-chip' + (overdue ? ' wu-chip-bad' : '');
            }

            if (sub) {
                sub.textContent = wcPassBoard.truncated && wcPassBoard.truncated.length
                    ? 'Longest-running only \u2014 more are open than fit on this board.'
                    : (whole ? 'Everyone currently out, school-wide.' : 'Your classes first.');
            }

            var now = Date.now();
            var html = '';

            if (rows.length === 0) {
                html += '<p class="wc-pass-empty">' +
                    (whole ? 'Nobody is out right now.' : 'None of your students are out.') +
                    '</p>';
            } else {
                html += rows.map(function (r) { return wcPassRowHtml(r, now); }).join('');
            }

            /* The rest of the school, folded. Real, but not this teacher's job
               this minute - and a teacher who needs it should not have to go
               to another screen to find out a child is missing. */
            if (!whole && elsewhere.length > 0) {
                var overdueElsewhere = elsewhere.filter(function (r) { return r.overdue; }).length;
                html += '<details class="wc-pass-more">' +
                    '<summary>' +
                        'Elsewhere in school (' + elsewhere.length +
                        (overdueElsewhere ? ', ' + overdueElsewhere + ' overdue' : '') + ')' +
                    '</summary>' +
                    '<div class="wc-pass-board wc-pass-more-list">' +
                        elsewhere.map(function (r) { return wcPassRowHtml(r, now); }).join('') +
                    '</div>' +
                '</details>';
            }

            list.innerHTML = html;
        }

        /* Only the digits are rewritten each second. Re-rendering the whole
           board every tick would fight anyone trying to read it. */
        function wcTickPassClocks() {
            var now = Date.now();
            var nodes = document.querySelectorAll('#dashPassList .wc-pass-clock[data-start]');
            for (var i = 0; i < nodes.length; i++) {
                var start = parseInt(nodes[i].getAttribute('data-start'), 10);
                if (!isFinite(start)) continue;
                nodes[i].textContent = wcElapsedClock((now - start) / 1000);
            }
        }

        function wcEsc(value) {
            return String(value == null ? '' : value)
                .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;');
        }

        /* Who sees what.

           A campus aide IS the person who goes and finds the child, so the
           whole school is their board and anything less makes it useless. A
           teacher with 34 children in front of them needs their own three at
           the top; the rest of the building is real but it is not their job
           this minute, so it goes behind a disclosure rather than being
           hidden or dumped on them. */
        function wcSeesWholeSchool() {
            var role = (currentUser && currentUser.role) ? String(currentUser.role).toLowerCase() : '';
            return role === 'campusaide' || role === 'admin' || role === 'superadmin';
        }

        async function loadHallPassBoard() {
            var panel = document.getElementById('dashPassPanel');
            var list = document.getElementById('dashPassList');
            if (!panel) return;
            try {
                // window.WildcatAuth, not a bare `auth`. There is no global by
                // that name - every call site in this file takes its own local
                // reference - so the bare form was always undefined and this
                // board quietly hid itself instead of loading.
                var auth = window.WildcatAuth;
                var session = auth && auth.getSession ? auth.getSession() : null;
                var token = session && session.idToken;
                if (!token) { panel.hidden = true; return; }

                var whole = wcSeesWholeSchool();
                var fetchedAt = Date.now();

                // A teacher asks for both: theirs to act on, the school's to
                // fold away. One round trip each, twenty seconds apart.
                var school = await auth.convexQuery('hallPasses:liveBoard', {}, token);
                var mine = whole
                    ? null
                    : await auth.convexQuery('hallPasses:myClassBoard', {}, token).catch(function () { return null; });

                var all = (school && school.passes) || [];
                all.forEach(function (r) { r.fetchedAt = fetchedAt; });

                var primary, elsewhere;
                if (whole || !mine) {
                    primary = all;
                    elsewhere = [];
                } else {
                    primary = (mine.passes || []);
                    primary.forEach(function (r) { r.fetchedAt = fetchedAt; });
                    var seen = {};
                    primary.forEach(function (r) { seen[r.id] = true; });
                    elsewhere = all.filter(function (r) { return !seen[r.id]; });
                }

                wcPassBoard.whole = whole;
                wcPassBoard.rows = primary;
                wcPassBoard.elsewhere = elsewhere;
                wcPassBoard.truncated = (school && school.truncatedStates) || [];
                wcPassBoard.at = fetchedAt;
                wcRenderPassRows();
                // Everything else drawn from this board, refreshed on the same
                // twenty seconds. The nav dot is the signal that a child is
                // waiting on an answer, so it has to move when the board does,
                // not only when the chrome happens to be redrawn.
                try { wcRenderRailDots(); } catch (e) { /* cosmetic only */ }
                // The dashboard's day timeline reads the same rows. Redrawn
                // only while it is on screen: off screen it is rebuilt on the
                // way in anyway, and this runs all day behind every mode.
                try {
                    var tlEl = document.getElementById('dashTimeline');
                    if (tlEl && tlEl.offsetParent !== null && typeof renderTeacherDashboard === 'function') {
                        renderTeacherDashboard();
                    }
                } catch (e) { console.warn('[dashboard refresh]', e); }
            } catch (err) {
                /*
                 * A board that hides itself on any failure cannot be told from
                 * a board with nothing to show, and that is exactly how this
                 * shipped broken and looked like an empty school.
                 *
                 * Not being staff is the one case that legitimately has no
                 * board. Everything else says so, on the panel, where someone
                 * will actually see it.
                 */
                var message = String((err && (err.message || err)) || '');
                var notStaff = /staff|forbidden|unauthor|not allowed|permission/i.test(message);
                if (notStaff) {
                    panel.hidden = true;
                    return;
                }
                panel.hidden = false;
                if (list) {
                    list.innerHTML = '<p class="wc-pass-empty">Could not load who is out. ' +
                        wcEsc(message || 'The server did not answer.') + '</p>';
                }
                console.warn('[hall pass board]', err);
            }
        }

        function startHallPassBoard() {
            stopHallPassBoard();
            loadHallPassBoard();
            // The server is asked rarely; the clocks move every second.
            wcPassBoard.poll = setInterval(loadHallPassBoard, 20000);
            wcPassBoard.tick = setInterval(wcTickPassClocks, 1000);
        }

        function stopHallPassBoard() {
            if (wcPassBoard.poll) clearInterval(wcPassBoard.poll);
            if (wcPassBoard.tick) clearInterval(wcPassBoard.tick);
            wcPassBoard.poll = null;
            wcPassBoard.tick = null;
        }

        function renderTeacherDashboard() {
            const host = document.getElementById('dashboard');
            if (!host) return;

            // Who is out, before anything else on the page is computed.
            startHallPassBoard();

            const roster = wcMyRoster();
            const all = (typeof enrolledStudents === 'function') ? enrolledStudents() : [];
            const sections = (currentUser && Array.isArray(currentUser.sections)) ? currentUser.sections : [];

            // ---- Identity card -------------------------------------
            // The reference's identity card carries the SCHOOL as its display
            // title and the person being viewed in a white pill under it. Ours
            // is the same: Westbrook Academy on two lines, and the signed-in
            // member of staff in the pill.
            const name = (currentUser && currentUser.name) ? currentUser.name : 'Signed in';
            const roleLabel = (currentUser && currentUser.role)
                ? ((typeof getFriendlyRoleName === 'function') ? getFriendlyRoleName(currentUser.role) : currentUser.role)
                : '';
            const initials = wcInitials(name);
            const cyc = (typeof currentCycle === 'object' && currentCycle) ? currentCycle.cycleNumber : null;
            const wk = (typeof currentWeek === 'number') ? currentWeek : null;
            const dur = (typeof cycleDuration === 'number' && cycleDuration) ? cycleDuration : 5;

            const idEl = document.getElementById('dashIdentity');
            if (idEl) {
                // The chevron is on a pill that GOES somewhere, My Activity,
                // which every role has. A chevron on a control that does
                // nothing is worse than no chevron.
                idEl.innerHTML = `
                    <h3 class="wu-identity-title"><span class="wu-line">Westbrook</span><span class="wu-line">Academy</span></h3>
                    <button type="button" class="wu-person" onclick="switchTab('myActivity')"
                            aria-label="Open My Activity">
                        <span class="wu-avatar" aria-hidden="true">${escapeHtml(initials)}</span>
                        <span class="wu-person-main">
                            <span class="wu-person-name">${escapeHtml(name)}</span>
                            <span class="wu-person-sub">${escapeHtml(roleLabel || 'staff')}${sections.length
                                ? ' &middot; ' + sections.length + ' section' + (sections.length === 1 ? '' : 's')
                                : (currentUser && currentUser.role === 'teacher'
                                    ? ' &middot; <span class="wu-absent" style="font-size:inherit;">no sections assigned</span>'
                                    : '')}</span>
                        </span>
                        <span class="wu-person-chev" aria-hidden="true">&#8250;</span>
                    </button>`;
            }

            // ---- Stat tiles ----------------------------------------
            const isAdmin = currentUser && (currentUser.role === 'admin' || currentUser.role === 'superadmin');
            const qualified = all.filter(isQualifiedForJackpot).length;

            const mine = (Array.isArray(auditLog) ? auditLog : []).filter(e =>
                e && e.action === 'Awarded Tickets' &&
                currentUser && e.teacherId === currentUser.id &&
                e.week === wk && entryBelongsToCurrentCycle(e));
            const myTickets = mine.reduce((sum, e) => sum + (Number(e.ticketCount) || 0), 0);

            const tiles = document.getElementById('dashTiles');
            if (tiles) {
                tiles.innerHTML = [
                    // An admin's tile counts the WHOLE roster, so it is only a
                    // fact once the roster is the authoritative one. On the
                    // Firestore fallback every record reads as enrolled and the
                    // number is roughly double the school. wcTile already has
                    // the idiom for this: pass null and say why.
                    wcTile('Your students',
                        (roster === null || (isAdmin && !rosterIsAuthoritative()))
                            ? null : roster.length,
                        { absent: (isAdmin && !rosterIsAuthoritative())
                            ? 'roster still loading'
                            : 'no sections assigned',
                          tone: 'brand',
                          onclick: isAdmin ? "switchTab('students')" : null,
                          arrowLabel: 'Open the student roster' }),
                    wcTile('Jackpot qualified',
                        all.length ? qualified : null,
                        { absent: 'roster not loaded',
                          onclick: isAdmin ? "switchTab('bigRaffle')" : null,
                          arrowLabel: 'Open Wildcat Jackpot' }),
                    // A measured zero here is a real fact: this teacher has
                    // awarded nothing yet this week. It is only absent when
                    // there is no week to count against.
                    wcTile('Your tickets this week',
                        wk === null ? null : myTickets,
                        { absent: 'no week set',
                          onclick: "switchTab('myActivity')",
                          arrowLabel: 'Open My Activity' })
                ].join('');
            }

            // ---- Arc gauge: jackpot qualification -------------------
            const gauge = document.getElementById('dashGauge');
            const gaugeVal = document.getElementById('dashGaugeValue');
            const legs = document.getElementById('dashGaugeLegs');
            const rate = all.length ? qualified / all.length : null;

            wcSetGauge(gauge, rate, rate === null
                ? 'Jackpot qualification rate: no roster loaded'
                : `Jackpot qualification rate ${Math.round(rate * 100)} percent`);
            if (gaugeVal) {
                gaugeVal.innerHTML = rate === null
                    ? '<span class="wu-absent">no roster</span>'
                    : `${Math.round(rate * 100)}%`;
            }

            if (legs) {
                if (!all.length) {
                    legs.innerHTML = '<p class="wu-absent">Qualification needs a roster. Nothing has loaded yet.</p>';
                } else {
                    const byGrade = new Map();
                    all.forEach(s => {
                        const g = (s.grade === undefined || s.grade === null || s.grade === '') ? null : String(s.grade);
                        if (g === null) return;
                        if (!byGrade.has(g)) byGrade.set(g, { n: 0, q: 0 });
                        const row = byGrade.get(g);
                        row.n += 1;
                        if (isQualifiedForJackpot(s)) row.q += 1;
                    });
                    const ranked = [...byGrade.entries()]
                        .filter(([, r]) => r.n >= 5)
                        .map(([g, r]) => ({ g, pct: Math.round((r.q / r.n) * 100) }))
                        .sort((a, b) => b.pct - a.pct);
                    if (ranked.length < 2) {
                        legs.innerHTML = '<p class="wu-absent">Not enough graded groups to rank.</p>';
                    } else {
                        const best = ranked[0];
                        const worst = ranked[ranked.length - 1];
                        legs.innerHTML = '<div class="wu-subrings">' +
                            wcSubring('Highest', 'Grade ' + best.g, best.pct, 'good') +
                            wcSubring('Lowest', 'Grade ' + worst.g, worst.pct, 'bad') +
                            '</div>';
                    }
                }
            }

            // ---- Day strip -----------------------------------------
            // Today first, then backwards. The reference's strip runs forward
            // from today because its events are lessons still to come; ours
            // looks back because what is recorded on a day is what happened on
            // it. Reading order is recency order either way.
            const days = document.getElementById('dashDays');
            const months = document.getElementById('dashDayMonths');
            const todayIso = wcIsoDay(new Date());
            const selected = wcDashDay || todayIso;
            if (days) {
                const cells = [];
                for (let i = 0; i < 7; i++) {
                    const d = new Date();
                    d.setDate(d.getDate() - i);
                    cells.push(d);
                }
                days.innerHTML = cells.map((d, i) => {
                    const iso = wcIsoDay(d);
                    const word = i === 0 ? 'Today' : (i === 1 ? 'Yesterday' : '');
                    return `<button type="button" class="wu-day" aria-pressed="${iso === selected}"
                                    onclick="wcDashPickDay('${iso}')">
                                ${word ? `<span class="wu-day-word">${word}</span>` : ''}
                                <span class="wu-day-dow">${d.toLocaleDateString(undefined, { weekday: 'short' })}</span>
                                <span class="wu-day-num">${d.getDate()}</span>
                             </button>`;
                }).join('');

                // The month runs above the strip and only where it changes,
                // as 03 sets it. A cell is 58px wide with an 8px gap.
                if (months) {
                    const runs = [];
                    cells.forEach(d => {
                        const label = d.toLocaleDateString(undefined, { month: 'long' });
                        const last = runs[runs.length - 1];
                        if (last && last.label === label) last.n += 1;
                        else runs.push({ label, n: 1 });
                    });
                    months.innerHTML = runs.map(r =>
                        `<span class="wu-days-month" style="min-width:${(r.n * 66) - 8}px;">${escapeHtml(r.label)}</span>`
                    ).join('');
                }
            }

            // ---- Timeline: today's periods, and open hall passes ----
            const tl = document.getElementById('dashTimeline');
            const chip = document.getElementById('dashScheduleChip');
            const tlTitle = document.getElementById('dashTimelineTitle');
            // Prefer today's REAL schedule from Convex (meal periods included);
            // fall back to the legacy block schedule and kick off the fetch so
            // the next render has the real one.
            let schedule = null;
            if (_wcDaySchedule && Array.isArray(_wcDaySchedule.periods) && _wcDaySchedule.periods.length) {
                schedule = _wcDaySchedule;
            } else {
                try { schedule = (typeof getActiveSchedule === 'function') ? getActiveSchedule() : null; } catch (e) { schedule = null; }
                if (typeof wcLoadDaySchedule === 'function') wcLoadDaySchedule();
            }

            // getActiveSchedule() auto-detects from the day of the week and
            // falls back to the all-periods schedule when the lookup misses,
            // which on a Saturday means it hands back Wednesday's bells. Laying
            // Wednesday out under the word "Today" would be a fabricated day.
            const dow = new Date(selected + 'T12:00:00').getDay();
            const isToday = selected === todayIso;
            // getActiveSchedule() answers for NOW, it reads today's day of the
            // week and has no way to be asked about another date. So periods
            // are laid out for today only. On any other day the strip shows
            // what is actually recorded for that day (the passes and, in the
            // feed, the awards) rather than a bell schedule reconstructed from
            // the wrong weekday.
            const schoolDay = isToday && dow >= 1 && dow <= 5;

            if (chip) {
                let label = '';
                if (!isToday) label = 'Recorded';
                else if (dow === 0 || dow === 6) label = 'No classes';
                else if (schedule && schedule.name) label = schedule.name;
                chip.textContent = label;
                chip.style.display = label ? '' : 'none';
            }
            if (tlTitle) {
                tlTitle.textContent = selected === todayIso ? 'Your day' : 'That day';
            }

            if (tl) {
                const periods = (schoolDay && schedule && Array.isArray(schedule.periods)) ? schedule.periods : [];
                const mySections = new Map();
                sections.forEach(s => { if (s && s.period) mySections.set(String(s.period), s); });

                const nowMin = (() => { const n = new Date(); return n.getHours() * 60 + n.getMinutes(); })();
                const toMin = hhmm => {
                    if (!hhmm) return null;
                    const [h, m] = String(hhmm).split(':').map(Number);
                    return isNaN(h) ? null : h * 60 + (m || 0);
                };

                const rows = [];
                periods.forEach(p => {
                    // A period this user teaches reads as an event: a card with
                    // an icon square, a title and a subtitle. Every other
                    // period is still on the strip, a teacher needs the shape
                    // of the day, but it is one quiet outlined line, which is
                    // exactly how 03 draws a break.
                    const mySection = mySections.get(String(p.period));
                    const start = toMin(p.start);
                    const end = toMin(p.end);
                    const isNow = selected === todayIso && start !== null && end !== null &&
                                  nowMin >= start && nowMin < end;
                    const span = `${escapeHtml(wcClock(p.start))} &ndash; ${escapeHtml(wcClock(p.end))}`;

                    if (!mySection) {
                        const plabel = String(p.period);
                        const isMeal = /breakfast|nutrition|lunch/i.test(plabel);
                        const isNumeric = /^\d+$/.test(plabel.trim());
                        // A meal shows its name with a food icon; a numeric period
                        // the teacher does not teach reads as "Period N"; anything
                        // else (Promise Time) shows its own label as written.
                        const title = isNumeric ? ('Period ' + plabel) : plabel;
                        const icon = isMeal ? '&#127869;&#65039; ' : '';
                        rows.push({
                            sort: start === null ? 9999 : start,
                            html: `
                            <div class="wu-tl-row wu-tl-break ${isMeal ? 'wu-tl-meal' : ''} ${isNow ? 'wu-tl-now' : ''}">
                                <span class="wu-tl-dot" aria-hidden="true"></span>
                                <div class="wu-tl-card">
                                    <span class="wu-tl-time">${span}</span>
                                    <span class="wu-tl-title">${icon}${escapeHtml(title)}</span>
                                </div>
                            </div>`
                        });
                        return;
                    }

                    rows.push({
                        sort: start === null ? 9999 : start,
                        html: `
                        <div class="wu-tl-row ${isNow ? 'wu-tl-now' : ''}">
                            <span class="wu-tl-dot" aria-hidden="true"></span>
                            <div class="wu-tl-card">
                                <div class="wu-tl-head">
                                    <span class="wu-tl-time">${span}</span>
                                    ${isNow ? '<span class="wu-chip wu-chip-good">Now</span>' : ''}
                                </div>
                                <div class="wu-tl-main">
                                    <span class="wu-tl-icon" aria-hidden="true">&#128218;</span>
                                    <div class="wu-tl-body">
                                        <div class="wu-tl-title">${escapeHtml(mySection.courseName || 'Your class')}</div>
                                        <div class="wu-tl-sub">Period ${escapeHtml(String(p.period))} &middot; ${(mySection.students || []).length} students</div>
                                    </div>
                                </div>
                            </div>
                        </div>`
                    });
                });

                // Open hall passes. A pass is an event with a start, a duration
                // and a state, which is exactly the shape of a timeline card.
                //
                // THESE CARDS NEVER APPEARED. They were built from `hallPasses`,
                // the pre-Convex array the deleted Student Kiosk used to fill,
                // and filtered on `status === 'active'`, a field name Convex
                // does not use either. A teacher's day timeline could not show
                // a hall pass no matter how many children were out.
                //
                // wcPassBoard is the live board: hallPasses:liveBoard every
                // twenty seconds, already scoped by role (a teacher's own
                // classes in `rows`, the rest of the school in `elsewhere`).
                // The dashboard shows both, because a pass out of somebody
                // else's room still crossed this teacher's day.
                //
                // ONLY TODAY. The live board holds open passes and nothing
                // else, so it cannot answer for a past day; a silent empty
                // stretch would read as "nobody was out", which is a claim
                // this screen is not entitled to make. Past days say so below.
                const board = (typeof wcPassBoard === 'object' && wcPassBoard) ? wcPassBoard : {};
                const live = selected === todayIso
                    ? [].concat(Array.isArray(board.rows) ? board.rows : [],
                                Array.isArray(board.elsewhere) ? board.elsewhere : [])
                    : [];
                const open = live.filter(p => p && String(p.state || '').toLowerCase() !== 'requested');
                open.forEach(p => {
                    // The clock starts when the pass was APPROVED, not when it
                    // was asked for: a request that waited ten minutes for a
                    // teacher did not have the child out of class for ten
                    // minutes. elapsedMinutes on the row is the server's own
                    // measure of how long it has been running.
                    const created = new Date(p.approvedAt || p.outAt || p.requestedAt);
                    const allowed = Number(p.expiresAfterMinutes);
                    const ran = Number(p.elapsedMinutes);
                    const overdue = Boolean(p.overdue);
                    const left = (isNaN(allowed) || isNaN(ran)) ? null : Math.round(allowed - ran);
                    rows.push({
                        sort: isNaN(created) ? 9999 : created.getHours() * 60 + created.getMinutes(),
                        html: `
                        <div class="wu-tl-row">
                            <span class="wu-tl-dot" aria-hidden="true"></span>
                            <div class="wu-tl-card">
                                <div class="wu-tl-head">
                                    <span class="wu-tl-time">${escapeHtml(created.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }))}</span>
                                    ${overdue ? '<span class="wu-chip wu-chip-bad">Overdue</span>' : '<span class="wu-chip">Out</span>'}
                                </div>
                                <div class="wu-tl-main">
                                    <span class="wu-tl-icon ${overdue ? 'wu-tl-icon-bad' : 'wu-tl-icon-warn'}" aria-hidden="true">&#127915;</span>
                                    <div class="wu-tl-body">
                                        <div class="wu-tl-title">${escapeHtml(p.studentName || 'Student')}</div>
                                        <div class="wu-tl-sub">Out to ${escapeHtml(p.assignedDestination || 'somewhere not recorded')} &middot; ${
                                            left === null ? '<span class="wu-absent">no return time recorded</span>'
                                            : overdue ? `${Math.abs(left)} min overdue`
                                            : `${left} min left`}</div>
                                    </div>
                                </div>
                            </div>
                        </div>`
                    });
                });

                rows.sort((a, b) => a.sort - b.sort);
                tl.innerHTML = rows.length
                    ? rows.map(r => r.html).join('')
                    : (!isToday
                        // A PAST DAY CANNOT SAY "no passes". The live board
                        // holds open passes only, so silence about a past day
                        // is ignorance, not evidence. Pass History is where a
                        // finished day is answered, and it is named here rather
                        // than left as a shrug.
                        ? '<p class="wu-absent">Nothing scheduled. Passes for a past day are in Pass History.</p>'
                        : (dow === 0 || dow === 6)
                            ? '<p class="wu-absent">Not a school day. Nothing was scheduled and no passes are open.</p>'
                            : schedule
                                ? '<p class="wu-absent">Nothing scheduled and no passes open.</p>'
                                : '<p class="wu-absent">No bell schedule has been set, so the day cannot be laid out.</p>');
            }

            // ---- Activity feed -------------------------------------
            const feed = document.getElementById('dashFeed');
            const filterRow = document.getElementById('dashFeedFilters');
            if (feed) {
                const log = Array.isArray(auditLog) ? auditLog : [];
                // On today, the feed is what the reference's feed is: the most
                // recent things that happened, each carrying its own date.
                // Scoping it strictly to today made a busy school with six
                // thousand log entries read "nothing recorded" every morning
                // before the first bell, which is true and useless.
                // Picking any other day on the strip does scope it to that day.
                const scoped = (selected === todayIso)
                    ? log
                    : log.filter(e => e && wcIsoDay(e.timestamp) === selected);

                // The chips are built from what is actually in the window, so
                // a chip can never select an empty result. A filter that can
                // only ever return nothing is a dead control.
                const window20 = scoped.slice(-20).reverse();
                const present = [];
                window20.forEach(e => {
                    const c = wcFeedCat(e);
                    if (!present.some(p => p.key === c.key)) present.push(c);
                });
                if (present.length && !present.some(p => p.key === wcFeedFilter)) wcFeedFilter = 'all';

                if (filterRow) {
                    filterRow.innerHTML = present.length > 1
                        ? [`<button type="button" class="wu-filter wu-filter-all" aria-pressed="${wcFeedFilter === 'all'}"
                                    onclick="wcDashPickFilter('all')">All</button>`]
                            .concat(present.map(c =>
                                `<button type="button" class="wu-filter" aria-pressed="${wcFeedFilter === c.key}"
                                         onclick="wcDashPickFilter('${c.key}')">${c.label}</button>`))
                            .join('')
                        : '';
                }

                const items = window20
                    .filter(e => wcFeedFilter === 'all' || wcFeedCat(e).key === wcFeedFilter)
                    .slice(0, 8);

                feed.innerHTML = items.length
                    ? items.map(e => {
                        const cat = wcFeedCat(e);
                        const count = (e.ticketCount === undefined || e.ticketCount === null)
                            ? '' : ` &middot; ${escapeHtml(String(e.ticketCount))}`;
                        const detail = [
                            escapeHtml(String(e.reason || e.action || 'Activity')),
                            e.teacher ? escapeHtml(e.teacher) : ''
                        ].filter(Boolean).join(' &middot; ') + count;

                        // The quick action exists only where there is somewhere
                        // to go. "Multiple" is what a bulk reversal writes into
                        // studentId, and it is not a student.
                        const sid = String(e.studentId || '');
                        const known = sid && sid !== 'Multiple' &&
                            Array.isArray(students) && students.some(s => String(s.id) === sid);
                        const action = known
                            ? `<div class="wu-feed-foot"><button type="button" class="wu-quick"
                                   onclick="openStudentProfile('${escapeHtml(sid)}')">Open student</button></div>`
                            : '';

                        return `
                        <div class="wu-feed-item">
                            <div class="wu-feed-head">
                                <span class="wu-feed-ico" aria-hidden="true">${cat.icon}</span>
                                <div class="wu-feed-main">
                                    <div class="wu-feed-title">${escapeHtml(e.studentName || e.action || 'Activity')}</div>
                                    <span class="wu-tag ${cat.tag}">${cat.label}</span>
                                </div>
                                <span class="wu-feed-when">${escapeHtml(wcWhen(e.timestamp))}</span>
                            </div>
                            <p class="wu-feed-body">${detail}</p>
                            ${action}
                        </div>`;
                    }).join('')
                    : (log.length
                        ? '<p class="wu-absent">Nothing was recorded on this day.</p>'
                        : '<p class="wu-absent">The audit log has not loaded.</p>');
            }
        }

        function wcDashPickDay(iso) {
            wcDashDay = iso;
            renderTeacherDashboard();
        }

        function wcDashPickFilter(key) {
            wcFeedFilter = key;
            renderTeacherDashboard();
        }

        // Decorate once at boot as well, so the sidebar is a rail on the first
        // paint rather than after the first tab switch.
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', function () {
                try { wcDecorateShell(); } catch (e) { /* cosmetic only */ }
            });
        } else {
            try { wcDecorateShell(); } catch (e) { /* cosmetic only */ }
        }
